class WebIndicatorSelectionPolicy:
    indicators_any: frozenset[str]
    indicator_prefixes_any: Tuple[str, ...]

    def matches(self, indicators: Iterable[str]) -> bool:
        values = {
            str(indicator).strip().lower()
            for indicator in indicators
            if str(indicator).strip()
        }
        return bool(
            self.indicators_any & values
            or any(
                indicator.startswith(prefix)
                for indicator in values
                for prefix in self.indicator_prefixes_any
            )
        )


@dataclass(frozen=True)
class WebOutcomeSelectionPolicy:
    strategy: str
    ranks: Dict[str, int]

    def select(self, candidates: Iterable[str]) -> str:
        admitted = tuple(dict.fromkeys(candidates))
        if not admitted:
            raise ValueError("web outcome selection requires at least one candidate")
        return max(admitted, key=self.ranks.__getitem__)


