@dataclass(frozen=True)
class RankedValueMergePolicy:
    strategy: str
    ranks: Dict[str, int]

    def merge(self, current: Any, candidate: str) -> str:
        current_value = _safe_str(current).strip()
        if self.strategy == "maximum_rank" and (
            current_value in self.ranks
            and self.ranks[current_value] >= self.ranks[candidate]
        ):
            return current_value
        return candidate


