@dataclass(frozen=True)
class ReferencedFileCorrelationPolicy:
    enabled: bool
    evidence_type: str
    current_path_field: str
    message_field: str
    execution_text_fields: Tuple[str, ...]
    execution_path_fields: Tuple[str, ...]
    parser_field: str
    request_field: str
    url_field: str
    response_code_field: str
    response_bytes_field: str
    upload_names_field: str
    upload_hashes_field: str
    upload_outcome_field: str
    web_outcome_field: str
    web_feature_fields: Dict[str, str]
    attack_indicators_field: str
    source_ip_field: str
    method_field: str
    endpoint_field: str
    status_field: str
    attack_techniques_field: str
    basename_fallback: str
    exclude_self_reference: bool
    document_roots: Tuple[str, ...]
    web_log_parser_tokens: Tuple[str, ...]
    upload_methods: frozenset[str]
    success_status_minimum: int
    success_status_maximum_exclusive: int
    emissions_by_id: Dict[str, DetectorEmissionPolicy]
    propagation: Dict[str, ReferencedFilePropagationPolicy]
    web_branches: Tuple[ReferencedFileWebBranchPolicy, ...]
    web_outcome_merge: RankedValueMergePolicy
    mapping_enabled: bool
    mapping_outputs: Dict[str, WebMappingOutputPolicy]
    mapping_branches: Tuple[WebMappingBranchPolicy, ...]
    policy_digest: str

    @property
    def emissions(self) -> Tuple[DetectorEmissionPolicy, ...]:
        mapping_emissions = (
            tuple(output.emission for output in self.mapping_outputs.values())
            if self.mapping_enabled
            else ()
        )
        return tuple(self.emissions_by_id.values()) + mapping_emissions

    @property
    def external_mapping_input_signals(self) -> frozenset[str]:
        if not self.mapping_enabled:
            return frozenset()
        # Web-branch emissions are available before mapping conditions are
        # evaluated. Mapping outputs are not: all branch conditions are
        # snapshotted first, then outputs are emitted. Treating those outputs
        # as owned inputs would therefore admit impossible same-pass
        # dependencies and bypass phase validation.
        owned = {emission.name for emission in self.emissions_by_id.values()}
        used = {
            signal
            for branch in self.mapping_branches
            for condition in (branch.conditions, branch.exclude)
            if condition is not None
            for signal in condition.signals_any
        }
        return frozenset(used - owned)


