class DetectorPolicy:
    version: int
    mode: str
    detectors: Tuple[DetectorDefinition, ...]

    def definition(self, detector_id: str) -> DetectorDefinition:
        for definition in self.detectors:
            if definition.detector_id == detector_id:
                return definition
        raise KeyError(detector_id)

    def definitions(
        self,
        *,
        stage: Optional[str] = None,
        executor: Optional[str] = None,
        enabled_only: bool = False,
    ) -> Tuple[DetectorDefinition, ...]:
        return tuple(
            definition
            for definition in self.detectors
            if (stage is None or definition.stage == stage)
            and (executor is None or definition.executor == executor)
            and (not enabled_only or bool(definition.payload.enabled))
        )

    @property
    def systemd_service_persistence(self) -> SystemdServicePersistencePolicy:
        return self.definition("systemd_service_persistence").payload

