def _detector_definition_required_fields(
    definition: DetectorDefinition,
) -> Set[str]:
    """Return raw dataset fields required by one enabled detector definition."""
    policy = definition.payload
    if not bool(policy.enabled):
        return set()
    if definition.executor == "clamav_classifier":
        return {"av_hit", "av_signature", "filename"}
    if definition.executor == "yara_classifier":
        return {"yara_match"}
    if definition.executor == "web_request_classifier":
        inputs = policy.inputs
        return {
            inputs.parser_field,
            inputs.message_field,
            inputs.request_field,
            inputs.url_field,
            inputs.headers_field,
            inputs.response_code_field,
            inputs.response_bytes_field,
            *inputs.source_ip_fields,
            inputs.user_agent_field,
            inputs.referer_field,
            inputs.body_field,
            inputs.content_disposition_field,
            inputs.upload_filename_field,
            inputs.upload_content_type_field,
            inputs.upload_sha256_field,
            inputs.request_content_length_field,
        }
    if definition.executor == "referenced_file_correlation":
        return {
            policy.current_path_field,
            policy.message_field,
            *policy.execution_text_fields,
            *policy.execution_path_fields,
            policy.parser_field,
            policy.request_field,
            policy.url_field,
            policy.response_code_field,
            policy.response_bytes_field,
            policy.upload_names_field,
            policy.upload_hashes_field,
            policy.upload_outcome_field,
            policy.web_outcome_field,
            *policy.web_feature_fields.values(),
            policy.attack_indicators_field,
            policy.source_ip_field,
            policy.method_field,
            policy.endpoint_field,
            policy.status_field,
        }
    if definition.executor == "webshell_artifact":
        return {
            *policy.path_fields,
            *policy.text_fields,
            *policy.first_existing_text_fields,
            *_policy_evidence_fields(policy.evidence),
        }
    if definition.executor == "systemd_service_persistence":
        return {
            *policy.path_fields,
            policy.timestamp_field,
            *policy.text_fields,
            *policy.first_existing_text_fields,
            *_policy_evidence_fields(policy.evidence),
        }
    if definition.executor == "signal_sequence_by_artifact":
        return {*policy.artifact_fields, policy.host_field}
    if definition.executor == "signal_gate":
        return _policy_evidence_fields(policy.evidence)
    if definition.executor == "signal_projection":
        return set()
    if definition.executor == "canonical_authentication":
        return {
            policy.outcome_field,
            policy.protocol_field,
            policy.direction_field,
            policy.logon_type_field,
            policy.message_field,
            policy.authentication_package_field,
        }
    if definition.executor == "execution_context_classifier":
        return {
            *policy.path_fields,
            *policy.command_fields,
            *policy.actor_fields,
        }
    if definition.executor == "file_lifecycle":
        return {
            *policy.path_fields,
            policy.timestamp_field,
            policy.host_field,
            policy.parser_field,
            policy.message_field,
            policy.file_size_field,
            policy.allocation_field,
        }
    if definition.executor == "mft_timestomping":
        return {
            *policy.path_fields,
            policy.parser_field,
            policy.timestamp_field,
        }
    if definition.executor == "geographic_continuity":
        return {
            *policy.key_fields,
            policy.country_field,
            policy.asn_field,
            policy.city_field,
            *policy.ip_fields,
        }
    if definition.executor == "impossible_travel":
        return {
            *policy.key_fields,
            policy.latitude_field,
            policy.longitude_field,
            policy.country_field,
            *policy.ip_fields,
        }
    if definition.executor == "ip_scope_continuity":
        return {*policy.key_fields, *policy.ip_fields}
    if definition.executor in {
        "ordered_row_rules", "ordered_signal_adjustments"
    }:
        return {
            field_name
            for input_policy in policy.inputs.values()
            for field_name in (
                *input_policy.fields,
                *input_policy.first_existing_fields,
            )
        }
    if definition.executor == "grouped_signal_window":
        return {
            policy.host_field,
            *policy.command_fields,
            policy.message_field,
        }
    if definition.executor == "signal_sequence":
        fields = _policy_evidence_fields(policy.evidence)
        if policy.key_scope == "field" and policy.key_field:
            fields.add(policy.key_field)
        if policy.target_context is not None:
            fields.update(policy.target_context.path_fields)
            fields.update(policy.target_context.combined_text_fields)
        return fields
    if definition.executor == "temporal_context_branches":
        return {*policy.note_path_fields, *_policy_evidence_fields(policy.evidence)}
    if definition.executor == "counted_signal_window":
        return _policy_evidence_fields(policy.evidence)
    if definition.executor == "artifact_follow_on_sequence":
        return {
            *policy.path_fields,
            *policy.text_fields,
            *_policy_evidence_fields(policy.evidence),
        }
    raise ValueError(
        f"detector_policy.detectors.{definition.detector_id}.executor: "
        f"unsupported executor {definition.executor!r}"
    )


def _resolve_continuity_evidence(
    fields: Iterable[ContinuityEvidenceFieldPolicy],
    values: Dict[str, Any],
) -> Dict[str, Any]:
    evidence: Dict[str, Any] = {}
    for evidence_field in fields:
        value = values[evidence_field.resolver]
        if evidence_field.round_digits is not None and isinstance(
            value, (int, float, np.number)
        ):
            value = round(float(value), evidence_field.round_digits)
        if evidence_field.max_chars is not None:
            value = _safe_str(value)[:evidence_field.max_chars]
        evidence[evidence_field.name] = value
    return evidence


_DETECTOR_POLICY_CONFIDENCE = frozenset({"low", "medium", "high"})


def _policy_mapping(value: Any, path: str) -> Dict[str, Any]:
    if not isinstance(value, dict):
        raise ValueError(f"{path}: expected a mapping")
    return value


def _policy_keys(
    value: Dict[str, Any],
    path: str,
    *,
    required: Iterable[str],
    optional: Iterable[str] = (),
) -> None:
    required_set = set(required)
    allowed = required_set | set(optional)
    missing = sorted(required_set - set(value))
    unknown = sorted(set(value) - allowed)
    if missing:
        raise ValueError(f"{path}: missing required key(s): {', '.join(missing)}")
    if unknown:
        raise ValueError(f"{path}: unknown key(s): {', '.join(unknown)}")


def _policy_string(value: Any, path: str, *, lower: bool = False) -> str:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{path}: expected a non-empty string")
    result = value.strip()
    return result.lower() if lower else result


def _policy_string_list(
    value: Any,
    path: str,
    *,
    lower: bool = False,
) -> Tuple[str, ...]:
    if not isinstance(value, list) or not value:
        raise ValueError(f"{path}: expected a non-empty list")
    result: List[str] = []
    for index, item in enumerate(value):
        text = _policy_string(item, f"{path}[{index}]", lower=lower)
        if text in result:
            raise ValueError(f"{path}[{index}]: duplicate value {text!r}")
        result.append(text)
    return tuple(result)


def _policy_string_list_or_empty(
    value: Any,
    path: str,
    *,
    lower: bool = False,
) -> Tuple[str, ...]:
    if not isinstance(value, list):
        raise ValueError(f"{path}: expected a list")
    if not value:
        return ()
    return _policy_string_list(value, path, lower=lower)


def _policy_literal_string_list(value: Any, path: str) -> Tuple[str, ...]:
    """Parse non-empty configured literals without discarding edge whitespace."""
    if not isinstance(value, list) or not value:
        raise ValueError(f"{path}: expected a non-empty list")
    result: List[str] = []
    for index, item in enumerate(value):
        if not isinstance(item, str) or not item.strip():
            raise ValueError(f"{path}[{index}]: expected a non-empty string")
        if item in result:
            raise ValueError(f"{path}[{index}]: duplicate value {item!r}")
        result.append(item)
    return tuple(result)


_POLICY_SIGNAL_NAME_RE = re.compile(r"^[a-z][a-z0-9_]*$")


def _policy_signal_name(value: Any, path: str) -> str:
    result = _policy_string(value, path)
    if not _POLICY_SIGNAL_NAME_RE.fullmatch(result):
        raise ValueError(
            f"{path}: signal names must use lowercase snake_case "
            "([a-z][a-z0-9_]*)"
        )
    return result


def _policy_signal_list(value: Any, path: str) -> Tuple[str, ...]:
    if not isinstance(value, list) or not value:
        raise ValueError(f"{path}: expected a non-empty list")
    result: List[str] = []
    for index, item in enumerate(value):
        signal_name = _policy_signal_name(item, f"{path}[{index}]")
        if signal_name in result:
            raise ValueError(f"{path}[{index}]: duplicate value {signal_name!r}")
        result.append(signal_name)
    return tuple(result)


def _policy_bool(value: Any, path: str) -> bool:
    if type(value) is not bool:
        raise ValueError(f"{path}: expected true or false")
    return value


def _policy_positive_number(value: Any, path: str) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"{path}: expected a positive finite number")
    result = float(value)
    if not math.isfinite(result) or result <= 0.0:
        raise ValueError(f"{path}: expected a positive finite number")
    return result


def _policy_nonnegative_number(value: Any, path: str) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"{path}: expected a non-negative finite number")
    result = float(value)
    if not math.isfinite(result) or result < 0.0:
        raise ValueError(f"{path}: expected a non-negative finite number")
    return result


def _policy_positive_int(value: Any, path: str) -> int:
    if type(value) is not int or value <= 0:
        raise ValueError(f"{path}: expected a positive integer")
    return int(value)


def _policy_nonnegative_int(value: Any, path: str) -> int:
    if type(value) is not int or value < 0:
        raise ValueError(f"{path}: expected a non-negative integer")
    return int(value)


def _compile_canonicalisation_regex(
    value: Any,
    path: str,
    flags: int = 0,
) -> re.Pattern[str]:
    pattern = _policy_string(value, path)
    try:
        return re.compile(pattern, flags)
    except (re.error, ValueError) as exc:
        raise ValueError(f"{path}: invalid regular expression: {exc}") from exc


def _parse_normalisation_policy(raw: Any, path: str) -> Tuple[NormalisationSpec, ...]:
    if not isinstance(raw, list) or not raw:
        raise ValueError(f"{path}: expected a non-empty list")
    parsed: List[NormalisationSpec] = []
    seen_names: Set[str] = set()
    for index, raw_spec in enumerate(raw):
        spec_path = f"{path}[{index}]"
        cfg = _policy_mapping(raw_spec, spec_path)
        method = _policy_enum(
            cfg.get("method"),
            f"{spec_path}.method",
            {"coalesce", "regex_first", "ipv4_first", "file_extension"},
        )
        name = _policy_string(cfg.get("name"), f"{spec_path}.name")
        if name in seen_names:
            raise ValueError(f"{spec_path}.name: duplicate output field {name!r}")
        seen_names.add(name)

        if method == "coalesce":
            _policy_keys(cfg, spec_path, required={"name", "method", "fields"})
            fields = _policy_string_list(cfg["fields"], f"{spec_path}.fields")
            parsed.append(NormalisationSpec(name=name, method=method, fields=fields))
            continue

        if method == "regex_first":
            _policy_keys(
                cfg,
                spec_path,
                required={"name", "method", "from", "pattern", "group"},
                optional={"flags"},
            )
            flags = (
                _policy_nonnegative_int(cfg["flags"], f"{spec_path}.flags")
                if "flags" in cfg
                else 0
            )
            compiled = _compile_canonicalisation_regex(
                cfg["pattern"], f"{spec_path}.pattern", flags
            )
            group = _policy_nonnegative_int(cfg["group"], f"{spec_path}.group")
            if group > compiled.groups:
                raise ValueError(
                    f"{spec_path}.group: capture group {group} does not exist "
                    f"in a pattern with {compiled.groups} group(s)"
                )
            parsed.append(
                NormalisationSpec(
                    name=name,
                    method=method,
                    source=_policy_string(cfg["from"], f"{spec_path}.from"),
                    pattern=compiled,
                    group=group,
                )
            )
            continue

        _policy_keys(cfg, spec_path, required={"name", "method", "from"})
        parsed.append(
            NormalisationSpec(
                name=name,
                method=method,
                source=_policy_string(cfg["from"], f"{spec_path}.from"),
            )
        )
    return tuple(parsed)


def _parse_geoip_enrichment_policy(
    raw: Any,
    path: str,
) -> GeoIPEnrichmentPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(cfg, path, required={"outputs"})
    outputs_path = f"{path}.outputs"
    outputs_cfg = _policy_mapping(cfg["outputs"], outputs_path)
    _policy_keys(
        outputs_cfg,
        outputs_path,
        required=set(GEOIP_ENRICHMENT_OUTPUT_ROLES),
    )
    output_fields = {
        role: _policy_string(outputs_cfg[role], f"{outputs_path}.{role}")
        for role in GEOIP_ENRICHMENT_OUTPUT_ROLES
    }
    duplicate_fields = sorted({
        field_name
        for field_name in output_fields.values()
        if tuple(output_fields.values()).count(field_name) > 1
    })
    if duplicate_fields:
        raise ValueError(
            f"{outputs_path}: output field names must be distinct; duplicate(s): "
            + ", ".join(duplicate_fields)
        )
    return GeoIPEnrichmentPolicy(output_fields=output_fields)


def _parse_windows_authentication_canonicalisation_policy(
    raw: Any,
    path: str,
) -> WindowsAuthenticationCanonicalisationPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "output_merge", "selector", "placeholders", "fields", "client_address",
            "classifications", "null_output_fields",
        },
    )
    output_merge = _policy_enum(
        cfg["output_merge"],
        f"{path}.output_merge",
        {"prefer_extracted", "preserve_existing"},
    )

    selector_path = f"{path}.selector"
    selector = _policy_mapping(cfg["selector"], selector_path)
    _policy_keys(
        selector,
        selector_path,
        required={"parser_field", "parser_prefixes", "xml_field"},
    )
    parser_field = _policy_string(
        selector["parser_field"], f"{selector_path}.parser_field"
    )
    parser_prefixes = _policy_string_list(
        selector["parser_prefixes"], f"{selector_path}.parser_prefixes", lower=True
    )
    xml_field = _policy_string(selector["xml_field"], f"{selector_path}.xml_field")
    placeholders = frozenset(
        _policy_string_list(cfg["placeholders"], f"{path}.placeholders", lower=True)
    )

    fields_raw = cfg["fields"]
    if not isinstance(fields_raw, list) or not fields_raw:
        raise ValueError(f"{path}.fields: expected a non-empty list")
    fields: List[WindowsEventFieldPolicy] = []
    field_ids: Set[str] = set()
    field_outputs: Set[str] = set()
    system_sources: Dict[str, str] = {}
    alias_owners: Dict[str, str] = {}
    for index, raw_field in enumerate(fields_raw):
        field_path = f"{path}.fields[{index}]"
        field_cfg = _policy_mapping(raw_field, field_path)
        _policy_keys(
            field_cfg,
            field_path,
            required={"id", "output_field", "event_data_aliases", "system_source"},
        )
        field_id = _policy_signal_name(field_cfg["id"], f"{field_path}.id")
        output_field = _policy_string(
            field_cfg["output_field"], f"{field_path}.output_field"
        )
        if field_id in field_ids:
            raise ValueError(f"{field_path}.id: duplicate field id {field_id!r}")
        if output_field in field_outputs:
            raise ValueError(
                f"{field_path}.output_field: duplicate output field {output_field!r}"
            )
        field_ids.add(field_id)
        field_outputs.add(output_field)
        system_source = _policy_enum(
            field_cfg["system_source"],
            f"{field_path}.system_source",
            {"none", "provider", "channel", "event_id"},
        )
        if system_source != "none":
            previous = system_sources.get(system_source)
            if previous is not None:
                raise ValueError(
                    f"{field_path}.system_source: {system_source!r} is already "
                    f"assigned to field id {previous!r}"
                )
            system_sources[system_source] = field_id
        aliases = tuple(
            _normalise_windows_event_field_name(alias)
            for alias in _policy_string_list(
                field_cfg["event_data_aliases"],
                f"{field_path}.event_data_aliases",
            )
        )
        if len(set(aliases)) != len(aliases):
            raise ValueError(
                f"{field_path}.event_data_aliases: aliases collide after normalisation"
            )
        for alias in aliases:
            previous_owner = alias_owners.get(alias)
            if previous_owner is not None:
                raise ValueError(
                    f"{field_path}.event_data_aliases: normalised alias {alias!r} "
                    f"is already assigned to field id {previous_owner!r}"
                )
            alias_owners[alias] = field_id
        fields.append(
            WindowsEventFieldPolicy(
                field_id=field_id,
                output_field=output_field,
                event_data_aliases=aliases,
                system_source=system_source,
            )
        )

    client_path = f"{path}.client_address"
    client = _policy_mapping(cfg["client_address"], client_path)
    _policy_keys(
        client,
        client_path,
        required={"source_field_ids", "output_field", "source_ip_output_field"},
    )
    client_source_ids = _policy_string_list(
        client["source_field_ids"], f"{client_path}.source_field_ids"
    )
    unknown_client_ids = sorted(set(client_source_ids) - field_ids)
    if unknown_client_ids:
        raise ValueError(
            f"{client_path}.source_field_ids: unknown field id(s): "
            + ", ".join(unknown_client_ids)
        )

    classifications_path = f"{path}.classifications"
    classifications = _policy_mapping(cfg["classifications"], classifications_path)
    _policy_keys(
        classifications,
        classifications_path,
        required={
            "event_identifier_field_id", "logon_type_field_id",
            "outcome_output_field", "outcomes", "direction_output_field",
            "remote_direction_value", "remote_direction_condition",
            "protocol_output_field", "protocol_branch_mode", "protocols",
        },
    )
    event_identifier_field_id = _policy_string(
        classifications["event_identifier_field_id"],
        f"{classifications_path}.event_identifier_field_id",
    )
    logon_type_field_id = _policy_string(
        classifications["logon_type_field_id"],
        f"{classifications_path}.logon_type_field_id",
    )
    for key_name, field_id in (
        ("event_identifier_field_id", event_identifier_field_id),
        ("logon_type_field_id", logon_type_field_id),
    ):
        if field_id not in field_ids:
            raise ValueError(
                f"{classifications_path}.{key_name}: unknown field id {field_id!r}"
            )

    outcomes_raw = classifications["outcomes"]
    if not isinstance(outcomes_raw, list) or not outcomes_raw:
        raise ValueError(f"{classifications_path}.outcomes: expected a non-empty list")
    outcomes: List[WindowsOutcomePolicy] = []
    assigned_event_ids: Set[str] = set()
    for index, raw_outcome in enumerate(outcomes_raw):
        outcome_path = f"{classifications_path}.outcomes[{index}]"
        outcome_cfg = _policy_mapping(raw_outcome, outcome_path)
        _policy_keys(outcome_cfg, outcome_path, required={"event_ids", "value"})
        event_ids = frozenset(
            _policy_string_list(outcome_cfg["event_ids"], f"{outcome_path}.event_ids")
        )
        overlap = sorted(assigned_event_ids & event_ids)
        if overlap:
            raise ValueError(
                f"{outcome_path}.event_ids: event id(s) are classified twice: "
                + ", ".join(overlap)
            )
        assigned_event_ids.update(event_ids)
        outcomes.append(
            WindowsOutcomePolicy(
                event_ids=event_ids,
                value=_policy_string(outcome_cfg["value"], f"{outcome_path}.value"),
            )
        )

    protocols_raw = classifications["protocols"]
    if not isinstance(protocols_raw, list) or not protocols_raw:
        raise ValueError(f"{classifications_path}.protocols: expected a non-empty list")
    protocols: List[WindowsProtocolPolicy] = []
    for index, raw_protocol in enumerate(protocols_raw):
        protocol_path = f"{classifications_path}.protocols[{index}]"
        protocol_cfg = _policy_mapping(raw_protocol, protocol_path)
        _policy_keys(
            protocol_cfg,
            protocol_path,
            required={
                "event_ids", "logon_types", "match",
                "require_client_address", "value",
            },
        )
        event_ids = frozenset(
            _policy_string_list_or_empty(
                protocol_cfg["event_ids"], f"{protocol_path}.event_ids"
            )
        )
        logon_types = frozenset(
            _policy_string_list_or_empty(
                protocol_cfg["logon_types"], f"{protocol_path}.logon_types"
            )
        )
        if not event_ids and not logon_types:
            raise ValueError(
                f"{protocol_path}: at least one event id or logon type is required"
            )
        protocols.append(
            WindowsProtocolPolicy(
                event_ids=event_ids,
                logon_types=logon_types,
                match=_policy_enum(
                    protocol_cfg["match"],
                    f"{protocol_path}.match",
                    {"any", "all"},
                ),
                require_client_address=_policy_bool(
                    protocol_cfg["require_client_address"],
                    f"{protocol_path}.require_client_address",
                ),
                value=_policy_string(protocol_cfg["value"], f"{protocol_path}.value"),
            )
        )

    result = WindowsAuthenticationCanonicalisationPolicy(
        output_merge=output_merge,
        parser_field=parser_field,
        parser_prefixes=parser_prefixes,
        xml_field=xml_field,
        placeholders=placeholders,
        fields=tuple(fields),
        client_source_field_ids=client_source_ids,
        client_output_field=_policy_string(
            client["output_field"], f"{client_path}.output_field"
        ),
        source_ip_output_field=_policy_string(
            client["source_ip_output_field"],
            f"{client_path}.source_ip_output_field",
        ),
        event_identifier_field_id=event_identifier_field_id,
        logon_type_field_id=logon_type_field_id,
        outcome_output_field=_policy_string(
            classifications["outcome_output_field"],
            f"{classifications_path}.outcome_output_field",
        ),
        outcomes=tuple(outcomes),
        direction_output_field=_policy_string(
            classifications["direction_output_field"],
            f"{classifications_path}.direction_output_field",
        ),
        remote_direction_value=_policy_string(
            classifications["remote_direction_value"],
            f"{classifications_path}.remote_direction_value",
        ),
        remote_direction_condition=_policy_enum(
            classifications["remote_direction_condition"],
            f"{classifications_path}.remote_direction_condition",
            {"client_address_present", "classified_protocol"},
        ),
        protocol_output_field=_policy_string(
            classifications["protocol_output_field"],
            f"{classifications_path}.protocol_output_field",
        ),
        protocol_branch_mode=_policy_enum(
            classifications["protocol_branch_mode"],
            f"{classifications_path}.protocol_branch_mode",
            {"first_match", "last_match"},
        ),
        protocols=tuple(protocols),
        null_output_fields=_policy_string_list(
            cfg["null_output_fields"], f"{path}.null_output_fields"
        ),
    )
    configured_outputs = [
        *(item.output_field for item in fields),
        result.client_output_field,
        result.source_ip_output_field,
        result.outcome_output_field,
        result.direction_output_field,
        result.protocol_output_field,
        *result.null_output_fields,
    ]
    duplicated_outputs = sorted({
        output for output in configured_outputs if configured_outputs.count(output) > 1
    })
    if duplicated_outputs:
        raise ValueError(
            f"{path}: configured output fields must be unique: "
            + ", ".join(duplicated_outputs)
        )
    return result


def _parse_ssh_authentication_canonicalisation_policy(
    raw: Any,
    path: str,
) -> SSHAuthenticationCanonicalisationPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "output_merge", "selector", "escaped_control_regex", "outputs",
            "values", "patterns",
        },
    )
    output_merge = _policy_enum(
        cfg["output_merge"],
        f"{path}.output_merge",
        {"prefer_extracted", "preserve_existing"},
    )
    selector_path = f"{path}.selector"
    selector = _policy_mapping(cfg["selector"], selector_path)
    _policy_keys(
        selector,
        selector_path,
        required={
            "parser_field", "parser_values", "message_field",
            "message_regex", "match",
        },
    )

    output_semantics = (
        "actor_user_auth", "actor_user_session", "auth_method", "source_ip",
        "destination_ip", "protocol", "direction", "outcome", "session_id",
        "logon_id",
    )
    outputs_path = f"{path}.outputs"
    outputs_cfg = _policy_mapping(cfg["outputs"], outputs_path)
    _policy_keys(outputs_cfg, outputs_path, required=output_semantics)
    outputs = {
        semantic: _policy_string(outputs_cfg[semantic], f"{outputs_path}.{semantic}")
        for semantic in output_semantics
    }
    if len(set(outputs.values())) != len(outputs):
        raise ValueError(f"{outputs_path}: output fields must be unique")

    value_semantics = (
        "protocol", "direction", "success_outcome", "failure_outcome",
    )
    values_path = f"{path}.values"
    values_cfg = _policy_mapping(cfg["values"], values_path)
    _policy_keys(values_cfg, values_path, required=value_semantics)
    values = {
        semantic: _policy_string(values_cfg[semantic], f"{values_path}.{semantic}")
        for semantic in value_semantics
    }

    patterns_raw = cfg["patterns"]
    if not isinstance(patterns_raw, list) or not patterns_raw:
        raise ValueError(f"{path}.patterns: expected a non-empty list")
    allowed_groups = {"actor_user_auth", "actor_user_session", "auth_method", "source_ip"}
    patterns: List[SSHAuthenticationPatternPolicy] = []
    pattern_ids: Set[str] = set()
    for index, raw_pattern in enumerate(patterns_raw):
        pattern_path = f"{path}.patterns[{index}]"
        pattern_cfg = _policy_mapping(raw_pattern, pattern_path)
        _policy_keys(
            pattern_cfg,
            pattern_path,
            required={
                "id", "regex", "outcome", "groups",
                "require_message_selector",
            },
        )
        pattern_id = _policy_signal_name(pattern_cfg["id"], f"{pattern_path}.id")
        if pattern_id in pattern_ids:
            raise ValueError(f"{pattern_path}.id: duplicate pattern id {pattern_id!r}")
        pattern_ids.add(pattern_id)
        compiled = _compile_canonicalisation_regex(
            pattern_cfg["regex"], f"{pattern_path}.regex"
        )
        groups_path = f"{pattern_path}.groups"
        groups_cfg = _policy_mapping(pattern_cfg["groups"], groups_path)
        if not groups_cfg:
            raise ValueError(f"{groups_path}: expected a non-empty mapping")
        unknown_groups = sorted(set(groups_cfg) - allowed_groups)
        if unknown_groups:
            raise ValueError(
                f"{groups_path}: unknown semantic group(s): " + ", ".join(unknown_groups)
            )
        groups: Dict[str, int] = {}
        for semantic, raw_group in groups_cfg.items():
            group = _policy_positive_int(raw_group, f"{groups_path}.{semantic}")
            if group > compiled.groups:
                raise ValueError(
                    f"{groups_path}.{semantic}: capture group {group} does not exist "
                    f"in a pattern with {compiled.groups} group(s)"
                )
            groups[semantic] = group
        patterns.append(
            SSHAuthenticationPatternPolicy(
                pattern_id=pattern_id,
                regex=compiled,
                outcome=_policy_enum(
                    pattern_cfg["outcome"],
                    f"{pattern_path}.outcome",
                    {"success", "failure"},
                ),
                groups=groups,
                require_message_selector=_policy_bool(
                    pattern_cfg["require_message_selector"],
                    f"{pattern_path}.require_message_selector",
                ),
            )
        )

    return SSHAuthenticationCanonicalisationPolicy(
        output_merge=output_merge,
        parser_field=_policy_string(
            selector["parser_field"], f"{selector_path}.parser_field"
        ),
        parser_values=frozenset(
            _policy_string_list(
                selector["parser_values"], f"{selector_path}.parser_values", lower=True
            )
        ),
        message_field=_policy_string(
            selector["message_field"], f"{selector_path}.message_field"
        ),
        message_regex=_compile_canonicalisation_regex(
            selector["message_regex"], f"{selector_path}.message_regex"
        ),
        selector_match=_policy_enum(
            selector["match"], f"{selector_path}.match", {"any", "all"}
        ),
        escaped_control_regex=_compile_canonicalisation_regex(
            cfg["escaped_control_regex"], f"{path}.escaped_control_regex"
        ),
        outputs=outputs,
        values=values,
        patterns=tuple(patterns),
    )


def _parse_pivot_destination_canonicalisation_policy(
    raw: Any,
    path: str,
) -> PivotDestinationCanonicalisationPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(cfg, path, required={"outputs", "sources", "precedence", "auth_like_any_fields"})
    roles = ("ip", "fqdn", "hostname")
    outputs_path = f"{path}.outputs"
    outputs_cfg = _policy_mapping(cfg["outputs"], outputs_path)
    _policy_keys(outputs_cfg, outputs_path, required={"identity", *roles})
    outputs = {
        role: _policy_string(outputs_cfg[role], f"{outputs_path}.{role}")
        for role in ("identity", *roles)
    }
    if len(set(outputs.values())) != len(outputs):
        raise ValueError(f"{outputs_path}: output fields must be unique")

    sources_path = f"{path}.sources"
    sources_cfg = _policy_mapping(cfg["sources"], sources_path)
    _policy_keys(sources_cfg, sources_path, required=roles)
    sources = {
        role: _policy_string_list(sources_cfg[role], f"{sources_path}.{role}")
        for role in roles
    }
    precedence_raw = cfg["precedence"]
    if not isinstance(precedence_raw, list) or not precedence_raw:
        raise ValueError(f"{path}.precedence: expected a non-empty list")
    precedence: List[PivotDestinationPrecedencePolicy] = []
    precedence_roles: List[str] = []
    for index, raw_item in enumerate(precedence_raw):
        item_path = f"{path}.precedence[{index}]"
        item = _policy_mapping(raw_item, item_path)
        _policy_keys(item, item_path, required={"role", "prefix"})
        role = _policy_enum(item["role"], f"{item_path}.role", roles)
        if role in precedence_roles:
            raise ValueError(f"{item_path}.role: duplicate role {role!r}")
        precedence_roles.append(role)
        precedence.append(
            PivotDestinationPrecedencePolicy(
                role=role,
                prefix=_policy_string(item["prefix"], f"{item_path}.prefix"),
            )
        )
    if set(precedence_roles) != set(roles):
        raise ValueError(f"{path}.precedence: must contain each destination role exactly once")
    return PivotDestinationCanonicalisationPolicy(
        outputs=outputs,
        sources=sources,
        precedence=tuple(precedence),
        auth_like_any_fields=_policy_string_list(
            cfg["auth_like_any_fields"], f"{path}.auth_like_any_fields"
        ),
    )


def _parse_ip_recovery_canonicalisation_policy(
    raw: Any,
    path: str,
) -> IPRecoveryCanonicalisationPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={"output_field", "parser_field", "windows_parser_prefixes", "context_regex", "sources"},
    )
    sources_raw = cfg["sources"]
    if not isinstance(sources_raw, list) or not sources_raw:
        raise ValueError(f"{path}.sources: expected a non-empty list")
    allowed_kinds = {"windows_fields", "windows_xml", "windows_strings", "text_fields"}
    sources: List[IPRecoverySourcePolicy] = []
    seen_kinds: Set[str] = set()
    for index, raw_source in enumerate(sources_raw):
        source_path = f"{path}.sources[{index}]"
        source_cfg = _policy_mapping(raw_source, source_path)
        kind = _policy_enum(source_cfg.get("kind"), f"{source_path}.kind", allowed_kinds)
        if kind in seen_kinds and kind != "text_fields":
            raise ValueError(f"{source_path}.kind: duplicate recovery source {kind!r}")
        seen_kinds.add(kind)
        if kind == "text_fields":
            _policy_keys(source_cfg, source_path, required={"kind", "fields", "require_context"})
            require_context = _policy_bool(
                source_cfg["require_context"], f"{source_path}.require_context"
            )
        else:
            _policy_keys(source_cfg, source_path, required={"kind", "fields"})
            require_context = False
        sources.append(
            IPRecoverySourcePolicy(
                kind=kind,
                fields=_policy_string_list(source_cfg["fields"], f"{source_path}.fields"),
                require_context=require_context,
            )
        )
    return IPRecoveryCanonicalisationPolicy(
        output_field=_policy_string(cfg["output_field"], f"{path}.output_field"),
        parser_field=_policy_string(cfg["parser_field"], f"{path}.parser_field"),
        windows_parser_prefixes=_policy_string_list(
            cfg["windows_parser_prefixes"], f"{path}.windows_parser_prefixes", lower=True
        ),
        context_regex=_compile_canonicalisation_regex(
            cfg["context_regex"], f"{path}.context_regex"
        ),
        sources=tuple(sources),
    )


def _parse_canonicalisation_policy(raw: Any, path: str) -> CanonicalisationPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "excluded_networks",
            "windows_authentication", "ssh_authentication",
            "pivot_destination", "ip_recovery",
        },
    )
    excluded_networks: List[Any] = []
    for index, network_text in enumerate(
        _policy_string_list_or_empty(
            cfg["excluded_networks"], f"{path}.excluded_networks"
        )
    ):
        try:
            network = ipaddress.ip_network(network_text, strict=False)
        except ValueError as exc:
            raise ValueError(
                f"{path}.excluded_networks[{index}]: invalid IP network: {exc}"
            ) from exc
        if network in excluded_networks:
            raise ValueError(
                f"{path}.excluded_networks[{index}]: duplicate network {network}"
            )
        excluded_networks.append(network)
    result = CanonicalisationPolicy(
        excluded_networks=tuple(excluded_networks),
        windows_authentication=_parse_windows_authentication_canonicalisation_policy(
            cfg["windows_authentication"], f"{path}.windows_authentication"
        ),
        ssh_authentication=_parse_ssh_authentication_canonicalisation_policy(
            cfg["ssh_authentication"], f"{path}.ssh_authentication"
        ),
        pivot_destination=_parse_pivot_destination_canonicalisation_policy(
            cfg["pivot_destination"], f"{path}.pivot_destination"
        ),
        ip_recovery=_parse_ip_recovery_canonicalisation_policy(
            cfg["ip_recovery"], f"{path}.ip_recovery"
        ),
    )
    return result


def _policy_percentage_int(value: Any, path: str) -> int:
    if type(value) is not int or not 0 <= value <= 100:
        raise ValueError(f"{path}: expected an integer from 0 to 100")
    return int(value)


def _policy_enum(value: Any, path: str, allowed: Iterable[str]) -> str:
    result = _policy_string(value, path)
    allowed_set = set(allowed)
    if result not in allowed_set:
        raise ValueError(f"{path}: expected one of {', '.join(sorted(allowed_set))}")
    return result


def _parse_rule_signal_merge_policy(
    raw: Any,
    path: str = "rule_signal_merge",
) -> RuleSignalMergePolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg, path, required={"atomic_rules", "temporal_rules"}
    )
    allowed = {"maximum", "sum"}
    return RuleSignalMergePolicy(
        atomic_rules=_policy_enum(
            cfg["atomic_rules"], f"{path}.atomic_rules", allowed
        ),
        temporal_rules=_policy_enum(
            cfg["temporal_rules"], f"{path}.temporal_rules", allowed
        ),
    )


def _policy_confidence(value: Any, path: str) -> str:
    return _policy_enum(value, path, _DETECTOR_POLICY_CONFIDENCE)


def _parse_policy_evidence(
    raw: Any,
    path: str,
    *,
    allowed_resolvers: Iterable[str],
) -> Tuple[PolicyEvidenceValue, ...]:
    cfg = _policy_mapping(raw, path)
    if not cfg:
        raise ValueError(f"{path}: expected a non-empty mapping")
    allowed = set(allowed_resolvers)
    parsed: List[PolicyEvidenceValue] = []
    for evidence_name, raw_value in cfg.items():
        name = _policy_string(evidence_name, f"{path} key")
        value_path = f"{path}.{name}"
        value_cfg = _policy_mapping(raw_value, value_path)
        resolver = _policy_enum(
            value_cfg.get("resolver"),
            f"{value_path}.resolver",
            allowed,
        )
        if resolver in {"row_field", "target_field"}:
            _policy_keys(
                value_cfg,
                value_path,
                required={"resolver", "field"},
                optional={"max_chars"},
            )
            fields = (_policy_string(value_cfg["field"], f"{value_path}.field"),)
        elif resolver in {"first_nonempty", "best_effort_file_path"}:
            _policy_keys(
                value_cfg,
                value_path,
                required={"resolver", "fields"},
                optional={"max_chars"},
            )
            fields = _policy_string_list(value_cfg["fields"], f"{value_path}.fields")
        else:
            _policy_keys(value_cfg, value_path, required={"resolver"})
            fields = ()
        max_chars = (
            _policy_positive_int(value_cfg["max_chars"], f"{value_path}.max_chars")
            if "max_chars" in value_cfg
            else None
        )
        parsed.append(
            PolicyEvidenceValue(
                name=name,
                resolver=resolver,
                fields=fields,
                max_chars=max_chars,
            )
        )
    return tuple(parsed)


def _policy_evidence_fields(evidence: Iterable[PolicyEvidenceValue]) -> Set[str]:
    return {
        field
        for evidence_value in evidence
        for field in evidence_value.fields
        if field
    }


def _parse_policy_emission(
    raw: Any,
    path: str,
    *,
    include_explanation: bool,
) -> DetectorEmissionPolicy:
    cfg = _policy_mapping(raw, path)
    required = {"name", "value", "rule_id"}
    if include_explanation:
        required.update({"description", "confidence"})
    _policy_keys(cfg, path, required=required)
    return DetectorEmissionPolicy(
        name=_policy_signal_name(cfg["name"], f"{path}.name"),
        value=_policy_positive_number(cfg["value"], f"{path}.value"),
        rule_id=_policy_string(cfg["rule_id"], f"{path}.rule_id"),
        description=(
            _policy_string(cfg["description"], f"{path}.description")
            if include_explanation
            else ""
        ),
        confidence=(
            _policy_confidence(cfg["confidence"], f"{path}.confidence")
            if include_explanation
            else "medium"
        ),
    )


def _parse_clamav_classifier_policy(
    raw: Any,
    path: str,
) -> ClamAVClassifierPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "stage", "executor", "enabled", "evidence_type",
            "default_category", "category_tokens", "family_overrides",
            "generic", "categories",
        },
    )
    _policy_enum(cfg["stage"], f"{path}.stage", {"atomic"})
    _policy_enum(cfg["executor"], f"{path}.executor", {"clamav_classifier"})
    enabled = _policy_bool(cfg["enabled"], f"{path}.enabled")
    evidence_type = _policy_enum(
        cfg["evidence_type"],
        f"{path}.evidence_type",
        {"direct"},
    )

    categories_path = f"{path}.categories"
    categories_cfg = _policy_mapping(cfg["categories"], categories_path)
    if not categories_cfg:
        raise ValueError(f"{categories_path}: expected a non-empty mapping")
    category_order: List[str] = []
    for raw_category in categories_cfg:
        category = _policy_signal_name(raw_category, f"{categories_path} key")
        if category in category_order:
            raise ValueError(
                f"{categories_path}.{category}: duplicate configured category"
            )
        category_order.append(category)
    category_universe = frozenset(category_order)
    default_category = _policy_enum(
        cfg["default_category"],
        f"{path}.default_category",
        category_universe,
    )

    category_tokens_path = f"{path}.category_tokens"
    category_tokens_cfg = _policy_mapping(cfg["category_tokens"], category_tokens_path)
    if not category_tokens_cfg:
        raise ValueError(f"{category_tokens_path}: expected a non-empty mapping")
    category_tokens: Dict[str, str] = {}
    for raw_token, raw_category in category_tokens_cfg.items():
        token = _policy_string(raw_token, f"{category_tokens_path} key")
        if token != token.lower() or not re.fullmatch(r"[a-z][a-z0-9_-]*", token):
            raise ValueError(
                f"{category_tokens_path}.{token}: category tokens must be lowercase identifiers"
            )
        if token in category_tokens:
            raise ValueError(
                f"{category_tokens_path}.{token}: duplicate normalised category token"
            )
        category_tokens[token] = _policy_enum(
            raw_category,
            f"{category_tokens_path}.{token}",
            category_universe,
        )

    overrides_path = f"{path}.family_overrides"
    raw_overrides = cfg["family_overrides"]
    if not isinstance(raw_overrides, list):
        raise ValueError(f"{overrides_path}: expected a list")
    family_overrides: List[Tuple[str, str]] = []
    seen_contains: Set[str] = set()
    for index, raw_override in enumerate(raw_overrides):
        override_path = f"{overrides_path}[{index}]"
        override_cfg = _policy_mapping(raw_override, override_path)
        _policy_keys(override_cfg, override_path, required={"contains", "category"})
        contains = _policy_string(
            override_cfg["contains"],
            f"{override_path}.contains",
        )
        if contains != contains.lower():
            raise ValueError(f"{override_path}.contains: expected a lowercase substring")
        if contains in seen_contains:
            raise ValueError(
                f"{override_path}.contains: duplicate value {contains!r}"
            )
        seen_contains.add(contains)
        family_overrides.append(
            (
                contains,
                _policy_enum(
                    override_cfg["category"],
                    f"{override_path}.category",
                    category_universe,
                ),
            )
        )

    allowed_evidence = {
        "filename",
        "av_signature",
        "platform",
        "category",
        "family",
        "forensic_category",
    }

    def parse_evidence(raw_evidence: Any, evidence_path: str) -> Tuple[str, ...]:
        evidence = _policy_string_list(raw_evidence, evidence_path)
        unsupported = sorted(set(evidence) - allowed_evidence)
        if unsupported:
            raise ValueError(
                f"{evidence_path}: unsupported value(s): {', '.join(unsupported)}"
            )
        return evidence

    generic_path = f"{path}.generic"
    generic_cfg = _policy_mapping(cfg["generic"], generic_path)
    _policy_keys(
        generic_cfg,
        generic_path,
        required={"emission", "unclassified_description", "evidence"},
    )
    generic_emission = _parse_policy_emission(
        generic_cfg["emission"],
        f"{generic_path}.emission",
        include_explanation=True,
    )
    template_probe = generic_emission.description.replace(
        "{forensic_category}",
        default_category,
    )
    if "{" in template_probe or "}" in template_probe:
        raise ValueError(
            f"{generic_path}.emission.description: only the "
            "{forensic_category} placeholder is supported"
        )
    generic_unclassified_description = _policy_string(
        generic_cfg["unclassified_description"],
        f"{generic_path}.unclassified_description",
    )
    generic_evidence = parse_evidence(
        generic_cfg["evidence"],
        f"{generic_path}.evidence",
    )

    categories: Dict[str, ClamAVCategoryPolicy] = {}
    for category in category_order:
        category_path = f"{categories_path}.{category}"
        category_cfg = _policy_mapping(categories_cfg[category], category_path)
        _policy_keys(
            category_cfg,
            category_path,
            required={"suppress_generic", "emission", "evidence"},
        )
        categories[category] = ClamAVCategoryPolicy(
            category=category,
            suppress_generic=_policy_bool(
                category_cfg["suppress_generic"],
                f"{category_path}.suppress_generic",
            ),
            emission=_parse_policy_emission(
                category_cfg["emission"],
                f"{category_path}.emission",
                include_explanation=True,
            ),
            evidence=parse_evidence(
                category_cfg["evidence"],
                f"{category_path}.evidence",
            ),
        )

    policy_digest = hashlib.sha256(
        json.dumps(
            cfg,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
        ).encode("utf-8")
    ).hexdigest()
    return ClamAVClassifierPolicy(
        enabled=enabled,
        default_category=default_category,
        category_tokens=category_tokens,
        family_overrides=tuple(family_overrides),
        generic_emission=generic_emission,
        generic_unclassified_description=generic_unclassified_description,
        generic_evidence=generic_evidence,
        categories=categories,
        evidence_type=evidence_type,
        policy_digest=policy_digest,
    )


def _parse_yara_score_confidence(
    raw: Any,
    path: str,
) -> YaraScoreConfidencePolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(cfg, path, required={"minimum_score", "confidence"})
    return YaraScoreConfidencePolicy(
        minimum_score=_policy_percentage_int(
            cfg["minimum_score"],
            f"{path}.minimum_score",
        ),
        confidence=_policy_confidence(
            cfg["confidence"],
            f"{path}.confidence",
        ),
    )


def _parse_yara_evidence(
    raw: Any,
    path: str,
    allowed: Iterable[str],
) -> Tuple[str, ...]:
    evidence = _policy_string_list(raw, path)
    unsupported = sorted(set(evidence) - set(allowed))
    if unsupported:
        raise ValueError(
            f"{path}: unsupported value(s): {', '.join(unsupported)}"
        )
    return evidence


def _parse_yara_classifier_policy(
    raw: Any,
    path: str,
) -> YaraClassifierPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "stage", "executor", "enabled", "evidence_type",
            "metadata", "classification", "strength", "categories",
            "referenced_file_gate",
        },
    )
    _policy_enum(cfg["stage"], f"{path}.stage", {"atomic"})
    _policy_enum(cfg["executor"], f"{path}.executor", {"yara_classifier"})
    enabled = _policy_bool(cfg["enabled"], f"{path}.enabled")
    evidence_type = _policy_enum(
        cfg["evidence_type"],
        f"{path}.evidence_type",
        {"direct"},
    )

    categories_path = f"{path}.categories"
    categories_cfg = _policy_mapping(cfg["categories"], categories_path)
    if not categories_cfg:
        raise ValueError(f"{categories_path}: expected a non-empty mapping")
    category_order: List[str] = []
    for raw_category in categories_cfg:
        category = _policy_signal_name(raw_category, f"{categories_path} key")
        if category in category_order:
            raise ValueError(
                f"{categories_path}.{category}: duplicate configured category"
            )
        category_order.append(category)
    category_universe = frozenset(category_order)

    metadata_path = f"{path}.metadata"
    metadata_cfg = _policy_mapping(cfg["metadata"], metadata_path)
    _policy_keys(
        metadata_cfg,
        metadata_path,
        required={
            "path", "on_missing", "on_parse_error", "defaults",
            "unindexed_rule",
        },
    )
    configured_metadata_path = _policy_string(
        metadata_cfg["path"],
        f"{metadata_path}.path",
    )
    on_missing = _policy_enum(
        metadata_cfg["on_missing"],
        f"{metadata_path}.on_missing",
        {"fail", "name_only"},
    )
    on_parse_error = _policy_enum(
        metadata_cfg["on_parse_error"],
        f"{metadata_path}.on_parse_error",
        {"fail", "name_only"},
    )
    defaults_path = f"{metadata_path}.defaults"
    defaults_cfg = _policy_mapping(metadata_cfg["defaults"], defaults_path)
    _policy_keys(defaults_cfg, defaults_path, required={"score", "quality"})
    default_score = _policy_percentage_int(
        defaults_cfg["score"],
        f"{defaults_path}.score",
    )
    default_quality = _policy_percentage_int(
        defaults_cfg["quality"],
        f"{defaults_path}.quality",
    )
    unindexed_path = f"{metadata_path}.unindexed_rule"
    unindexed_cfg = _policy_mapping(
        metadata_cfg["unindexed_rule"],
        unindexed_path,
    )
    _policy_keys(
        unindexed_cfg,
        unindexed_path,
        required={"classification", "score", "quality"},
    )
    unindexed_rule = _policy_enum(
        unindexed_cfg["classification"],
        f"{unindexed_path}.classification",
        {"default_category", "name_only"},
    )
    unindexed_score = _policy_percentage_int(
        unindexed_cfg["score"],
        f"{unindexed_path}.score",
    )
    unindexed_quality = _policy_percentage_int(
        unindexed_cfg["quality"],
        f"{unindexed_path}.quality",
    )

    classification_path = f"{path}.classification"
    classification_cfg = _policy_mapping(
        cfg["classification"],
        classification_path,
    )
    _policy_keys(
        classification_cfg,
        classification_path,
        required={"mode", "default_category", "ordered_rules"},
    )
    _policy_enum(
        classification_cfg["mode"],
        f"{classification_path}.mode",
        {"first_match"},
    )
    default_category = _policy_enum(
        classification_cfg["default_category"],
        f"{classification_path}.default_category",
        category_universe,
    )
    raw_rules = classification_cfg["ordered_rules"]
    rules_path = f"{classification_path}.ordered_rules"
    if not isinstance(raw_rules, list) or not raw_rules:
        raise ValueError(f"{rules_path}: expected a non-empty list")
    classification_rules: List[YaraClassificationRulePolicy] = []
    seen_rule_ids: Set[str] = set()
    seen_rule_signatures: Set[Tuple[Any, ...]] = set()
    allowed_fields = {"rule_name", "tags", "category", "tc_detection_type"}
    for rule_index, raw_rule in enumerate(raw_rules):
        rule_path = f"{rules_path}[{rule_index}]"
        rule_cfg = _policy_mapping(raw_rule, rule_path)
        _policy_keys(rule_cfg, rule_path, required={"id", "category", "all"})
        rule_id = _policy_string(rule_cfg["id"], f"{rule_path}.id")
        if rule_id in seen_rule_ids:
            raise ValueError(f"{rule_path}.id: duplicate value {rule_id!r}")
        seen_rule_ids.add(rule_id)
        category = _policy_enum(
            rule_cfg["category"],
            f"{rule_path}.category",
            category_universe,
        )
        raw_conditions = rule_cfg["all"]
        conditions_path = f"{rule_path}.all"
        if not isinstance(raw_conditions, list) or not raw_conditions:
            raise ValueError(f"{conditions_path}: expected a non-empty list")
        conditions: List[YaraClassificationConditionPolicy] = []
        seen_conditions: Set[Tuple[Any, ...]] = set()
        for condition_index, raw_condition in enumerate(raw_conditions):
            condition_path = f"{conditions_path}[{condition_index}]"
            condition_cfg = _policy_mapping(raw_condition, condition_path)
            field_name = _policy_enum(
                condition_cfg.get("field"),
                f"{condition_path}.field",
                allowed_fields,
            )
            op = _policy_enum(
                condition_cfg.get("op"),
                f"{condition_path}.op",
                {"equals_any", "contains_any", "contains_none", "regex"},
            )
            if op == "regex":
                _policy_keys(
                    condition_cfg,
                    condition_path,
                    required={"field", "op", "pattern"},
                )
                pattern = _policy_string(
                    condition_cfg["pattern"],
                    f"{condition_path}.pattern",
                )
                try:
                    re.compile(pattern, flags=re.IGNORECASE)
                except re.error as exc:
                    raise ValueError(
                        f"{condition_path}.pattern: invalid regular expression: {exc}"
                    ) from exc
                values: Tuple[str, ...] = ()
            else:
                _policy_keys(
                    condition_cfg,
                    condition_path,
                    required={"field", "op", "values"},
                )
                raw_values = _policy_string_list(
                    condition_cfg["values"],
                    f"{condition_path}.values",
                )
                values_list: List[str] = []
                for value_index, raw_value in enumerate(raw_values):
                    normalised = raw_value.casefold()
                    if normalised in values_list:
                        raise ValueError(
                            f"{condition_path}.values[{value_index}]: duplicate "
                            f"normalised value {normalised!r}"
                        )
                    values_list.append(normalised)
                values = tuple(values_list)
                pattern = ""
            signature = (field_name, op, values, pattern)
            if signature in seen_conditions:
                raise ValueError(
                    f"{condition_path}: duplicate classification condition"
                )
            seen_conditions.add(signature)
            conditions.append(
                YaraClassificationConditionPolicy(
                    field=field_name,
                    op=op,
                    values=values,
                    pattern=pattern,
                )
            )
        rule_signature = (
            category,
            tuple(
                (condition.field, condition.op, condition.values, condition.pattern)
                for condition in conditions
            ),
        )
        if rule_signature in seen_rule_signatures:
            raise ValueError(f"{rule_path}: duplicate classification rule")
        seen_rule_signatures.add(rule_signature)
        classification_rules.append(
            YaraClassificationRulePolicy(
                rule_id=rule_id,
                category=category,
                conditions=tuple(conditions),
            )
        )

    strength_path = f"{path}.strength"
    strength_cfg = _policy_mapping(cfg["strength"], strength_path)
    _policy_keys(
        strength_cfg,
        strength_path,
        required={
            "rule_count", "saturation_count", "score_multiplier",
            "unnamed_matches", "emission", "score_confidence", "evidence",
            "max_rule_names",
        },
    )
    rule_count = _policy_enum(
        strength_cfg["rule_count"],
        f"{strength_path}.rule_count",
        {"distinct_rule_names"},
    )
    saturation_count = _policy_positive_int(
        strength_cfg["saturation_count"],
        f"{strength_path}.saturation_count",
    )
    multiplier_path = f"{strength_path}.score_multiplier"
    multiplier_cfg = _policy_mapping(
        strength_cfg["score_multiplier"],
        multiplier_path,
    )
    _policy_keys(
        multiplier_cfg,
        multiplier_path,
        required={"aggregate", "divisor", "floor", "ceiling"},
    )
    score_reducer = _policy_enum(
        multiplier_cfg["aggregate"],
        f"{multiplier_path}.aggregate",
        {"maximum"},
    )
    score_divisor = _policy_positive_number(
        multiplier_cfg["divisor"],
        f"{multiplier_path}.divisor",
    )
    minimum_multiplier = _policy_nonnegative_number(
        multiplier_cfg["floor"],
        f"{multiplier_path}.floor",
    )
    maximum_multiplier = _policy_nonnegative_number(
        multiplier_cfg["ceiling"],
        f"{multiplier_path}.ceiling",
    )
    if minimum_multiplier > maximum_multiplier:
        raise ValueError(
            f"{multiplier_path}: floor must be less than or equal to ceiling"
        )
    unnamed_path = f"{strength_path}.unnamed_matches"
    unnamed_cfg = _policy_mapping(
        strength_cfg["unnamed_matches"],
        unnamed_path,
    )
    _policy_keys(unnamed_cfg, unnamed_path, required={"mode", "multiplier"})
    unnamed_mode = _policy_enum(
        unnamed_cfg["mode"],
        f"{unnamed_path}.mode",
        {"raw_count"},
    )
    unnamed_multiplier = _policy_nonnegative_number(
        unnamed_cfg["multiplier"],
        f"{unnamed_path}.multiplier",
    )
    strength_emission = _parse_policy_emission(
        strength_cfg["emission"],
        f"{strength_path}.emission",
        include_explanation=True,
    )
    strength_policy = YaraStrengthPolicy(
        rule_count=rule_count,
        saturation_count=saturation_count,
        score_reducer=score_reducer,
        score_divisor=score_divisor,
        minimum_multiplier=minimum_multiplier,
        maximum_multiplier=maximum_multiplier,
        unnamed_mode=unnamed_mode,
        unnamed_multiplier=unnamed_multiplier,
        emission=strength_emission,
        score_confidence=_parse_yara_score_confidence(
            strength_cfg["score_confidence"],
            f"{strength_path}.score_confidence",
        ),
        evidence=_parse_yara_evidence(
            strength_cfg["evidence"],
            f"{strength_path}.evidence",
            {
                "yara_match_count", "contributing_rule_count", "strength",
                "best_score", "score_multiplier", "rule_names",
            },
        ),
        max_rule_names=_policy_positive_int(
            strength_cfg["max_rule_names"],
            f"{strength_path}.max_rule_names",
        ),
    )

    categories: Dict[str, YaraCategoryPolicy] = {}
    for category in category_order:
        category_path = f"{categories_path}.{category}"
        category_cfg = _policy_mapping(categories_cfg[category], category_path)
        _policy_keys(
            category_cfg,
            category_path,
            required={
                "contributes_to_strength", "emission", "score_confidence",
                "evidence", "max_rule_names",
            },
        )
        categories[category] = YaraCategoryPolicy(
            category=category,
            contributes_to_strength=_policy_bool(
                category_cfg["contributes_to_strength"],
                f"{category_path}.contributes_to_strength",
            ),
            emission=_parse_policy_emission(
                category_cfg["emission"],
                f"{category_path}.emission",
                include_explanation=True,
            ),
            score_confidence=_parse_yara_score_confidence(
                category_cfg["score_confidence"],
                f"{category_path}.score_confidence",
            ),
            evidence=_parse_yara_evidence(
                category_cfg["evidence"],
                f"{category_path}.evidence",
                {"category", "rule_count", "rule_names", "best_score", "best_quality"},
            ),
            max_rule_names=_policy_positive_int(
                category_cfg["max_rule_names"],
                f"{category_path}.max_rule_names",
            ),
        )
    if not any(
        category.contributes_to_strength for category in categories.values()
    ):
        raise ValueError(
            f"{categories_path}: at least one category must contribute to strength"
        )

    gate_path = f"{path}.referenced_file_gate"
    gate_cfg = _policy_mapping(cfg["referenced_file_gate"], gate_path)
    _policy_keys(
        gate_cfg,
        gate_path,
        required={
            "minimum_score", "minimum_quality", "categories", "allow_unnamed",
        },
    )
    gate_categories = frozenset(
        _policy_string_list(
            gate_cfg["categories"],
            f"{gate_path}.categories",
            lower=True,
        )
    )
    unsupported_gate_categories = sorted(
        gate_categories - category_universe
    )
    if unsupported_gate_categories:
        raise ValueError(
            f"{gate_path}.categories: unsupported value(s): "
            + ", ".join(unsupported_gate_categories)
        )
    referenced_file_gate = YaraReferencedFileGatePolicy(
        minimum_score=_policy_percentage_int(
            gate_cfg["minimum_score"],
            f"{gate_path}.minimum_score",
        ),
        minimum_quality=_policy_percentage_int(
            gate_cfg["minimum_quality"],
            f"{gate_path}.minimum_quality",
        ),
        categories=gate_categories,
        allow_unnamed=_policy_bool(
            gate_cfg["allow_unnamed"],
            f"{gate_path}.allow_unnamed",
        ),
    )

    policy_digest = hashlib.sha256(
        json.dumps(
            cfg,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
        ).encode("utf-8")
    ).hexdigest()
    return YaraClassifierPolicy(
        enabled=enabled,
        metadata_path=configured_metadata_path,
        metadata_on_missing=on_missing,
        metadata_on_parse_error=on_parse_error,
        default_score=default_score,
        default_quality=default_quality,
        unindexed_score=unindexed_score,
        unindexed_quality=unindexed_quality,
        unindexed_rule=unindexed_rule,
        default_category=default_category,
        classification_rules=tuple(classification_rules),
        strength=strength_policy,
        categories=categories,
        referenced_file_gate=referenced_file_gate,
        evidence_type=evidence_type,
        policy_digest=policy_digest,
    )


def _compile_policy_regex(value: Any, path: str) -> Tuple[str, re.Pattern]:
    expression = _policy_string(value, path)
    try:
        return expression, re.compile(expression)
    except re.error as exc:
        raise ValueError(f"{path}: invalid regular expression: {exc}") from exc


def _parse_web_request_classifier_policy(
    raw: Any,
    path: str,
) -> WebRequestClassifierPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "stage", "executor", "enabled", "evidence_type",
            "inputs", "outputs", "matching", "indicators", "upload",
            "outcomes", "emissions", "sqli", "exploit",
        },
    )
    _policy_enum(cfg["stage"], f"{path}.stage", {"atomic"})
    _policy_enum(
        cfg["executor"], f"{path}.executor", {"web_request_classifier"}
    )
    enabled = _policy_bool(cfg["enabled"], f"{path}.enabled")
    evidence_type = _policy_enum(
        cfg["evidence_type"], f"{path}.evidence_type", {"contextual"}
    )

    inputs_path = f"{path}.inputs"
    inputs_cfg = _policy_mapping(cfg["inputs"], inputs_path)
    _policy_keys(
        inputs_cfg,
        inputs_path,
        required={
            "parser", "message", "request", "url", "headers",
            "response_code", "response_bytes", "source_ip_fields",
            "user_agent", "referer", "body", "content_disposition",
            "upload_filename", "upload_content_type", "upload_sha256",
            "request_content_length",
        },
    )
    input_policy = WebRequestInputPolicy(
        parser_field=_policy_string(inputs_cfg["parser"], f"{inputs_path}.parser"),
        message_field=_policy_string(inputs_cfg["message"], f"{inputs_path}.message"),
        request_field=_policy_string(inputs_cfg["request"], f"{inputs_path}.request"),
        url_field=_policy_string(inputs_cfg["url"], f"{inputs_path}.url"),
        headers_field=_policy_string(inputs_cfg["headers"], f"{inputs_path}.headers"),
        response_code_field=_policy_string(
            inputs_cfg["response_code"], f"{inputs_path}.response_code"
        ),
        response_bytes_field=_policy_string(
            inputs_cfg["response_bytes"], f"{inputs_path}.response_bytes"
        ),
        source_ip_fields=_policy_string_list(
            inputs_cfg["source_ip_fields"], f"{inputs_path}.source_ip_fields"
        ),
        user_agent_field=_policy_string(
            inputs_cfg["user_agent"], f"{inputs_path}.user_agent"
        ),
        referer_field=_policy_string(inputs_cfg["referer"], f"{inputs_path}.referer"),
        body_field=_policy_string(inputs_cfg["body"], f"{inputs_path}.body"),
        content_disposition_field=_policy_string(
            inputs_cfg["content_disposition"], f"{inputs_path}.content_disposition"
        ),
        upload_filename_field=_policy_string(
            inputs_cfg["upload_filename"], f"{inputs_path}.upload_filename"
        ),
        upload_content_type_field=_policy_string(
            inputs_cfg["upload_content_type"], f"{inputs_path}.upload_content_type"
        ),
        upload_sha256_field=_policy_string(
            inputs_cfg["upload_sha256"], f"{inputs_path}.upload_sha256"
        ),
        request_content_length_field=_policy_string(
            inputs_cfg["request_content_length"],
            f"{inputs_path}.request_content_length",
        ),
    )

    outputs_path = f"{path}.outputs"
    outputs_cfg = _policy_mapping(cfg["outputs"], outputs_path)
    _policy_keys(
        outputs_cfg,
        outputs_path,
        required={
            "upload_names", "upload_hashes", "upload_outcome", "web_outcome",
            "attack_indicators", "source_ip", "method", "endpoint", "status",
        },
    )
    output_values = {
        name: _policy_string(value, f"{outputs_path}.{name}")
        for name, value in outputs_cfg.items()
    }
    invalid_output_fields = sorted(
        field_name
        for field_name in output_values.values()
        if not field_name.startswith("chronosift_")
    )
    if invalid_output_fields:
        raise ValueError(
            f"{outputs_path}: materialised fields must use the 'chronosift_' "
            "sidecar namespace: " + ", ".join(invalid_output_fields)
        )
    canonical_outputs = {
        "upload_names": "chronosift_web_upload_names",
        "upload_hashes": "chronosift_web_upload_hashes",
        "upload_outcome": "chronosift_web_upload_outcome",
        "web_outcome": "chronosift_web_outcome",
        "attack_indicators": "chronosift_web_attack_indicators",
        "source_ip": "chronosift_web_source_ip",
        "method": "chronosift_web_method",
        "endpoint": "chronosift_web_endpoint",
        "status": "chronosift_web_status_code",
    }
    canonical_names = set(canonical_outputs.values())
    misbound_canonical = sorted(
        f"{role}={field_name}"
        for role, field_name in output_values.items()
        if field_name in canonical_names and field_name != canonical_outputs[role]
    )
    reserved_outputs = {
        CHRONOSIFT_ROW_ID_COLUMN,
        "chronosift_score", "chronosift_signals", "chronosift_explain",
        "chronosift_combined_command_text", "chronosift_dt_sort",
        "chronosift_activity_deficit_score",
        "chronosift_metadata", "chronosift_norm_hash", "chronosift_part_month",
        "chronosift_part_year", "chronosift_profile_metadata",
        "chronosift_quiet_hours_profile", "chronosift_row_id_sort",
        "chronosift_sparse", "chronosift_web_request_target",
        "chronosift_web_query", "chronosift_web_host",
        "chronosift_web_user_agent", "chronosift_web_referer",
        "chronosift_web_content_type", "chronosift_web_upload_name",
        "chronosift_web_upload_content_types", "chronosift_web_response_bytes",
        "chronosift_web_upload_count", "chronosift_web_request_body_bytes",
        "chronosift_web_is_event", "chronosift_web_file_hit_types",
        "chronosift_web_file_categories", "chronosift_web_file_rules",
        "chronosift_web_file_families", "chronosift_attack_techniques",
    }
    reserved_collisions = sorted(set(output_values.values()) & reserved_outputs)
    duplicate_outputs = sorted({
        field_name
        for field_name in output_values.values()
        if list(output_values.values()).count(field_name) > 1
    })
    raw_input_fields = {
        input_policy.parser_field, input_policy.message_field,
        input_policy.request_field, input_policy.url_field,
        input_policy.headers_field, input_policy.response_code_field,
        input_policy.response_bytes_field, *input_policy.source_ip_fields,
        input_policy.user_agent_field, input_policy.referer_field,
        input_policy.body_field, input_policy.content_disposition_field,
        input_policy.upload_filename_field, input_policy.upload_content_type_field,
        input_policy.upload_sha256_field,
        input_policy.request_content_length_field,
    }
    raw_collisions = sorted(raw_input_fields & set(output_values.values()))
    if misbound_canonical or reserved_collisions or duplicate_outputs or raw_collisions:
        details = [
            *(f"canonical role collision {value}" for value in misbound_canonical),
            *(f"reserved field {value}" for value in reserved_collisions),
            *(f"duplicate field {value}" for value in duplicate_outputs),
            *(f"raw input field {value}" for value in raw_collisions),
        ]
        raise ValueError(
            f"{outputs_path}: invalid materialised field binding(s): "
            + ", ".join(details)
        )
    output_policy = WebRequestOutputPolicy(
        upload_names_field=output_values["upload_names"],
        upload_hashes_field=output_values["upload_hashes"],
        upload_outcome_field=output_values["upload_outcome"],
        web_outcome_field=output_values["web_outcome"],
        attack_indicators_field=output_values["attack_indicators"],
        source_ip_field=output_values["source_ip"],
        method_field=output_values["method"],
        endpoint_field=output_values["endpoint"],
        status_field=output_values["status"],
    )

    matching_path = f"{path}.matching"
    matching_cfg = _policy_mapping(cfg["matching"], matching_path)
    _policy_keys(matching_cfg, matching_path, required={"web_log_parser_tokens"})
    web_log_parser_tokens = _policy_string_list_or_empty(
        matching_cfg["web_log_parser_tokens"],
        f"{matching_path}.web_log_parser_tokens",
        lower=True,
    )

    indicators_path = f"{path}.indicators"
    indicators_cfg = _policy_mapping(cfg["indicators"], indicators_path)
    _policy_keys(
        indicators_cfg,
        indicators_path,
        required={
            "decode_rounds", "sqli", "path_traversal",
            "local_file_inclusion", "remote_file_inclusion",
            "command_injection", "injection_probe",
            "webshell_command_parameter",
        },
    )
    decode_rounds = _policy_nonnegative_int(
        indicators_cfg["decode_rounds"], f"{indicators_path}.decode_rounds"
    )
    if decode_rounds > 4:
        raise ValueError(
            f"{indicators_path}.decode_rounds: expected a bounded value from 0 to 4"
        )

    sqli_path = f"{indicators_path}.sqli"
    sqli_cfg = _policy_mapping(indicators_cfg["sqli"], sqli_path)
    _policy_keys(sqli_cfg, sqli_path, required={"prefix", "patterns"})
    sqli_prefix = _policy_string(sqli_cfg["prefix"], f"{sqli_path}.prefix").lower()
    raw_patterns = sqli_cfg["patterns"]
    if not isinstance(raw_patterns, list) or not raw_patterns:
        raise ValueError(f"{sqli_path}.patterns: expected a non-empty list")
    sqli_patterns: List[NamedRegexPolicy] = []
    for index, raw_pattern in enumerate(raw_patterns):
        pattern_path = f"{sqli_path}.patterns[{index}]"
        pattern_cfg = _policy_mapping(raw_pattern, pattern_path)
        _policy_keys(pattern_cfg, pattern_path, required={"name", "regex"})
        name = _policy_signal_name(pattern_cfg["name"], f"{pattern_path}.name")
        expression, compiled = _compile_policy_regex(
            pattern_cfg["regex"], f"{pattern_path}.regex"
        )
        sqli_patterns.append(NamedRegexPolicy(name, expression, compiled))
    duplicate_sqli_names = sorted({
        pattern.name
        for pattern in sqli_patterns
        if sum(other.name == pattern.name for other in sqli_patterns) > 1
    })
    if duplicate_sqli_names:
        raise ValueError(
            f"{sqli_path}.patterns: duplicate name(s): "
            + ", ".join(duplicate_sqli_names)
        )

    def parse_token_indicator(
        key: str,
        *,
        token_keys: Tuple[str, ...],
    ) -> Tuple[str, Dict[str, Tuple[str, ...]]]:
        indicator_path = f"{indicators_path}.{key}"
        indicator_cfg = _policy_mapping(indicators_cfg[key], indicator_path)
        _policy_keys(
            indicator_cfg,
            indicator_path,
            required={"indicator", *token_keys},
        )
        indicator = _policy_signal_name(
            indicator_cfg["indicator"], f"{indicator_path}.indicator"
        )
        values = {
            token_key: _policy_string_list(
                indicator_cfg[token_key],
                f"{indicator_path}.{token_key}",
                lower=True,
            )
            for token_key in token_keys
        }
        return indicator, values

    traversal_indicator, traversal_tokens = parse_token_indicator(
        "path_traversal", token_keys=("decoded_contains", "raw_contains")
    )
    lfi_indicator, lfi_tokens = parse_token_indicator(
        "local_file_inclusion", token_keys=("decoded_contains",)
    )

    rfi_path = f"{indicators_path}.remote_file_inclusion"
    rfi_cfg = _policy_mapping(indicators_cfg["remote_file_inclusion"], rfi_path)
    _policy_keys(rfi_cfg, rfi_path, required={"indicator", "regex_any"})
    rfi_indicator = _policy_signal_name(
        rfi_cfg["indicator"], f"{rfi_path}.indicator"
    )
    raw_rfi_patterns = rfi_cfg["regex_any"]
    if not isinstance(raw_rfi_patterns, list) or not raw_rfi_patterns:
        raise ValueError(f"{rfi_path}.regex_any: expected a non-empty list")
    rfi_patterns = tuple(
        _compile_policy_regex(value, f"{rfi_path}.regex_any[{index}]")[1]
        for index, value in enumerate(raw_rfi_patterns)
    )

    command_path = f"{indicators_path}.command_injection"
    command_cfg = _policy_mapping(indicators_cfg["command_injection"], command_path)
    _policy_keys(command_cfg, command_path, required={"indicator", "regex"})
    command_indicator = _policy_signal_name(
        command_cfg["indicator"], f"{command_path}.indicator"
    )
    _, command_pattern = _compile_policy_regex(
        command_cfg["regex"], f"{command_path}.regex"
    )

    probe_path = f"{indicators_path}.injection_probe"
    probe_cfg = _policy_mapping(indicators_cfg["injection_probe"], probe_path)
    _policy_keys(
        probe_cfg,
        probe_path,
        required={
            "indicator", "breakout_regex", "metacharacter_regex",
            "quote_regex", "minimum_metacharacters",
            "minimum_distinct_metacharacters",
        },
    )
    breakout_expression, breakout_pattern = _compile_policy_regex(
        probe_cfg["breakout_regex"], f"{probe_path}.breakout_regex"
    )
    metachar_expression, metachar_pattern = _compile_policy_regex(
        probe_cfg["metacharacter_regex"], f"{probe_path}.metacharacter_regex"
    )
    quote_expression, quote_pattern = _compile_policy_regex(
        probe_cfg["quote_regex"], f"{probe_path}.quote_regex"
    )
    injection_probe = WebInjectionProbePolicy(
        indicator=_policy_signal_name(
            probe_cfg["indicator"], f"{probe_path}.indicator"
        ),
        breakout_expression=breakout_expression,
        breakout_pattern=breakout_pattern,
        metacharacter_expression=metachar_expression,
        metacharacter_pattern=metachar_pattern,
        quote_expression=quote_expression,
        quote_pattern=quote_pattern,
        minimum_metacharacters=_policy_positive_int(
            probe_cfg["minimum_metacharacters"],
            f"{probe_path}.minimum_metacharacters",
        ),
        minimum_distinct_metacharacters=_policy_positive_int(
            probe_cfg["minimum_distinct_metacharacters"],
            f"{probe_path}.minimum_distinct_metacharacters",
        ),
    )
    if (
        injection_probe.minimum_distinct_metacharacters
        > injection_probe.minimum_metacharacters
    ):
        raise ValueError(
            f"{probe_path}.minimum_distinct_metacharacters: expected a value "
            "less than or equal to minimum_metacharacters"
        )

    webshell_path = f"{indicators_path}.webshell_command_parameter"
    webshell_cfg = _policy_mapping(
        indicators_cfg["webshell_command_parameter"], webshell_path
    )
    _policy_keys(webshell_cfg, webshell_path, required={"indicator", "regex"})
    webshell_indicator = _policy_signal_name(
        webshell_cfg["indicator"], f"{webshell_path}.indicator"
    )
    _, webshell_pattern = _compile_policy_regex(
        webshell_cfg["regex"], f"{webshell_path}.regex"
    )
    indicator_policy = WebIndicatorPolicy(
        decode_rounds=decode_rounds,
        sqli_prefix=sqli_prefix,
        sqli_patterns=tuple(sqli_patterns),
        path_traversal_indicator=traversal_indicator,
        path_traversal_decoded_tokens=traversal_tokens["decoded_contains"],
        path_traversal_raw_tokens=traversal_tokens["raw_contains"],
        local_file_inclusion_indicator=lfi_indicator,
        local_file_inclusion_tokens=lfi_tokens["decoded_contains"],
        remote_file_inclusion_indicator=rfi_indicator,
        remote_file_inclusion_patterns=rfi_patterns,
        command_injection_indicator=command_indicator,
        command_injection_pattern=command_pattern,
        injection_probe=injection_probe,
        webshell_parameter_indicator=webshell_indicator,
        webshell_parameter_pattern=webshell_pattern,
    )

    upload_path = f"{path}.upload"
    upload_cfg = _policy_mapping(cfg["upload"], upload_path)
    _policy_keys(
        upload_cfg,
        upload_path,
        required={
            "methods", "query_parameter_names", "filename_extension_admission",
            "endpoint_tokens", "nameless_methods",
            "multipart_content_type", "executable_extensions",
            "image_extensions", "image_content_type_prefix",
            "mime_value_pairing", "mime_mismatch",
            "double_extension_minimum_dots", "indicators",
        },
    )
    nameless_methods = frozenset(
        value.upper()
        for value in _policy_string_list_or_empty(
            upload_cfg["nameless_methods"], f"{upload_path}.nameless_methods"
        )
    )
    invalid_methods = sorted(
        method for method in nameless_methods if not re.fullmatch(r"[A-Z]+", method)
    )
    if invalid_methods:
        raise ValueError(
            f"{upload_path}.nameless_methods: unsupported value(s): "
            + ", ".join(invalid_methods)
        )
    upload_methods = frozenset(
        value.upper()
        for value in _policy_string_list_or_empty(
            upload_cfg["methods"], f"{upload_path}.methods"
        )
    )
    invalid_upload_methods = sorted(
        method for method in upload_methods if not re.fullmatch(r"[A-Z]+", method)
    )
    if invalid_upload_methods:
        raise ValueError(
            f"{upload_path}.methods: unsupported value(s): "
            + ", ".join(invalid_upload_methods)
        )
    invalid_nameless_methods = sorted(nameless_methods - upload_methods)
    if invalid_nameless_methods:
        raise ValueError(
            f"{upload_path}.nameless_methods: method(s) are not enabled upload "
            "methods: " + ", ".join(invalid_nameless_methods)
        )
    executable_extensions = _policy_string_list(
        upload_cfg["executable_extensions"],
        f"{upload_path}.executable_extensions",
        lower=True,
    )
    image_extensions = frozenset(
        _policy_string_list(
            upload_cfg["image_extensions"],
            f"{upload_path}.image_extensions",
            lower=True,
        )
    )
    invalid_extensions = sorted(
        extension
        for extension in (*executable_extensions, *image_extensions)
        if not extension.startswith(".")
    )
    if invalid_extensions:
        raise ValueError(
            f"{upload_path}: extensions must start with '.': "
            + ", ".join(invalid_extensions)
        )

    mime_mismatch_path = f"{upload_path}.mime_mismatch"
    mime_mismatch_cfg = _policy_mapping(
        upload_cfg["mime_mismatch"], mime_mismatch_path
    )
    _policy_keys(
        mime_mismatch_cfg,
        mime_mismatch_path,
        required={"match", "branches"},
    )
    mime_mismatch_match = _policy_enum(
        mime_mismatch_cfg["match"],
        f"{mime_mismatch_path}.match",
        {"any"},
    )
    raw_mime_branches = mime_mismatch_cfg["branches"]
    mime_branches_path = f"{mime_mismatch_path}.branches"
    if not isinstance(raw_mime_branches, list) or not raw_mime_branches:
        raise ValueError(f"{mime_branches_path}: expected a non-empty list")
    allowed_mime_facts = {
        "image_extension", "executable_extension", "image_content_type",
    }

    def parse_mime_facts(value: Any, fact_path: str) -> frozenset[str]:
        if not isinstance(value, list):
            raise ValueError(f"{fact_path}: expected a list")
        facts: List[str] = []
        for fact_index, raw_fact in enumerate(value):
            fact = _policy_signal_name(raw_fact, f"{fact_path}[{fact_index}]")
            if fact not in allowed_mime_facts:
                raise ValueError(
                    f"{fact_path}[{fact_index}]: unknown fact {fact!r}; expected "
                    + ", ".join(sorted(allowed_mime_facts))
                )
            if fact in facts:
                raise ValueError(
                    f"{fact_path}[{fact_index}]: duplicate fact {fact!r}"
                )
            facts.append(fact)
        return frozenset(facts)

    mime_mismatch_branches: List[WebMimeMismatchBranchPolicy] = []
    seen_mime_branch_ids: Set[str] = set()
    seen_mime_branch_signatures: Set[
        Tuple[frozenset[str], frozenset[str], frozenset[str]]
    ] = set()
    for branch_index, raw_branch in enumerate(raw_mime_branches):
        branch_path = f"{mime_branches_path}[{branch_index}]"
        branch_cfg = _policy_mapping(raw_branch, branch_path)
        _policy_keys(
            branch_cfg,
            branch_path,
            required={"id", "all", "any", "none"},
        )
        branch_id = _policy_signal_name(branch_cfg["id"], f"{branch_path}.id")
        if branch_id in seen_mime_branch_ids:
            raise ValueError(f"{branch_path}.id: duplicate value {branch_id!r}")
        seen_mime_branch_ids.add(branch_id)
        require_all = parse_mime_facts(branch_cfg["all"], f"{branch_path}.all")
        require_any = parse_mime_facts(branch_cfg["any"], f"{branch_path}.any")
        exclude_any = parse_mime_facts(branch_cfg["none"], f"{branch_path}.none")
        if not require_all and not require_any:
            raise ValueError(
                f"{branch_path}: at least one fact is required in all or any"
            )
        overlaps = sorted(
            (set(require_all) | set(require_any)) & set(exclude_any)
        )
        if overlaps:
            raise ValueError(
                f"{branch_path}: fact(s) cannot be both required and excluded: "
                + ", ".join(overlaps)
            )
        signature = (require_all, require_any, exclude_any)
        if signature in seen_mime_branch_signatures:
            raise ValueError(f"{branch_path}: duplicate MIME mismatch branch")
        seen_mime_branch_signatures.add(signature)
        mime_mismatch_branches.append(
            WebMimeMismatchBranchPolicy(
                branch_id=branch_id,
                decision=BooleanFactDecisionPolicy(
                    require_all=require_all,
                    require_any=require_any,
                    exclude_any=exclude_any,
                ),
            )
        )
    mime_mismatch_policy = WebMimeMismatchPolicy(
        match=mime_mismatch_match,
        branches=tuple(mime_mismatch_branches),
    )

    upload_indicators_path = f"{upload_path}.indicators"
    upload_indicators_cfg = _policy_mapping(
        upload_cfg["indicators"], upload_indicators_path
    )
    _policy_keys(
        upload_indicators_cfg,
        upload_indicators_path,
        required={
            "file_upload", "executable_upload", "double_extension_upload",
            "mime_extension_mismatch",
        },
    )
    parsed_upload_indicators = {
        name: _policy_signal_name(value, f"{upload_indicators_path}.{name}")
        for name, value in upload_indicators_cfg.items()
    }
    upload_policy = WebUploadFeaturePolicy(
        upload_methods=upload_methods,
        query_parameter_names=frozenset(
            _policy_string_list_or_empty(
                upload_cfg["query_parameter_names"],
                f"{upload_path}.query_parameter_names",
                lower=True,
            )
        ),
        filename_extension_admission=_policy_enum(
            upload_cfg["filename_extension_admission"],
            f"{upload_path}.filename_extension_admission",
            {"any_nonempty_basename", "nonempty_suffix"},
        ),
        endpoint_tokens=_policy_string_list(
            upload_cfg["endpoint_tokens"],
            f"{upload_path}.endpoint_tokens",
            lower=True,
        ),
        nameless_methods=nameless_methods,
        multipart_content_type=_policy_string(
            upload_cfg["multipart_content_type"],
            f"{upload_path}.multipart_content_type",
        ).lower(),
        executable_extensions=executable_extensions,
        image_extensions=image_extensions,
        image_content_type_prefix=_policy_string(
            upload_cfg["image_content_type_prefix"],
            f"{upload_path}.image_content_type_prefix",
        ).lower(),
        mime_value_pairing=_policy_enum(
            upload_cfg["mime_value_pairing"],
            f"{upload_path}.mime_value_pairing",
            {"exactly_one", "any_pair"},
        ),
        mime_mismatch=mime_mismatch_policy,
        double_extension_minimum_dots=_policy_positive_int(
            upload_cfg["double_extension_minimum_dots"],
            f"{upload_path}.double_extension_minimum_dots",
        ),
        file_upload_indicator=parsed_upload_indicators["file_upload"],
        executable_upload_indicator=parsed_upload_indicators["executable_upload"],
        double_extension_indicator=parsed_upload_indicators["double_extension_upload"],
        mime_extension_mismatch_indicator=parsed_upload_indicators[
            "mime_extension_mismatch"
        ],
    )

    indicator_names = [
        traversal_indicator,
        lfi_indicator,
        rfi_indicator,
        command_indicator,
        injection_probe.indicator,
        webshell_indicator,
        *parsed_upload_indicators.values(),
    ]
    duplicate_indicator_names = sorted({
        name for name in indicator_names if indicator_names.count(name) > 1
    })
    if duplicate_indicator_names:
        raise ValueError(
            f"{path}: duplicate indicator name(s): "
            + ", ".join(duplicate_indicator_names)
        )
    available_exact_indicators = {
        *indicator_names,
        *(
            f"{sqli_prefix}{pattern.name}"
            for pattern in sqli_patterns
        ),
    }

    outcomes_path = f"{path}.outcomes"
    outcomes_cfg = _policy_mapping(cfg["outcomes"], outcomes_path)
    _policy_keys(
        outcomes_cfg,
        outcomes_path,
        required={"upload", "success_status", "redirect_status", "web"},
    )
    upload_outcomes_path = f"{outcomes_path}.upload"
    upload_outcomes_cfg = _policy_mapping(
        outcomes_cfg["upload"], upload_outcomes_path
    )
    _policy_keys(
        upload_outcomes_cfg,
        upload_outcomes_path,
        required={"unknown", "accepted", "redirected", "rejected"},
    )
    upload_outcomes = {
        name: _policy_string(value, f"{upload_outcomes_path}.{name}")
        for name, value in upload_outcomes_cfg.items()
    }
    if len(set(upload_outcomes.values())) != len(upload_outcomes):
        raise ValueError(f"{upload_outcomes_path}: outcome values must be distinct")
    success_path = f"{outcomes_path}.success_status"
    success_cfg = _policy_mapping(outcomes_cfg["success_status"], success_path)
    _policy_keys(success_cfg, success_path, required={"minimum", "maximum_exclusive"})
    success_minimum = _policy_nonnegative_int(
        success_cfg["minimum"], f"{success_path}.minimum"
    )
    success_maximum = _policy_positive_int(
        success_cfg["maximum_exclusive"], f"{success_path}.maximum_exclusive"
    )
    if success_minimum >= success_maximum:
        raise ValueError(
            f"{success_path}: minimum must be less than maximum_exclusive"
        )
    redirect_path = f"{outcomes_path}.redirect_status"
    redirect_cfg = _policy_mapping(outcomes_cfg["redirect_status"], redirect_path)
    _policy_keys(redirect_cfg, redirect_path, required={"minimum", "maximum_exclusive"})
    redirect_minimum = _policy_nonnegative_int(
        redirect_cfg["minimum"], f"{redirect_path}.minimum"
    )
    redirect_maximum = _policy_positive_int(
        redirect_cfg["maximum_exclusive"], f"{redirect_path}.maximum_exclusive"
    )
    if redirect_minimum >= redirect_maximum:
        raise ValueError(
            f"{redirect_path}: minimum must be less than maximum_exclusive"
        )
    if max(success_minimum, redirect_minimum) < min(
        success_maximum, redirect_maximum
    ):
        raise ValueError(
            f"{outcomes_path}: success_status and redirect_status ranges must "
            "not overlap"
        )
    web_outcomes_path = f"{outcomes_path}.web"
    web_outcomes_cfg = _policy_mapping(outcomes_cfg["web"], web_outcomes_path)
    _policy_keys(
        web_outcomes_cfg,
        web_outcomes_path,
        required={
            "observed", "attempt", "probable_success", "attempt_when",
            "selection",
        },
    )
    web_outcomes = {
        name: _policy_string(value, f"{web_outcomes_path}.{name}")
        for name, value in web_outcomes_cfg.items()
        if name not in {"attempt_when", "selection"}
    }
    if len(set(web_outcomes.values())) != len(web_outcomes):
        raise ValueError(f"{web_outcomes_path}: outcome values must be distinct")
    selection_path = f"{web_outcomes_path}.selection"
    selection_cfg = _policy_mapping(
        web_outcomes_cfg["selection"], selection_path
    )
    _policy_keys(
        selection_cfg,
        selection_path,
        required={"strategy", "ranks"},
    )
    selection_strategy = _policy_enum(
        selection_cfg["strategy"],
        f"{selection_path}.strategy",
        {"maximum_rank"},
    )
    selection_ranks_path = f"{selection_path}.ranks"
    selection_ranks_cfg = _policy_mapping(
        selection_cfg["ranks"], selection_ranks_path
    )
    _policy_keys(
        selection_ranks_cfg,
        selection_ranks_path,
        required={"observed", "attempt", "probable_success"},
    )
    selection_ranks = {
        semantic: _policy_nonnegative_int(
            rank, f"{selection_ranks_path}.{semantic}"
        )
        for semantic, rank in selection_ranks_cfg.items()
    }
    if len(set(selection_ranks.values())) != len(selection_ranks):
        raise ValueError(f"{selection_ranks_path}: rank values must be distinct")
    attempt_when_path = f"{web_outcomes_path}.attempt_when"
    attempt_when_cfg = _policy_mapping(
        web_outcomes_cfg["attempt_when"], attempt_when_path
    )
    _policy_keys(
        attempt_when_cfg,
        attempt_when_path,
        required={"indicators_any", "indicator_prefixes_any"},
    )
    attempt_indicators_any = frozenset(
        _policy_string_list_or_empty(
            attempt_when_cfg["indicators_any"],
            f"{attempt_when_path}.indicators_any",
            lower=True,
        )
    )
    attempt_indicator_prefixes = _policy_string_list_or_empty(
        attempt_when_cfg["indicator_prefixes_any"],
        f"{attempt_when_path}.indicator_prefixes_any",
        lower=True,
    )
    if not attempt_indicators_any and not attempt_indicator_prefixes:
        raise ValueError(f"{attempt_when_path}: expected at least one indicator selector")
    unknown_attempt_indicators = sorted(
        attempt_indicators_any - available_exact_indicators
    )
    if unknown_attempt_indicators:
        raise ValueError(
            f"{attempt_when_path}.indicators_any: unknown indicator(s): "
            + ", ".join(unknown_attempt_indicators)
        )
    unmatched_attempt_prefixes = sorted(
        prefix
        for prefix in attempt_indicator_prefixes
        if not any(
            indicator.startswith(prefix)
            for indicator in available_exact_indicators
        )
    )
    if unmatched_attempt_prefixes:
        raise ValueError(
            f"{attempt_when_path}.indicator_prefixes_any: prefix(es) match no "
            "configured indicator: " + ", ".join(unmatched_attempt_prefixes)
        )
    outcomes = WebOutcomePolicy(
        upload_unknown=upload_outcomes["unknown"],
        upload_accepted=upload_outcomes["accepted"],
        upload_redirected=upload_outcomes["redirected"],
        upload_rejected=upload_outcomes["rejected"],
        success_status_minimum=success_minimum,
        success_status_maximum_exclusive=success_maximum,
        redirect_status_minimum=redirect_minimum,
        redirect_status_maximum_exclusive=redirect_maximum,
        web_observed=web_outcomes["observed"],
        web_attempt=web_outcomes["attempt"],
        web_probable_success=web_outcomes["probable_success"],
        attempt_when=WebIndicatorSelectionPolicy(
            indicators_any=attempt_indicators_any,
            indicator_prefixes_any=attempt_indicator_prefixes,
        ),
        selection=WebOutcomeSelectionPolicy(
            strategy=selection_strategy,
            ranks=selection_ranks,
        ),
    )

    emissions_path = f"{path}.emissions"
    emissions = _parse_referenced_file_emission_registry(
        cfg["emissions"], emissions_path
    )

    inference_path = f"{path}.sqli"
    inference_cfg = _policy_mapping(cfg["sqli"], inference_path)
    _policy_keys(
        inference_cfg,
        inference_path,
        required={"baseline", "decisions", "emissions", "evidence"},
    )
    baseline_path = f"{inference_path}.baseline"
    baseline_cfg = _policy_mapping(inference_cfg["baseline"], baseline_path)
    _policy_keys(
        baseline_cfg,
        baseline_path,
        required={
            "key_fields", "require_nonempty_keys", "scope", "lookback",
            "sample", "statistic", "minimum_samples", "threshold_combine",
            "threshold_terms", "threshold_comparison", "response_ratio",
            "response_delta_bytes", "response_minimum_bytes",
            "absolute_large_response_bytes",
        },
    )
    baseline_key_fields = _policy_string_list(
        baseline_cfg["key_fields"], f"{baseline_path}.key_fields"
    )
    allowed_baseline_keys = {"endpoint", "host", "method"}
    unknown_baseline_keys = sorted(
        set(baseline_key_fields) - allowed_baseline_keys
    )
    if unknown_baseline_keys:
        raise ValueError(
            f"{baseline_path}.key_fields: unknown role(s): "
            + ", ".join(unknown_baseline_keys)
        )
    require_nonempty_keys = frozenset(
        _policy_string_list_or_empty(
            baseline_cfg["require_nonempty_keys"],
            f"{baseline_path}.require_nonempty_keys",
        )
    )
    unavailable_required_keys = sorted(
        require_nonempty_keys - set(baseline_key_fields)
    )
    if unavailable_required_keys:
        raise ValueError(
            f"{baseline_path}.require_nonempty_keys: role(s) are not present "
            "in key_fields: " + ", ".join(unavailable_required_keys)
        )
    baseline_scope = _policy_enum(
        baseline_cfg["scope"],
        f"{baseline_path}.scope",
        {"partition", "prior_rows"},
    )
    raw_baseline_lookback = baseline_cfg["lookback"]
    if (
        isinstance(raw_baseline_lookback, str)
        and raw_baseline_lookback.strip().lower() == "unbounded"
    ):
        baseline_lookback = None
    else:
        baseline_lookback = _parse_policy_lookback(
            raw_baseline_lookback, f"{baseline_path}.lookback"
        )
    sample_path = f"{baseline_path}.sample"
    sample_cfg = _policy_mapping(baseline_cfg["sample"], sample_path)
    _policy_keys(
        sample_cfg,
        sample_path,
        required={"indicators", "response", "bytes"},
    )
    baseline_sample_indicators = _policy_enum(
        sample_cfg["indicators"],
        f"{sample_path}.indicators",
        {"absent", "any", "present"},
    )
    baseline_sample_response = _policy_enum(
        sample_cfg["response"],
        f"{sample_path}.response",
        {"any", "successful"},
    )
    baseline_sample_bytes = _policy_enum(
        sample_cfg["bytes"],
        f"{sample_path}.bytes",
        {"nonnegative", "positive"},
    )
    baseline_statistic = _policy_enum(
        baseline_cfg["statistic"],
        f"{baseline_path}.statistic",
        {"mean", "median"},
    )
    threshold_combine = _policy_enum(
        baseline_cfg["threshold_combine"],
        f"{baseline_path}.threshold_combine",
        {"maximum", "minimum"},
    )
    threshold_terms = _policy_string_list(
        baseline_cfg["threshold_terms"],
        f"{baseline_path}.threshold_terms",
    )
    allowed_threshold_terms = {
        "baseline_delta", "baseline_ratio", "response_minimum"
    }
    unknown_threshold_terms = sorted(
        set(threshold_terms) - allowed_threshold_terms
    )
    if unknown_threshold_terms:
        raise ValueError(
            f"{baseline_path}.threshold_terms: unknown term(s): "
            + ", ".join(unknown_threshold_terms)
        )
    threshold_comparison = _policy_enum(
        baseline_cfg["threshold_comparison"],
        f"{baseline_path}.threshold_comparison",
        {"greater_than", "greater_than_or_equal"},
    )
    response_ratio = _policy_positive_number(
        baseline_cfg["response_ratio"], f"{baseline_path}.response_ratio"
    )
    if response_ratio < 1.0:
        raise ValueError(f"{baseline_path}.response_ratio: expected a value >= 1")
    response_minimum = _policy_nonnegative_int(
        baseline_cfg["response_minimum_bytes"],
        f"{baseline_path}.response_minimum_bytes",
    )
    absolute_large = _policy_nonnegative_int(
        baseline_cfg["absolute_large_response_bytes"],
        f"{baseline_path}.absolute_large_response_bytes",
    )
    if absolute_large < response_minimum:
        raise ValueError(
            f"{baseline_path}.absolute_large_response_bytes: expected a value "
            "greater than or equal to response_minimum_bytes"
        )
    inference_emissions_path = f"{inference_path}.emissions"
    inference_emissions_cfg = _policy_mapping(
        inference_cfg["emissions"], inference_emissions_path
    )
    _policy_keys(
        inference_emissions_cfg,
        inference_emissions_path,
        required={"attempt", "response_anomaly", "probable_success"},
    )
    inference_emission_ids = {
        name: _policy_string(value, f"{inference_emissions_path}.{name}")
        for name, value in inference_emissions_cfg.items()
    }
    for role, emission_id in inference_emission_ids.items():
        if emission_id not in emissions:
            raise ValueError(
                f"{inference_emissions_path}.{role}: unknown emission: {emission_id}"
            )
    if len(set(inference_emission_ids.values())) != len(inference_emission_ids):
        raise ValueError(
            f"{inference_emissions_path}: SQLi emission roles must reference "
            "distinct emissions"
        )
    sqli_evidence_allowed = {
        "http_method", "http_path", "canonical_endpoint", "sqli_indicators",
        "http_response_code", "http_response_bytes", "baseline_response_statistic",
        "baseline_statistic", "baseline_sample_count",
        "response_anomaly_threshold", "actor_ip",
        "http_request_user_agent",
    }
    inference_decisions = _parse_boolean_fact_decisions(
        inference_cfg["decisions"],
        f"{inference_path}.decisions",
        ("attempt", "response_anomaly", "probable_success"),
        {
            "baseline_available", "indicators", "response_bytes",
            "successful_response", "threshold_exceeded",
        },
    )
    sqli_inference = WebSqliInferencePolicy(
        baseline_key_fields=baseline_key_fields,
        baseline_require_nonempty_keys=require_nonempty_keys,
        baseline_scope=baseline_scope,
        baseline_lookback=baseline_lookback,
        baseline_sample_indicators=baseline_sample_indicators,
        baseline_sample_response=baseline_sample_response,
        baseline_sample_bytes=baseline_sample_bytes,
        baseline_statistic=baseline_statistic,
        baseline_min_samples=_policy_positive_int(
            baseline_cfg["minimum_samples"], f"{baseline_path}.minimum_samples"
        ),
        threshold_combine=threshold_combine,
        threshold_terms=threshold_terms,
        threshold_comparison=threshold_comparison,
        response_ratio=response_ratio,
        response_delta_bytes=_policy_nonnegative_int(
            baseline_cfg["response_delta_bytes"],
            f"{baseline_path}.response_delta_bytes",
        ),
        response_minimum_bytes=response_minimum,
        absolute_large_response_bytes=absolute_large,
        attempt_emission_id=inference_emission_ids["attempt"],
        anomaly_emission_id=inference_emission_ids["response_anomaly"],
        probable_success_emission_id=inference_emission_ids["probable_success"],
        decisions_by_semantic=inference_decisions,
        evidence=_parse_policy_evidence_names(
            inference_cfg["evidence"],
            f"{inference_path}.evidence",
            sqli_evidence_allowed,
        ),
    )

    exploit_path = f"{path}.exploit"
    exploit_cfg = _policy_mapping(cfg["exploit"], exploit_path)
    _policy_keys(exploit_cfg, exploit_path, required={"emission", "branches"})
    exploit_emission_id = _policy_string(
        exploit_cfg["emission"], f"{exploit_path}.emission"
    )
    if exploit_emission_id not in emissions:
        raise ValueError(
            f"{exploit_path}.emission: unknown emission: {exploit_emission_id}"
        )
    if exploit_emission_id in inference_emission_ids.values():
        raise ValueError(
            f"{exploit_path}.emission: exploit and SQLi roles must reference "
            "distinct emissions"
        )
    branches_path = f"{exploit_path}.branches"
    branches_cfg = _policy_mapping(exploit_cfg["branches"], branches_path)
    if not branches_cfg:
        raise ValueError(f"{branches_path}: expected at least one branch")
    exploit_evidence_allowed = {
        "http_method", "http_path", "canonical_endpoint", "http_response_code",
        "http_response_bytes", "attack_indicators", "upload_name", "upload_names",
        "upload_outcome", "actor_ip", "http_request_user_agent",
    }
    exploit_branches: List[WebExploitBranchPolicy] = []
    for branch_id, raw_branch in branches_cfg.items():
        _policy_signal_name(branch_id, f"{branches_path} key")
        branch_path = f"{branches_path}.{branch_id}"
        branch_cfg = _policy_mapping(raw_branch, branch_path)
        _policy_keys(
            branch_cfg,
            branch_path,
            required={"conditions", "description", "confidence", "evidence"},
        )
        conditions_path = f"{branch_path}.conditions"
        conditions_cfg = _policy_mapping(branch_cfg["conditions"], conditions_path)
        _policy_keys(
            conditions_cfg,
            conditions_path,
            required=set(),
            optional={
                "indicators_all", "indicators_any", "indicator_prefixes_any",
                "signals_any", "minimum_signal_value_exclusive",
            },
        )
        indicators_all = frozenset(
            _policy_string_list(
                conditions_cfg["indicators_all"],
                f"{conditions_path}.indicators_all",
                lower=True,
            ) if "indicators_all" in conditions_cfg else ()
        )
        indicators_any = frozenset(
            _policy_string_list(
                conditions_cfg["indicators_any"],
                f"{conditions_path}.indicators_any",
                lower=True,
            ) if "indicators_any" in conditions_cfg else ()
        )
        indicator_prefixes_any = (
            _policy_string_list(
                conditions_cfg["indicator_prefixes_any"],
                f"{conditions_path}.indicator_prefixes_any",
                lower=True,
            ) if "indicator_prefixes_any" in conditions_cfg else ()
        )
        signals_any = frozenset(
            _policy_signal_list(
                conditions_cfg["signals_any"], f"{conditions_path}.signals_any"
            ) if "signals_any" in conditions_cfg else ()
        )
        threshold_present = "minimum_signal_value_exclusive" in conditions_cfg
        if bool(signals_any) != threshold_present:
            requirement = "required" if signals_any else "not allowed"
            raise ValueError(
                f"{conditions_path}.minimum_signal_value_exclusive: {requirement} "
                "when signals_any is configured"
            )
        minimum_signal_value_exclusive = (
            _policy_nonnegative_number(
                conditions_cfg["minimum_signal_value_exclusive"],
                f"{conditions_path}.minimum_signal_value_exclusive",
            )
            if threshold_present
            else None
        )
        if not any((indicators_all, indicators_any, indicator_prefixes_any, signals_any)):
            raise ValueError(f"{conditions_path}: expected at least one condition")
        exploit_branches.append(WebExploitBranchPolicy(
            branch_id=branch_id,
            conditions=WebExploitConditionPolicy(
                indicators_all=indicators_all,
                indicators_any=indicators_any,
                indicator_prefixes_any=indicator_prefixes_any,
                signals_any=signals_any,
                minimum_signal_value_exclusive=minimum_signal_value_exclusive,
            ),
            description=_policy_string(
                branch_cfg["description"], f"{branch_path}.description"
            ),
            confidence=_policy_confidence(
                branch_cfg["confidence"], f"{branch_path}.confidence"
            ),
            evidence=_parse_policy_evidence_names(
                branch_cfg["evidence"],
                f"{branch_path}.evidence",
                exploit_evidence_allowed,
            ),
        ))

    for branch in exploit_branches:
        conditions_path = (
            f"{branches_path}.{branch.branch_id}.conditions"
        )
        exact_references = (
            branch.conditions.indicators_all
            | branch.conditions.indicators_any
        )
        unknown_indicators = sorted(
            exact_references - available_exact_indicators
        )
        if unknown_indicators:
            raise ValueError(
                f"{conditions_path}: unknown indicator(s): "
                + ", ".join(unknown_indicators)
            )
        unmatched_prefixes = sorted(
            prefix
            for prefix in branch.conditions.indicator_prefixes_any
            if not any(
                indicator.startswith(prefix)
                for indicator in available_exact_indicators
            )
        )
        if unmatched_prefixes:
            raise ValueError(
                f"{conditions_path}.indicator_prefixes_any: prefix(es) match no "
                "configured indicator: " + ", ".join(unmatched_prefixes)
            )

    used_emission_ids = {
        *inference_emission_ids.values(),
        exploit_emission_id,
    }
    unused_emission_ids = sorted(set(emissions) - used_emission_ids)
    if unused_emission_ids:
        raise ValueError(
            f"{path}: emission(s) are never referenced: "
            + ", ".join(unused_emission_ids)
        )
    policy_digest = hashlib.sha256(
        json.dumps(
            cfg,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
        ).encode("utf-8")
    ).hexdigest()
    return WebRequestClassifierPolicy(
        enabled=enabled,
        evidence_type=evidence_type,
        inputs=input_policy,
        outputs=output_policy,
        web_log_parser_tokens=web_log_parser_tokens,
        indicators=indicator_policy,
        upload=upload_policy,
        outcomes=outcomes,
        emissions_by_id=emissions,
        sqli=sqli_inference,
        exploit_emission_id=exploit_emission_id,
        exploit_branches=tuple(exploit_branches),
        policy_digest=policy_digest,
    )


_REFERENCED_FILE_HIT_TYPES = frozenset({"av", "luhn", "yara"})


def _parse_policy_evidence_names(
    raw: Any,
    path: str,
    allowed: Iterable[str],
) -> Tuple[str, ...]:
    evidence = _policy_string_list(raw, path)
    unsupported = sorted(set(evidence) - set(allowed))
    if unsupported:
        raise ValueError(
            f"{path}: unsupported value(s): {', '.join(unsupported)}"
        )
    return evidence


def _parse_referenced_file_emission_registry(
    raw: Any,
    path: str,
) -> Dict[str, DetectorEmissionPolicy]:
    cfg = _policy_mapping(raw, path)
    if not cfg:
        raise ValueError(f"{path}: expected at least one emission")
    for emission_id in cfg:
        _policy_signal_name(emission_id, f"{path} key")
    return {
        emission_id: _parse_policy_emission(
            cfg[emission_id],
            f"{path}.{emission_id}",
            include_explanation=True,
        )
        for emission_id in cfg
    }


def _parse_web_mapping_condition(
    raw: Any,
    path: str,
    *,
    supported_categories: frozenset[str],
    allow_empty: bool = False,
) -> WebMappingConditionPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={"match"},
        optional={
            "indicators_any",
            "indicator_prefixes_any",
            "signals_any",
            "minimum_signal_value_exclusive",
            "categories_any",
            "methods_any",
            "upload_outcomes_any",
            "source_ip_scopes_any",
        },
    )

    def optional_strings(name: str, *, lower: bool = False) -> Tuple[str, ...]:
        if name not in cfg:
            return ()
        return _policy_string_list(cfg[name], f"{path}.{name}", lower=lower)

    categories = frozenset(optional_strings("categories_any", lower=True))
    unsupported_categories = sorted(categories - supported_categories)
    if unsupported_categories:
        raise ValueError(
            f"{path}.categories_any: unsupported value(s): "
            + ", ".join(unsupported_categories)
        )
    methods = frozenset(
        value.upper() for value in optional_strings("methods_any")
    )
    invalid_methods = sorted(
        method for method in methods if not re.fullmatch(r"[A-Z]+", method)
    )
    if invalid_methods:
        raise ValueError(
            f"{path}.methods_any: unsupported value(s): {', '.join(invalid_methods)}"
        )
    source_ip_scopes = frozenset(optional_strings("source_ip_scopes_any", lower=True))
    invalid_scopes = sorted(source_ip_scopes - {"private", "public"})
    if invalid_scopes:
        raise ValueError(
            f"{path}.source_ip_scopes_any: unsupported value(s): {', '.join(invalid_scopes)}"
        )
    signals_any = frozenset(
        _policy_signal_list(cfg["signals_any"], f"{path}.signals_any")
        if "signals_any" in cfg
        else ()
    )
    threshold_present = "minimum_signal_value_exclusive" in cfg
    if bool(signals_any) != threshold_present:
        requirement = "required" if signals_any else "not allowed"
        raise ValueError(
            f"{path}.minimum_signal_value_exclusive: {requirement} when "
            "signals_any is configured"
        )
    condition = WebMappingConditionPolicy(
        match=_policy_enum(cfg["match"], f"{path}.match", {"all", "any"}),
        indicators_any=frozenset(optional_strings("indicators_any", lower=True)),
        indicator_prefixes_any=optional_strings("indicator_prefixes_any", lower=True),
        signals_any=signals_any,
        minimum_signal_value_exclusive=(
            _policy_nonnegative_number(
                cfg["minimum_signal_value_exclusive"],
                f"{path}.minimum_signal_value_exclusive",
            )
            if threshold_present
            else None
        ),
        categories_any=categories,
        methods_any=methods,
        upload_outcomes_any=frozenset(optional_strings("upload_outcomes_any", lower=True)),
        source_ip_scopes_any=source_ip_scopes,
    )
    if condition.is_empty and not allow_empty:
        raise ValueError(f"{path}: expected at least one condition group")
    return condition


def _parse_referenced_file_correlation_policy(
    raw: Any,
    path: str,
    web_policy: WebRequestClassifierPolicy,
    supported_categories: frozenset[str],
) -> ReferencedFileCorrelationPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "stage", "executor", "enabled", "evidence_type",
            "inputs", "matching", "emissions", "propagation", "web",
            "web_outcome_merge", "mappings",
        },
    )
    _policy_enum(cfg["stage"], f"{path}.stage", {"contextual"})
    _policy_enum(
        cfg["executor"],
        f"{path}.executor",
        {"referenced_file_correlation"},
    )
    enabled = _policy_bool(cfg["enabled"], f"{path}.enabled")
    evidence_type = _policy_enum(
        cfg["evidence_type"],
        f"{path}.evidence_type",
        {"contextual"},
    )

    inputs_path = f"{path}.inputs"
    inputs = _policy_mapping(cfg["inputs"], inputs_path)
    _policy_keys(
        inputs,
        inputs_path,
        required={
            "current_path", "message", "execution_text_fields",
            "execution_path_fields", "web",
        },
    )
    current_path_field = _policy_string(inputs["current_path"], f"{inputs_path}.current_path")
    message_field = _policy_string(inputs["message"], f"{inputs_path}.message")
    execution_text_fields = _policy_string_list(
        inputs["execution_text_fields"],
        f"{inputs_path}.execution_text_fields",
    )
    execution_path_fields = _policy_string_list(
        inputs["execution_path_fields"],
        f"{inputs_path}.execution_path_fields",
    )
    web_inputs_path = f"{inputs_path}.web"
    web_inputs = _policy_mapping(inputs["web"], web_inputs_path)
    _policy_keys(
        web_inputs,
        web_inputs_path,
        required={
            "feature_fields", "attack_techniques",
        },
    )
    feature_path = f"{web_inputs_path}.feature_fields"
    feature_fields_cfg = _policy_mapping(web_inputs["feature_fields"], feature_path)
    _policy_keys(
        feature_fields_cfg,
        feature_path,
        required={"hit_types", "categories", "rules", "families"},
    )
    web_feature_fields = {
        name: _policy_string(value, f"{feature_path}.{name}")
        for name, value in feature_fields_cfg.items()
    }
    parser_field = web_policy.inputs.parser_field
    request_field = web_policy.inputs.request_field
    url_field = web_policy.inputs.url_field
    response_code_field = web_policy.inputs.response_code_field
    response_bytes_field = web_policy.inputs.response_bytes_field
    materialised_web_fields = {
        "upload_names": web_policy.outputs.upload_names_field,
        "upload_hashes": web_policy.outputs.upload_hashes_field,
        "upload_outcome": web_policy.outputs.upload_outcome_field,
        "web_outcome": web_policy.outputs.web_outcome_field,
        "attack_indicators": web_policy.outputs.attack_indicators_field,
        "source_ip": web_policy.outputs.source_ip_field,
        "method": web_policy.outputs.method_field,
        "endpoint": web_policy.outputs.endpoint_field,
        "status": web_policy.outputs.status_field,
        "attack_techniques": _policy_string(
            web_inputs["attack_techniques"], f"{web_inputs_path}.attack_techniques"
        ),
        **{f"feature_fields.{name}": value for name, value in web_feature_fields.items()},
    }
    invalid_materialised_fields = sorted(
        field_name
        for field_name in materialised_web_fields.values()
        if not field_name.startswith("chronosift_")
    )
    if invalid_materialised_fields:
        raise ValueError(
            f"{web_inputs_path}: materialised fields must use the 'chronosift_' "
            "sidecar namespace: " + ", ".join(invalid_materialised_fields)
        )
    canonical_fields_by_role = {
        "upload_names": "chronosift_web_upload_names",
        "upload_hashes": "chronosift_web_upload_hashes",
        "upload_outcome": "chronosift_web_upload_outcome",
        "web_outcome": "chronosift_web_outcome",
        "attack_indicators": "chronosift_web_attack_indicators",
        "source_ip": "chronosift_web_source_ip",
        "method": "chronosift_web_method",
        "endpoint": "chronosift_web_endpoint",
        "status": "chronosift_web_status_code",
        "attack_techniques": "chronosift_attack_techniques",
        "feature_fields.hit_types": "chronosift_web_file_hit_types",
        "feature_fields.categories": "chronosift_web_file_categories",
        "feature_fields.rules": "chronosift_web_file_rules",
        "feature_fields.families": "chronosift_web_file_families",
    }
    canonical_materialised_names = set(canonical_fields_by_role.values())
    misbound_canonical_fields = sorted(
        f"{role}={field_name}"
        for role, field_name in materialised_web_fields.items()
        if field_name in canonical_materialised_names
        and field_name != canonical_fields_by_role[role]
    )
    reserved_materialised_names = {
        CHRONOSIFT_ROW_ID_COLUMN,
        "chronosift_score",
        "chronosift_signals",
        "chronosift_explain",
        "chronosift_combined_command_text",
        "chronosift_dt_sort",
        "chronosift_activity_deficit_score",
        "chronosift_metadata",
        "chronosift_norm_hash",
        "chronosift_part_month",
        "chronosift_part_year",
        "chronosift_profile_metadata",
        "chronosift_quiet_hours_profile",
        "chronosift_row_id_sort",
        "chronosift_sparse",
        "chronosift_web_request_target",
        "chronosift_web_query",
        "chronosift_web_host",
        "chronosift_web_user_agent",
        "chronosift_web_referer",
        "chronosift_web_content_type",
        "chronosift_web_upload_name",
        "chronosift_web_upload_content_types",
        "chronosift_web_response_bytes",
        "chronosift_web_upload_count",
        "chronosift_web_request_body_bytes",
        "chronosift_web_is_event",
    }
    reserved_field_collisions = sorted(
        set(materialised_web_fields.values()) & reserved_materialised_names
    )
    if misbound_canonical_fields or reserved_field_collisions:
        details = [
            *(f"canonical role collision {value}" for value in misbound_canonical_fields),
            *(f"reserved field {value}" for value in reserved_field_collisions),
        ]
        raise ValueError(
            f"{web_inputs_path}: invalid materialised field binding(s): "
            + ", ".join(details)
        )
    duplicate_materialised_fields = sorted({
        field_name
        for field_name in materialised_web_fields.values()
        if list(materialised_web_fields.values()).count(field_name) > 1
    })
    if duplicate_materialised_fields:
        raise ValueError(
            f"{web_inputs_path}: materialised fields must be distinct: "
            + ", ".join(duplicate_materialised_fields)
        )
    raw_web_fields = {
        parser_field, request_field, url_field,
        response_code_field, response_bytes_field,
        current_path_field, message_field,
        *execution_text_fields, *execution_path_fields,
    }
    overlapping_web_fields = sorted(
        raw_web_fields & set(materialised_web_fields.values())
    )
    if overlapping_web_fields:
        raise ValueError(
            f"{web_inputs_path}: materialised fields may not overwrite raw inputs: "
            + ", ".join(overlapping_web_fields)
        )

    matching_path = f"{path}.matching"
    matching = _policy_mapping(cfg["matching"], matching_path)
    _policy_keys(
        matching,
        matching_path,
        required={
            "exclude_self_reference", "basename_fallback", "web_document_roots",
        },
    )
    document_roots = _policy_string_list_or_empty(
        matching["web_document_roots"],
        f"{matching_path}.web_document_roots",
    )
    web_log_parser_tokens = web_policy.web_log_parser_tokens
    upload_methods = web_policy.upload.upload_methods
    success_minimum = web_policy.outcomes.success_status_minimum
    success_maximum = web_policy.outcomes.success_status_maximum_exclusive

    emissions_path = f"{path}.emissions"
    emissions = _parse_referenced_file_emission_registry(
        cfg["emissions"], emissions_path
    )
    propagation_path = f"{path}.propagation"
    propagation_cfg = _policy_mapping(cfg["propagation"], propagation_path)
    unknown_hit_types = sorted(set(propagation_cfg) - _REFERENCED_FILE_HIT_TYPES)
    if unknown_hit_types:
        raise ValueError(
            f"{propagation_path}: unknown key(s): {', '.join(unknown_hit_types)}"
        )
    propagation_evidence_allowed = {
        "evidence_type", "signal_value", "target_filename", "source_path_count",
        "referenced_paths", "message",
    }
    propagation: Dict[str, ReferencedFilePropagationPolicy] = {}
    for hit_type in propagation_cfg:
        branch_path = f"{propagation_path}.{hit_type}"
        branch_cfg = _policy_mapping(propagation_cfg[hit_type], branch_path)
        _policy_keys(branch_cfg, branch_path, required={"emission", "evidence"})
        emission_id = _policy_string(
            branch_cfg["emission"], f"{branch_path}.emission"
        )
        if emission_id not in emissions:
            raise ValueError(
                f"{branch_path}.emission: unknown emission: {emission_id}"
            )
        propagation[hit_type] = ReferencedFilePropagationPolicy(
            hit_type=hit_type,
            emission_id=emission_id,
            evidence=_parse_policy_evidence_names(
                branch_cfg["evidence"],
                f"{branch_path}.evidence",
                propagation_evidence_allowed,
            ),
        )

    web_path = f"{path}.web"
    web_cfg = _policy_mapping(cfg["web"], web_path)
    web_evidence_allowed = {
        "evidence_type", "http_method", "http_path", "canonical_web_path",
        "http_response_code", "http_response_bytes", "upload_outcome",
        "file_hit_types", "file_categories", "yara_rules", "av_families",
        "yara_rule_metadata",
    }
    web_branches: List[ReferencedFileWebBranchPolicy] = []
    used_emission_ids = {
        branch.emission_id for branch in propagation.values()
    }
    for branch_id in web_cfg:
        _policy_signal_name(branch_id, f"{web_path} key")
        branch_path = f"{web_path}.{branch_id}"
        branch_cfg = _policy_mapping(web_cfg[branch_id], branch_path)
        _policy_keys(
            branch_cfg,
            branch_path,
            required={"source", "response", "emission", "evidence"},
            optional={"hit_types", "categories", "methods", "outcome"},
        )
        hit_types = frozenset(
            _policy_string_list(
                branch_cfg["hit_types"], f"{branch_path}.hit_types", lower=True
            ) if "hit_types" in branch_cfg else ()
        )
        invalid_hit_types = sorted(hit_types - _REFERENCED_FILE_HIT_TYPES)
        if invalid_hit_types:
            raise ValueError(
                f"{branch_path}.hit_types: unsupported value(s): {', '.join(invalid_hit_types)}"
            )
        categories = frozenset(
            _policy_string_list(
                branch_cfg["categories"], f"{branch_path}.categories", lower=True
            ) if "categories" in branch_cfg else ()
        )
        invalid_categories = sorted(categories - supported_categories)
        if invalid_categories:
            raise ValueError(
                f"{branch_path}.categories: unsupported value(s): {', '.join(invalid_categories)}"
            )
        methods = frozenset(
            value.upper()
            for value in (
                _policy_string_list(
                    branch_cfg["methods"], f"{branch_path}.methods"
                ) if "methods" in branch_cfg else ()
            )
        )
        invalid_methods = sorted(
            method for method in methods if not re.fullmatch(r"[A-Z]+", method)
        )
        if invalid_methods:
            raise ValueError(
                f"{branch_path}.methods: unsupported value(s): {', '.join(invalid_methods)}"
            )
        if not hit_types and not categories:
            raise ValueError(
                f"{branch_path}: expected hit_types and/or categories"
            )
        successful_outcome = ""
        other_outcome = ""
        if "outcome" in branch_cfg:
            outcome_path = f"{branch_path}.outcome"
            outcome_cfg = _policy_mapping(branch_cfg["outcome"], outcome_path)
            _policy_keys(
                outcome_cfg,
                outcome_path,
                required={"successful_response", "other"},
            )
            successful_outcome = _policy_string(
                outcome_cfg["successful_response"],
                f"{outcome_path}.successful_response",
            )
            other_outcome = _policy_string(outcome_cfg["other"], f"{outcome_path}.other")
        emission_id = _policy_string(
            branch_cfg["emission"], f"{branch_path}.emission"
        )
        if emission_id not in emissions:
            raise ValueError(
                f"{branch_path}.emission: unknown emission: {emission_id}"
            )
        used_emission_ids.add(emission_id)
        web_branches.append(
            ReferencedFileWebBranchPolicy(
                branch_id=branch_id,
                source=_policy_enum(
                    branch_cfg["source"],
                    f"{branch_path}.source",
                    {"access", "upload", "either"},
                ),
                hit_types=hit_types,
                categories=categories,
                methods=methods,
                response=_policy_enum(
                    branch_cfg["response"],
                    f"{branch_path}.response",
                    {"any", "successful"},
                ),
                emission_id=emission_id,
                evidence=_parse_policy_evidence_names(
                    branch_cfg["evidence"],
                    f"{branch_path}.evidence",
                    web_evidence_allowed,
                ),
                successful_outcome=successful_outcome,
                other_outcome=other_outcome,
            )
        )

    outcome_merge_path = f"{path}.web_outcome_merge"
    outcome_merge_cfg = _policy_mapping(
        cfg["web_outcome_merge"], outcome_merge_path
    )
    _policy_keys(
        outcome_merge_cfg,
        outcome_merge_path,
        required={"strategy", "ranks"},
    )
    outcome_merge_strategy = _policy_enum(
        outcome_merge_cfg["strategy"],
        f"{outcome_merge_path}.strategy",
        {"maximum_rank"},
    )
    ranks_path = f"{outcome_merge_path}.ranks"
    ranks_cfg = _policy_mapping(outcome_merge_cfg["ranks"], ranks_path)
    outcome_ranks = {
        _policy_string(name, f"{ranks_path} key"): _policy_nonnegative_int(
            rank, f"{ranks_path}.{name}"
        )
        for name, rank in ranks_cfg.items()
    }
    if len(set(outcome_ranks.values())) != len(outcome_ranks):
        raise ValueError(f"{ranks_path}: rank values must be distinct")
    referenced_outcome_values = {
        web_policy.outcomes.web_observed,
        web_policy.outcomes.web_attempt,
        web_policy.outcomes.web_probable_success,
        *(
            outcome
            for branch in web_branches
            for outcome in (branch.successful_outcome, branch.other_outcome)
            if outcome
        ),
    }
    missing_outcome_ranks = sorted(referenced_outcome_values - set(outcome_ranks))
    unused_outcome_ranks = sorted(set(outcome_ranks) - referenced_outcome_values)
    if missing_outcome_ranks or unused_outcome_ranks:
        details = [
            *(f"missing rank for {value}" for value in missing_outcome_ranks),
            *(f"unreferenced outcome {value}" for value in unused_outcome_ranks),
        ]
        raise ValueError(f"{ranks_path}: " + "; ".join(details))
    web_outcome_merge = RankedValueMergePolicy(
        strategy=outcome_merge_strategy,
        ranks=outcome_ranks,
    )
    unused_emission_ids = sorted(set(emissions) - used_emission_ids)
    if unused_emission_ids:
        raise ValueError(
            f"{path}: emission(s) are never referenced: "
            + ", ".join(unused_emission_ids)
        )

    mappings_path = f"{path}.mappings"
    mappings_cfg = _policy_mapping(cfg["mappings"], mappings_path)
    _policy_keys(
        mappings_cfg,
        mappings_path,
        required={"enabled", "outputs", "branches"},
    )
    mapping_enabled = _policy_bool(
        mappings_cfg["enabled"], f"{mappings_path}.enabled"
    )
    outputs_path = f"{mappings_path}.outputs"
    outputs_cfg = _policy_mapping(mappings_cfg["outputs"], outputs_path)
    if mapping_enabled and not outputs_cfg:
        raise ValueError(f"{outputs_path}: expected at least one output")
    mapping_outputs: Dict[str, WebMappingOutputPolicy] = {}
    for output_id in outputs_cfg:
        _policy_signal_name(output_id, f"{outputs_path} key")
        output_path = f"{outputs_path}.{output_id}"
        output_cfg = _policy_mapping(outputs_cfg[output_id], output_path)
        _policy_keys(
            output_cfg,
            output_path,
            required={"emission"},
            optional={"attack_technique_id"},
        )
        technique_id = ""
        if "attack_technique_id" in output_cfg:
            technique_id = _policy_string(
                output_cfg["attack_technique_id"],
                f"{output_path}.attack_technique_id",
            )
            if not re.fullmatch(r"T\d{4}(?:\.\d{3})?", technique_id):
                raise ValueError(
                    f"{output_path}.attack_technique_id: expected an ATT&CK technique ID"
                )
        mapping_outputs[output_id] = WebMappingOutputPolicy(
            output_id=output_id,
            emission=_parse_policy_emission(
                output_cfg["emission"],
                f"{output_path}.emission",
                include_explanation=True,
            ),
            attack_technique_id=technique_id,
        )

    branches_path = f"{mappings_path}.branches"
    branches_cfg = _policy_mapping(mappings_cfg["branches"], branches_path)
    if mapping_enabled and not branches_cfg:
        raise ValueError(f"{branches_path}: expected at least one branch")
    mapping_evidence_allowed = {
        "attack_technique_id", "http_method", "canonical_endpoint",
        "http_response_code", "attack_indicators", "file_categories",
        "source_ip", "upload_outcome",
    }
    mapping_branches: List[WebMappingBranchPolicy] = []
    used_mapping_outputs: Set[str] = set()
    for branch_id, raw_branch in branches_cfg.items():
        _policy_signal_name(branch_id, f"{branches_path} key")
        branch_path = f"{branches_path}.{branch_id}"
        branch_cfg = _policy_mapping(raw_branch, branch_path)
        _policy_keys(
            branch_cfg,
            branch_path,
            required={"conditions", "emissions", "evidence"},
            optional={"exclude"},
        )
        output_ids = _policy_string_list(
            branch_cfg["emissions"], f"{branch_path}.emissions"
        )
        unknown_branch_outputs = sorted(set(output_ids) - set(mapping_outputs))
        if unknown_branch_outputs:
            raise ValueError(
                f"{branch_path}.emissions: unknown output(s): "
                + ", ".join(unknown_branch_outputs)
            )
        branch_evidence = _parse_policy_evidence_names(
            branch_cfg["evidence"],
            f"{branch_path}.evidence",
            mapping_evidence_allowed,
        )
        branch_technique_ids = {
            mapping_outputs[output_id].attack_technique_id
            for output_id in output_ids
            if mapping_outputs[output_id].attack_technique_id
        }
        if (
            "attack_technique_id" in branch_evidence
            and any(
                not mapping_outputs[output_id].attack_technique_id
                for output_id in output_ids
            )
            and len(branch_technique_ids) != 1
        ):
            raise ValueError(
                f"{branch_path}.evidence: attack_technique_id is ambiguous for "
                "an output without its own technique ID"
            )
        used_mapping_outputs.update(output_ids)
        mapping_branches.append(
            WebMappingBranchPolicy(
                branch_id=branch_id,
                conditions=_parse_web_mapping_condition(
                    branch_cfg["conditions"],
                    f"{branch_path}.conditions",
                    supported_categories=supported_categories,
                ),
                exclude=(
                    _parse_web_mapping_condition(
                        branch_cfg["exclude"],
                        f"{branch_path}.exclude",
                        supported_categories=supported_categories,
                    )
                    if "exclude" in branch_cfg
                    else None
                ),
                output_ids=output_ids,
                evidence=branch_evidence,
            )
        )
    unused_mapping_outputs = sorted(set(mapping_outputs) - used_mapping_outputs)
    if unused_mapping_outputs:
        raise ValueError(
            f"{branches_path}: output(s) are never emitted: "
            + ", ".join(unused_mapping_outputs)
        )

    all_emission_names = [
        *(emission.name for emission in emissions.values()),
        *(output.emission.name for output in mapping_outputs.values()),
    ]
    duplicate_emission_names = sorted({
        name for name in all_emission_names if all_emission_names.count(name) > 1
    })
    if duplicate_emission_names:
        raise ValueError(
            f"{path}: duplicate emission name(s): "
            + ", ".join(duplicate_emission_names)
        )

    policy_digest = hashlib.sha256(
        json.dumps(
            cfg,
            # Branch registries are deliberately evaluated in YAML insertion
            # order, so their order is part of the policy's provenance.
            sort_keys=False,
            separators=(",", ":"),
            ensure_ascii=False,
        ).encode("utf-8")
    ).hexdigest()
    return ReferencedFileCorrelationPolicy(
        enabled=enabled,
        evidence_type=evidence_type,
        current_path_field=current_path_field,
        message_field=message_field,
        execution_text_fields=execution_text_fields,
        execution_path_fields=execution_path_fields,
        parser_field=parser_field,
        request_field=request_field,
        url_field=url_field,
        response_code_field=response_code_field,
        response_bytes_field=response_bytes_field,
        upload_names_field=materialised_web_fields["upload_names"],
        upload_hashes_field=materialised_web_fields["upload_hashes"],
        upload_outcome_field=materialised_web_fields["upload_outcome"],
        web_outcome_field=materialised_web_fields["web_outcome"],
        web_feature_fields=web_feature_fields,
        attack_indicators_field=materialised_web_fields["attack_indicators"],
        source_ip_field=materialised_web_fields["source_ip"],
        method_field=materialised_web_fields["method"],
        endpoint_field=materialised_web_fields["endpoint"],
        status_field=materialised_web_fields["status"],
        attack_techniques_field=materialised_web_fields["attack_techniques"],
        basename_fallback=_policy_enum(
            matching["basename_fallback"],
            f"{matching_path}.basename_fallback",
            {"disabled", "relative_only"},
        ),
        exclude_self_reference=_policy_bool(
            matching["exclude_self_reference"],
            f"{matching_path}.exclude_self_reference",
        ),
        document_roots=document_roots,
        web_log_parser_tokens=web_log_parser_tokens,
        upload_methods=upload_methods,
        success_status_minimum=success_minimum,
        success_status_maximum_exclusive=success_maximum,
        emissions_by_id=emissions,
        propagation=propagation,
        web_branches=tuple(web_branches),
        web_outcome_merge=web_outcome_merge,
        mapping_enabled=mapping_enabled,
        mapping_outputs=mapping_outputs,
        mapping_branches=tuple(mapping_branches),
        policy_digest=policy_digest,
    )


def _parse_webshell_artifact_policy(
    raw: Any,
    path: str,
) -> WebshellArtifactPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "stage", "executor", "enabled", "evidence_type",
            "inputs", "conditions", "emissions", "evidence",
        },
    )
    _policy_enum(cfg["stage"], f"{path}.stage", {"contextual"})
    _policy_enum(cfg["executor"], f"{path}.executor", {"webshell_artifact"})
    enabled = _policy_bool(cfg["enabled"], f"{path}.enabled")
    evidence_type = _policy_enum(
        cfg["evidence_type"], f"{path}.evidence_type", {"direct", "contextual"}
    )

    inputs_path = f"{path}.inputs"
    inputs = _policy_mapping(cfg["inputs"], inputs_path)
    _policy_keys(inputs, inputs_path, required={"path", "combined_text"})

    path_input_path = f"{inputs_path}.path"
    path_input = _policy_mapping(inputs["path"], path_input_path)
    _policy_keys(path_input, path_input_path, required={"resolver", "fields"})
    _policy_enum(
        path_input["resolver"],
        f"{path_input_path}.resolver",
        {"best_effort_file_path"},
    )
    path_fields = _policy_string_list(
        path_input["fields"], f"{path_input_path}.fields"
    )

    text_input_path = f"{inputs_path}.combined_text"
    text_input = _policy_mapping(inputs["combined_text"], text_input_path)
    _policy_keys(
        text_input,
        text_input_path,
        required={"resolver", "fields", "first_existing"},
    )
    _policy_enum(
        text_input["resolver"], f"{text_input_path}.resolver", {"concat_lower"}
    )
    text_fields = _policy_string_list(
        text_input["fields"], f"{text_input_path}.fields"
    )
    first_existing_text_fields = _policy_string_list(
        text_input["first_existing"], f"{text_input_path}.first_existing"
    )

    conditions_path = f"{path}.conditions"
    conditions = _policy_mapping(cfg["conditions"], conditions_path)
    _policy_keys(
        conditions,
        conditions_path,
        required={"path_contains", "extension_in", "support"},
    )
    path_patterns = _policy_string_list(
        conditions["path_contains"],
        f"{conditions_path}.path_contains",
        lower=True,
    )
    script_extensions = frozenset(
        _policy_string_list(
            conditions["extension_in"],
            f"{conditions_path}.extension_in",
            lower=True,
        )
    )
    invalid_extensions = sorted(
        extension
        for extension in script_extensions
        if not re.fullmatch(r"\.[a-z0-9][a-z0-9_+-]*", extension)
    )
    if invalid_extensions:
        raise ValueError(
            f"{conditions_path}.extension_in: unsupported extension(s): "
            + ", ".join(invalid_extensions)
        )

    support_path = f"{conditions_path}.support"
    support = _policy_mapping(conditions["support"], support_path)
    _policy_keys(
        support,
        support_path,
        required={
            "match", "basename_contains", "combined_text_contains",
            "signals_any", "minimum_signal_value_exclusive",
        },
    )
    support_match = _policy_enum(
        support["match"], f"{support_path}.match", {"any", "all"}
    )
    basename_tokens = _policy_string_list(
        support["basename_contains"],
        f"{support_path}.basename_contains",
        lower=True,
    )
    combined_text_tokens = _policy_string_list(
        support["combined_text_contains"],
        f"{support_path}.combined_text_contains",
        lower=True,
    )
    support_signals = frozenset(
        _policy_signal_list(support["signals_any"], f"{support_path}.signals_any")
    )
    minimum_signal_value_exclusive = _policy_nonnegative_number(
        support["minimum_signal_value_exclusive"],
        f"{support_path}.minimum_signal_value_exclusive",
    )

    emissions_path = f"{path}.emissions"
    if not isinstance(cfg["emissions"], list) or len(cfg["emissions"]) != 1:
        raise ValueError(f"{emissions_path}: expected exactly one emission")
    emission = _parse_policy_emission(
        cfg["emissions"][0],
        f"{emissions_path}[0]",
        include_explanation=True,
    )
    evidence = _parse_policy_evidence(
        cfg["evidence"],
        f"{path}.evidence",
        allowed_resolvers={
            "row_field", "first_nonempty", "best_effort_file_path",
            "matched_signals",
        },
    )
    return WebshellArtifactPolicy(
        enabled=enabled,
        path_fields=path_fields,
        text_fields=text_fields,
        first_existing_text_fields=first_existing_text_fields,
        path_patterns=path_patterns,
        script_extensions=script_extensions,
        support_match=support_match,
        basename_tokens=basename_tokens,
        combined_text_tokens=combined_text_tokens,
        support_signals=support_signals,
        minimum_signal_value_exclusive=minimum_signal_value_exclusive,
        emission=emission,
        evidence=evidence,
        evidence_type=evidence_type,
    )


def _parse_signal_gate_policy(
    raw: Any,
    path: str,
    *,
    allowed_stages: Iterable[str] = ("atomic", "contextual"),
) -> SignalGatePolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "stage", "executor", "enabled", "evidence_type",
            "inputs", "conditions", "emissions", "evidence",
        },
    )
    _policy_enum(cfg["stage"], f"{path}.stage", set(allowed_stages))
    _policy_enum(cfg["executor"], f"{path}.executor", {"signal_gate"})
    enabled = _policy_bool(cfg["enabled"], f"{path}.enabled")
    evidence_type = _policy_enum(
        cfg["evidence_type"],
        f"{path}.evidence_type",
        {"direct", "contextual"},
    )

    inputs_path = f"{path}.inputs"
    inputs = _policy_mapping(cfg["inputs"], inputs_path)
    _policy_keys(inputs, inputs_path, required={"signals"})
    input_signals = frozenset(
        _policy_signal_list(inputs["signals"], f"{inputs_path}.signals")
    )

    conditions_path = f"{path}.conditions"
    conditions = _policy_mapping(cfg["conditions"], conditions_path)
    _policy_keys(
        conditions,
        conditions_path,
        required={"match", "minimum_value_exclusive"},
        optional={"groups"},
    )
    match = _policy_enum(conditions["match"], f"{conditions_path}.match", {"any", "all"})
    minimum_value_exclusive = _policy_nonnegative_number(
        conditions["minimum_value_exclusive"],
        f"{conditions_path}.minimum_value_exclusive",
    )
    input_groups: Tuple[SignalGateInputGroupPolicy, ...]
    if "groups" in conditions:
        groups_path = f"{conditions_path}.groups"
        if not isinstance(conditions["groups"], list) or not conditions["groups"]:
            raise ValueError(f"{groups_path}: expected a non-empty list")
        parsed_groups: List[SignalGateInputGroupPolicy] = []
        grouped_signals: Set[str] = set()
        for group_index, raw_group in enumerate(conditions["groups"]):
            group_path = f"{groups_path}[{group_index}]"
            group = _policy_mapping(raw_group, group_path)
            _policy_keys(group, group_path, required={"match", "signals"})
            group_signals = frozenset(
                _policy_signal_list(group["signals"], f"{group_path}.signals")
            )
            undeclared = sorted(group_signals - input_signals)
            if undeclared:
                raise ValueError(
                    f"{group_path}.signals: signal(s) are not declared in inputs.signals: "
                    + ", ".join(undeclared)
                )
            duplicate_members = sorted(grouped_signals & set(group_signals))
            if duplicate_members:
                raise ValueError(
                    f"{group_path}.signals: signal(s) already belong to another group: "
                    + ", ".join(duplicate_members)
                )
            grouped_signals.update(group_signals)
            parsed_groups.append(
                SignalGateInputGroupPolicy(
                    signals=group_signals,
                    match=_policy_enum(
                        group["match"], f"{group_path}.match", {"any", "all"}
                    ),
                )
            )
        unused_inputs = sorted(input_signals - grouped_signals)
        if unused_inputs:
            raise ValueError(
                f"{groups_path}: input signal(s) are not assigned to a group: "
                + ", ".join(unused_inputs)
            )
        input_groups = tuple(parsed_groups)
    else:
        input_groups = (
            SignalGateInputGroupPolicy(signals=input_signals, match=match),
        )

    emissions_path = f"{path}.emissions"
    if not isinstance(cfg["emissions"], list) or not cfg["emissions"]:
        raise ValueError(f"{emissions_path}: expected a non-empty list")
    emissions = tuple(
        _parse_policy_emission(
            item,
            f"{emissions_path}[{index}]",
            include_explanation=True,
        )
        for index, item in enumerate(cfg["emissions"])
    )
    evidence = _parse_policy_evidence(
        cfg["evidence"],
        f"{path}.evidence",
        allowed_resolvers={
            "row_field",
            "first_nonempty",
            "best_effort_file_path",
            "matched_signals",
        },
    )
    return SignalGatePolicy(
        enabled=enabled,
        input_signals=input_signals,
        input_groups=input_groups,
        match=match,
        minimum_value_exclusive=minimum_value_exclusive,
        emissions=emissions,
        evidence=evidence,
        evidence_type=evidence_type,
    )


def _parse_named_policy_emissions(
    raw: Any,
    path: str,
    semantic_names: Iterable[str],
) -> Dict[str, DetectorEmissionPolicy]:
    cfg = _policy_mapping(raw, path)
    required_names = set(semantic_names)
    missing = sorted(required_names - set(cfg))
    unknown = sorted(set(cfg) - required_names)
    if missing:
        raise ValueError(f"{path}: missing required key(s): {', '.join(missing)}")
    if unknown:
        raise ValueError(f"{path}: unknown key(s): {', '.join(unknown)}")
    return {
        semantic: _parse_policy_emission(
            cfg[semantic],
            f"{path}.{semantic}",
            include_explanation=True,
        )
        for semantic in semantic_names
    }


def _parse_boolean_fact_decision(
    raw: Any,
    path: str,
    allowed_facts: Set[str],
) -> BooleanFactDecisionPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(cfg, path, required={"all", "any", "none"})

    def fact_list(value: Any, value_path: str) -> frozenset[str]:
        if not isinstance(value, list):
            raise ValueError(f"{value_path}: expected a list")
        parsed: List[str] = []
        for index, item in enumerate(value):
            fact = _policy_signal_name(item, f"{value_path}[{index}]")
            if fact not in allowed_facts:
                raise ValueError(
                    f"{value_path}[{index}]: unknown fact {fact!r}; expected "
                    + ", ".join(sorted(allowed_facts))
                )
            if fact in parsed:
                raise ValueError(
                    f"{value_path}[{index}]: duplicate fact {fact!r}"
                )
            parsed.append(fact)
        return frozenset(parsed)

    require_all = fact_list(cfg["all"], f"{path}.all")
    require_any = fact_list(cfg["any"], f"{path}.any")
    exclude_any = fact_list(cfg["none"], f"{path}.none")
    if not require_all and not require_any:
        raise ValueError(
            f"{path}: at least one fact is required in all or any"
        )
    overlaps = sorted(
        (set(require_all) | set(require_any)) & set(exclude_any)
    )
    if overlaps:
        raise ValueError(
            f"{path}: fact(s) cannot be both required and excluded: "
            + ", ".join(overlaps)
        )
    return BooleanFactDecisionPolicy(
        require_all=require_all,
        require_any=require_any,
        exclude_any=exclude_any,
    )


def _parse_boolean_fact_decisions(
    raw: Any,
    path: str,
    semantic_names: Iterable[str],
    allowed_facts: Set[str],
) -> Dict[str, BooleanFactDecisionPolicy]:
    cfg = _policy_mapping(raw, path)
    semantics = tuple(semantic_names)
    _policy_keys(cfg, path, required=set(semantics))

    decisions: Dict[str, BooleanFactDecisionPolicy] = {}
    for semantic in semantics:
        decision_path = f"{path}.{semantic}"
        decisions[semantic] = _parse_boolean_fact_decision(
            cfg[semantic], decision_path, allowed_facts
        )
    return decisions


def _parse_canonical_authentication_policy(
    raw: Any,
    path: str,
) -> CanonicalAuthenticationPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "stage", "executor", "enabled", "evidence_type",
            "inputs", "outcomes", "semantics", "eligibility", "decisions",
            "emissions", "evidence",
        },
    )
    _policy_enum(cfg["stage"], f"{path}.stage", {"atomic"})
    _policy_enum(
        cfg["executor"], f"{path}.executor", {"canonical_authentication"}
    )
    enabled = _policy_bool(cfg["enabled"], f"{path}.enabled")
    evidence_type = _policy_enum(
        cfg["evidence_type"], f"{path}.evidence_type", {"direct"}
    )
    inputs_path = f"{path}.inputs"
    inputs_cfg = _policy_mapping(cfg["inputs"], inputs_path)
    _policy_keys(inputs_cfg, inputs_path, required={"fields", "source_signals"})
    fields_path = f"{inputs_path}.fields"
    fields_cfg = _policy_mapping(inputs_cfg["fields"], fields_path)
    field_names = (
        "outcome", "protocol", "direction", "logon_type", "message",
        "authentication_package",
    )
    _policy_keys(fields_cfg, fields_path, required=set(field_names))
    fields = {
        name: _policy_string(fields_cfg[name], f"{fields_path}.{name}")
        for name in field_names
    }
    source_path = f"{inputs_path}.source_signals"
    source_cfg = _policy_mapping(inputs_cfg["source_signals"], source_path)
    _policy_keys(
        source_cfg,
        source_path,
        required={"success", "failure", "minimum_signal_value_exclusive"},
    )
    success_sources = frozenset(
        _policy_signal_list(source_cfg["success"], f"{source_path}.success")
    )
    failure_sources = frozenset(
        _policy_signal_list(source_cfg["failure"], f"{source_path}.failure")
    )

    outcomes_path = f"{path}.outcomes"
    outcomes_cfg = _policy_mapping(cfg["outcomes"], outcomes_path)
    _policy_keys(
        outcomes_cfg,
        outcomes_path,
        required={
            "success", "failure", "outcome_source_match",
            "conflict_resolution",
        },
    )
    success_value = _policy_string(
        outcomes_cfg["success"], f"{outcomes_path}.success", lower=True
    )
    failure_value = _policy_string(
        outcomes_cfg["failure"], f"{outcomes_path}.failure", lower=True
    )
    if success_value == failure_value:
        raise ValueError(f"{outcomes_path}: success and failure must differ")
    outcome_source_match = _policy_enum(
        outcomes_cfg["outcome_source_match"],
        f"{outcomes_path}.outcome_source_match",
        {"all", "any"},
    )
    conflict_resolution = _policy_enum(
        outcomes_cfg["conflict_resolution"],
        f"{outcomes_path}.conflict_resolution",
        {"allow_both", "prefer_failure", "prefer_success", "suppress_both"},
    )

    semantics_path = f"{path}.semantics"
    semantics_cfg = _policy_mapping(cfg["semantics"], semantics_path)
    semantic_names = (
        "remote", "remote_interactive", "remote_shell", "invalid_user",
        "new_credentials", "service_logon", "ntlm_remote",
        "lateral_movement",
    )
    _policy_keys(semantics_cfg, semantics_path, required=set(semantic_names))

    def semantic_mapping(name: str, required: Set[str]) -> Dict[str, Any]:
        semantic_path = f"{semantics_path}.{name}"
        semantic_cfg = _policy_mapping(semantics_cfg[name], semantic_path)
        _policy_keys(semantic_cfg, semantic_path, required=required)
        return semantic_cfg

    remote_cfg = semantic_mapping(
        "remote", {"match", "direction_values", "protocol_values"}
    )
    interactive_cfg = semantic_mapping(
        "remote_interactive", {"match", "protocol_values", "logon_types"}
    )
    shell_cfg = semantic_mapping("remote_shell", {"protocol_values"})
    invalid_cfg = semantic_mapping("invalid_user", {"message_contains"})
    new_credentials_cfg = semantic_mapping(
        "new_credentials", {"logon_types"}
    )
    service_cfg = semantic_mapping("service_logon", {"logon_types"})
    ntlm_cfg = semantic_mapping(
        "ntlm_remote", {"authentication_packages"}
    )
    lateral_cfg = semantic_mapping(
        "lateral_movement",
        {
            "include_remote", "logon_types", "authentication_packages",
            "minimum_matches",
        },
    )
    lateral_include_remote = _policy_bool(
        lateral_cfg["include_remote"],
        f"{semantics_path}.lateral_movement.include_remote",
    )
    lateral_minimum = _policy_positive_int(
        lateral_cfg["minimum_matches"],
        f"{semantics_path}.lateral_movement.minimum_matches",
    )
    lateral_factor_count = 2 + int(lateral_include_remote)
    if lateral_minimum > lateral_factor_count:
        raise ValueError(
            f"{semantics_path}.lateral_movement.minimum_matches: maximum is "
            f"{lateral_factor_count}"
        )
    emission_semantics = (
        "success", "failure", "remote_success", "remote_failure",
        "local_success", "local_failure", "remote_interactive_success",
        "remote_shell_success", "invalid_user", "new_credentials_logon",
        "service_logon", "ntlm_remote", "lateral_movement",
    )
    decision_facts = {
        "success", "failure", "remote", "remote_interactive",
        "remote_shell", "invalid_user", "new_credentials",
        "service_logon", "ntlm_package", "lateral_movement",
    }
    decisions = _parse_boolean_fact_decisions(
        cfg["decisions"],
        f"{path}.decisions",
        emission_semantics,
        decision_facts,
    )
    evidence = _policy_string_list(cfg["evidence"], f"{path}.evidence")
    unsupported_evidence = sorted(set(evidence) - {"derived_from"})
    if unsupported_evidence:
        raise ValueError(
            f"{path}.evidence: unsupported value(s): "
            + ", ".join(unsupported_evidence)
        )
    return CanonicalAuthenticationPolicy(
        enabled=enabled,
        outcome_field=fields["outcome"],
        protocol_field=fields["protocol"],
        direction_field=fields["direction"],
        logon_type_field=fields["logon_type"],
        message_field=fields["message"],
        authentication_package_field=fields["authentication_package"],
        success_sources=success_sources,
        failure_sources=failure_sources,
        source_minimum_signal_value_exclusive=_policy_nonnegative_number(
            source_cfg["minimum_signal_value_exclusive"],
            f"{source_path}.minimum_signal_value_exclusive",
        ),
        success_value=success_value,
        failure_value=failure_value,
        outcome_source_match=outcome_source_match,
        conflict_resolution=conflict_resolution,
        remote_direction_values=frozenset(_policy_string_list(
            remote_cfg["direction_values"],
            f"{semantics_path}.remote.direction_values", lower=True,
        )),
        remote_protocol_values=frozenset(_policy_string_list(
            remote_cfg["protocol_values"],
            f"{semantics_path}.remote.protocol_values", lower=True,
        )),
        remote_match=_policy_enum(
            remote_cfg["match"],
            f"{semantics_path}.remote.match",
            {"all", "any"},
        ),
        remote_interactive_protocol_values=frozenset(_policy_string_list(
            interactive_cfg["protocol_values"],
            f"{semantics_path}.remote_interactive.protocol_values", lower=True,
        )),
        remote_interactive_logon_types=frozenset(_policy_string_list(
            interactive_cfg["logon_types"],
            f"{semantics_path}.remote_interactive.logon_types",
        )),
        remote_interactive_match=_policy_enum(
            interactive_cfg["match"],
            f"{semantics_path}.remote_interactive.match",
            {"all", "any"},
        ),
        remote_shell_protocol_values=frozenset(_policy_string_list(
            shell_cfg["protocol_values"],
            f"{semantics_path}.remote_shell.protocol_values", lower=True,
        )),
        invalid_user_tokens=_policy_string_list(
            invalid_cfg["message_contains"],
            f"{semantics_path}.invalid_user.message_contains", lower=True,
        ),
        new_credentials_logon_types=frozenset(_policy_string_list(
            new_credentials_cfg["logon_types"],
            f"{semantics_path}.new_credentials.logon_types",
        )),
        service_logon_types=frozenset(_policy_string_list(
            service_cfg["logon_types"],
            f"{semantics_path}.service_logon.logon_types",
        )),
        ntlm_authentication_packages=frozenset(_policy_string_list(
            ntlm_cfg["authentication_packages"],
            f"{semantics_path}.ntlm_remote.authentication_packages", lower=True,
        )),
        lateral_include_remote=lateral_include_remote,
        lateral_logon_types=frozenset(_policy_string_list(
            lateral_cfg["logon_types"],
            f"{semantics_path}.lateral_movement.logon_types",
        )),
        lateral_authentication_packages=frozenset(_policy_string_list(
            lateral_cfg["authentication_packages"],
            f"{semantics_path}.lateral_movement.authentication_packages",
            lower=True,
        )),
        lateral_minimum_matches=lateral_minimum,
        eligibility=_parse_boolean_fact_decision(
            cfg["eligibility"], f"{path}.eligibility", decision_facts
        ),
        decisions_by_semantic=decisions,
        emissions_by_semantic=_parse_named_policy_emissions(
            cfg["emissions"], f"{path}.emissions", emission_semantics
        ),
        evidence=evidence,
        evidence_type=evidence_type,
    )


def _parse_execution_context_classifier_policy(
    raw: Any,
    path: str,
) -> ExecutionContextClassifierPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "stage", "executor", "enabled", "evidence_type",
            "inputs", "classification", "decisions", "emissions", "evidence",
        },
    )
    _policy_enum(cfg["stage"], f"{path}.stage", {"atomic"})
    _policy_enum(
        cfg["executor"], f"{path}.executor", {"execution_context_classifier"}
    )
    enabled = _policy_bool(cfg["enabled"], f"{path}.enabled")
    evidence_type = _policy_enum(
        cfg["evidence_type"], f"{path}.evidence_type", {"direct"}
    )
    inputs_path = f"{path}.inputs"
    inputs_cfg = _policy_mapping(cfg["inputs"], inputs_path)
    _policy_keys(inputs_cfg, inputs_path, required={"path", "command", "actor"})

    def first_nonempty_fields(name: str) -> Tuple[str, ...]:
        input_path = f"{inputs_path}.{name}"
        input_cfg = _policy_mapping(inputs_cfg[name], input_path)
        _policy_keys(input_cfg, input_path, required={"resolver", "fields"})
        _policy_enum(
            input_cfg["resolver"], f"{input_path}.resolver", {"first_nonempty"}
        )
        return _policy_string_list(input_cfg["fields"], f"{input_path}.fields")

    classification_path = f"{path}.classification"
    classification_cfg = _policy_mapping(
        cfg["classification"], classification_path
    )
    class_names = (
        "temporary_path_contains", "user_writable_path_contains",
        "suspicious_path_contains", "system_binary_names", "command_names",
        "privileged_actors", "suid_regex",
    )
    _policy_keys(classification_cfg, classification_path, required=set(class_names))
    command_path = f"{classification_path}.command_names"
    command_cfg = _policy_mapping(
        classification_cfg["command_names"], command_path
    )
    _policy_keys(
        command_cfg,
        command_path,
        required={"compiler", "shell", "network", "archive"},
    )
    suid_pattern_text = _policy_string(
        classification_cfg["suid_regex"], f"{classification_path}.suid_regex"
    )
    try:
        suid_pattern = re.compile(suid_pattern_text)
    except re.error as exc:
        raise ValueError(
            f"{classification_path}.suid_regex: invalid regular expression: {exc}"
        ) from exc
    emission_semantics = (
        "from_tmp", "from_user_writable", "suspicious_path",
        "system_binary_in_user_path", "compiler_activity", "shell_spawn",
        "network_tool", "archive_tool", "privileged_context",
        "new_suid_binary",
    )
    decision_facts = {
        "temporary_path", "user_writable_path", "suspicious_path",
        "system_binary_name", "compiler_command", "shell_command",
        "network_command", "archive_command", "privileged_actor",
        "suid_command",
    }
    decisions = _parse_boolean_fact_decisions(
        cfg["decisions"],
        f"{path}.decisions",
        emission_semantics,
        decision_facts,
    )
    evidence = _policy_string_list(cfg["evidence"], f"{path}.evidence")
    unsupported_evidence = sorted(
        set(evidence) - {"path", "command", "actor_user", "derived_from"}
    )
    if unsupported_evidence:
        raise ValueError(
            f"{path}.evidence: unsupported value(s): "
            + ", ".join(unsupported_evidence)
        )
    return ExecutionContextClassifierPolicy(
        enabled=enabled,
        path_fields=first_nonempty_fields("path"),
        command_fields=first_nonempty_fields("command"),
        actor_fields=first_nonempty_fields("actor"),
        temporary_path_tokens=tuple(
            token.replace("\\", "/")
            for token in _policy_string_list(
                classification_cfg["temporary_path_contains"],
                f"{classification_path}.temporary_path_contains", lower=True,
            )
        ),
        user_writable_path_tokens=tuple(
            token.replace("\\", "/")
            for token in _policy_string_list(
                classification_cfg["user_writable_path_contains"],
                f"{classification_path}.user_writable_path_contains", lower=True,
            )
        ),
        suspicious_path_tokens=tuple(
            token.replace("\\", "/")
            for token in _policy_string_list(
                classification_cfg["suspicious_path_contains"],
                f"{classification_path}.suspicious_path_contains", lower=True,
            )
        ),
        system_binary_names=frozenset(_policy_string_list(
            classification_cfg["system_binary_names"],
            f"{classification_path}.system_binary_names", lower=True,
        )),
        compiler_names=frozenset(_policy_string_list(
            command_cfg["compiler"], f"{command_path}.compiler", lower=True,
        )),
        shell_names=frozenset(_policy_string_list(
            command_cfg["shell"], f"{command_path}.shell", lower=True,
        )),
        network_tool_names=frozenset(_policy_string_list(
            command_cfg["network"], f"{command_path}.network", lower=True,
        )),
        archive_tool_names=frozenset(_policy_string_list(
            command_cfg["archive"], f"{command_path}.archive", lower=True,
        )),
        privileged_actors=frozenset(_policy_string_list(
            classification_cfg["privileged_actors"],
            f"{classification_path}.privileged_actors", lower=True,
        )),
        suid_pattern=suid_pattern,
        decisions_by_semantic=decisions,
        emissions_by_semantic=_parse_named_policy_emissions(
            cfg["emissions"], f"{path}.emissions", emission_semantics
        ),
        evidence=evidence,
        evidence_type=evidence_type,
    )


def _parse_row_inputs(raw: Any, path: str) -> Dict[str, RowInputPolicy]:
    inputs_cfg = _policy_mapping(raw, path)
    if not inputs_cfg:
        raise ValueError(f"{path}: expected at least one configured input")
    inputs: Dict[str, RowInputPolicy] = {}
    for input_name_raw, raw_input in inputs_cfg.items():
        input_name = _policy_signal_name(
            input_name_raw, f"{path} key"
        )
        input_path = f"{path}.{input_name}"
        input_cfg = _policy_mapping(raw_input, input_path)
        resolver = _policy_enum(
            input_cfg.get("resolver"),
            f"{input_path}.resolver",
            {
                "row_field", "best_effort_file_path", "first_nonempty",
                "concat", "timestamp_kind",
            },
        )
        required_keys = {"resolver", "fields", "normalise"}
        optional_keys: Set[str] = set()
        if resolver == "concat":
            optional_keys.add("first_existing")
        if resolver == "timestamp_kind":
            required_keys.add("kinds")
        _policy_keys(
            input_cfg,
            input_path,
            required=required_keys,
            optional=optional_keys,
        )
        fields = _policy_string_list(
            input_cfg["fields"], f"{input_path}.fields"
        )
        if resolver in {"row_field", "timestamp_kind"} and len(fields) != 1:
            raise ValueError(
                f"{input_path}.fields: resolver {resolver!r} requires exactly one field"
            )
        normalise = _policy_enum(
            input_cfg["normalise"],
            f"{input_path}.normalise",
            {"none", "lower", "path_lower"},
        )
        first_existing = (
            _policy_string_list(
                input_cfg["first_existing"], f"{input_path}.first_existing"
            )
            if resolver == "concat" and "first_existing" in input_cfg
            else ()
        )
        kind_priority: Tuple[str, ...] = ()
        kind_tokens: Dict[str, Tuple[str, ...]] = {}
        if resolver == "timestamp_kind":
            kinds_path = f"{input_path}.kinds"
            kinds_cfg = _policy_mapping(input_cfg["kinds"], kinds_path)
            _policy_keys(kinds_cfg, kinds_path, required={"priority", "contains"})
            kind_priority = _policy_string_list(
                kinds_cfg["priority"], f"{kinds_path}.priority", lower=True
            )
            if len(kind_priority) != len(set(kind_priority)):
                raise ValueError(f"{kinds_path}.priority: duplicate kind name")
            contains_path = f"{kinds_path}.contains"
            contains_cfg = _policy_mapping(kinds_cfg["contains"], contains_path)
            _policy_keys(
                contains_cfg, contains_path, required=set(kind_priority)
            )
            kind_tokens = {
                name: _policy_string_list(
                    contains_cfg[name], f"{contains_path}.{name}", lower=True
                )
                for name in kind_priority
            }
        inputs[input_name] = RowInputPolicy(
            resolver=resolver,
            fields=fields,
            normalise=normalise,
            first_existing_fields=first_existing,
            timestamp_kind_priority=kind_priority,
            timestamp_kind_tokens=kind_tokens,
        )
    return inputs


def _parse_row_predicate(
    raw: Any,
    path: str,
    inputs: Dict[str, RowInputPolicy],
) -> RowPredicatePolicy:
    predicate_cfg = _policy_mapping(raw, path)
    combinators = set(predicate_cfg) & {"all", "any", "not", "at_least"}
    if combinators:
        if len(predicate_cfg) != 1 or len(combinators) != 1:
            raise ValueError(
                f"{path}: expected exactly one expression combinator"
            )
        operator = next(iter(combinators))
        raw_children = predicate_cfg[operator]
        minimum_count = 0
        if operator == "not":
            children = (
                _parse_row_predicate(raw_children, f"{path}.not", inputs),
            )
        elif operator == "at_least":
            at_path = f"{path}.at_least"
            at_cfg = _policy_mapping(raw_children, at_path)
            _policy_keys(at_cfg, at_path, required={"count", "conditions"})
            minimum_count = _policy_positive_int(
                at_cfg["count"], f"{at_path}.count"
            )
            raw_conditions = at_cfg["conditions"]
            if not isinstance(raw_conditions, list) or not raw_conditions:
                raise ValueError(f"{at_path}.conditions: expected a non-empty list")
            children = tuple(
                _parse_row_predicate(
                    item, f"{at_path}.conditions[{index}]", inputs
                )
                for index, item in enumerate(raw_conditions)
            )
            if minimum_count > len(children):
                raise ValueError(
                    f"{at_path}.count: cannot exceed number of conditions"
                )
        else:
            if not isinstance(raw_children, list) or not raw_children:
                raise ValueError(
                    f"{path}.{operator}: expected a non-empty list"
                )
            children = tuple(
                _parse_row_predicate(
                    item, f"{path}.{operator}[{index}]", inputs
                )
                for index, item in enumerate(raw_children)
            )
        return RowPredicatePolicy(
            operator=operator,
            children=children,
            minimum_count=minimum_count,
        )

    op = _policy_enum(
        predicate_cfg.get("op"),
        f"{path}.op",
        {
            "contains_any", "equals_any", "starts_with_any",
            "ends_with_any", "regex", "nonempty",
            "signal_any_positive", "signal_all_positive",
        },
    )
    if op in {"signal_any_positive", "signal_all_positive"}:
        _policy_keys(
            predicate_cfg,
            path,
            required={"op", "signals", "minimum_value_exclusive"},
        )
        return RowPredicatePolicy(
            operator=op,
            signals=frozenset(_policy_signal_list(
                predicate_cfg["signals"], f"{path}.signals"
            )),
            minimum_value_exclusive=_policy_nonnegative_number(
                predicate_cfg["minimum_value_exclusive"],
                f"{path}.minimum_value_exclusive",
            ),
        )

    required = {"input", "op"}
    if op in {
        "contains_any", "equals_any", "starts_with_any", "ends_with_any"
    }:
        required.add("values")
    elif op == "regex":
        required.add("pattern")
    _policy_keys(predicate_cfg, path, required=required)
    input_name = _policy_signal_name(
        predicate_cfg["input"], f"{path}.input"
    )
    if input_name not in inputs:
        raise ValueError(
            f"{path}.input: unknown configured input {input_name!r}"
        )
    values: Tuple[str, ...] = ()
    pattern: Optional[re.Pattern[str]] = None
    if "values" in required:
        values = _policy_literal_string_list(
            predicate_cfg["values"], f"{path}.values"
        )
    elif op == "regex":
        pattern_text = _policy_string(
            predicate_cfg["pattern"], f"{path}.pattern"
        )
        try:
            pattern = re.compile(pattern_text)
        except re.error as exc:
            raise ValueError(
                f"{path}.pattern: invalid regular expression: {exc}"
            ) from exc
    return RowPredicatePolicy(
        operator=op,
        input_name=input_name,
        values=values,
        pattern=pattern,
    )


def _parse_ordered_row_rules_policy(
    raw: Any,
    path: str,
) -> OrderedRowRulesPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "stage", "executor", "enabled", "phase", "evidence_type",
            "inputs", "ordered_rules", "emissions", "evidence",
        },
    )
    _policy_enum(cfg["stage"], f"{path}.stage", {"contextual"})
    _policy_enum(cfg["executor"], f"{path}.executor", {"ordered_row_rules"})
    enabled = _policy_bool(cfg["enabled"], f"{path}.enabled")
    execution_phase = _policy_positive_int(cfg["phase"], f"{path}.phase")
    evidence_type = _policy_enum(
        cfg["evidence_type"], f"{path}.evidence_type", {"direct"}
    )

    inputs = _parse_row_inputs(cfg["inputs"], f"{path}.inputs")

    emissions_path = f"{path}.emissions"
    emissions_cfg = _policy_mapping(cfg["emissions"], emissions_path)
    if not emissions_cfg:
        raise ValueError(f"{emissions_path}: expected at least one emission")
    emissions: Dict[str, DetectorEmissionPolicy] = {}
    for emission_id_raw, raw_emission in emissions_cfg.items():
        emission_id = _policy_signal_name(
            emission_id_raw, f"{emissions_path} key"
        )
        emissions[emission_id] = _parse_policy_emission(
            raw_emission,
            f"{emissions_path}.{emission_id}",
            include_explanation=True,
        )

    evidence_path = f"{path}.evidence"
    evidence_cfg = _policy_mapping(cfg["evidence"], evidence_path)
    if not evidence_cfg:
        raise ValueError(f"{evidence_path}: expected at least one evidence resolver")
    evidence: Dict[str, RowEvidencePolicy] = {}
    for evidence_name_raw, raw_evidence in evidence_cfg.items():
        evidence_name = _policy_signal_name(
            evidence_name_raw, f"{evidence_path} key"
        )
        item_path = f"{evidence_path}.{evidence_name}"
        item_cfg = _policy_mapping(raw_evidence, item_path)
        resolver = _policy_enum(
            item_cfg.get("resolver"),
            f"{item_path}.resolver",
            {"input", "regex_capture"},
        )
        required = {"resolver", "input"}
        if resolver == "regex_capture":
            required.add("pattern")
        optional = {"max_chars"}
        _policy_keys(item_cfg, item_path, required=required, optional=optional)
        input_name = _policy_signal_name(
            item_cfg["input"], f"{item_path}.input"
        )
        if input_name not in inputs:
            raise ValueError(
                f"{item_path}.input: unknown configured input {input_name!r}"
            )
        pattern = None
        if resolver == "regex_capture":
            pattern_text = _policy_string(
                item_cfg["pattern"], f"{item_path}.pattern"
            )
            try:
                pattern = re.compile(pattern_text)
            except re.error as exc:
                raise ValueError(
                    f"{item_path}.pattern: invalid regular expression: {exc}"
                ) from exc
        max_chars = (
            _policy_positive_int(item_cfg["max_chars"], f"{item_path}.max_chars")
            if "max_chars" in item_cfg
            else None
        )
        evidence[evidence_name] = RowEvidencePolicy(
            resolver=resolver,
            input_name=input_name,
            pattern=pattern,
            max_chars=max_chars,
        )

    rules_path = f"{path}.ordered_rules"
    raw_rules = cfg["ordered_rules"]
    if not isinstance(raw_rules, list) or not raw_rules:
        raise ValueError(f"{rules_path}: expected a non-empty list")
    rules: List[OrderedRowRulePolicy] = []
    seen_rule_ids: Set[str] = set()
    referenced_emissions: Set[str] = set()
    for rule_index, raw_rule in enumerate(raw_rules):
        rule_path = f"{rules_path}[{rule_index}]"
        rule_cfg = _policy_mapping(raw_rule, rule_path)
        _policy_keys(
            rule_cfg,
            rule_path,
            required={
                "id", "when", "emission", "description", "confidence",
                "evidence",
            },
        )
        rule_id = _policy_signal_name(rule_cfg["id"], f"{rule_path}.id")
        if rule_id in seen_rule_ids:
            raise ValueError(f"{rule_path}.id: duplicate rule id {rule_id!r}")
        seen_rule_ids.add(rule_id)
        emission_id = _policy_signal_name(
            rule_cfg["emission"], f"{rule_path}.emission"
        )
        if emission_id not in emissions:
            raise ValueError(
                f"{rule_path}.emission: unknown emission id {emission_id!r}"
            )
        evidence_names = _policy_string_list(
            rule_cfg["evidence"], f"{rule_path}.evidence"
        )
        unknown_evidence = sorted(set(evidence_names) - set(evidence))
        if unknown_evidence:
            raise ValueError(
                f"{rule_path}.evidence: unknown resolver(s): "
                + ", ".join(unknown_evidence)
            )
        rules.append(OrderedRowRulePolicy(
            rule_id=rule_id,
            predicate=_parse_row_predicate(
                rule_cfg["when"], f"{rule_path}.when", inputs
            ),
            emission_id=emission_id,
            description=_policy_string(
                rule_cfg["description"], f"{rule_path}.description"
            ),
            confidence=_policy_confidence(
                rule_cfg["confidence"], f"{rule_path}.confidence"
            ),
            evidence=evidence_names,
        ))
        referenced_emissions.add(emission_id)
    unused_emissions = sorted(set(emissions) - referenced_emissions)
    if unused_emissions:
        raise ValueError(
            f"{emissions_path}: emission id(s) are never referenced: "
            + ", ".join(unused_emissions)
        )

    output_names = {emission.name for emission in emissions.values()}
    produced_before: Set[str] = set()
    external_signals: Set[str] = set()
    for rule_index, rule in enumerate(rules):
        referenced_signals = set(rule.predicate.input_signals)
        invalid_internal = sorted(
            (referenced_signals & output_names) - produced_before
        )
        if invalid_internal:
            raise ValueError(
                f"{rules_path}[{rule_index}].when: same-policy signal(s) are "
                "not produced by an earlier ordered rule: "
                + ", ".join(invalid_internal)
            )
        external_signals.update(referenced_signals - output_names)
        produced_before.add(emissions[rule.emission_id].name)

    return OrderedRowRulesPolicy(
        enabled=enabled,
        execution_phase=execution_phase,
        inputs=inputs,
        rules=tuple(rules),
        emissions_by_id=emissions,
        evidence=evidence,
        external_input_signals=frozenset(external_signals),
        evidence_type=evidence_type,
    )


def _parse_ordered_signal_adjustments_policy(
    raw: Any,
    path: str,
) -> OrderedSignalAdjustmentsPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "stage", "executor", "enabled", "phase", "evidence_type",
            "inputs", "ordered_rules", "evidence",
        },
    )
    _policy_enum(cfg["stage"], f"{path}.stage", {"contextual"})
    _policy_enum(
        cfg["executor"],
        f"{path}.executor",
        {"ordered_signal_adjustments"},
    )
    enabled = _policy_bool(cfg["enabled"], f"{path}.enabled")
    execution_phase = _policy_positive_int(cfg["phase"], f"{path}.phase")
    evidence_type = _policy_enum(
        cfg["evidence_type"], f"{path}.evidence_type", {"contextual"}
    )
    inputs = _parse_row_inputs(cfg["inputs"], f"{path}.inputs")

    evidence_path = f"{path}.evidence"
    evidence_cfg = _policy_mapping(cfg["evidence"], evidence_path)
    if not evidence_cfg:
        raise ValueError(f"{evidence_path}: expected at least one evidence resolver")
    evidence: Dict[str, SignalAdjustmentEvidencePolicy] = {}
    for evidence_name_raw, raw_evidence in evidence_cfg.items():
        evidence_name = _policy_signal_name(
            evidence_name_raw, f"{evidence_path} key"
        )
        item_path = f"{evidence_path}.{evidence_name}"
        item_cfg = _policy_mapping(raw_evidence, item_path)
        resolver = _policy_enum(
            item_cfg.get("resolver"),
            f"{item_path}.resolver",
            {
                "input", "changed_signals", "preserved_positive_signals",
                "action_multiplier",
            },
        )
        required = {"resolver"}
        optional = {"max_chars"}
        input_name = ""
        if resolver == "input":
            required.add("input")
            input_name = _policy_signal_name(
                item_cfg.get("input"), f"{item_path}.input"
            )
            if input_name not in inputs:
                raise ValueError(
                    f"{item_path}.input: unknown configured input {input_name!r}"
                )
        _policy_keys(
            item_cfg,
            item_path,
            required=required,
            optional=optional,
        )
        max_chars = (
            _policy_positive_int(item_cfg["max_chars"], f"{item_path}.max_chars")
            if "max_chars" in item_cfg
            else None
        )
        evidence[evidence_name] = SignalAdjustmentEvidencePolicy(
            resolver=resolver,
            input_name=input_name,
            max_chars=max_chars,
        )

    rules_path = f"{path}.ordered_rules"
    raw_rules = cfg["ordered_rules"]
    if not isinstance(raw_rules, list) or not raw_rules:
        raise ValueError(f"{rules_path}: expected a non-empty list")
    rules: List[OrderedSignalAdjustmentRulePolicy] = []
    seen_rule_ids: Set[str] = set()
    external_signals: Set[str] = set()
    for rule_index, raw_rule in enumerate(raw_rules):
        rule_path = f"{rules_path}[{rule_index}]"
        rule_cfg = _policy_mapping(raw_rule, rule_path)
        _policy_keys(
            rule_cfg,
            rule_path,
            required={
                "id", "when", "signal_conditions", "target_signals",
                "action", "explanation", "evidence",
            },
        )
        config_rule_id = _policy_signal_name(
            rule_cfg["id"], f"{rule_path}.id"
        )
        if config_rule_id in seen_rule_ids:
            raise ValueError(
                f"{rule_path}.id: duplicate rule id {config_rule_id!r}"
            )
        seen_rule_ids.add(config_rule_id)
        predicate = _parse_row_predicate(
            rule_cfg["when"], f"{rule_path}.when", inputs
        )

        conditions_path = f"{rule_path}.signal_conditions"
        conditions_cfg = _policy_mapping(
            rule_cfg["signal_conditions"], conditions_path
        )
        condition_names = {
            "minimum_value_exclusive", "required_any", "required_all",
            "forbidden_any", "preserved",
        }
        _policy_keys(
            conditions_cfg,
            conditions_path,
            required={"minimum_value_exclusive"},
            optional=condition_names - {"minimum_value_exclusive"},
        )

        def condition_signals(name: str) -> frozenset[str]:
            return (
                frozenset(_policy_signal_list(
                    conditions_cfg[name], f"{conditions_path}.{name}"
                ))
                if name in conditions_cfg
                else frozenset()
            )

        conditions = SignalAdjustmentConditionsPolicy(
            minimum_value_exclusive=_policy_nonnegative_number(
                conditions_cfg["minimum_value_exclusive"],
                f"{conditions_path}.minimum_value_exclusive",
            ),
            required_any=condition_signals("required_any"),
            required_all=condition_signals("required_all"),
            forbidden_any=condition_signals("forbidden_any"),
            preserved=condition_signals("preserved"),
        )
        target_signals = _policy_signal_list(
            rule_cfg["target_signals"], f"{rule_path}.target_signals"
        )
        preserved_targets = sorted(
            set(target_signals) & conditions.preserved
        )
        if preserved_targets:
            raise ValueError(
                f"{rule_path}: target_signals and signal_conditions.preserved "
                "must be disjoint: " + ", ".join(preserved_targets)
            )

        action_path = f"{rule_path}.action"
        action_cfg = _policy_mapping(rule_cfg["action"], action_path)
        action = _policy_enum(
            action_cfg.get("type"), f"{action_path}.type", {"zero", "multiply"}
        )
        multiplier: Optional[float] = None
        if action == "zero":
            _policy_keys(action_cfg, action_path, required={"type"})
        else:
            _policy_keys(
                action_cfg, action_path, required={"type", "multiplier"}
            )
            multiplier = _policy_positive_number(
                action_cfg["multiplier"], f"{action_path}.multiplier"
            )
            if multiplier == 1.0:
                raise ValueError(
                    f"{action_path}.multiplier: expected a value other than 1"
                )

        explanation_path = f"{rule_path}.explanation"
        explanation_cfg = _policy_mapping(
            rule_cfg["explanation"], explanation_path
        )
        _policy_keys(
            explanation_cfg,
            explanation_path,
            required={"rule_id", "description", "confidence"},
        )
        evidence_names = _policy_string_list(
            rule_cfg["evidence"], f"{rule_path}.evidence"
        )
        unknown_evidence = sorted(set(evidence_names) - set(evidence))
        if unknown_evidence:
            raise ValueError(
                f"{rule_path}.evidence: unknown resolver(s): "
                + ", ".join(unknown_evidence)
            )
        rules.append(OrderedSignalAdjustmentRulePolicy(
            rule_id=_policy_string(
                explanation_cfg["rule_id"], f"{explanation_path}.rule_id"
            ),
            predicate=predicate,
            conditions=conditions,
            target_signals=target_signals,
            action=action,
            multiplier=multiplier,
            description=_policy_string(
                explanation_cfg["description"],
                f"{explanation_path}.description",
            ),
            confidence=_policy_confidence(
                explanation_cfg["confidence"],
                f"{explanation_path}.confidence",
            ),
            evidence=evidence_names,
        ))
        external_signals.update(predicate.input_signals)
        external_signals.update(conditions.input_signals)
        external_signals.update(target_signals)

    return OrderedSignalAdjustmentsPolicy(
        enabled=enabled,
        execution_phase=execution_phase,
        inputs=inputs,
        rules=tuple(rules),
        evidence=evidence,
        external_input_signals=frozenset(external_signals),
        evidence_type=evidence_type,
    )


def _parse_grouped_signal_window_policy(
    raw: Any,
    path: str,
) -> GroupedSignalWindowPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "stage", "executor", "enabled", "phase", "evidence_type",
            "inputs", "key", "lookback", "threshold", "window_bounds",
            "max_emissions_per_key", "emissions", "evidence",
        },
    )
    _policy_enum(cfg["stage"], f"{path}.stage", {"contextual"})
    _policy_enum(
        cfg["executor"], f"{path}.executor", {"grouped_signal_window"}
    )
    enabled = _policy_bool(cfg["enabled"], f"{path}.enabled")
    execution_phase = _policy_positive_int(cfg["phase"], f"{path}.phase")
    evidence_type = _policy_enum(
        cfg["evidence_type"], f"{path}.evidence_type", {"direct"}
    )
    inputs_path = f"{path}.inputs"
    inputs_cfg = _policy_mapping(cfg["inputs"], inputs_path)
    _policy_keys(
        inputs_cfg,
        inputs_path,
        required={"signals", "minimum_value_exclusive"},
    )
    key_path = f"{path}.key"
    key_cfg = _policy_mapping(cfg["key"], key_path)
    _policy_keys(
        key_cfg,
        key_path,
        required={
            "host_field", "command_fields", "message_field",
            "message_regex", "message_fallback_max_chars", "normalise",
        },
    )
    _policy_enum(key_cfg["normalise"], f"{key_path}.normalise", {"lower"})
    pattern_text = _policy_string(
        key_cfg["message_regex"], f"{key_path}.message_regex"
    )
    try:
        message_pattern = re.compile(pattern_text)
    except re.error as exc:
        raise ValueError(
            f"{key_path}.message_regex: invalid regular expression: {exc}"
        ) from exc
    evidence = _policy_string_list(cfg["evidence"], f"{path}.evidence")
    unsupported = sorted(
        set(evidence)
        - {"hostname", "command", "count_in_window", "window_seconds"}
    )
    if unsupported:
        raise ValueError(
            f"{path}.evidence: unsupported value(s): "
            + ", ".join(unsupported)
        )
    return GroupedSignalWindowPolicy(
        enabled=enabled,
        execution_phase=execution_phase,
        source_signals=frozenset(_policy_signal_list(
            inputs_cfg["signals"], f"{inputs_path}.signals"
        )),
        minimum_signal_value_exclusive=_policy_nonnegative_number(
            inputs_cfg["minimum_value_exclusive"],
            f"{inputs_path}.minimum_value_exclusive",
        ),
        host_field=_policy_string(
            key_cfg["host_field"], f"{key_path}.host_field"
        ),
        command_fields=_policy_string_list(
            key_cfg["command_fields"], f"{key_path}.command_fields"
        ),
        message_field=_policy_string(
            key_cfg["message_field"], f"{key_path}.message_field"
        ),
        message_pattern=message_pattern,
        message_fallback_max_chars=_policy_positive_int(
            key_cfg["message_fallback_max_chars"],
            f"{key_path}.message_fallback_max_chars",
        ),
        lookback=_parse_policy_lookback(cfg["lookback"], f"{path}.lookback"),
        threshold=_policy_positive_int(cfg["threshold"], f"{path}.threshold"),
        window_bounds=_policy_enum(
            cfg["window_bounds"], f"{path}.window_bounds", {"closed"}
        ),
        max_emissions_per_key=_policy_positive_int(
            cfg["max_emissions_per_key"], f"{path}.max_emissions_per_key"
        ),
        emission=_parse_single_policy_emission(
            cfg["emissions"], f"{path}.emissions"
        ),
        evidence=evidence,
        evidence_type=evidence_type,
    )


def _parse_file_lifecycle_policy(
    raw: Any,
    path: str,
) -> FileLifecyclePolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "stage", "executor", "enabled", "evidence_type",
            "inputs", "classification", "conditions", "emissions",
            "evidence",
        },
    )
    _policy_enum(cfg["stage"], f"{path}.stage", {"contextual"})
    _policy_enum(cfg["executor"], f"{path}.executor", {"file_lifecycle"})
    enabled = _policy_bool(cfg["enabled"], f"{path}.enabled")
    evidence_type = _policy_enum(
        cfg["evidence_type"], f"{path}.evidence_type", {"direct"}
    )

    inputs_path = f"{path}.inputs"
    inputs_cfg = _policy_mapping(cfg["inputs"], inputs_path)
    input_names = {
        "path", "timestamp_description_field", "host_field", "parser_field",
        "message_field", "file_size_field", "allocation_field",
    }
    _policy_keys(inputs_cfg, inputs_path, required=input_names)
    path_input_path = f"{inputs_path}.path"
    path_input_cfg = _policy_mapping(inputs_cfg["path"], path_input_path)
    _policy_keys(path_input_cfg, path_input_path, required={"resolver", "fields"})
    _policy_enum(
        path_input_cfg["resolver"],
        f"{path_input_path}.resolver",
        {"best_effort_file_path"},
    )

    classification_path = f"{path}.classification"
    classification_cfg = _policy_mapping(
        cfg["classification"], classification_path
    )
    _policy_keys(
        classification_cfg,
        classification_path,
        required={
            "timestamp_kinds", "path_contains", "extensions",
            "suspicious_temp_basename_contains",
            "ransomware_extension_suffixes", "derived_predicates",
        },
    )
    kinds_path = f"{classification_path}.timestamp_kinds"
    kinds_cfg = _policy_mapping(classification_cfg["timestamp_kinds"], kinds_path)
    _policy_keys(kinds_cfg, kinds_path, required={"priority", "contains"})
    kind_semantics = ("create", "delete", "modify", "access")
    kind_priority = _policy_string_list(
        kinds_cfg["priority"], f"{kinds_path}.priority", lower=True
    )
    if len(kind_priority) != len(set(kind_priority)) or set(kind_priority) != set(kind_semantics):
        raise ValueError(
            f"{kinds_path}.priority: expected each of create, delete, modify, access exactly once"
        )
    kind_contains_path = f"{kinds_path}.contains"
    kind_contains_cfg = _policy_mapping(
        kinds_cfg["contains"], kind_contains_path
    )
    _policy_keys(
        kind_contains_cfg, kind_contains_path, required=set(kind_semantics)
    )

    path_contains_path = f"{classification_path}.path_contains"
    path_contains_cfg = _policy_mapping(
        classification_cfg["path_contains"], path_contains_path
    )
    path_classes = (
        "web_root", "sensitive", "database_dump_name", "excluded_update"
    )
    _policy_keys(path_contains_cfg, path_contains_path, required=set(path_classes))

    extensions_path = f"{classification_path}.extensions"
    extensions_cfg = _policy_mapping(
        classification_cfg["extensions"], extensions_path
    )
    extension_classes = ("web_script", "web_content", "database_dump", "archive")
    _policy_keys(extensions_cfg, extensions_path, required=set(extension_classes))

    def extension_set(name: str) -> frozenset[str]:
        values = frozenset(_policy_string_list(
            extensions_cfg[name], f"{extensions_path}.{name}", lower=True
        ))
        invalid = sorted(value for value in values if not value.startswith("."))
        if invalid:
            raise ValueError(
                f"{extensions_path}.{name}: extension(s) must start with '.': "
                + ", ".join(invalid)
            )
        return values

    base_row_facts = {
        "path_present", "extension_present", "web_root",
        "web_script_extension", "web_content_extension",
        "archive_extension", "database_dump_extension",
        "database_dump_basename", "database_dump_message",
        "sensitive_path", "allocated", "unallocated",
        "excluded_update_path", "suspicious_temp_basename",
        "ransomware_extension_suffix",
    }
    derived_path = f"{classification_path}.derived_predicates"
    derived_cfg = _policy_mapping(
        classification_cfg["derived_predicates"], derived_path
    )
    if not derived_cfg:
        raise ValueError(f"{derived_path}: expected at least one predicate")

    def lifecycle_fact_list(value: Any, value_path: str) -> frozenset[str]:
        if not isinstance(value, list):
            raise ValueError(f"{value_path}: expected a list")
        facts: List[str] = []
        for index, item in enumerate(value):
            fact = _policy_signal_name(item, f"{value_path}[{index}]")
            if fact not in base_row_facts:
                raise ValueError(
                    f"{value_path}[{index}]: unknown base fact {fact!r}; "
                    "expected " + ", ".join(sorted(base_row_facts))
                )
            if fact in facts:
                raise ValueError(
                    f"{value_path}[{index}]: duplicate fact {fact!r}"
                )
            facts.append(fact)
        return frozenset(facts)

    derived_predicates: Dict[str, BooleanFactDecisionPolicy] = {}
    for raw_name, raw_predicate in derived_cfg.items():
        name = _policy_signal_name(raw_name, f"{derived_path} key")
        predicate_path = f"{derived_path}.{name}"
        if name in base_row_facts:
            raise ValueError(
                f"{predicate_path}: derived predicate collides with a base fact"
            )
        predicate_cfg = _policy_mapping(raw_predicate, predicate_path)
        _policy_keys(
            predicate_cfg,
            predicate_path,
            required={"all", "any", "none"},
        )
        require_all = lifecycle_fact_list(
            predicate_cfg["all"], f"{predicate_path}.all"
        )
        require_any = lifecycle_fact_list(
            predicate_cfg["any"], f"{predicate_path}.any"
        )
        exclude_any = lifecycle_fact_list(
            predicate_cfg["none"], f"{predicate_path}.none"
        )
        if not require_all and not require_any:
            raise ValueError(
                f"{predicate_path}: at least one base fact is required in all or any"
            )
        overlaps = sorted(
            (set(require_all) | set(require_any)) & set(exclude_any)
        )
        if overlaps:
            raise ValueError(
                f"{predicate_path}: fact(s) cannot be both required and "
                "excluded: " + ", ".join(overlaps)
            )
        derived_predicates[name] = BooleanFactDecisionPolicy(
            require_all=require_all,
            require_any=require_any,
            exclude_any=exclude_any,
        )

    conditions_path = f"{path}.conditions"
    conditions_cfg = _policy_mapping(cfg["conditions"], conditions_path)
    _policy_keys(
        conditions_cfg,
        conditions_path,
        required={
            "row_emissions", "weight_aware_semantics", "windows",
        },
    )
    row_semantics = (
        "created", "modified", "deleted", "web_executable_created",
        "archive_created", "database_dump_candidate",
        "defacement_candidate", "sensitive_file_access",
    )
    row_predicates = base_row_facts | set(derived_predicates)

    def lifecycle_kind_set(
        raw_kinds: Any,
        kind_path: str,
        *,
        allow_empty: bool = False,
    ) -> frozenset[str]:
        parser = _policy_string_list_or_empty if allow_empty else _policy_string_list
        values = frozenset(parser(raw_kinds, kind_path, lower=True))
        unknown = sorted(values - set(kind_semantics))
        if unknown:
            raise ValueError(
                f"{kind_path}: unknown timestamp kind(s): "
                + ", ".join(unknown)
            )
        return values

    row_decisions_path = f"{conditions_path}.row_emissions"
    row_decisions_cfg = _policy_mapping(
        conditions_cfg["row_emissions"], row_decisions_path
    )
    _policy_keys(
        row_decisions_cfg, row_decisions_path, required=set(row_semantics)
    )
    row_decisions: Dict[str, FileLifecycleRowDecisionPolicy] = {}
    for semantic in row_semantics:
        decision_path = f"{row_decisions_path}.{semantic}"
        decision_cfg = _policy_mapping(
            row_decisions_cfg[semantic], decision_path
        )
        _policy_keys(
            decision_cfg,
            decision_path,
            required={"match", "timestamp_kinds", "derived_predicates"},
        )
        decision_kinds = lifecycle_kind_set(
            decision_cfg["timestamp_kinds"],
            f"{decision_path}.timestamp_kinds",
            allow_empty=True,
        )
        decision_predicates = frozenset(_policy_string_list_or_empty(
            decision_cfg["derived_predicates"],
            f"{decision_path}.derived_predicates",
            lower=True,
        ))
        unknown_predicates = sorted(decision_predicates - row_predicates)
        if unknown_predicates:
            raise ValueError(
                f"{decision_path}.derived_predicates: unknown predicate(s): "
                + ", ".join(unknown_predicates)
            )
        if not decision_kinds and not decision_predicates:
            raise ValueError(
                f"{decision_path}: expected at least one timestamp kind or "
                "derived predicate"
            )
        row_decisions[semantic] = FileLifecycleRowDecisionPolicy(
            match=_policy_enum(
                decision_cfg["match"], f"{decision_path}.match", {"all", "any"}
            ),
            timestamp_kinds=decision_kinds,
            derived_predicates=decision_predicates,
        )

    windows_path = f"{conditions_path}.windows"
    windows_cfg = _policy_mapping(conditions_cfg["windows"], windows_path)
    window_names = (
        "short_lived_file", "mass_file_modification",
        "ransomware_extension_burst",
    )
    _policy_keys(windows_cfg, windows_path, required=set(window_names))

    def fact_conditions(
        raw_conditions: Any,
        condition_path: str,
        allowed_facts: Set[str],
    ) -> AnyAllFactConditionPolicy:
        condition_cfg = _policy_mapping(raw_conditions, condition_path)
        _policy_keys(condition_cfg, condition_path, required={"any"})
        raw_clauses = condition_cfg["any"]
        if not isinstance(raw_clauses, list) or not raw_clauses:
            raise ValueError(f"{condition_path}.any: expected a non-empty list")
        clauses: List[frozenset[str]] = []
        for clause_index, raw_clause in enumerate(raw_clauses):
            clause_path = f"{condition_path}.any[{clause_index}]"
            clause_cfg = _policy_mapping(raw_clause, clause_path)
            _policy_keys(clause_cfg, clause_path, required={"all"})
            facts = frozenset(_policy_string_list(
                clause_cfg["all"], f"{clause_path}.all", lower=True
            ))
            unknown_facts = sorted(facts - allowed_facts)
            if unknown_facts:
                raise ValueError(
                    f"{clause_path}.all: unknown fact(s): "
                    + ", ".join(unknown_facts)
                )
            if facts in clauses:
                raise ValueError(f"{clause_path}: duplicate condition clause")
            clauses.append(facts)
        return AnyAllFactConditionPolicy(any_all=tuple(clauses))

    short_path = f"{windows_path}.short_lived_file"
    short_cfg = _policy_mapping(windows_cfg["short_lived_file"], short_path)
    _policy_keys(
        short_cfg,
        short_path,
        required={
            "lookback", "key_fields", "source_timestamp_kinds",
            "target_timestamp_kinds", "source_selection", "ordering",
            "window_bounds", "emit_on", "conditions",
        },
    )
    short_key_fields = _policy_string_list(
        short_cfg["key_fields"], f"{short_path}.key_fields", lower=True
    )
    unknown_short_keys = sorted(
        set(short_key_fields) - {"host", "path", "parent_directory"}
    )
    if unknown_short_keys:
        raise ValueError(
            f"{short_path}.key_fields: unknown key field(s): "
            + ", ".join(unknown_short_keys)
        )
    short_lived = FileLifecycleShortLivedWindowPolicy(
        lookback=_parse_policy_lookback(
            short_cfg["lookback"], f"{short_path}.lookback"
        ),
        key_fields=short_key_fields,
        source_timestamp_kinds=lifecycle_kind_set(
            short_cfg["source_timestamp_kinds"],
            f"{short_path}.source_timestamp_kinds",
        ),
        target_timestamp_kinds=lifecycle_kind_set(
            short_cfg["target_timestamp_kinds"],
            f"{short_path}.target_timestamp_kinds",
        ),
        source_selection=_policy_enum(
            short_cfg["source_selection"],
            f"{short_path}.source_selection",
            {"earliest", "latest"},
        ),
        ordering=_policy_enum(
            short_cfg["ordering"],
            f"{short_path}.ordering",
            {"before_or_same", "strictly_before"},
        ),
        window_bounds=_policy_enum(
            short_cfg["window_bounds"],
            f"{short_path}.window_bounds",
            {"closed", "open"},
        ),
        emit_on=_policy_enum(
            short_cfg["emit_on"], f"{short_path}.emit_on", {"source", "target"}
        ),
        conditions=fact_conditions(
            short_cfg["conditions"],
            f"{short_path}.conditions",
            {
                f"{role}_{fact}"
                for role in ("source", "target")
                for fact in row_predicates
            },
        ),
    )

    def threshold_window(
        name: str,
        *,
        allowed_facts: Set[str],
    ) -> FileLifecycleThresholdWindowPolicy:
        window_path = f"{windows_path}.{name}"
        window_cfg = _policy_mapping(windows_cfg[name], window_path)
        _policy_keys(
            window_cfg,
            window_path,
            required={
                "lookback", "threshold", "threshold_comparison",
                "window_bounds", "eligible_timestamp_kinds", "group_by",
                "max_emissions_per_group", "conditions",
            },
        )
        group_by = _policy_string_list(
            window_cfg["group_by"], f"{window_path}.group_by", lower=True
        )
        unknown_group_fields = sorted(
            set(group_by) - {"host", "path", "parent_directory"}
        )
        if unknown_group_fields:
            raise ValueError(
                f"{window_path}.group_by: unknown key field(s): "
                + ", ".join(unknown_group_fields)
            )
        return FileLifecycleThresholdWindowPolicy(
            lookback=_parse_policy_lookback(
                window_cfg["lookback"], f"{window_path}.lookback"
            ),
            threshold=_policy_positive_int(
                window_cfg["threshold"], f"{window_path}.threshold"
            ),
            threshold_comparison=_policy_enum(
                window_cfg["threshold_comparison"],
                f"{window_path}.threshold_comparison",
                {"at_least", "greater_than"},
            ),
            window_bounds=_policy_enum(
                window_cfg["window_bounds"],
                f"{window_path}.window_bounds",
                {"closed", "open"},
            ),
            eligible_timestamp_kinds=lifecycle_kind_set(
                window_cfg["eligible_timestamp_kinds"],
                f"{window_path}.eligible_timestamp_kinds",
            ),
            group_by=group_by,
            max_emissions_per_group=_policy_positive_int(
                window_cfg["max_emissions_per_group"],
                f"{window_path}.max_emissions_per_group",
            ),
            conditions=fact_conditions(
                window_cfg["conditions"],
                f"{window_path}.conditions",
                allowed_facts,
            ),
        )

    mass_modification = threshold_window(
        "mass_file_modification",
        allowed_facts=row_predicates,
    )
    ransomware_burst = threshold_window(
        "ransomware_extension_burst",
        allowed_facts=row_predicates,
    )

    emission_semantics = (
        "created", "modified", "deleted", "web_executable_created",
        "archive_created", "database_dump_candidate",
        "defacement_candidate", "sensitive_file_access", "short_lived_file",
        "mass_file_modification", "ransomware_extension_burst",
    )
    emissions = _parse_named_policy_emissions(
        cfg["emissions"], f"{path}.emissions", emission_semantics
    )
    weight_aware = frozenset(_policy_string_list(
        conditions_cfg["weight_aware_semantics"],
        f"{conditions_path}.weight_aware_semantics",
        lower=True,
    ))
    unknown_weight_aware = sorted(weight_aware - set(emission_semantics))
    if unknown_weight_aware:
        raise ValueError(
            f"{conditions_path}.weight_aware_semantics: unknown semantic(s): "
            + ", ".join(unknown_weight_aware)
        )

    evidence_path = f"{path}.evidence"
    evidence_cfg = _policy_mapping(cfg["evidence"], evidence_path)
    _policy_keys(evidence_cfg, evidence_path, required=set(emission_semantics))
    allowed_evidence = {
        "path", "timestamp_desc", "parser", "hostname", "file_size",
        "message", "is_allocated", "create_timestamp", "delete_timestamp",
        "lifetime_seconds", "host", "directory", "window_seconds",
        "count_in_window", "extensions",
    }
    evidence_by_semantic: Dict[str, Tuple[str, ...]] = {}
    for semantic in emission_semantics:
        evidence = _policy_string_list(
            evidence_cfg[semantic], f"{evidence_path}.{semantic}"
        )
        unsupported = sorted(set(evidence) - allowed_evidence)
        if unsupported:
            raise ValueError(
                f"{evidence_path}.{semantic}: unsupported value(s): "
                + ", ".join(unsupported)
            )
        evidence_by_semantic[semantic] = evidence

    def path_tokens(name: str) -> Tuple[str, ...]:
        return tuple(
            token.replace("\\", "/")
            for token in _policy_string_list(
                path_contains_cfg[name], f"{path_contains_path}.{name}", lower=True
            )
        )

    return FileLifecyclePolicy(
        enabled=enabled,
        path_fields=_policy_string_list(
            path_input_cfg["fields"], f"{path_input_path}.fields"
        ),
        timestamp_field=_policy_string(
            inputs_cfg["timestamp_description_field"],
            f"{inputs_path}.timestamp_description_field",
        ),
        host_field=_policy_string(inputs_cfg["host_field"], f"{inputs_path}.host_field"),
        parser_field=_policy_string(inputs_cfg["parser_field"], f"{inputs_path}.parser_field"),
        message_field=_policy_string(inputs_cfg["message_field"], f"{inputs_path}.message_field"),
        file_size_field=_policy_string(inputs_cfg["file_size_field"], f"{inputs_path}.file_size_field"),
        allocation_field=_policy_string(inputs_cfg["allocation_field"], f"{inputs_path}.allocation_field"),
        timestamp_kind_priority=kind_priority,
        timestamp_kind_tokens={
            name: _policy_string_list(
                kind_contains_cfg[name], f"{kind_contains_path}.{name}", lower=True
            )
            for name in kind_semantics
        },
        web_root_tokens=path_tokens("web_root"),
        sensitive_path_tokens=path_tokens("sensitive"),
        database_dump_name_tokens=path_tokens("database_dump_name"),
        excluded_update_path_tokens=path_tokens("excluded_update"),
        web_script_extensions=extension_set("web_script"),
        web_content_extensions=extension_set("web_content"),
        database_dump_extensions=extension_set("database_dump"),
        archive_extensions=extension_set("archive"),
        suspicious_temp_basename_tokens=_policy_string_list(
            classification_cfg["suspicious_temp_basename_contains"],
            f"{classification_path}.suspicious_temp_basename_contains",
            lower=True,
        ),
        ransomware_extension_suffixes=_policy_string_list(
            classification_cfg["ransomware_extension_suffixes"],
            f"{classification_path}.ransomware_extension_suffixes",
            lower=True,
        ),
        derived_predicates_by_name=derived_predicates,
        row_decisions_by_semantic=row_decisions,
        short_lived=short_lived,
        mass_modification=mass_modification,
        ransomware_burst=ransomware_burst,
        weight_aware_semantics=weight_aware,
        emissions_by_semantic=emissions,
        evidence_by_semantic=evidence_by_semantic,
        evidence_type=evidence_type,
    )


def _parse_mft_timestomping_policy(
    raw: Any,
    path: str,
) -> MftTimestompingPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "stage", "executor", "enabled", "evidence_type",
            "inputs", "conditions", "branches", "emissions",
        },
    )
    _policy_enum(cfg["stage"], f"{path}.stage", {"contextual"})
    _policy_enum(cfg["executor"], f"{path}.executor", {"mft_timestomping"})
    enabled = _policy_bool(cfg["enabled"], f"{path}.enabled")
    evidence_type = _policy_enum(
        cfg["evidence_type"], f"{path}.evidence_type", {"direct"}
    )

    inputs_path = f"{path}.inputs"
    inputs_cfg = _policy_mapping(cfg["inputs"], inputs_path)
    _policy_keys(
        inputs_cfg,
        inputs_path,
        required={"path", "parser_field", "timestamp_description_field"},
    )
    path_input_path = f"{inputs_path}.path"
    path_input_cfg = _policy_mapping(inputs_cfg["path"], path_input_path)
    _policy_keys(path_input_cfg, path_input_path, required={"resolver", "fields"})
    _policy_enum(
        path_input_cfg["resolver"],
        f"{path_input_path}.resolver",
        {"best_effort_file_path"},
    )

    conditions_path = f"{path}.conditions"
    conditions_cfg = _policy_mapping(cfg["conditions"], conditions_path)
    _policy_keys(
        conditions_cfg,
        conditions_path,
        required={
            "parser_contains", "creation_contains", "attributes",
            "minimum_delta", "excluded_path_contains", "bulk_extraction",
        },
    )
    attributes_path = f"{conditions_path}.attributes"
    attributes_cfg = _policy_mapping(
        conditions_cfg["attributes"], attributes_path
    )
    _policy_keys(
        attributes_cfg,
        attributes_path,
        required={"standard_information_contains", "file_name_contains"},
    )
    bulk_path = f"{conditions_path}.bulk_extraction"
    bulk_cfg = _policy_mapping(conditions_cfg["bulk_extraction"], bulk_path)
    _policy_keys(bulk_cfg, bulk_path, required={"group_by", "threshold"})
    _policy_enum(
        bulk_cfg["group_by"], f"{bulk_path}.group_by", {"parent_directory"}
    )

    branches_path = f"{path}.branches"
    branches_cfg = _policy_mapping(cfg["branches"], branches_path)
    _policy_keys(
        branches_cfg,
        branches_path,
        required={"targeted", "bulk_extraction_likely"},
    )
    allowed_evidence = {
        "path", "si_creation", "fn_creation", "delta_seconds",
        "bulk_extraction_dampened", "directory_hit_count",
    }

    def parse_explanation(name: str) -> TimestompExplanationPolicy:
        branch_path = f"{branches_path}.{name}"
        branch_cfg = _policy_mapping(branches_cfg[name], branch_path)
        _policy_keys(
            branch_cfg,
            branch_path,
            required={"description", "confidence", "evidence"},
        )
        evidence = _policy_string_list(
            branch_cfg["evidence"], f"{branch_path}.evidence"
        )
        unsupported = sorted(set(evidence) - allowed_evidence)
        if unsupported:
            raise ValueError(
                f"{branch_path}.evidence: unsupported value(s): "
                + ", ".join(unsupported)
            )
        return TimestompExplanationPolicy(
            description=_policy_string(
                branch_cfg["description"], f"{branch_path}.description"
            ),
            confidence=_policy_confidence(
                branch_cfg["confidence"], f"{branch_path}.confidence"
            ),
            evidence=evidence,
        )

    return MftTimestompingPolicy(
        enabled=enabled,
        path_fields=_policy_string_list(
            path_input_cfg["fields"], f"{path_input_path}.fields"
        ),
        parser_field=_policy_string(
            inputs_cfg["parser_field"], f"{inputs_path}.parser_field"
        ),
        timestamp_field=_policy_string(
            inputs_cfg["timestamp_description_field"],
            f"{inputs_path}.timestamp_description_field",
        ),
        parser_tokens=_policy_string_list(
            conditions_cfg["parser_contains"],
            f"{conditions_path}.parser_contains",
            lower=True,
        ),
        creation_tokens=_policy_string_list(
            conditions_cfg["creation_contains"],
            f"{conditions_path}.creation_contains",
            lower=True,
        ),
        standard_information_tokens=_policy_string_list(
            attributes_cfg["standard_information_contains"],
            f"{attributes_path}.standard_information_contains",
            lower=True,
        ),
        file_name_tokens=_policy_string_list(
            attributes_cfg["file_name_contains"],
            f"{attributes_path}.file_name_contains",
            lower=True,
        ),
        minimum_delta=_parse_policy_lookback(
            conditions_cfg["minimum_delta"],
            f"{conditions_path}.minimum_delta",
        ),
        excluded_path_tokens=tuple(
            token.replace("\\", "/")
            for token in _policy_string_list(
                conditions_cfg["excluded_path_contains"],
                f"{conditions_path}.excluded_path_contains",
                lower=True,
            )
        ),
        bulk_group_threshold=_policy_positive_int(
            bulk_cfg["threshold"], f"{bulk_path}.threshold"
        ),
        emission=_parse_single_policy_emission(
            cfg["emissions"], f"{path}.emissions"
        ),
        targeted_explanation=parse_explanation("targeted"),
        bulk_explanation=parse_explanation("bulk_extraction_likely"),
        evidence_type=evidence_type,
    )


def _parse_signal_projection_policy(
    raw: Any,
    path: str,
) -> SignalProjectionPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "stage", "executor", "enabled", "evidence_type",
            "projections", "evidence",
        },
    )
    _policy_enum(cfg["stage"], f"{path}.stage", {"contextual", "temporal"})
    _policy_enum(cfg["executor"], f"{path}.executor", {"signal_projection"})
    enabled = _policy_bool(cfg["enabled"], f"{path}.enabled")
    evidence_type = _policy_enum(
        cfg["evidence_type"], f"{path}.evidence_type", {"direct", "contextual"}
    )
    raw_projections = cfg["projections"]
    projections_path = f"{path}.projections"
    if not isinstance(raw_projections, list) or not raw_projections:
        raise ValueError(f"{projections_path}: expected a non-empty list")
    projections: List[SignalProjectionRulePolicy] = []
    for projection_index, raw_projection in enumerate(raw_projections):
        projection_path = f"{projections_path}[{projection_index}]"
        projection_cfg = _policy_mapping(raw_projection, projection_path)
        _policy_keys(
            projection_cfg,
            projection_path,
            required={"inputs", "conditions", "strength", "emissions"},
        )
        inputs_path = f"{projection_path}.inputs"
        inputs_cfg = _policy_mapping(projection_cfg["inputs"], inputs_path)
        _policy_keys(inputs_cfg, inputs_path, required={"signals"})
        input_signals = frozenset(
            _policy_signal_list(inputs_cfg["signals"], f"{inputs_path}.signals")
        )
        conditions_path = f"{projection_path}.conditions"
        conditions_cfg = _policy_mapping(
            projection_cfg["conditions"], conditions_path
        )
        _policy_keys(
            conditions_cfg,
            conditions_path,
            required={"match", "minimum_value_exclusive"},
        )
        match = _policy_enum(
            conditions_cfg["match"], f"{conditions_path}.match", {"any", "all"}
        )
        minimum_value_exclusive = _policy_nonnegative_number(
            conditions_cfg["minimum_value_exclusive"],
            f"{conditions_path}.minimum_value_exclusive",
        )
        strength = _policy_enum(
            projection_cfg["strength"],
            f"{projection_path}.strength",
            {"maximum_matched_times_emission_value"},
        )
        projections.append(
            SignalProjectionRulePolicy(
                input_signals=input_signals,
                match=match,
                minimum_value_exclusive=minimum_value_exclusive,
                strength=strength,
                emission=_parse_single_policy_emission(
                    projection_cfg["emissions"],
                    f"{projection_path}.emissions",
                ),
            )
        )
    evidence = _parse_policy_evidence(
        cfg["evidence"],
        f"{path}.evidence",
        allowed_resolvers={"matched_signals"},
    )
    return SignalProjectionPolicy(
        enabled=enabled,
        projections=tuple(projections),
        evidence=evidence,
        evidence_type=evidence_type,
    )


def _parse_signal_sequence_policy(
    raw: Any,
    path: str,
) -> SignalSequencePolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "stage", "executor", "enabled", "evidence_type", "lookback",
            "ordering", "window_bounds", "source_selection", "emit_on", "key",
            "source", "target", "emissions", "evidence",
        },
    )
    _policy_enum(cfg["stage"], f"{path}.stage", {"temporal"})
    _policy_enum(cfg["executor"], f"{path}.executor", {"signal_sequence"})
    enabled = _policy_bool(cfg["enabled"], f"{path}.enabled")
    evidence_type = _policy_enum(
        cfg["evidence_type"],
        f"{path}.evidence_type",
        {"contextual"},
    )
    try:
        lookback = parse_lookback(cfg["lookback"])
    except ValueError as exc:
        raise ValueError(f"{path}.lookback: {exc}") from exc
    if lookback <= timedelta(0):
        raise ValueError(f"{path}.lookback: expected a duration greater than zero")
    ordering = _policy_enum(
        cfg["ordering"],
        f"{path}.ordering",
        {"source_at_or_before_target", "source_before_target"},
    )
    window_bounds = _policy_enum(
        cfg["window_bounds"],
        f"{path}.window_bounds",
        {"closed"},
    )
    source_selection = _policy_enum(
        cfg["source_selection"],
        f"{path}.source_selection",
        {"earliest_in_window", "latest_in_window"},
    )
    _policy_enum(cfg["emit_on"], f"{path}.emit_on", {"target"})

    key_path = f"{path}.key"
    key = _policy_mapping(cfg["key"], key_path)
    _policy_keys(key, key_path, required={"scope"}, optional={"field"})
    key_scope = _policy_enum(
        key["scope"],
        f"{key_path}.scope",
        {"deadbox_global", "field"},
    )
    if key_scope == "field":
        if "field" not in key:
            raise ValueError(f"{key_path}.field: required when scope is 'field'")
        key_field = _policy_string(key["field"], f"{key_path}.field")
    else:
        if "field" in key:
            raise ValueError(f"{key_path}.field: not allowed when scope is 'deadbox_global'")
        key_field = ""

    source_path = f"{path}.source"
    source = _policy_mapping(cfg["source"], source_path)
    _policy_keys(
        source,
        source_path,
        required={"any_signals", "minimum_signal_value_exclusive"},
    )
    source_signals = frozenset(
        _policy_signal_list(source["any_signals"], f"{source_path}.any_signals")
    )
    target_path = f"{path}.target"
    target = _policy_mapping(cfg["target"], target_path)
    _policy_keys(
        target,
        target_path,
        required={"any_signals", "minimum_signal_value_exclusive"},
        optional={"where"},
    )
    target_signals = frozenset(
        _policy_signal_list(target["any_signals"], f"{target_path}.any_signals")
    )
    target_context: Optional[SignalSequenceTargetContextPolicy] = None
    if "where" in target:
        where_path = f"{target_path}.where"
        where_cfg = _policy_mapping(target["where"], where_path)
        _policy_keys(
            where_cfg,
            where_path,
            required={"match"},
            optional={"path", "combined_text"},
        )
        where_match = _policy_enum(
            where_cfg["match"], f"{where_path}.match", {"any", "all"}
        )
        path_fields: Tuple[str, ...] = ()
        path_contains: Tuple[str, ...] = ()
        if "path" in where_cfg:
            context_path = f"{where_path}.path"
            context_cfg = _policy_mapping(where_cfg["path"], context_path)
            _policy_keys(
                context_cfg,
                context_path,
                required={"resolver", "fields", "contains_any"},
            )
            _policy_enum(
                context_cfg["resolver"],
                f"{context_path}.resolver",
                {"best_effort_file_path"},
            )
            path_fields = _policy_string_list(
                context_cfg["fields"], f"{context_path}.fields"
            )
            path_contains = tuple(
                token.replace("\\", "/")
                for token in _policy_string_list(
                    context_cfg["contains_any"],
                    f"{context_path}.contains_any",
                    lower=True,
                )
            )
        combined_fields: Tuple[str, ...] = ()
        combined_contains: Tuple[str, ...] = ()
        if "combined_text" in where_cfg:
            context_path = f"{where_path}.combined_text"
            context_cfg = _policy_mapping(
                where_cfg["combined_text"], context_path
            )
            _policy_keys(
                context_cfg,
                context_path,
                required={"resolver", "fields", "contains_any"},
            )
            _policy_enum(
                context_cfg["resolver"],
                f"{context_path}.resolver",
                {"concat_lower"},
            )
            combined_fields = _policy_string_list(
                context_cfg["fields"], f"{context_path}.fields"
            )
            combined_contains = _policy_string_list(
                context_cfg["contains_any"],
                f"{context_path}.contains_any",
                lower=True,
            )
        if not path_contains and not combined_contains:
            raise ValueError(
                f"{where_path}: expected path and/or combined_text conditions"
            )
        target_context = SignalSequenceTargetContextPolicy(
            match=where_match,
            path_fields=path_fields,
            path_contains=path_contains,
            combined_text_fields=combined_fields,
            combined_text_contains=combined_contains,
        )

    emissions_path = f"{path}.emissions"
    if not isinstance(cfg["emissions"], list) or not cfg["emissions"]:
        raise ValueError(f"{emissions_path}: expected a non-empty list")
    emissions = tuple(
        _parse_policy_emission(
            item,
            f"{emissions_path}[{index}]",
            include_explanation=True,
        )
        for index, item in enumerate(cfg["emissions"])
    )
    evidence = _parse_policy_evidence(
        cfg["evidence"],
        f"{path}.evidence",
        allowed_resolvers={"target_field", "source_timestamp", "target_timestamp"},
    )
    return SignalSequencePolicy(
        enabled=enabled,
        lookback=lookback,
        ordering=ordering,
        window_bounds=window_bounds,
        source_selection=source_selection,
        key_scope=key_scope,
        key_field=key_field,
        source_signals=source_signals,
        source_minimum_signal_value_exclusive=_policy_nonnegative_number(
            source["minimum_signal_value_exclusive"],
            f"{source_path}.minimum_signal_value_exclusive",
        ),
        target_signals=target_signals,
        target_minimum_signal_value_exclusive=_policy_nonnegative_number(
            target["minimum_signal_value_exclusive"],
            f"{target_path}.minimum_signal_value_exclusive",
        ),
        target_context=target_context,
        emissions=emissions,
        evidence=evidence,
        evidence_type=evidence_type,
    )


def _parse_policy_lookback(value: Any, path: str) -> timedelta:
    try:
        parsed = parse_lookback(value)
    except ValueError as exc:
        raise ValueError(f"{path}: {exc}") from exc
    if parsed <= timedelta(0):
        raise ValueError(f"{path}: expected a duration greater than zero")
    return parsed


def _parse_single_policy_emission(raw: Any, path: str) -> DetectorEmissionPolicy:
    if not isinstance(raw, list) or len(raw) != 1:
        raise ValueError(f"{path}: expected a list containing exactly one emission")
    return _parse_policy_emission(raw[0], f"{path}[0]", include_explanation=True)


def _parse_ransomware_impact_policy(raw: Any, path: str) -> RansomwareImpactPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "stage", "executor", "enabled", "evidence_type",
            "lookback", "window_bounds", "key", "emit_on", "source",
            "branches", "emissions", "evidence",
        },
    )
    _policy_enum(cfg["stage"], f"{path}.stage", {"temporal"})
    _policy_enum(cfg["executor"], f"{path}.executor", {"temporal_context_branches"})
    enabled = _policy_bool(cfg["enabled"], f"{path}.enabled")
    evidence_type = _policy_enum(cfg["evidence_type"], f"{path}.evidence_type", {"contextual"})
    lookback = _parse_policy_lookback(cfg["lookback"], f"{path}.lookback")
    _policy_enum(cfg["window_bounds"], f"{path}.window_bounds", {"closed"})
    _policy_enum(cfg["emit_on"], f"{path}.emit_on", {"source"})
    key_path = f"{path}.key"
    key_cfg = _policy_mapping(cfg["key"], key_path)
    _policy_keys(key_cfg, key_path, required={"scope"})
    key_scope = _policy_enum(key_cfg["scope"], f"{key_path}.scope", {"deadbox_global"})
    source_path = f"{path}.source"
    source_cfg = _policy_mapping(cfg["source"], source_path)
    _policy_keys(
        source_cfg,
        source_path,
        required={"any_signals", "minimum_signal_value_exclusive"},
    )
    source_signals = frozenset(
        _policy_signal_list(source_cfg["any_signals"], f"{source_path}.any_signals")
    )

    branches_path = f"{path}.branches"
    branches_cfg = _policy_mapping(cfg["branches"], branches_path)
    _policy_keys(branches_cfg, branches_path, required={"prior_support", "ransom_note"})
    prior_path = f"{branches_path}.prior_support"
    prior_cfg = _policy_mapping(branches_cfg["prior_support"], prior_path)
    _policy_keys(
        prior_cfg,
        prior_path,
        required={
            "direction", "any_signals", "minimum_signal_value_exclusive",
            "description",
        },
    )
    _policy_enum(prior_cfg["direction"], f"{prior_path}.direction", {"before_or_same"})
    support_signals = frozenset(
        _policy_signal_list(prior_cfg["any_signals"], f"{prior_path}.any_signals")
    )
    support_description = _policy_string(prior_cfg["description"], f"{prior_path}.description")

    note_path = f"{branches_path}.ransom_note"
    note_cfg = _policy_mapping(branches_cfg["ransom_note"], note_path)
    _policy_keys(note_cfg, note_path, required={"direction", "path", "basename_contains", "description"})
    _policy_enum(note_cfg["direction"], f"{note_path}.direction", {"same_or_after"})
    note_input_path = f"{note_path}.path"
    note_input = _policy_mapping(note_cfg["path"], note_input_path)
    _policy_keys(note_input, note_input_path, required={"resolver", "fields"})
    _policy_enum(note_input["resolver"], f"{note_input_path}.resolver", {"best_effort_file_path"})
    note_path_fields = _policy_string_list(note_input["fields"], f"{note_input_path}.fields")
    note_basename_tokens = _policy_string_list(
        note_cfg["basename_contains"], f"{note_path}.basename_contains", lower=True
    )
    note_description = _policy_string(note_cfg["description"], f"{note_path}.description")
    evidence = _parse_policy_evidence(
        cfg["evidence"],
        f"{path}.evidence",
        allowed_resolvers={
            "row_field",
            "matched_source_signals",
            "support_timestamp",
            "ransom_note_timestamp",
        },
    )
    return RansomwareImpactPolicy(
        enabled=enabled,
        lookback=lookback,
        key_scope=key_scope,
        source_signals=source_signals,
        source_minimum_signal_value_exclusive=_policy_nonnegative_number(
            source_cfg["minimum_signal_value_exclusive"],
            f"{source_path}.minimum_signal_value_exclusive",
        ),
        support_signals=support_signals,
        support_minimum_signal_value_exclusive=_policy_nonnegative_number(
            prior_cfg["minimum_signal_value_exclusive"],
            f"{prior_path}.minimum_signal_value_exclusive",
        ),
        note_path_fields=note_path_fields,
        note_basename_tokens=note_basename_tokens,
        support_description=support_description,
        note_description=note_description,
        emission=_parse_single_policy_emission(cfg["emissions"], f"{path}.emissions"),
        evidence=evidence,
        evidence_type=evidence_type,
    )


def _parse_counted_signal_window_policy(raw: Any, path: str) -> CountedSignalWindowPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "stage", "executor", "enabled", "evidence_type",
            "lookback", "window_bounds", "key", "emit_on", "threshold",
            "minimum_signal_value_exclusive", "count", "support",
            "emissions", "evidence",
        },
    )
    _policy_enum(cfg["stage"], f"{path}.stage", {"temporal"})
    _policy_enum(cfg["executor"], f"{path}.executor", {"counted_signal_window"})
    enabled = _policy_bool(cfg["enabled"], f"{path}.enabled")
    evidence_type = _policy_enum(cfg["evidence_type"], f"{path}.evidence_type", {"contextual"})
    lookback = _parse_policy_lookback(cfg["lookback"], f"{path}.lookback")
    _policy_enum(cfg["window_bounds"], f"{path}.window_bounds", {"closed"})
    emit_on_roles = frozenset(
        _policy_enum(
            role,
            f"{path}.emit_on[{index}]",
            {"counted", "current_support", "window_support"},
        )
        for index, role in enumerate(
            _policy_string_list(cfg["emit_on"], f"{path}.emit_on", lower=True)
        )
    )
    key_path = f"{path}.key"
    key_cfg = _policy_mapping(cfg["key"], key_path)
    _policy_keys(key_cfg, key_path, required={"scope"})
    key_scope = _policy_enum(key_cfg["scope"], f"{key_path}.scope", {"deadbox_global"})
    count_path = f"{path}.count"
    count_cfg = _policy_mapping(cfg["count"], count_path)
    _policy_keys(count_cfg, count_path, required={"any_signals", "mode"})
    _policy_enum(count_cfg["mode"], f"{count_path}.mode", {"rows_once"})
    counted_signals = frozenset(
        _policy_signal_list(count_cfg["any_signals"], f"{count_path}.any_signals")
    )
    support_path = f"{path}.support"
    support_cfg = _policy_mapping(cfg["support"], support_path)
    _policy_keys(support_cfg, support_path, required={"window_any_signals", "current_any_signals"})
    window_support = frozenset(
        _policy_signal_list(support_cfg["window_any_signals"], f"{support_path}.window_any_signals")
    )
    current_support = frozenset(
        _policy_signal_list(support_cfg["current_any_signals"], f"{support_path}.current_any_signals")
    )
    role_signals = {
        "counted": counted_signals,
        "current_support": current_support,
        "window_support": window_support,
    }
    for role in emit_on_roles:
        if not role_signals[role]:
            raise ValueError(
                f"{path}.emit_on: role {role!r} requires a non-empty configured signal set"
            )
    evidence = _parse_policy_evidence(
        cfg["evidence"],
        f"{path}.evidence",
        allowed_resolvers={"row_field", "count_in_window", "window_seconds"},
    )
    return CountedSignalWindowPolicy(
        enabled=enabled,
        lookback=lookback,
        key_scope=key_scope,
        threshold=_policy_positive_int(cfg["threshold"], f"{path}.threshold"),
        minimum_signal_value_exclusive=_policy_nonnegative_number(
            cfg["minimum_signal_value_exclusive"],
            f"{path}.minimum_signal_value_exclusive",
        ),
        counted_signals=counted_signals,
        window_support_signals=window_support,
        current_support_signals=current_support,
        emit_on_roles=emit_on_roles,
        emission=_parse_single_policy_emission(cfg["emissions"], f"{path}.emissions"),
        evidence=evidence,
        evidence_type=evidence_type,
    )


def _parse_artifact_follow_on_policy(raw: Any, path: str) -> ArtifactFollowOnPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "stage", "executor", "enabled", "evidence_type",
            "lookback", "window_bounds", "ordering", "key", "emit_on",
            "source", "inputs", "labels", "copy_stage", "follow_on",
            "follow_on_qualification", "emissions", "evidence",
        },
    )
    _policy_enum(cfg["stage"], f"{path}.stage", {"temporal"})
    _policy_enum(cfg["executor"], f"{path}.executor", {"artifact_follow_on_sequence"})
    enabled = _policy_bool(cfg["enabled"], f"{path}.enabled")
    evidence_type = _policy_enum(cfg["evidence_type"], f"{path}.evidence_type", {"contextual"})
    lookback = _parse_policy_lookback(cfg["lookback"], f"{path}.lookback")
    _policy_enum(cfg["window_bounds"], f"{path}.window_bounds", {"closed"})
    _policy_enum(cfg["ordering"], f"{path}.ordering", {"source_at_or_before_follow_on"})
    _policy_enum(cfg["emit_on"], f"{path}.emit_on", {"source"})
    key_path = f"{path}.key"
    key_cfg = _policy_mapping(cfg["key"], key_path)
    _policy_keys(key_cfg, key_path, required={"scope"})
    key_scope = _policy_enum(key_cfg["scope"], f"{key_path}.scope", {"deadbox_global"})
    source_path = f"{path}.source"
    source_cfg = _policy_mapping(cfg["source"], source_path)
    _policy_keys(
        source_cfg,
        source_path,
        required={"any_signals", "minimum_signal_value_exclusive"},
    )
    source_signals = frozenset(
        _policy_signal_list(source_cfg["any_signals"], f"{source_path}.any_signals")
    )
    inputs_path = f"{path}.inputs"
    inputs_cfg = _policy_mapping(cfg["inputs"], inputs_path)
    _policy_keys(inputs_cfg, inputs_path, required={"path", "combined_text"})
    path_input_path = f"{inputs_path}.path"
    path_input = _policy_mapping(inputs_cfg["path"], path_input_path)
    _policy_keys(path_input, path_input_path, required={"resolver", "fields"})
    _policy_enum(path_input["resolver"], f"{path_input_path}.resolver", {"best_effort_file_path"})
    path_fields = _policy_string_list(path_input["fields"], f"{path_input_path}.fields")
    text_input_path = f"{inputs_path}.combined_text"
    text_input = _policy_mapping(inputs_cfg["combined_text"], text_input_path)
    _policy_keys(text_input, text_input_path, required={"resolver", "fields"})
    _policy_enum(text_input["resolver"], f"{text_input_path}.resolver", {"concat_lower"})
    text_fields = _policy_string_list(text_input["fields"], f"{text_input_path}.fields")
    labels_path = f"{path}.labels"
    labels_cfg = _policy_mapping(cfg["labels"], labels_path)
    _policy_keys(labels_cfg, labels_path, required={"contains_any"})
    source_label_tokens = _policy_string_list(labels_cfg["contains_any"], f"{labels_path}.contains_any", lower=True)
    copy_path = f"{path}.copy_stage"
    copy_cfg = _policy_mapping(cfg["copy_stage"], copy_path)
    _policy_keys(
        copy_cfg,
        copy_path,
        required={
            "command_tokens", "support_text_tokens", "support_signals",
            "minimum_signal_value_exclusive",
        },
    )
    copy_tokens = _policy_string_list(copy_cfg["command_tokens"], f"{copy_path}.command_tokens", lower=True)
    copy_text_support_tokens = _policy_string_list(copy_cfg["support_text_tokens"], f"{copy_path}.support_text_tokens", lower=True)
    copy_support_signals = frozenset(
        _policy_signal_list(copy_cfg["support_signals"], f"{copy_path}.support_signals")
    )
    follow_path = f"{path}.follow_on"
    follow_cfg = _policy_mapping(cfg["follow_on"], follow_path)
    _policy_keys(
        follow_cfg,
        follow_path,
        required={
            "any_signals", "minimum_signal_value_exclusive",
            "allow_unlabelled",
        },
    )
    follow_on_signals = frozenset(
        _policy_signal_list(follow_cfg["any_signals"], f"{follow_path}.any_signals")
    )
    allow_unlabelled = _policy_bool(follow_cfg["allow_unlabelled"], f"{follow_path}.allow_unlabelled")
    qualification_path = f"{path}.follow_on_qualification"
    qualification_cfg = _policy_mapping(
        cfg["follow_on_qualification"], qualification_path
    )
    _policy_keys(qualification_cfg, qualification_path, required={"any"})
    raw_clauses = qualification_cfg["any"]
    if not isinstance(raw_clauses, list) or not raw_clauses:
        raise ValueError(
            f"{qualification_path}.any: expected a non-empty list"
        )
    allowed_qualification_facts = {
        "copy_command", "copy_text_support", "copy_signal_support",
        "follow_on_signal",
    }
    qualification_clauses: List[frozenset[str]] = []
    for clause_index, raw_clause in enumerate(raw_clauses):
        clause_path = f"{qualification_path}.any[{clause_index}]"
        clause_cfg = _policy_mapping(raw_clause, clause_path)
        _policy_keys(clause_cfg, clause_path, required={"all"})
        facts = frozenset(_policy_string_list(
            clause_cfg["all"], f"{clause_path}.all", lower=True
        ))
        unknown_facts = sorted(facts - allowed_qualification_facts)
        if unknown_facts:
            raise ValueError(
                f"{clause_path}.all: unknown fact(s): "
                + ", ".join(unknown_facts)
            )
        if facts in qualification_clauses:
            raise ValueError(f"{clause_path}: duplicate condition clause")
        qualification_clauses.append(facts)
    evidence = _parse_policy_evidence(
        cfg["evidence"],
        f"{path}.evidence",
        allowed_resolvers={"row_field", "source_timestamp", "window_seconds"},
    )
    return ArtifactFollowOnPolicy(
        enabled=enabled,
        lookback=lookback,
        key_scope=key_scope,
        source_signals=source_signals,
        source_minimum_signal_value_exclusive=_policy_nonnegative_number(
            source_cfg["minimum_signal_value_exclusive"],
            f"{source_path}.minimum_signal_value_exclusive",
        ),
        path_fields=path_fields,
        text_fields=text_fields,
        source_label_tokens=source_label_tokens,
        copy_tokens=copy_tokens,
        copy_text_support_tokens=copy_text_support_tokens,
        copy_support_signals=copy_support_signals,
        copy_support_minimum_signal_value_exclusive=_policy_nonnegative_number(
            copy_cfg["minimum_signal_value_exclusive"],
            f"{copy_path}.minimum_signal_value_exclusive",
        ),
        follow_on_signals=follow_on_signals,
        follow_on_minimum_signal_value_exclusive=_policy_nonnegative_number(
            follow_cfg["minimum_signal_value_exclusive"],
            f"{follow_path}.minimum_signal_value_exclusive",
        ),
        follow_on_qualification=AnyAllFactConditionPolicy(
            any_all=tuple(qualification_clauses)
        ),
        allow_unlabelled_follow_on=allow_unlabelled,
        emission=_parse_single_policy_emission(cfg["emissions"], f"{path}.emissions"),
        evidence=evidence,
        evidence_type=evidence_type,
    )


def _parse_continuity_output_fields(
    raw: Any,
    path: str,
    semantics: Set[str],
) -> Dict[str, str]:
    cfg = _policy_mapping(raw, path)
    _policy_keys(cfg, path, required=semantics)
    fields = {
        semantic: _policy_signal_name(cfg[semantic], f"{path}.{semantic}")
        for semantic in semantics
    }
    duplicates = sorted(
        field_name
        for field_name in set(fields.values())
        if list(fields.values()).count(field_name) > 1
    )
    if duplicates:
        raise ValueError(
            f"{path}: output field names must be distinct: "
            + ", ".join(duplicates)
        )
    return fields


def _parse_continuity_emissions(
    raw: Any,
    path: str,
    semantics: Set[str],
) -> Dict[str, DetectorEmissionPolicy]:
    cfg = _policy_mapping(raw, path)
    _policy_keys(cfg, path, required=semantics)
    return {
        semantic: _parse_policy_emission(
            cfg[semantic],
            f"{path}.{semantic}",
            include_explanation=True,
        )
        for semantic in semantics
    }


def _parse_continuity_evidence_fields(
    raw: Any,
    path: str,
    allowed_resolvers: Set[str],
) -> Tuple[ContinuityEvidenceFieldPolicy, ...]:
    cfg = _policy_mapping(raw, path)
    if not cfg:
        raise ValueError(f"{path}: expected a non-empty mapping")
    parsed: List[ContinuityEvidenceFieldPolicy] = []
    for raw_name, raw_evidence in cfg.items():
        name = _policy_string(raw_name, f"{path} key")
        evidence_path = f"{path}.{name}"
        evidence_cfg = _policy_mapping(raw_evidence, evidence_path)
        _policy_keys(
            evidence_cfg,
            evidence_path,
            required={"resolver"},
            optional={"max_chars", "round_digits"},
        )
        resolver = _policy_enum(
            evidence_cfg["resolver"],
            f"{evidence_path}.resolver",
            allowed_resolvers,
        )
        max_chars = (
            _policy_positive_int(
                evidence_cfg["max_chars"], f"{evidence_path}.max_chars"
            )
            if "max_chars" in evidence_cfg
            else None
        )
        round_digits = (
            _policy_nonnegative_int(
                evidence_cfg["round_digits"],
                f"{evidence_path}.round_digits",
            )
            if "round_digits" in evidence_cfg
            else None
        )
        parsed.append(
            ContinuityEvidenceFieldPolicy(
                name=name,
                resolver=resolver,
                max_chars=max_chars,
                round_digits=round_digits,
            )
        )
    return tuple(parsed)


def _parse_continuity_evidence_by_semantic(
    raw: Any,
    path: str,
    allowed_by_semantic: Dict[str, Set[str]],
) -> Dict[str, Tuple[ContinuityEvidenceFieldPolicy, ...]]:
    cfg = _policy_mapping(raw, path)
    _policy_keys(cfg, path, required=set(allowed_by_semantic))
    return {
        semantic: _parse_continuity_evidence_fields(
            cfg[semantic],
            f"{path}.{semantic}",
            allowed_by_semantic[semantic],
        )
        for semantic in allowed_by_semantic
    }


def _parse_geographic_continuity_policy(
    raw: Any,
    path: str,
) -> GeographicContinuityPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "stage", "executor", "enabled", "evidence_type",
            "inputs", "history", "output_fields", "emissions", "evidence",
        },
    )
    _policy_enum(cfg["stage"], f"{path}.stage", {"temporal"})
    _policy_enum(
        cfg["executor"], f"{path}.executor", {"geographic_continuity"}
    )
    enabled = _policy_bool(cfg["enabled"], f"{path}.enabled")
    evidence_type = _policy_enum(
        cfg["evidence_type"], f"{path}.evidence_type", {"contextual"}
    )

    inputs_path = f"{path}.inputs"
    inputs = _policy_mapping(cfg["inputs"], inputs_path)
    _policy_keys(
        inputs,
        inputs_path,
        required={
            "key_fields", "success_signals",
            "minimum_signal_value_exclusive", "country_field", "asn_field",
            "city_field", "ip_fields",
        },
    )
    key_fields = _policy_string_list(
        inputs["key_fields"], f"{inputs_path}.key_fields"
    )
    success_signals = frozenset(
        _policy_signal_list(
            inputs["success_signals"], f"{inputs_path}.success_signals"
        )
    )
    country_field = _policy_string(
        inputs["country_field"], f"{inputs_path}.country_field"
    )
    asn_field = _policy_string(inputs["asn_field"], f"{inputs_path}.asn_field")
    city_field = _policy_string(
        inputs["city_field"], f"{inputs_path}.city_field"
    )
    ip_fields = _policy_string_list(inputs["ip_fields"], f"{inputs_path}.ip_fields")

    history_path = f"{path}.history"
    history = _policy_mapping(cfg["history"], history_path)
    _policy_keys(
        history,
        history_path,
        required={
            "retention", "novelty_reference", "mark_first_observation",
            "emit_first_observation", "boundary_reference",
        },
    )
    retention = history["retention"]
    if isinstance(retention, str) and retention.strip().lower() == "lifetime":
        history_lookback = None
    else:
        history_lookback = _parse_policy_lookback(
            retention, f"{history_path}.retention"
        )
    novelty_reference = _policy_enum(
        history["novelty_reference"],
        f"{history_path}.novelty_reference",
        {"all_seen", "previous_observation"},
    )
    mark_first_observation = _policy_bool(
        history["mark_first_observation"],
        f"{history_path}.mark_first_observation",
    )
    emit_first_observation = _policy_bool(
        history["emit_first_observation"],
        f"{history_path}.emit_first_observation",
    )
    boundary_reference = _policy_enum(
        history["boundary_reference"],
        f"{history_path}.boundary_reference",
        {"previous_observation", "any_prior_distinct"},
    )

    semantics = {"new_country", "new_asn", "new_city", "boundary_crossing"}
    output_fields = _parse_continuity_output_fields(
        cfg["output_fields"], f"{path}.output_fields", semantics
    )
    input_fields = {*key_fields, country_field, asn_field, city_field, *ip_fields}
    collisions = sorted(set(output_fields.values()) & input_fields)
    if collisions:
        raise ValueError(
            f"{path}.output_fields: output field(s) collide with input fields: "
            + ", ".join(collisions)
        )
    emissions = _parse_continuity_emissions(
        cfg["emissions"], f"{path}.emissions", semantics
    )
    evidence = _parse_continuity_evidence_by_semantic(
        cfg["evidence"],
        f"{path}.evidence",
        {
            "new_country": {
                "current_country", "previous_countries", "current_ip",
                "key_fields", "actor_key",
            },
            "new_asn": {
                "current_asn", "previous_asns", "current_ip",
                "key_fields", "actor_key",
            },
            "new_city": {
                "current_city", "current_country", "previous_cities",
                "current_ip", "key_fields", "actor_key",
            },
            "boundary_crossing": {
                "previous_country", "current_country", "previous_ip",
                "current_ip", "key_fields", "actor_key",
            },
        },
    )
    return GeographicContinuityPolicy(
        enabled=enabled,
        key_fields=key_fields,
        success_signals=success_signals,
        minimum_signal_value_exclusive=_policy_nonnegative_number(
            inputs["minimum_signal_value_exclusive"],
            f"{inputs_path}.minimum_signal_value_exclusive",
        ),
        history_lookback=history_lookback,
        novelty_reference=novelty_reference,
        mark_first_observation=mark_first_observation,
        emit_first_observation=emit_first_observation,
        boundary_reference=boundary_reference,
        country_field=country_field,
        asn_field=asn_field,
        city_field=city_field,
        ip_fields=ip_fields,
        output_fields=output_fields,
        emissions_by_semantic=emissions,
        evidence_by_semantic=evidence,
        evidence_type=evidence_type,
    )


def _parse_impossible_travel_policy(
    raw: Any,
    path: str,
) -> ImpossibleTravelPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "stage", "executor", "enabled", "evidence_type",
            "inputs", "state", "thresholds", "output_fields", "emissions",
            "evidence",
        },
    )
    _policy_enum(cfg["stage"], f"{path}.stage", {"temporal"})
    _policy_enum(cfg["executor"], f"{path}.executor", {"impossible_travel"})
    enabled = _policy_bool(cfg["enabled"], f"{path}.enabled")
    evidence_type = _policy_enum(
        cfg["evidence_type"], f"{path}.evidence_type", {"contextual"}
    )

    inputs_path = f"{path}.inputs"
    inputs = _policy_mapping(cfg["inputs"], inputs_path)
    _policy_keys(
        inputs,
        inputs_path,
        required={
            "key_fields", "success_signals",
            "minimum_signal_value_exclusive", "latitude_field",
            "longitude_field", "country_field", "ip_fields",
        },
    )
    key_fields = _policy_string_list(
        inputs["key_fields"], f"{inputs_path}.key_fields"
    )
    success_signals = frozenset(
        _policy_signal_list(
            inputs["success_signals"], f"{inputs_path}.success_signals"
        )
    )
    latitude_field = _policy_string(
        inputs["latitude_field"], f"{inputs_path}.latitude_field"
    )
    longitude_field = _policy_string(
        inputs["longitude_field"], f"{inputs_path}.longitude_field"
    )
    country_field = _policy_string(
        inputs["country_field"], f"{inputs_path}.country_field"
    )
    ip_fields = _policy_string_list(inputs["ip_fields"], f"{inputs_path}.ip_fields")

    state_path = f"{path}.state"
    state = _policy_mapping(cfg["state"], state_path)
    _policy_keys(
        state,
        state_path,
        required={
            "reference_selection", "rejected_observation_update",
            "qualifying_comparison_update",
        },
    )
    reference_selection = _policy_enum(
        state["reference_selection"],
        f"{state_path}.reference_selection",
        {"retained_reference", "previous_observation"},
    )
    rejected_observation_update = _policy_enum(
        state["rejected_observation_update"],
        f"{state_path}.rejected_observation_update",
        {"retain_reference", "update_reference"},
    )
    qualifying_comparison_update = _policy_enum(
        state["qualifying_comparison_update"],
        f"{state_path}.qualifying_comparison_update",
        {"retain_reference", "update_reference"},
    )

    thresholds_path = f"{path}.thresholds"
    thresholds = _policy_mapping(cfg["thresholds"], thresholds_path)
    _policy_keys(
        thresholds,
        thresholds_path,
        required={
            "minimum_distance_km", "minimum_distance_comparison",
            "minimum_time_seconds", "minimum_time_comparison",
            "velocity_kmh", "velocity_comparison",
        },
    )
    output_semantics = {
        "distance_km", "dt_hours", "velocity_kmh", "from_country",
        "to_country", "from_ip",
    }
    output_fields = _parse_continuity_output_fields(
        cfg["output_fields"], f"{path}.output_fields", output_semantics
    )
    input_fields = {
        *key_fields, latitude_field, longitude_field, country_field, *ip_fields,
    }
    collisions = sorted(set(output_fields.values()) & input_fields)
    if collisions:
        raise ValueError(
            f"{path}.output_fields: output field(s) collide with input fields: "
            + ", ".join(collisions)
        )
    return ImpossibleTravelPolicy(
        enabled=enabled,
        key_fields=key_fields,
        success_signals=success_signals,
        minimum_signal_value_exclusive=_policy_nonnegative_number(
            inputs["minimum_signal_value_exclusive"],
            f"{inputs_path}.minimum_signal_value_exclusive",
        ),
        latitude_field=latitude_field,
        longitude_field=longitude_field,
        country_field=country_field,
        ip_fields=ip_fields,
        reference_selection=reference_selection,
        rejected_observation_update=rejected_observation_update,
        qualifying_comparison_update=qualifying_comparison_update,
        minimum_distance_km=_policy_positive_number(
            thresholds["minimum_distance_km"],
            f"{thresholds_path}.minimum_distance_km",
        ),
        minimum_distance_comparison=_policy_enum(
            thresholds["minimum_distance_comparison"],
            f"{thresholds_path}.minimum_distance_comparison",
            {"greater_than", "greater_than_or_equal"},
        ),
        minimum_time_seconds=_policy_positive_number(
            thresholds["minimum_time_seconds"],
            f"{thresholds_path}.minimum_time_seconds",
        ),
        minimum_time_comparison=_policy_enum(
            thresholds["minimum_time_comparison"],
            f"{thresholds_path}.minimum_time_comparison",
            {"greater_than", "greater_than_or_equal"},
        ),
        velocity_kmh_threshold=_policy_positive_number(
            thresholds["velocity_kmh"], f"{thresholds_path}.velocity_kmh"
        ),
        velocity_comparison=_policy_enum(
            thresholds["velocity_comparison"],
            f"{thresholds_path}.velocity_comparison",
            {"greater_than", "greater_than_or_equal"},
        ),
        output_fields=output_fields,
        emission=_parse_continuity_emissions(
            cfg["emissions"], f"{path}.emissions", {"impossible_travel"}
        )["impossible_travel"],
        evidence=_parse_continuity_evidence_fields(
            cfg["evidence"],
            f"{path}.evidence",
            {
                "distance_km", "dt_hours", "velocity_kmh", "previous_ip",
                "current_ip", "previous_country", "current_country",
                "velocity_threshold_kmh", "minimum_distance_km",
                "key_fields", "actor_key",
            },
        ),
        evidence_type=evidence_type,
    )


def _parse_ip_scope_continuity_policy(
    raw: Any,
    path: str,
) -> IPScopeContinuityPolicy:
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "stage", "executor", "enabled", "evidence_type",
            "inputs", "history", "lookback", "conditions",
            "subnet_prefixes", "branch_mode", "transition_rules",
            "emissions", "evidence",
        },
    )
    _policy_enum(cfg["stage"], f"{path}.stage", {"temporal"})
    _policy_enum(
        cfg["executor"], f"{path}.executor", {"ip_scope_continuity"}
    )
    enabled = _policy_bool(cfg["enabled"], f"{path}.enabled")
    evidence_type = _policy_enum(
        cfg["evidence_type"], f"{path}.evidence_type", {"contextual"}
    )
    history_path = f"{path}.history"
    history = _policy_mapping(cfg["history"], history_path)
    _policy_keys(
        history,
        history_path,
        required={"reference_selection", "state_update"},
    )
    reference_selection = _policy_enum(
        history["reference_selection"],
        f"{history_path}.reference_selection",
        {"retained_reference", "previous_observation"},
    )
    state_update = _policy_enum(
        history["state_update"],
        f"{history_path}.state_update",
        {
            "every_valid_observation",
            "after_in_window_comparison",
            "after_transition_match",
        },
    )

    lookback_path = f"{path}.lookback"
    lookback_cfg = _policy_mapping(cfg["lookback"], lookback_path)
    _policy_keys(
        lookback_cfg,
        lookback_path,
        required={"duration", "window_bounds"},
    )
    try:
        lookback = parse_lookback(lookback_cfg["duration"])
    except ValueError as exc:
        raise ValueError(f"{lookback_path}.duration: {exc}") from exc
    if lookback <= timedelta(0):
        raise ValueError(
            f"{lookback_path}.duration: expected a duration greater than zero"
        )
    lookback_window_bounds = _policy_enum(
        lookback_cfg["window_bounds"],
        f"{lookback_path}.window_bounds",
        {"open", "closed"},
    )

    inputs_path = f"{path}.inputs"
    inputs = _policy_mapping(cfg["inputs"], inputs_path)
    _policy_keys(inputs, inputs_path, required={"key_fields", "ip_fields"})
    key_fields = _policy_string_list(
        inputs["key_fields"], f"{inputs_path}.key_fields"
    )
    ip_fields = _policy_string_list(inputs["ip_fields"], f"{inputs_path}.ip_fields")

    conditions_path = f"{path}.conditions"
    conditions = _policy_mapping(cfg["conditions"], conditions_path)
    _policy_keys(conditions, conditions_path, required={"require_address_change"})
    require_address_change = _policy_bool(
        conditions["require_address_change"],
        f"{conditions_path}.require_address_change",
    )

    prefixes_path = f"{path}.subnet_prefixes"
    prefixes = _policy_mapping(cfg["subnet_prefixes"], prefixes_path)
    _policy_keys(
        prefixes, prefixes_path, required={"ipv4_prefix_length", "ipv6_prefix_length"}
    )
    prefix_v4 = _policy_nonnegative_int(
        prefixes["ipv4_prefix_length"], f"{prefixes_path}.ipv4_prefix_length"
    )
    prefix_v6 = _policy_nonnegative_int(
        prefixes["ipv6_prefix_length"], f"{prefixes_path}.ipv6_prefix_length"
    )
    if prefix_v4 > 32:
        raise ValueError(f"{prefixes_path}.ipv4_prefix_length: expected 0..32")
    if prefix_v6 > 128:
        raise ValueError(f"{prefixes_path}.ipv6_prefix_length: expected 0..128")
    branch_mode = _policy_enum(
        cfg["branch_mode"],
        f"{path}.branch_mode",
        {"all_matches", "first_match"},
    )

    semantics = {
        "changed_private_ip", "crossed_private_subnet",
        "private_to_public", "public_to_private",
    }
    emissions = _parse_continuity_emissions(
        cfg["emissions"], f"{path}.emissions", semantics
    )
    transition_path = f"{path}.transition_rules"
    raw_rules = cfg["transition_rules"]
    if not isinstance(raw_rules, list) or not raw_rules:
        raise ValueError(f"{transition_path}: expected a non-empty list")
    transition_rules: List[IPScopeTransitionRulePolicy] = []
    seen_ids: Set[str] = set()
    seen_emissions: Set[str] = set()
    for index, raw_rule in enumerate(raw_rules):
        rule_path = f"{transition_path}[{index}]"
        rule_cfg = _policy_mapping(raw_rule, rule_path)
        _policy_keys(
            rule_cfg,
            rule_path,
            required={
                "id", "previous_scope", "current_scope", "subnet_change",
                "emission",
            },
        )
        rule_id = _policy_signal_name(rule_cfg["id"], f"{rule_path}.id")
        if rule_id in seen_ids:
            raise ValueError(f"{rule_path}.id: duplicate value {rule_id!r}")
        seen_ids.add(rule_id)
        emission_id = _policy_enum(
            rule_cfg["emission"], f"{rule_path}.emission", semantics
        )
        if emission_id in seen_emissions:
            raise ValueError(
                f"{rule_path}.emission: duplicate transition emission {emission_id!r}"
            )
        seen_emissions.add(emission_id)
        previous_scope = _policy_enum(
            rule_cfg["previous_scope"],
            f"{rule_path}.previous_scope",
            {"private", "public"},
        )
        current_scope = _policy_enum(
            rule_cfg["current_scope"],
            f"{rule_path}.current_scope",
            {"private", "public"},
        )
        subnet_change = _policy_enum(
            rule_cfg["subnet_change"],
            f"{rule_path}.subnet_change",
            {"any", "required"},
        )
        if subnet_change == "required" and (
            previous_scope != "private" or current_scope != "private"
        ):
            raise ValueError(
                f"{rule_path}.subnet_change: 'required' is valid only for "
                "private-to-private transitions"
            )
        transition_rules.append(
            IPScopeTransitionRulePolicy(
                rule_id=rule_id,
                previous_scope=previous_scope,
                current_scope=current_scope,
                subnet_change=subnet_change,
                emission_id=emission_id,
            )
        )
    missing_transition_emissions = sorted(semantics - seen_emissions)
    if missing_transition_emissions:
        raise ValueError(
            f"{transition_path}: missing transition for emission(s): "
            + ", ".join(missing_transition_emissions)
        )
    evidence = _parse_continuity_evidence_by_semantic(
        cfg["evidence"],
        f"{path}.evidence",
        {
            "changed_private_ip": {
                "actor_key", "previous_ip", "current_ip", "delta_seconds",
                "previous_subnet", "current_subnet", "previous_scope",
                "current_scope", "key_fields",
            },
            "crossed_private_subnet": {
                "actor_key", "previous_ip", "current_ip", "delta_seconds",
                "previous_subnet", "current_subnet", "previous_scope",
                "current_scope", "key_fields",
            },
            "private_to_public": {
                "actor_key", "previous_ip", "current_ip", "delta_seconds",
                "previous_subnet", "current_subnet", "previous_scope",
                "current_scope", "key_fields",
            },
            "public_to_private": {
                "actor_key", "previous_ip", "current_ip", "delta_seconds",
                "previous_subnet", "current_subnet", "previous_scope",
                "current_scope", "key_fields",
            },
        },
    )
    return IPScopeContinuityPolicy(
        enabled=enabled,
        key_fields=key_fields,
        ip_fields=ip_fields,
        reference_selection=reference_selection,
        state_update=state_update,
        lookback=lookback,
        lookback_window_bounds=lookback_window_bounds,
        require_address_change=require_address_change,
        subnet_prefix_v4=prefix_v4,
        subnet_prefix_v6=prefix_v6,
        branch_mode=branch_mode,
        transition_rules=tuple(transition_rules),
        emissions_by_semantic=emissions,
        evidence_by_semantic=evidence,
        evidence_type=evidence_type,
    )


def _parse_detector_policy(
    rules_doc: Dict[str, Any],
    weights_doc: Dict[str, Any],
) -> DetectorPolicy:
    raw_policy = (rules_doc or {}).get("detector_policy")
    if raw_policy is None:
        raise ValueError(
            "detector_policy: missing required top-level section; provide "
            "detector_policy.version=1 and complete migrated detector definitions"
        )

    root = "detector_policy"
    policy_cfg = _policy_mapping(raw_policy, root)
    _policy_keys(policy_cfg, root, required={"version", "mode", "detectors"})
    if type(policy_cfg["version"]) is not int or policy_cfg["version"] != 1:
        raise ValueError("detector_policy.version: only version 1 is supported")
    mode = _policy_enum(policy_cfg["mode"], "detector_policy.mode", {"authoritative"})
    detectors = _policy_mapping(policy_cfg["detectors"], "detector_policy.detectors")
    required_detector_ids = {
        "clamav_classification",
        "yara_classification",
        "web_request_classification",
        "referenced_file_correlation",
        "webshell_artifact",
        "canonical_authentication",
        "execution_context_classifier",
        "file_lifecycle",
        "mft_timestomping",
        "geographic_continuity",
        "impossible_travel",
        "ip_scope_continuity",
        "persistence_configuration",
        "direct_attack_semantics",
        "contextual_signal_adjustments",
        "repeated_scheduled_execution",
        "systemd_service_persistence",
        "download_to_execution",
        "masquerading",
        "webshell_activity",
        "web_upload_execution_chain",
        "execution_lolbin",
        "execution_lolbin_suspicious_args",
        "execution_interpreter",
        "execution_scheduled",
        "execution_privileged_scheduled",
        "suspicious_execution",
        "automated_collection",
        "canonical_persistence_projection",
        "canonical_transfer_projection",
        "canonical_transfer_post_temporal_projection",
        "ransomware_impact",
        "automated_exfiltration",
        "credential_dump_collection",
        "password_store_exfil_chain",
    }
    missing_detectors = sorted(required_detector_ids - set(detectors))
    if missing_detectors:
        raise ValueError(
            "detector_policy.detectors: missing required key(s): "
            + ", ".join(missing_detectors)
        )
    for detector_id in detectors:
        _policy_signal_name(detector_id, "detector_policy.detectors key")

    engine_cfg = _policy_mapping(
        (rules_doc or {}).get("engine_config", {}) or {},
        "engine_config",
    )
    obsolete_engine_sections = sorted(
        section
        for section in (
            "path_taxonomy",
            "detection_vocabulary",
            "detection_event_ids",
            "detection_thresholds",
        )
        if section in engine_cfg
    )
    if obsolete_engine_sections:
        raise ValueError(
            "engine_config: obsolete shared rule-logic section(s): "
            + ", ".join(obsolete_engine_sections)
            + "; configure values in the owning detector_policy definition"
        )
    if "yara_forge_metadata_path" in engine_cfg:
        raise ValueError(
            "engine_config.yara_forge_metadata_path: obsolete when detector_policy "
            "is authoritative; use detector_policy.detectors.yara_classification."
            "metadata.path"
        )
    if "referenced_file_hit_propagation" in engine_cfg:
        raise ValueError(
            "engine_config.referenced_file_hit_propagation: obsolete when "
            "detector_policy is authoritative; use detector_policy.detectors."
            "referenced_file_correlation"
        )
    if "canonical_auth_signals" in engine_cfg:
        raise ValueError(
            "engine_config.canonical_auth_signals: obsolete when detector_policy "
            "is authoritative; use detector_policy.detectors."
            "canonical_authentication"
        )
    obsolete_top_level_sections = sorted(
        section
        for section in ("impossible_travel", "private_ip_continuity")
        if section in (rules_doc or {})
    )
    if obsolete_top_level_sections:
        raise ValueError(
            "obsolete top-level detector section(s): "
            + ", ".join(obsolete_top_level_sections)
            + "; configure the mandatory detector_policy continuity definitions"
        )
    clamav_path = "detector_policy.detectors.clamav_classification"
    clamav_policy = _parse_clamav_classifier_policy(
        detectors["clamav_classification"],
        clamav_path,
    )

    yara_path = "detector_policy.detectors.yara_classification"
    yara_policy = _parse_yara_classifier_policy(
        detectors["yara_classification"],
        yara_path,
    )

    web_request_path = "detector_policy.detectors.web_request_classification"
    web_request_policy = _parse_web_request_classifier_policy(
        detectors["web_request_classification"],
        web_request_path,
    )

    referenced_file_path = "detector_policy.detectors.referenced_file_correlation"
    referenced_file_policy = _parse_referenced_file_correlation_policy(
        detectors["referenced_file_correlation"],
        referenced_file_path,
        web_request_policy,
        clamav_policy.category_universe | yara_policy.category_universe,
    )

    webshell_artifact_path = "detector_policy.detectors.webshell_artifact"
    webshell_artifact_policy = _parse_webshell_artifact_policy(
        detectors["webshell_artifact"],
        webshell_artifact_path,
    )

    canonical_auth_policy = _parse_canonical_authentication_policy(
        detectors["canonical_authentication"],
        "detector_policy.detectors.canonical_authentication",
    )
    execution_context_policy = _parse_execution_context_classifier_policy(
        detectors["execution_context_classifier"],
        "detector_policy.detectors.execution_context_classifier",
    )
    file_lifecycle_policy = _parse_file_lifecycle_policy(
        detectors["file_lifecycle"],
        "detector_policy.detectors.file_lifecycle",
    )
    mft_timestomping_policy = _parse_mft_timestomping_policy(
        detectors["mft_timestomping"],
        "detector_policy.detectors.mft_timestomping",
    )
    persistence_configuration_policy = _parse_ordered_row_rules_policy(
        detectors["persistence_configuration"],
        "detector_policy.detectors.persistence_configuration",
    )
    direct_attack_semantics_policy = _parse_ordered_row_rules_policy(
        detectors["direct_attack_semantics"],
        "detector_policy.detectors.direct_attack_semantics",
    )
    contextual_signal_adjustments_policy = (
        _parse_ordered_signal_adjustments_policy(
            detectors["contextual_signal_adjustments"],
            "detector_policy.detectors.contextual_signal_adjustments",
        )
    )
    repeated_scheduled_execution_policy = _parse_grouped_signal_window_policy(
        detectors["repeated_scheduled_execution"],
        "detector_policy.detectors.repeated_scheduled_execution",
    )
    fixed_execution_phases = {
        "persistence_configuration": (
            persistence_configuration_policy, 19
        ),
        "repeated_scheduled_execution": (
            repeated_scheduled_execution_policy, 19
        ),
        "direct_attack_semantics": (direct_attack_semantics_policy, 28),
        "contextual_signal_adjustments": (
            contextual_signal_adjustments_policy, 35
        ),
    }
    for detector_id, (parsed_policy, expected_phase) in (
        fixed_execution_phases.items()
    ):
        if parsed_policy.execution_phase != expected_phase:
            raise ValueError(
                f"detector_policy.detectors.{detector_id}.phase: expected "
                f"fixed executor phase {expected_phase}; this field declares "
                "the runtime schedule and cannot reschedule the executor"
            )
    geographic_continuity_policy = _parse_geographic_continuity_policy(
        detectors["geographic_continuity"],
        "detector_policy.detectors.geographic_continuity",
    )
    impossible_travel_policy = _parse_impossible_travel_policy(
        detectors["impossible_travel"],
        "detector_policy.detectors.impossible_travel",
    )
    ip_scope_continuity_policy = _parse_ip_scope_continuity_policy(
        detectors["ip_scope_continuity"],
        "detector_policy.detectors.ip_scope_continuity",
    )

    systemd_path = "detector_policy.detectors.systemd_service_persistence"
    systemd_cfg = _policy_mapping(detectors["systemd_service_persistence"], systemd_path)
    _policy_keys(
        systemd_cfg,
        systemd_path,
        required={
            "stage", "executor", "enabled", "branch_mode", "branch_order",
            "evidence_type", "inputs", "branches", "emissions", "evidence",
        },
    )
    _policy_enum(systemd_cfg["stage"], f"{systemd_path}.stage", {"contextual"})
    _policy_enum(
        systemd_cfg["executor"],
        f"{systemd_path}.executor",
        {"systemd_service_persistence"},
    )
    systemd_enabled = _policy_bool(systemd_cfg["enabled"], f"{systemd_path}.enabled")
    systemd_branch_mode = _policy_enum(
        systemd_cfg["branch_mode"],
        f"{systemd_path}.branch_mode",
        {"all_matches", "first_match"},
    )
    systemd_evidence_type = _policy_enum(
        systemd_cfg["evidence_type"],
        f"{systemd_path}.evidence_type",
        {"direct"},
    )

    inputs_path = f"{systemd_path}.inputs"
    inputs_cfg = _policy_mapping(systemd_cfg["inputs"], inputs_path)
    _policy_keys(inputs_cfg, inputs_path, required={"path", "timestamp_kind", "combined_text"})
    path_input_path = f"{inputs_path}.path"
    path_input = _policy_mapping(inputs_cfg["path"], path_input_path)
    _policy_keys(path_input, path_input_path, required={"resolver", "fields"})
    _policy_enum(path_input["resolver"], f"{path_input_path}.resolver", {"best_effort_file_path"})
    path_fields = _policy_string_list(path_input["fields"], f"{path_input_path}.fields")

    timestamp_input_path = f"{inputs_path}.timestamp_kind"
    timestamp_input = _policy_mapping(inputs_cfg["timestamp_kind"], timestamp_input_path)
    _policy_keys(
        timestamp_input,
        timestamp_input_path,
        required={"resolver", "field", "kinds"},
    )
    _policy_enum(
        timestamp_input["resolver"],
        f"{timestamp_input_path}.resolver",
        {"timestamp_desc_kind"},
    )
    timestamp_field = _policy_string(timestamp_input["field"], f"{timestamp_input_path}.field")
    timestamp_kinds_path = f"{timestamp_input_path}.kinds"
    timestamp_kinds_cfg = _policy_mapping(
        timestamp_input["kinds"], timestamp_kinds_path
    )
    _policy_keys(
        timestamp_kinds_cfg,
        timestamp_kinds_path,
        required={"priority", "contains"},
    )
    timestamp_kind_priority = _policy_string_list(
        timestamp_kinds_cfg["priority"],
        f"{timestamp_kinds_path}.priority",
        lower=True,
    )
    if len(timestamp_kind_priority) != len(set(timestamp_kind_priority)):
        raise ValueError(
            f"{timestamp_kinds_path}.priority: duplicate kind name"
        )
    timestamp_contains_path = f"{timestamp_kinds_path}.contains"
    timestamp_contains_cfg = _policy_mapping(
        timestamp_kinds_cfg["contains"], timestamp_contains_path
    )
    _policy_keys(
        timestamp_contains_cfg,
        timestamp_contains_path,
        required=set(timestamp_kind_priority),
    )
    timestamp_kind_tokens = {
        name: _policy_string_list(
            timestamp_contains_cfg[name],
            f"{timestamp_contains_path}.{name}",
            lower=True,
        )
        for name in timestamp_kind_priority
    }

    text_input_path = f"{inputs_path}.combined_text"
    text_input = _policy_mapping(inputs_cfg["combined_text"], text_input_path)
    _policy_keys(text_input, text_input_path, required={"resolver", "fields", "first_existing"})
    _policy_enum(text_input["resolver"], f"{text_input_path}.resolver", {"concat_lower"})
    text_fields = _policy_string_list(text_input["fields"], f"{text_input_path}.fields")
    first_existing_fields = _policy_string_list(
        text_input["first_existing"],
        f"{text_input_path}.first_existing",
    )

    systemd_evidence = _parse_policy_evidence(
        systemd_cfg["evidence"],
        f"{systemd_path}.evidence",
        allowed_resolvers={
            "best_effort_file_path", "row_field", "first_nonempty"
        },
    )
    systemd_evidence_names = {item.name for item in systemd_evidence}

    branches_path = f"{systemd_path}.branches"
    branches_cfg = _policy_mapping(systemd_cfg["branches"], branches_path)
    _policy_keys(branches_cfg, branches_path, required={"artifact_change", "command_activity"})
    systemd_branch_order = _policy_string_list(
        systemd_cfg["branch_order"], f"{systemd_path}.branch_order"
    )
    expected_systemd_branches = {"artifact_change", "command_activity"}
    if (
        len(systemd_branch_order) != len(expected_systemd_branches)
        or set(systemd_branch_order) != expected_systemd_branches
    ):
        raise ValueError(
            f"{systemd_path}.branch_order: expected artifact_change and "
            "command_activity exactly once"
        )

    systemd_condition_facts = {
        "artifact_path", "unit_extension", "timestamp_kind",
        "persistent_token", "transient_token", "unit_reference_extension",
        "unit_reference_path",
    }

    def parse_systemd_conditions(
        raw_conditions: Any,
        condition_path: str,
    ) -> SystemdBranchConditionPolicy:
        condition_cfg = _policy_mapping(raw_conditions, condition_path)
        _policy_keys(condition_cfg, condition_path, required={"any"})
        raw_clauses = condition_cfg["any"]
        if not isinstance(raw_clauses, list) or not raw_clauses:
            raise ValueError(f"{condition_path}.any: expected a non-empty list")
        clauses: List[frozenset[str]] = []
        for clause_index, raw_clause in enumerate(raw_clauses):
            clause_path = f"{condition_path}.any[{clause_index}]"
            clause_cfg = _policy_mapping(raw_clause, clause_path)
            _policy_keys(clause_cfg, clause_path, required={"all"})
            facts = frozenset(
                _policy_string_list(
                    clause_cfg["all"], f"{clause_path}.all"
                )
            )
            unknown_facts = sorted(facts - systemd_condition_facts)
            if unknown_facts:
                raise ValueError(
                    f"{clause_path}.all: unknown fact(s): "
                    + ", ".join(unknown_facts)
                )
            if any(facts == existing for existing in clauses):
                raise ValueError(
                    f"{clause_path}: duplicate condition clause"
                )
            clauses.append(facts)
        return SystemdBranchConditionPolicy(any_all=tuple(clauses))

    artifact_path = f"{branches_path}.artifact_change"
    artifact_cfg = _policy_mapping(branches_cfg["artifact_change"], artifact_path)
    _policy_keys(
        artifact_cfg,
        artifact_path,
        required={
            "conditions", "path_contains", "extension_in", "timestamp_kinds",
            "description", "confidence", "evidence",
        },
    )
    artifact_evidence = _policy_string_list(artifact_cfg["evidence"], f"{artifact_path}.evidence")
    unsupported_artifact_evidence = set(artifact_evidence) - systemd_evidence_names
    if unsupported_artifact_evidence:
        raise ValueError(
            f"{artifact_path}.evidence: unsupported value(s): "
            f"{', '.join(sorted(unsupported_artifact_evidence))}"
        )
    artifact = SystemdArtifactPolicy(
        conditions=parse_systemd_conditions(
            artifact_cfg["conditions"], f"{artifact_path}.conditions"
        ),
        path_patterns=_policy_string_list(
            artifact_cfg["path_contains"],
            f"{artifact_path}.path_contains",
            lower=True,
        ),
        unit_extensions=_policy_string_list(
            artifact_cfg["extension_in"],
            f"{artifact_path}.extension_in",
            lower=True,
        ),
        timestamp_kinds=frozenset(
            _policy_string_list(
                artifact_cfg["timestamp_kinds"],
                f"{artifact_path}.timestamp_kinds",
                lower=True,
            )
        ),
        description=_policy_string(artifact_cfg["description"], f"{artifact_path}.description"),
        confidence=_policy_confidence(artifact_cfg["confidence"], f"{artifact_path}.confidence"),
        evidence=artifact_evidence,
    )
    unknown_timestamp_kinds = (
        artifact.timestamp_kinds - set(timestamp_kind_priority)
    )
    if unknown_timestamp_kinds:
        raise ValueError(
            f"{artifact_path}.timestamp_kinds: unsupported value(s): "
            f"{', '.join(sorted(unknown_timestamp_kinds))}"
        )

    command_path = f"{branches_path}.command_activity"
    command_cfg = _policy_mapping(branches_cfg["command_activity"], command_path)
    _policy_keys(
        command_cfg,
        command_path,
        required={
            "conditions", "persistent_tokens", "transient_tokens", "unit_reference_extensions",
            "unit_reference_path_tokens", "description", "confidence", "evidence",
        },
    )
    command_evidence = _policy_string_list(command_cfg["evidence"], f"{command_path}.evidence")
    unsupported_command_evidence = set(command_evidence) - systemd_evidence_names
    if unsupported_command_evidence:
        raise ValueError(
            f"{command_path}.evidence: unsupported value(s): "
            f"{', '.join(sorted(unsupported_command_evidence))}"
        )
    command = SystemdCommandPolicy(
        conditions=parse_systemd_conditions(
            command_cfg["conditions"], f"{command_path}.conditions"
        ),
        persistent_tokens=_policy_string_list(
            command_cfg["persistent_tokens"],
            f"{command_path}.persistent_tokens",
            lower=True,
        ),
        transient_tokens=_policy_string_list(
            command_cfg["transient_tokens"],
            f"{command_path}.transient_tokens",
            lower=True,
        ),
        unit_reference_extensions=_policy_string_list(
            command_cfg["unit_reference_extensions"],
            f"{command_path}.unit_reference_extensions",
            lower=True,
        ),
        unit_reference_path_tokens=_policy_string_list(
            command_cfg["unit_reference_path_tokens"],
            f"{command_path}.unit_reference_path_tokens",
            lower=True,
        ),
        description=_policy_string(command_cfg["description"], f"{command_path}.description"),
        confidence=_policy_confidence(command_cfg["confidence"], f"{command_path}.confidence"),
        evidence=command_evidence,
    )

    systemd_emissions_path = f"{systemd_path}.emissions"
    if not isinstance(systemd_cfg["emissions"], list) or len(systemd_cfg["emissions"]) != 1:
        raise ValueError(f"{systemd_emissions_path}: expected exactly one emission")
    systemd_emission = _parse_policy_emission(
        systemd_cfg["emissions"][0],
        f"{systemd_emissions_path}[0]",
        include_explanation=False,
    )
    systemd_policy = SystemdServicePersistencePolicy(
        enabled=systemd_enabled,
        branch_mode=systemd_branch_mode,
        branch_order=systemd_branch_order,
        path_fields=path_fields,
        timestamp_field=timestamp_field,
        timestamp_kind_priority=timestamp_kind_priority,
        timestamp_kind_tokens=timestamp_kind_tokens,
        text_fields=text_fields,
        first_existing_text_fields=first_existing_fields,
        artifact=artifact,
        command=command,
        emission=systemd_emission,
        evidence=systemd_evidence,
        evidence_type=systemd_evidence_type,
    )

    download_path = "detector_policy.detectors.download_to_execution"
    download_cfg = _policy_mapping(detectors["download_to_execution"], download_path)
    _policy_keys(
        download_cfg,
        download_path,
        required={
            "stage", "executor", "enabled", "evidence_type", "lookback",
            "ordering", "window_bounds", "source_selection", "emit_on", "key",
            "source", "target", "emissions", "evidence",
        },
    )
    _policy_enum(download_cfg["stage"], f"{download_path}.stage", {"temporal"})
    _policy_enum(
        download_cfg["executor"],
        f"{download_path}.executor",
        {"signal_sequence_by_artifact"},
    )
    download_enabled = _policy_bool(download_cfg["enabled"], f"{download_path}.enabled")
    download_evidence_type = _policy_enum(
        download_cfg["evidence_type"],
        f"{download_path}.evidence_type",
        {"contextual"},
    )
    try:
        download_lookback = parse_lookback(download_cfg["lookback"])
    except ValueError as exc:
        raise ValueError(f"{download_path}.lookback: {exc}") from exc
    if download_lookback <= timedelta(0):
        raise ValueError(f"{download_path}.lookback: expected a duration greater than zero")
    ordering = _policy_enum(
        download_cfg["ordering"],
        f"{download_path}.ordering",
        {"source_at_or_before_target", "source_before_target"},
    )
    window_bounds = _policy_enum(
        download_cfg["window_bounds"],
        f"{download_path}.window_bounds",
        {"closed"},
    )
    source_selection = _policy_enum(
        download_cfg["source_selection"],
        f"{download_path}.source_selection",
        {"earliest_in_window", "latest_in_window"},
    )
    _policy_enum(download_cfg["emit_on"], f"{download_path}.emit_on", {"target"})

    key_path = f"{download_path}.key"
    key_cfg = _policy_mapping(download_cfg["key"], key_path)
    _policy_keys(
        key_cfg,
        key_path,
        required={"scope", "host_field", "artifact"},
    )
    key_scope = _policy_enum(
        key_cfg["scope"],
        f"{key_path}.scope",
        {"deadbox_global", "hostname"},
    )
    host_field = _policy_string(
        key_cfg["host_field"],
        f"{key_path}.host_field",
    )
    artifact_key_path = f"{key_path}.artifact"
    artifact_key_cfg = _policy_mapping(key_cfg["artifact"], artifact_key_path)
    _policy_keys(artifact_key_cfg, artifact_key_path, required={"resolver", "fields"})
    _policy_enum(
        artifact_key_cfg["resolver"],
        f"{artifact_key_path}.resolver",
        {"best_effort_file_basename"},
    )
    artifact_fields = _policy_string_list(
        artifact_key_cfg["fields"],
        f"{artifact_key_path}.fields",
    )

    source_path = f"{download_path}.source"
    source_cfg = _policy_mapping(download_cfg["source"], source_path)
    _policy_keys(
        source_cfg,
        source_path,
        required={"any_signals", "minimum_signal_value_exclusive"},
    )
    source_signals = frozenset(
        _policy_signal_list(source_cfg["any_signals"], f"{source_path}.any_signals")
    )
    target_path = f"{download_path}.target"
    target_cfg = _policy_mapping(download_cfg["target"], target_path)
    _policy_keys(
        target_cfg,
        target_path,
        required={"any_signals", "minimum_signal_value_exclusive"},
    )
    target_signals = frozenset(
        _policy_signal_list(target_cfg["any_signals"], f"{target_path}.any_signals")
    )

    download_emissions_path = f"{download_path}.emissions"
    if not isinstance(download_cfg["emissions"], list) or not download_cfg["emissions"]:
        raise ValueError(f"{download_emissions_path}: expected a non-empty list")
    download_emissions = tuple(
        _parse_policy_emission(
            item,
            f"{download_emissions_path}[{index}]",
            include_explanation=True,
        )
        for index, item in enumerate(download_cfg["emissions"])
    )
    download_evidence = _policy_string_list(download_cfg["evidence"], f"{download_path}.evidence")
    unsupported_download_evidence = set(download_evidence) - {
        "filename", "download_timestamp", "execution_timestamp", "hostname",
    }
    if unsupported_download_evidence:
        raise ValueError(
            f"{download_path}.evidence: unsupported value(s): "
            f"{', '.join(sorted(unsupported_download_evidence))}"
        )
    download_policy = DownloadExecutionPolicy(
        enabled=download_enabled,
        lookback=download_lookback,
        ordering=ordering,
        window_bounds=window_bounds,
        source_selection=source_selection,
        key_scope=key_scope,
        host_field=host_field,
        artifact_fields=artifact_fields,
        source_signals=source_signals,
        source_minimum_signal_value_exclusive=_policy_nonnegative_number(
            source_cfg["minimum_signal_value_exclusive"],
            f"{source_path}.minimum_signal_value_exclusive",
        ),
        target_signals=target_signals,
        target_minimum_signal_value_exclusive=_policy_nonnegative_number(
            target_cfg["minimum_signal_value_exclusive"],
            f"{target_path}.minimum_signal_value_exclusive",
        ),
        emissions=download_emissions,
        evidence=download_evidence,
        evidence_type=download_evidence_type,
    )

    masquerading_path = "detector_policy.detectors.masquerading"
    masquerading_policy = _parse_signal_gate_policy(
        detectors["masquerading"],
        masquerading_path,
        allowed_stages={"contextual"},
    )

    webshell_path = "detector_policy.detectors.webshell_activity"
    webshell_policy = _parse_signal_sequence_policy(
        detectors["webshell_activity"],
        webshell_path,
    )

    ransomware_policy = _parse_ransomware_impact_policy(
        detectors["ransomware_impact"],
        "detector_policy.detectors.ransomware_impact",
    )
    automated_exfiltration_policy = _parse_counted_signal_window_policy(
        detectors["automated_exfiltration"],
        "detector_policy.detectors.automated_exfiltration",
    )
    credential_dump_collection_policy = _parse_artifact_follow_on_policy(
        detectors["credential_dump_collection"],
        "detector_policy.detectors.credential_dump_collection",
    )
    password_store_exfil_policy = _parse_artifact_follow_on_policy(
        detectors["password_store_exfil_chain"],
        "detector_policy.detectors.password_store_exfil_chain",
    )

    definitions: List[DetectorDefinition] = [
        DetectorDefinition(
            detector_id="clamav_classification",
            stage="atomic",
            executor="clamav_classifier",
            payload=clamav_policy,
            emissions=clamav_policy.emissions,
        ),
        DetectorDefinition(
            detector_id="yara_classification",
            stage="atomic",
            executor="yara_classifier",
            payload=yara_policy,
            emissions=yara_policy.emissions,
        ),
        DetectorDefinition(
            detector_id="web_request_classification",
            stage="atomic",
            executor="web_request_classifier",
            payload=web_request_policy,
            emissions=web_request_policy.emissions,
        ),
        DetectorDefinition(
            detector_id="referenced_file_correlation",
            stage="contextual",
            executor="referenced_file_correlation",
            payload=referenced_file_policy,
            emissions=referenced_file_policy.emissions,
        ),
        DetectorDefinition(
            detector_id="webshell_artifact",
            stage="contextual",
            executor="webshell_artifact",
            payload=webshell_artifact_policy,
            emissions=(webshell_artifact_policy.emission,),
        ),
        DetectorDefinition(
            detector_id="canonical_authentication",
            stage="atomic",
            executor="canonical_authentication",
            payload=canonical_auth_policy,
            emissions=canonical_auth_policy.emissions,
        ),
        DetectorDefinition(
            detector_id="execution_context_classifier",
            stage="atomic",
            executor="execution_context_classifier",
            payload=execution_context_policy,
            emissions=execution_context_policy.emissions,
        ),
        DetectorDefinition(
            detector_id="file_lifecycle",
            stage="contextual",
            executor="file_lifecycle",
            payload=file_lifecycle_policy,
            emissions=file_lifecycle_policy.emissions,
        ),
        DetectorDefinition(
            detector_id="mft_timestomping",
            stage="contextual",
            executor="mft_timestomping",
            payload=mft_timestomping_policy,
            emissions=mft_timestomping_policy.emissions,
        ),
        DetectorDefinition(
            detector_id="persistence_configuration",
            stage="contextual",
            executor="ordered_row_rules",
            payload=persistence_configuration_policy,
            emissions=persistence_configuration_policy.emissions,
        ),
        DetectorDefinition(
            detector_id="direct_attack_semantics",
            stage="contextual",
            executor="ordered_row_rules",
            payload=direct_attack_semantics_policy,
            emissions=direct_attack_semantics_policy.emissions,
        ),
        DetectorDefinition(
            detector_id="contextual_signal_adjustments",
            stage="contextual",
            executor="ordered_signal_adjustments",
            payload=contextual_signal_adjustments_policy,
            emissions=contextual_signal_adjustments_policy.emissions,
        ),
        DetectorDefinition(
            detector_id="repeated_scheduled_execution",
            stage="contextual",
            executor="grouped_signal_window",
            payload=repeated_scheduled_execution_policy,
            emissions=repeated_scheduled_execution_policy.emissions,
        ),
        DetectorDefinition(
            detector_id="systemd_service_persistence",
            stage="contextual",
            executor="systemd_service_persistence",
            payload=systemd_policy,
            emissions=(systemd_emission,),
        ),
        DetectorDefinition(
            detector_id="download_to_execution",
            stage="temporal",
            executor="signal_sequence_by_artifact",
            payload=download_policy,
            emissions=download_emissions,
        ),
        DetectorDefinition(
            detector_id="geographic_continuity",
            stage="temporal",
            executor="geographic_continuity",
            payload=geographic_continuity_policy,
            emissions=geographic_continuity_policy.emissions,
        ),
        DetectorDefinition(
            detector_id="impossible_travel",
            stage="temporal",
            executor="impossible_travel",
            payload=impossible_travel_policy,
            emissions=impossible_travel_policy.emissions,
        ),
        DetectorDefinition(
            detector_id="ip_scope_continuity",
            stage="temporal",
            executor="ip_scope_continuity",
            payload=ip_scope_continuity_policy,
            emissions=ip_scope_continuity_policy.emissions,
        ),
        DetectorDefinition(
            detector_id="masquerading",
            stage="contextual",
            executor="signal_gate",
            payload=masquerading_policy,
            emissions=masquerading_policy.emissions,
        ),
        DetectorDefinition(
            detector_id="webshell_activity",
            stage="temporal",
            executor="signal_sequence",
            payload=webshell_policy,
            emissions=webshell_policy.emissions,
        ),
        DetectorDefinition(
            detector_id="ransomware_impact",
            stage="temporal",
            executor="temporal_context_branches",
            payload=ransomware_policy,
            emissions=(ransomware_policy.emission,),
        ),
        DetectorDefinition(
            detector_id="automated_exfiltration",
            stage="temporal",
            executor="counted_signal_window",
            payload=automated_exfiltration_policy,
            emissions=(automated_exfiltration_policy.emission,),
        ),
        DetectorDefinition(
            detector_id="credential_dump_collection",
            stage="temporal",
            executor="artifact_follow_on_sequence",
            payload=credential_dump_collection_policy,
            emissions=(credential_dump_collection_policy.emission,),
        ),
        DetectorDefinition(
            detector_id="password_store_exfil_chain",
            stage="temporal",
            executor="artifact_follow_on_sequence",
            payload=password_store_exfil_policy,
            emissions=(password_store_exfil_policy.emission,),
        ),
    ]
    specialised_detector_ids = {
        "clamav_classification",
        "yara_classification",
        "web_request_classification",
        "referenced_file_correlation",
        "webshell_artifact",
        "canonical_authentication",
        "execution_context_classifier",
        "file_lifecycle",
        "mft_timestomping",
        "geographic_continuity",
        "impossible_travel",
        "ip_scope_continuity",
        "persistence_configuration",
        "direct_attack_semantics",
        "contextual_signal_adjustments",
        "repeated_scheduled_execution",
        "systemd_service_persistence",
        "download_to_execution",
        "masquerading",
        "webshell_activity",
        "ransomware_impact",
        "automated_exfiltration",
        "credential_dump_collection",
        "password_store_exfil_chain",
    }
    required_atomic_gate_ids = {
        "execution_lolbin",
        "execution_lolbin_suspicious_args",
        "execution_interpreter",
        "execution_scheduled",
        "execution_privileged_scheduled",
        "suspicious_execution",
    }
    required_contextual_gate_ids = {"automated_collection"}
    required_projection_stages = {
        "canonical_persistence_projection": "contextual",
        "canonical_transfer_projection": "contextual",
        "canonical_transfer_post_temporal_projection": "temporal",
    }
    for detector_id, raw_detector in detectors.items():
        if detector_id in specialised_detector_ids:
            continue
        detector_path = f"detector_policy.detectors.{detector_id}"
        detector_cfg = _policy_mapping(raw_detector, detector_path)
        executor = _policy_string(
            detector_cfg.get("executor"),
            f"{detector_path}.executor",
        )
        if detector_id in required_atomic_gate_ids and executor != "signal_gate":
            raise ValueError(
                f"{detector_path}.executor: required canonical execution "
                "detectors must use 'signal_gate'"
            )
        if detector_id in required_contextual_gate_ids and executor != "signal_gate":
            raise ValueError(
                f"{detector_path}.executor: required contextual grouped "
                "detectors must use 'signal_gate'"
            )
        if detector_id in required_projection_stages and executor != "signal_projection":
            raise ValueError(
                f"{detector_path}.executor: required canonical projection "
                "detectors must use 'signal_projection'"
            )
        if detector_id == "web_upload_execution_chain" and executor != "signal_sequence":
            raise ValueError(
                f"{detector_path}.executor: required web-upload execution detector "
                "must use 'signal_sequence'"
            )
        if executor == "signal_gate":
            payload = _parse_signal_gate_policy(raw_detector, detector_path)
            stage = _policy_enum(
                detector_cfg.get("stage"),
                f"{detector_path}.stage",
                {"atomic", "contextual"},
            )
            if detector_id in required_atomic_gate_ids and stage != "atomic":
                raise ValueError(
                    f"{detector_path}.stage: required canonical execution "
                    "detectors must use 'atomic'"
                )
            if detector_id in required_contextual_gate_ids and stage != "contextual":
                raise ValueError(
                    f"{detector_path}.stage: required contextual grouped "
                    "detectors must use 'contextual'"
                )
        elif executor == "signal_sequence":
            payload = _parse_signal_sequence_policy(
                raw_detector, detector_path
            )
            stage = "temporal"
        elif executor == "signal_projection":
            payload = _parse_signal_projection_policy(
                raw_detector, detector_path
            )
            stage = _policy_enum(
                detector_cfg.get("stage"),
                f"{detector_path}.stage",
                {"contextual", "temporal"},
            )
            required_stage = required_projection_stages.get(detector_id)
            if required_stage is not None and stage != required_stage:
                raise ValueError(
                    f"{detector_path}.stage: required canonical projection "
                    f"must use {required_stage!r}"
                )
        else:
            raise ValueError(
                f"{detector_path}.executor: additional detectors must use one of "
                "signal_gate, signal_sequence, signal_projection"
            )
        definitions.append(
            DetectorDefinition(
                detector_id=detector_id,
                stage=stage,
                executor=executor,
                payload=payload,
                emissions=payload.emissions,
            )
        )
    definitions_tuple = tuple(definitions)
    policy_outputs = [
        emission
        for definition in definitions_tuple
        for emission in definition.emissions
    ]
    output_names = [emission.name for emission in policy_outputs]
    duplicate_outputs = sorted({name for name in output_names if output_names.count(name) > 1})
    if duplicate_outputs:
        raise ValueError(
            "detector_policy.detectors: duplicate emission name(s): "
            + ", ".join(duplicate_outputs)
        )
    rule_ids = [emission.rule_id for emission in policy_outputs]
    duplicate_rule_ids = sorted({rule_id for rule_id in rule_ids if rule_ids.count(rule_id) > 1})
    if duplicate_rule_ids:
        raise ValueError(
            "detector_policy.detectors: duplicate emission rule_id(s): "
            + ", ".join(duplicate_rule_ids)
        )

    rules_without_policy = dict(rules_doc or {})
    rules_without_policy.pop("detector_policy", None)
    for section_name in ("rules", "temporal_rules"):
        for rule_index, rule in enumerate((rules_doc or {}).get(section_name, []) or []):
            emit = (rule or {}).get("emit", {}) or {}
            for signal_index, signal_cfg in enumerate(emit.get("signals", []) or []):
                if isinstance(signal_cfg, dict) and signal_cfg.get("name") is not None:
                    _policy_signal_name(
                        signal_cfg["name"],
                        f"{section_name}[{rule_index}].emit.signals[{signal_index}].name",
                    )
    existing_producers = _collect_emitted_signals_from_rules(rules_without_policy)
    collisions = sorted(set(output_names) & existing_producers)
    if collisions:
        raise ValueError(
            "detector_policy.detectors: emission name(s) already owned by another producer: "
            + ", ".join(collisions)
        )

    configured_rule_ids = {
        str((rule or {}).get("id", "")).strip()
        for section in ("rules", "temporal_rules")
        for rule in (rules_doc or {}).get(section, []) or []
        if str((rule or {}).get("id", "")).strip()
    }
    rule_id_collisions = sorted(set(rule_ids) & configured_rule_ids)
    if rule_id_collisions:
        raise ValueError(
            "detector_policy.detectors: emission rule_id(s) already owned by a YAML rule: "
            + ", ".join(rule_id_collisions)
        )

    weight_keys = set()
    for name in ((weights_doc or {}).get("weights", {}) or {}):
        signal_name = _policy_signal_name(name, f"weights.{name}")
        weight_keys.add(signal_name)
    missing_weights = sorted(set(output_names) - weight_keys)
    if missing_weights:
        raise ValueError(
            "detector_policy.detectors: emissions missing weights: "
            + ", ".join(missing_weights)
        )

    # Inputs must come from producers that have completed before the selected
    # executor snapshots its inputs. Policy dependencies are permitted only
    # across an explicit earlier execution phase; same-phase and backwards
    # dependencies remain invalid because detector mapping order is not an
    # execution graph.
    temporal_rule_outputs = _collect_temporal_rule_output_signals(rules_doc)
    policy_output_names = set(output_names)
    enabled_definitions = tuple(
        definition
        for definition in definitions_tuple
        if bool(getattr(definition.payload, "enabled", False))
    )
    enabled_policy_output_names = {
        emission.name
        for definition in enabled_definitions
        for emission in definition.emissions
    }
    disabled_policy_output_names = (
        policy_output_names - enabled_policy_output_names
    )
    atomic_rule_outputs = {
        str((signal_cfg or {}).get("name", "")).strip().lower()
        for rule in (rules_doc or {}).get("rules", []) or []
        for signal_cfg in (((rule or {}).get("emit", {}) or {}).get("signals", []) or [])
        if isinstance(signal_cfg, dict) and str(signal_cfg.get("name", "")).strip()
    }

    def policy_phase(definition: DetectorDefinition) -> int:
        if definition.executor in {
            "clamav_classifier", "yara_classifier", "web_request_classifier",
            "canonical_authentication", "execution_context_classifier",
        }:
            return 5
        if definition.executor == "signal_gate" and definition.stage == "atomic":
            return 10
        if definition.executor == "file_lifecycle":
            return 15
        if definition.executor == "mft_timestomping":
            return 18
        if definition.executor in {
            "ordered_row_rules", "ordered_signal_adjustments",
            "grouped_signal_window",
        }:
            return definition.payload.execution_phase
        if definition.executor == "systemd_service_persistence":
            return 20
        if definition.executor == "referenced_file_correlation":
            return 25
        if definition.executor == "webshell_artifact":
            return 27
        if definition.executor == "signal_gate" and definition.stage == "contextual":
            return 30
        if definition.executor == "signal_projection" and definition.stage == "contextual":
            return 29
        if definition.executor == "signal_projection" and definition.stage == "temporal":
            return 45
        if definition.stage == "temporal":
            return 40
        raise ValueError(
            f"detector_policy.detectors.{definition.detector_id}: unsupported "
            f"execution phase for stage={definition.stage!r}, executor={definition.executor!r}"
        )

    policy_output_phases = {
        emission.name: policy_phase(definition)
        for definition in enabled_definitions
        for emission in definition.emissions
    }
    policy_inputs_by_path: List[
        Tuple[str, str, str, int, frozenset[str]]
    ] = []
    for definition in enabled_definitions:
        input_path = f"detector_policy.detectors.{definition.detector_id}"
        if definition.executor == "signal_gate":
            inputs = definition.payload.input_signals
            blocked_groups: List[frozenset[str]] = []
            for group in definition.payload.input_groups:
                disabled_group_inputs = group.signals & disabled_policy_output_names
                if disabled_group_inputs and (
                    group.match == "all"
                    or not (group.signals - disabled_policy_output_names)
                ):
                    blocked_groups.append(disabled_group_inputs)
            if blocked_groups and (
                definition.payload.match == "all"
                or len(blocked_groups) == len(definition.payload.input_groups)
            ):
                disabled_inputs = set().union(*blocked_groups)
                raise ValueError(
                    f"{input_path}: input signal(s) have no enabled policy producer path: "
                    + ", ".join(sorted(disabled_inputs))
                )
        elif definition.executor in {"signal_sequence", "signal_sequence_by_artifact"}:
            inputs = definition.payload.source_signals | definition.payload.target_signals
            blocked_groups = [
                signal_group & disabled_policy_output_names
                for signal_group in (
                    definition.payload.source_signals,
                    definition.payload.target_signals,
                )
                if signal_group
                and not (signal_group - disabled_policy_output_names)
            ]
            if blocked_groups:
                disabled_inputs = set().union(*blocked_groups)
                raise ValueError(
                    f"{input_path}: input signal(s) have no enabled policy producer path: "
                    + ", ".join(sorted(disabled_inputs))
                )
        elif definition.executor == "signal_projection":
            inputs = definition.payload.source_signals
            for projection_index, projection in enumerate(
                definition.payload.projections
            ):
                disabled_projection_inputs = (
                    projection.input_signals & disabled_policy_output_names
                )
                if disabled_projection_inputs and (
                    projection.match == "all"
                    or not (
                        projection.input_signals
                        - disabled_policy_output_names
                    )
                ):
                    raise ValueError(
                        f"{input_path}.projections[{projection_index}]: input "
                        "signal(s) have no enabled policy producer path: "
                        + ", ".join(sorted(disabled_projection_inputs))
                    )
        elif definition.executor == "canonical_authentication":
            inputs = definition.payload.input_signals
            for semantic, signal_group in (
                ("success", definition.payload.success_sources),
                ("failure", definition.payload.failure_sources),
            ):
                disabled_inputs = signal_group & disabled_policy_output_names
                if disabled_inputs and not (
                    signal_group - disabled_policy_output_names
                ):
                    raise ValueError(
                        f"{input_path}.inputs.source_signals.{semantic}: "
                        "signal(s) have no enabled policy producer path: "
                        + ", ".join(sorted(disabled_inputs))
                    )
        elif definition.executor == "execution_context_classifier":
            inputs = frozenset()
        elif definition.executor == "file_lifecycle":
            inputs = frozenset()
        elif definition.executor == "mft_timestomping":
            inputs = frozenset()
        elif definition.executor in {
            "geographic_continuity", "impossible_travel",
        }:
            inputs = definition.payload.success_signals
            disabled_inputs = inputs & disabled_policy_output_names
            if disabled_inputs and not (inputs - disabled_policy_output_names):
                raise ValueError(
                    f"{input_path}.inputs.success_signals: signal(s) have no "
                    "enabled policy producer path: "
                    + ", ".join(sorted(disabled_inputs))
                )
        elif definition.executor == "ip_scope_continuity":
            inputs = frozenset()
        elif definition.executor in {
            "ordered_row_rules", "ordered_signal_adjustments",
            "grouped_signal_window",
        }:
            inputs = definition.payload.input_signals
        elif definition.executor == "temporal_context_branches":
            inputs = definition.payload.source_signals | definition.payload.support_signals
            disabled_source = (
                definition.payload.source_signals & disabled_policy_output_names
            )
            if disabled_source and not (
                definition.payload.source_signals - disabled_policy_output_names
            ):
                raise ValueError(
                    f"{input_path}: source signal(s) have no enabled policy producer path: "
                    + ", ".join(sorted(disabled_source))
                )
        elif definition.executor == "counted_signal_window":
            inputs = (
                definition.payload.counted_signals
                | definition.payload.window_support_signals
                | definition.payload.current_support_signals
            )
            disabled_counted = (
                definition.payload.counted_signals & disabled_policy_output_names
            )
            if disabled_counted and not (
                definition.payload.counted_signals - disabled_policy_output_names
            ):
                raise ValueError(
                    f"{input_path}: counted signal(s) have no enabled policy producer path: "
                    + ", ".join(sorted(disabled_counted))
                )
            support_signals = (
                definition.payload.window_support_signals
                | definition.payload.current_support_signals
            )
            disabled_support = support_signals & disabled_policy_output_names
            if disabled_support and not (
                support_signals - disabled_policy_output_names
            ):
                raise ValueError(
                    f"{input_path}: support signal(s) have no enabled policy producer path: "
                    + ", ".join(sorted(disabled_support))
                )
        elif definition.executor == "artifact_follow_on_sequence":
            inputs = (
                definition.payload.source_signals
                | definition.payload.copy_support_signals
                | definition.payload.follow_on_signals
            )
            disabled_source = (
                definition.payload.source_signals & disabled_policy_output_names
            )
            if disabled_source and not (
                definition.payload.source_signals - disabled_policy_output_names
            ):
                raise ValueError(
                    f"{input_path}: source signal(s) have no enabled policy producer path: "
                    + ", ".join(sorted(disabled_source))
                )
        elif definition.executor == "referenced_file_correlation":
            inputs = definition.payload.external_mapping_input_signals
            disabled_inputs = inputs & disabled_policy_output_names
            if disabled_inputs:
                raise ValueError(
                    f"{input_path}: mapping input signal(s) have no enabled policy "
                    "producer path: " + ", ".join(sorted(disabled_inputs))
                )
        elif definition.executor == "web_request_classifier":
            inputs = definition.payload.external_input_signals
            disabled_inputs = inputs & disabled_policy_output_names
            if disabled_inputs:
                raise ValueError(
                    f"{input_path}: exploit input signal(s) have no enabled policy "
                    "producer path: " + ", ".join(sorted(disabled_inputs))
                )
        elif definition.executor == "webshell_artifact":
            inputs = definition.payload.support_signals
            disabled_inputs = inputs & disabled_policy_output_names
            if (
                definition.payload.support_match == "all"
                and disabled_inputs
                and not (inputs - disabled_policy_output_names)
            ):
                raise ValueError(
                    f"{input_path}: support signal(s) have no enabled policy "
                    "producer path: " + ", ".join(sorted(disabled_inputs))
                )
        else:
            continue
        policy_inputs_by_path.append(
            (
                input_path,
                definition.stage,
                definition.executor,
                policy_phase(definition),
                inputs,
            )
        )
    for input_path, stage, executor, consumer_phase, inputs in policy_inputs_by_path:
        policy_dependencies = sorted(inputs & enabled_policy_output_names)
        unavailable_policy_dependencies = [
            name
            for name in policy_dependencies
            if policy_output_phases[name] >= consumer_phase
        ]
        if unavailable_policy_dependencies:
            raise ValueError(
                f"{input_path}: policy-to-policy input signal(s) are not available "
                f"before the {stage} {executor} executor runs: "
                + ", ".join(unavailable_policy_dependencies)
            )
        unknown_inputs = sorted(
            inputs - existing_producers - policy_output_names
        )
        if unknown_inputs:
            raise ValueError(
                f"{input_path}: input signal(s) have no known producer: "
                + ", ".join(unknown_inputs)
            )
        unavailable: Set[str] = set()
        if executor == "web_request_classifier":
            available_web_inputs = atomic_rule_outputs
            unavailable.update(
                (inputs - disabled_policy_output_names) - available_web_inputs
            )
            unavailable.update(temporal_rule_outputs)
        elif executor == "canonical_authentication":
            available_auth_inputs = atomic_rule_outputs
            unavailable.update(
                (inputs - disabled_policy_output_names) - available_auth_inputs
            )
            unavailable.update(temporal_rule_outputs)
        elif executor == "signal_gate" and stage == "atomic":
            available_atomic = (
                atomic_rule_outputs
                | {
                    name
                    for name in policy_dependencies
                    if policy_output_phases[name] < consumer_phase
                }
            )
            unavailable.update(
                (inputs - disabled_policy_output_names) - available_atomic
            )
            unavailable.update(temporal_rule_outputs)
        elif executor == "referenced_file_correlation":
            available_at_correlation = (
                atomic_rule_outputs
                | {
                    name
                    for name in policy_dependencies
                    if policy_output_phases[name] < consumer_phase
                }
            )
            unavailable.update(
                (inputs - disabled_policy_output_names)
                - available_at_correlation
            )
            unavailable.update(temporal_rule_outputs)
        elif executor == "webshell_artifact":
            available_at_webshell = (
                atomic_rule_outputs
                | {
                    name
                    for name in policy_dependencies
                    if policy_output_phases[name] < consumer_phase
                }
            )
            unavailable.update(
                (inputs - disabled_policy_output_names) - available_at_webshell
            )
            unavailable.update(temporal_rule_outputs)
        elif executor == "signal_projection" and stage == "contextual":
            unavailable.update(temporal_rule_outputs)
        elif executor == "signal_gate":
            unavailable.update(_collect_profiling_output_signals(rules_doc))
            unavailable.update(temporal_rule_outputs)
        unavailable_inputs = sorted(inputs & unavailable)
        if unavailable_inputs:
            raise ValueError(
                f"{input_path}: input signal(s) are emitted after the "
                f"{executor} executor runs: "
                + ", ".join(unavailable_inputs)
            )

    return DetectorPolicy(
        version=1,
        mode=mode,
        detectors=definitions_tuple,
    )


def _validate_geoip_enrichment_bindings(
    geoip_policy: GeoIPEnrichmentPolicy,
    detector_policy: DetectorPolicy,
    canonicalisation_policy: CanonicalisationPolicy,
    normalisation: Tuple[NormalisationSpec, ...],
) -> None:
    output_columns = set(geoip_policy.output_columns)
    earlier_derived_fields = set(canonicalisation_policy.output_fields) | {
        spec.name for spec in normalisation
    }
    earlier_collisions = sorted(output_columns & earlier_derived_fields)
    if earlier_collisions:
        raise ValueError(
            "geoip_enrichment.outputs: output field(s) collide with "
            "canonicalisation or normalisation outputs: "
            + ", ".join(earlier_collisions)
        )

    geographic = detector_policy.geographic_continuity
    travel = detector_policy.impossible_travel
    later_derived_fields = {
        *geographic.output_fields.values(),
        *travel.output_fields.values(),
    }
    later_collisions = sorted(output_columns & later_derived_fields)
    if later_collisions:
        raise ValueError(
            "geoip_enrichment.outputs: output field(s) collide with continuity "
            "result fields: " + ", ".join(later_collisions)
        )

    bindings = (
        (
            "detector_policy.detectors.geographic_continuity.inputs.country_field",
            "country_iso",
            geographic.country_field,
        ),
        (
            "detector_policy.detectors.geographic_continuity.inputs.asn_field",
            "asn",
            geographic.asn_field,
        ),
        (
            "detector_policy.detectors.geographic_continuity.inputs.city_field",
            "city_name",
            geographic.city_field,
        ),
        (
            "detector_policy.detectors.impossible_travel.inputs.latitude_field",
            "latitude",
            travel.latitude_field,
        ),
        (
            "detector_policy.detectors.impossible_travel.inputs.longitude_field",
            "longitude",
            travel.longitude_field,
        ),
        (
            "detector_policy.detectors.impossible_travel.inputs.country_field",
            "country_iso",
            travel.country_field,
        ),
    )
    for consumer_path, output_role, actual_field in bindings:
        expected_field = geoip_policy.output_fields[output_role]
        if actual_field != expected_field:
            raise ValueError(
                f"{consumer_path}: must match "
                f"geoip_enrichment.outputs.{output_role} "
                f"({expected_field!r}); got {actual_field!r}"
            )


