def _parse_hour_of_week_validation_policy(
    raw: Any, parent_path: str
) -> HourOfWeekValidationPolicy:
    path = f"{parent_path}.validation"
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "method", "reference", "block", "minimum_complete_weeks",
            "confidence_level", "bootstrap_resamples", "random_seed",
            "acceptance", "uncertainty_band", "amplification_gate",
        },
    )
    confidence_level = _policy_positive_number(
        cfg["confidence_level"], f"{path}.confidence_level"
    )
    if confidence_level <= 0.5 or confidence_level >= 1.0:
        raise ValueError(
            f"{path}.confidence_level: expected a value greater than 0.5 "
            "and less than 1"
        )
    bootstrap_resamples = _policy_positive_int(
        cfg["bootstrap_resamples"], f"{path}.bootstrap_resamples"
    )
    minimum_resamples = max(
        100,
        int(math.ceil(5.0 / (1.0 - confidence_level))),
    )
    if bootstrap_resamples < minimum_resamples:
        raise ValueError(
            f"{path}.bootstrap_resamples: expected at least "
            f"{minimum_resamples} for confidence_level={confidence_level:g} "
            "(minimum 100 total and five expected resamples per tail)"
        )
    return HourOfWeekValidationPolicy(
        method=_policy_enum(
            cfg["method"],
            f"{path}.method",
            {"leave_one_calendar_week_out_log_score"},
        ),
        reference=_policy_enum(
            cfg["reference"],
            f"{path}.reference",
            {"uniform_hour_of_week"},
        ),
        block=_policy_enum(
            cfg["block"],
            f"{path}.block",
            {"complete_calendar_week"},
        ),
        minimum_complete_weeks=_policy_positive_int(
            cfg["minimum_complete_weeks"],
            f"{path}.minimum_complete_weeks",
        ),
        confidence_level=confidence_level,
        bootstrap_resamples=bootstrap_resamples,
        random_seed=_policy_nonnegative_int(
            cfg["random_seed"], f"{path}.random_seed"
        ),
        acceptance=_policy_enum(
            cfg["acceptance"],
            f"{path}.acceptance",
            {"bootstrap_lower_bound_above_zero"},
        ),
        uncertainty_band=_policy_enum(
            cfg["uncertainty_band"],
            f"{path}.uncertainty_band",
            {"simultaneous_bootstrap_upper_probability"},
        ),
        amplification_gate=_policy_enum(
            cfg["amplification_gate"],
            f"{path}.amplification_gate",
            {"require_positive_activity_deficit"},
        ),
    )


def _parse_hour_of_week_amplifier_policy(
    raw: Any, parent_path: str
) -> HourOfWeekAmplifierPolicy:
    path = f"{parent_path}.score_amplifier"
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "enabled", "method", "scope", "on_invalid_profile", "explanation",
        },
    )
    explanation_path = f"{path}.explanation"
    explanation_cfg = _policy_mapping(
        cfg["explanation"], explanation_path
    )
    _policy_keys(
        explanation_cfg,
        explanation_path,
        required={
            "rule_id", "description", "confidence", "evidence_type", "evidence",
        },
    )
    evidence = _policy_string_list(
        explanation_cfg["evidence"], f"{explanation_path}.evidence"
    )
    allowed_evidence = {
        "hour_of_week", "activity_probability", "upper_probability_bound",
        "reference_probability", "activity_deficit", "multiplier",
        "validation_lower_bound", "complete_week_count",
    }
    unsupported = sorted(set(evidence) - allowed_evidence)
    if unsupported:
        raise ValueError(
            f"{explanation_path}.evidence: unsupported value(s): "
            + ", ".join(unsupported)
        )
    return HourOfWeekAmplifierPolicy(
        enabled=_policy_bool(cfg["enabled"], f"{path}.enabled"),
        method=_policy_enum(
            cfg["method"],
            f"{path}.method",
            {"one_plus_conservative_relative_activity_deficit"},
        ),
        scope=_policy_enum(
            cfg["scope"], f"{path}.scope", {"post_trust_event_score"}
        ),
        on_invalid_profile=_policy_enum(
            cfg["on_invalid_profile"],
            f"{path}.on_invalid_profile",
            {"neutral"},
        ),
        explanation=ProfilingExplanationPolicy(
            rule_id=_policy_string(
                explanation_cfg["rule_id"], f"{explanation_path}.rule_id"
            ),
            description=_policy_string(
                explanation_cfg["description"],
                f"{explanation_path}.description",
            ),
            confidence=_policy_confidence(
                explanation_cfg["confidence"],
                f"{explanation_path}.confidence",
            ),
            evidence_type=_policy_enum(
                explanation_cfg["evidence_type"],
                f"{explanation_path}.evidence_type",
                {"profiling"},
            ),
            evidence=evidence,
        ),
    )


def _parse_hour_of_week_profiling_policy(raw: Any) -> HourOfWeekProfilingPolicy:
    path = "profiling.hour_of_week"
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "enabled", "smoothing_alpha", "quiet_quantile",
            "min_profile_events", "parser_field", "filename_field",
            "nsrl_is_os_component_field", "nsrl_application_type_field",
            "nsrl_exclusion_combine",
            "include_parser_regex", "insufficient_filtered_events",
            "exclude_nsrl_application_type_contains", "exclude_parser_contains",
            "exclude_filename_contains", "hour_of_week_field", "activity_deficit_signal",
            "quiet_signal", "activity_deficit_score_field", "emit_activity_deficit_signal",
            "emit_quiet_time_signal", "activity_deficit_signal_merge",
            "quiet_signal_value", "quiet_signal_merge",
            "activity_deficit_explanation", "quiet_explanation",
            "validation", "score_amplifier",
        },
    )
    quiet_quantile = _policy_positive_number(
        cfg["quiet_quantile"], f"{path}.quiet_quantile"
    )
    if quiet_quantile >= 1.0:
        raise ValueError(f"{path}.quiet_quantile: expected a value less than 1")
    include_expression = _policy_string(
        cfg["include_parser_regex"], f"{path}.include_parser_regex"
    )
    try:
        include_pattern = re.compile(include_expression, re.I)
    except re.error as exc:
        raise ValueError(f"{path}.include_parser_regex: invalid regex: {exc}") from exc
    nsrl_is_os_component_field = _policy_string(
        cfg["nsrl_is_os_component_field"],
        f"{path}.nsrl_is_os_component_field",
    )
    nsrl_application_type_field = _policy_string(
        cfg["nsrl_application_type_field"],
        f"{path}.nsrl_application_type_field",
    )
    if nsrl_is_os_component_field == nsrl_application_type_field:
        raise ValueError(
            f"{path}: NSRL application-type and OS-component fields must differ"
        )

    hour_of_week_field = _policy_string(
        cfg["hour_of_week_field"], f"{path}.hour_of_week_field"
    )
    activity_deficit_signal = _policy_signal_name(
        cfg["activity_deficit_signal"], f"{path}.activity_deficit_signal"
    )
    quiet_signal = _policy_signal_name(
        cfg["quiet_signal"], f"{path}.quiet_signal"
    )
    activity_deficit_score_field = _policy_string(
        cfg["activity_deficit_score_field"], f"{path}.activity_deficit_score_field"
    )
    if not activity_deficit_score_field.startswith("chronosift_"):
        raise ValueError(
            f"{path}.activity_deficit_score_field: materialised field must use the "
            "'chronosift_' sidecar namespace"
        )
    profile_names = {
        "hour_of_week_field": hour_of_week_field,
        "activity_deficit_signal": activity_deficit_signal,
        "quiet_signal": quiet_signal,
        "activity_deficit_score_field": activity_deficit_score_field,
    }
    duplicate_profile_names = sorted({
        value
        for value in profile_names.values()
        if list(profile_names.values()).count(value) > 1
    })
    if duplicate_profile_names:
        raise ValueError(
            f"{path}: profile field and signal names must be distinct: "
            + ", ".join(duplicate_profile_names)
        )
    raw_profile_fields = {
        _policy_string(cfg["parser_field"], f"{path}.parser_field"),
        _policy_string(cfg["filename_field"], f"{path}.filename_field"),
        nsrl_is_os_component_field,
        nsrl_application_type_field,
    }
    raw_collisions = sorted(set(profile_names.values()) & raw_profile_fields)
    if raw_collisions:
        raise ValueError(
            f"{path}: output name(s) collide with profiling input fields: "
            + ", ".join(raw_collisions)
        )
    reserved_profile_outputs = {
        CHRONOSIFT_ROW_ID_COLUMN,
        "chronosift_score", "chronosift_signals", "chronosift_explain",
        "chronosift_combined_command_text", "chronosift_dt_sort",
        "chronosift_metadata",
        "chronosift_norm_hash", "chronosift_part_month",
        "chronosift_part_year", "chronosift_profile_metadata",
        "chronosift_quiet_hours_profile", "chronosift_row_id_sort",
        "chronosift_sparse",
    }
    reserved_collisions = sorted(
        set(profile_names.values()) & reserved_profile_outputs
    )
    canonical_score_misbindings = sorted(
        role
        for role, value in profile_names.items()
        if value == "chronosift_activity_deficit_score"
        and role != "activity_deficit_score_field"
    )
    if reserved_collisions or canonical_score_misbindings:
        details = [
            *(f"reserved field {value}" for value in reserved_collisions),
            *(
                f"canonical activity-deficit score field bound to {role}"
                for role in canonical_score_misbindings
            ),
        ]
        raise ValueError(f"{path}: " + "; ".join(details))

    def parse_explanation(
        name: str,
        *,
        require_rule_id: bool,
        allowed_evidence: Set[str],
    ) -> ProfilingExplanationPolicy:
        explanation_path = f"{path}.{name}"
        explanation_cfg = _policy_mapping(cfg[name], explanation_path)
        required = {"description", "confidence", "evidence_type", "evidence"}
        if require_rule_id:
            required.add("rule_id")
        _policy_keys(explanation_cfg, explanation_path, required=required)
        evidence = _policy_string_list(
            explanation_cfg["evidence"], f"{explanation_path}.evidence"
        )
        unsupported = sorted(set(evidence) - allowed_evidence)
        if unsupported:
            raise ValueError(
                f"{explanation_path}.evidence: unsupported value(s): "
                + ", ".join(unsupported)
            )
        return ProfilingExplanationPolicy(
            rule_id=(
                _policy_string(
                    explanation_cfg["rule_id"], f"{explanation_path}.rule_id"
                )
                if require_rule_id
                else ""
            ),
            description=_policy_string(
                explanation_cfg["description"], f"{explanation_path}.description"
            ),
            confidence=_policy_confidence(
                explanation_cfg["confidence"], f"{explanation_path}.confidence"
            ),
            evidence_type=_policy_enum(
                explanation_cfg["evidence_type"],
                f"{explanation_path}.evidence_type",
                {"profiling"},
            ),
            evidence=evidence,
        )

    return HourOfWeekProfilingPolicy(
        enabled=_policy_bool(cfg["enabled"], f"{path}.enabled"),
        smoothing_alpha=_policy_positive_number(
            cfg["smoothing_alpha"], f"{path}.smoothing_alpha"
        ),
        quiet_quantile=quiet_quantile,
        min_profile_events=_policy_positive_int(
            cfg["min_profile_events"], f"{path}.min_profile_events"
        ),
        parser_field=_policy_string(cfg["parser_field"], f"{path}.parser_field"),
        filename_field=_policy_string(
            cfg["filename_field"], f"{path}.filename_field"
        ),
        nsrl_is_os_component_field=nsrl_is_os_component_field,
        nsrl_application_type_field=nsrl_application_type_field,
        nsrl_exclusion_combine=_policy_enum(
            cfg["nsrl_exclusion_combine"],
            f"{path}.nsrl_exclusion_combine",
            {"any_available", "component_field_preferred"},
        ),
        include_parser_expression=include_expression,
        include_parser_pattern=include_pattern,
        insufficient_filtered_events=_policy_enum(
            cfg["insufficient_filtered_events"],
            f"{path}.insufficient_filtered_events",
            {"full_dataset", "empty_profile"},
        ),
        exclude_nsrl_application_type_contains=_policy_string_list_or_empty(
            cfg["exclude_nsrl_application_type_contains"],
            f"{path}.exclude_nsrl_application_type_contains",
        ),
        exclude_parser_contains=_policy_string_list_or_empty(
            cfg["exclude_parser_contains"], f"{path}.exclude_parser_contains"
        ),
        exclude_filename_contains=_policy_string_list_or_empty(
            cfg["exclude_filename_contains"], f"{path}.exclude_filename_contains"
        ),
        hour_of_week_field=hour_of_week_field,
        activity_deficit_signal=activity_deficit_signal,
        quiet_signal=quiet_signal,
        activity_deficit_score_field=activity_deficit_score_field,
        emit_activity_deficit_signal=_policy_bool(
            cfg["emit_activity_deficit_signal"], f"{path}.emit_activity_deficit_signal"
        ),
        emit_quiet_signal=_policy_bool(
            cfg["emit_quiet_time_signal"], f"{path}.emit_quiet_time_signal"
        ),
        activity_deficit_signal_merge=_policy_enum(
            cfg["activity_deficit_signal_merge"],
            f"{path}.activity_deficit_signal_merge",
            {"maximum", "sum"},
        ),
        quiet_signal_value=_policy_positive_number(
            cfg["quiet_signal_value"], f"{path}.quiet_signal_value"
        ),
        quiet_signal_merge=_policy_enum(
            cfg["quiet_signal_merge"],
            f"{path}.quiet_signal_merge",
            {"maximum", "sum"},
        ),
        activity_deficit_explanation=parse_explanation(
            "activity_deficit_explanation",
            require_rule_id=True,
            allowed_evidence={"score_column", "activity_deficit_column"},
        ),
        quiet_explanation=parse_explanation(
            "quiet_explanation",
            require_rule_id=True,
            allowed_evidence={"hour_of_week", "quiet_quantile"},
        ),
        validation=_parse_hour_of_week_validation_policy(cfg["validation"], path),
        score_amplifier=_parse_hour_of_week_amplifier_policy(
            cfg["score_amplifier"], path
        ),
    )


@dataclass(frozen=True)
class TrustDampeningPolicy:
    enabled: bool
    multiplier: float
    selector_match: str
    reason_precedence: Tuple[str, ...]
    signals: frozenset[str]
    principal_field: str
    ip_field: str
    asn_field: str
    trusted_principals: frozenset[str]
    trusted_principal_patterns: Tuple[re.Pattern[str], ...]
    trusted_ips: frozenset[str]
    trusted_asns: frozenset[str]
    rule_id: str
    description: str
    confidence: str
    evidence_type: str
    evidence: Tuple[str, ...]


def _parse_trust_dampening_policy(raw: Any) -> TrustDampeningPolicy:
    path = "engine_config.trust_dampening"
    cfg = _policy_mapping(raw, path)
    _policy_keys(
        cfg,
        path,
        required={
            "enabled", "multiplier", "selector_match", "reason_precedence",
            "inputs", "signals",
            "trusted_actor_principals", "trusted_actor_principal_regex",
            "trusted_ips", "trusted_asns", "explanation",
        },
    )
    enabled = _policy_bool(cfg["enabled"], f"{path}.enabled")
    multiplier = _policy_positive_number(
        cfg["multiplier"], f"{path}.multiplier"
    )
    if multiplier >= 1.0:
        raise ValueError(f"{path}.multiplier: expected a value less than 1")
    selector_match = _policy_enum(
        cfg["selector_match"], f"{path}.selector_match", {"any", "all"}
    )
    reason_precedence = _policy_string_list(
        cfg["reason_precedence"], f"{path}.reason_precedence"
    )
    selector_roles = {"principal_literal", "principal_regex", "ip", "asn"}
    if set(reason_precedence) != selector_roles or len(reason_precedence) != len(
        selector_roles
    ):
        raise ValueError(
            f"{path}.reason_precedence: expected each selector role exactly once: "
            + ", ".join(sorted(selector_roles))
        )

    inputs_path = f"{path}.inputs"
    inputs_cfg = _policy_mapping(cfg["inputs"], inputs_path)
    _policy_keys(
        inputs_cfg,
        inputs_path,
        required={"principal_field", "ip_field", "asn_field"},
    )

    regex_path = f"{path}.trusted_actor_principal_regex"
    regex_values = _policy_string_list_or_empty(cfg["trusted_actor_principal_regex"], regex_path)
    compiled_patterns: List[re.Pattern[str]] = []
    for index, expression in enumerate(regex_values):
        try:
            compiled_patterns.append(re.compile(expression, re.I))
        except re.error as exc:
            raise ValueError(f"{regex_path}[{index}]: invalid regex: {exc}") from exc

    explanation_path = f"{path}.explanation"
    explanation_cfg = _policy_mapping(cfg["explanation"], explanation_path)
    _policy_keys(
        explanation_cfg,
        explanation_path,
        required={
            "rule_id", "description", "confidence", "evidence_type",
            "evidence",
        },
    )
    evidence = _policy_string_list(
        explanation_cfg["evidence"], f"{explanation_path}.evidence"
    )
    unsupported_evidence = sorted(set(evidence) - {"reason", "multiplier", "signals"})
    if unsupported_evidence:
        raise ValueError(
            f"{explanation_path}.evidence: unsupported value(s): "
            + ", ".join(unsupported_evidence)
        )

    return TrustDampeningPolicy(
        enabled=enabled,
        multiplier=multiplier,
        selector_match=selector_match,
        reason_precedence=reason_precedence,
        signals=frozenset(_policy_signal_list(cfg["signals"], f"{path}.signals")),
        principal_field=_policy_string(
            inputs_cfg["principal_field"], f"{inputs_path}.principal_field"
        ),
        ip_field=_policy_string(inputs_cfg["ip_field"], f"{inputs_path}.ip_field"),
        asn_field=_policy_string(inputs_cfg["asn_field"], f"{inputs_path}.asn_field"),
        trusted_principals=frozenset(
            value.lower()
            for value in _policy_string_list_or_empty(
                cfg["trusted_actor_principals"], f"{path}.trusted_actor_principals"
            )
        ),
        trusted_principal_patterns=tuple(compiled_patterns),
        trusted_ips=frozenset(
            _policy_string_list_or_empty(cfg["trusted_ips"], f"{path}.trusted_ips")
        ),
        trusted_asns=frozenset(
            _policy_string_list_or_empty(cfg["trusted_asns"], f"{path}.trusted_asns")
        ),
        rule_id=_policy_string(
            explanation_cfg["rule_id"], f"{explanation_path}.rule_id"
        ),
        description=_policy_string(
            explanation_cfg["description"], f"{explanation_path}.description"
        ),
        confidence=_policy_confidence(
            explanation_cfg["confidence"], f"{explanation_path}.confidence"
        ),
        evidence_type=_policy_enum(
            explanation_cfg["evidence_type"],
            f"{explanation_path}.evidence_type",
            {"contextual"},
        ),
        evidence=evidence,
    )


# =============================================================================
# ChronoSift engine
# =============================================================================



_PATH_RE_UNIX = re.compile(r'/(?:[^ \t\r\n"\'<>|]+/)*[^ \t\r\n"\'<>|]+')
_PATH_RE_WIN = re.compile(r'[A-Za-z]:\\(?:[^ \t\r\n"\'<>|]+\\)*[^ \t\r\n"\'<>|]+')
_PATH_RE_REL = re.compile(r'(?:(?:\./)|(?:\.\./))[^ \t\r\n"\'<>|]+')
def _activity_deficit_explain_item(
    policy: HourOfWeekProfilingPolicy,
) -> Dict[str, Any]:
    explanation = policy.activity_deficit_explanation
    evidence_values = {
        "score_column": policy.activity_deficit_score_field,
        "activity_deficit_column": policy.activity_deficit_signal,
    }
    return {
        "rule_id": explanation.rule_id,
        "description": explanation.description,
        "confidence": explanation.confidence,
        "evidence_type": explanation.evidence_type,
        "signals": [policy.activity_deficit_signal],
        "evidence": {
            name: evidence_values[name] for name in explanation.evidence
        },
    }


def _quiet_time_explain_item(
    policy: HourOfWeekProfilingPolicy,
    hour_of_week: int,
) -> Dict[str, Any]:
    explanation = policy.quiet_explanation
    evidence_values = {
        "hour_of_week": int(hour_of_week),
        "quiet_quantile": policy.quiet_quantile,
    }
    return {
        "rule_id": explanation.rule_id,
        "description": explanation.description,
        "confidence": explanation.confidence,
        "evidence_type": explanation.evidence_type,
        "signals": [policy.quiet_signal],
        "evidence": {
            name: evidence_values[name] for name in explanation.evidence
        },
    }


@lru_cache(maxsize=131072)
def _normalise_reference_path_from_string(s: str) -> Optional[str]:
    """Cached string-only helper backing conservative reference-path normalisation."""
    s = s.strip()
    if not s:
        return None
    # Remove surrounding quotes/backticks first.
    s = s.strip('\'"`')
    # Trim punctuation commonly adjacent in messages/commands.
    s = s.rstrip('.,;:)]}>')
    s = s.lstrip('([{<')
    # A second pass helps with wrapped cron/syslog command strings like CMD (/path/to/file)
    s = s.strip('\'"`')
    # Normalise trivial duplicate separators without attempting expensive path resolution.
    s = s.replace('\\\\', '\\')
    while '//' in s:
        s = s.replace('//', '/')
    return s or None


def _normalise_reference_path(value: Any) -> Optional[str]:
    """Normalise an extracted path token conservatively for exact-match comparison."""
    s = _safe_str(value)
    if not s:
        return None
    return _normalise_reference_path_from_string(s)


@lru_cache(maxsize=131072)
def _basename_from_reference_path(path: str) -> str:
    return os.path.basename(path.replace("\\", "/"))


def _extract_referenced_paths_from_text(value: Any) -> Tuple[str, ...]:
    """Extract file-like paths from free-text messages for referenced-file correlation."""
    s = _safe_str(value)
    if not s:
        return tuple()

    return _extract_referenced_paths_from_string(s)


@lru_cache(maxsize=32768)
def _extract_referenced_paths_from_string(s: str) -> Tuple[str, ...]:
    """Cached string-only helper backing referenced-file path extraction."""
    if not s:
        return tuple()

    out: List[str] = []
    seen: Set[str] = set()

    for rx in (_PATH_RE_UNIX, _PATH_RE_WIN):
        for m in rx.finditer(s):
            p = _normalise_reference_path(m.group(0))
            if p and p not in seen:
                seen.add(p)
                out.append(p)

    # Also recognise very common relative execution forms in shell and cron contexts.
    for m in _PATH_RE_REL.finditer(s):
        p = _normalise_reference_path(m.group(0))
        if p and p not in seen:
            seen.add(p)
            out.append(p)

    return tuple(out)


_COMMAND_TOKEN_RE = re.compile(r"[A-Za-z0-9_./:\\-]+")


def _normalise_reference_path_series(series: "pd.Series") -> "pd.Series":
    """Vectorised equivalent of _normalise_reference_path for path coalescing."""
    s = series.astype("string").fillna("").str.strip()
    if len(s) == 0:
        return pd.Series([], index=series.index, dtype=object)
    s = s.str.strip("'\"`")
    s = s.str.rstrip(".,;:)]}>")
    s = s.str.lstrip("([{<")
    s = s.str.strip("'\"`")
    s = s.str.replace("\\\\", "\\", regex=False)
    s = s.str.replace(r"/{2,}", "/", regex=True)
    s = s.mask(s.eq(""))
    out = s.astype(object)
    return out.where(pd.notna(out), None)


def _best_effort_file_path_vectorised(
    df: "pd.DataFrame",
    fields: Iterable[str],
) -> "pd.Series":
    """Coalesce configured path columns; first non-empty normalised path wins."""
    path_columns = tuple(str(field) for field in fields if str(field))
    result = np.full(len(df), None, dtype=object)
    filled_mask = np.zeros(len(df), dtype=bool)
    for col in path_columns:
        if col not in df.columns:
            continue
        if filled_mask.all():
            break
        norm_vals = _normalise_reference_path_series(df[col]).to_numpy(dtype=object, copy=False)
        take = (~filled_mask) & pd.notna(norm_vals)
        if bool(take.any()):
            result[take] = norm_vals[take]
            filled_mask[take] = True
    return pd.Series(result, index=df.index, dtype=object)


def _column_values_or_none(df: "pd.DataFrame", column: str) -> np.ndarray:
    if column in df.columns:
        return df[column].to_numpy(copy=False)
    return np.full(len(df), None, dtype=object)


def _normalised_text_array(
    df: "pd.DataFrame",
    column: str,
    *,
    lower: bool = False,
) -> np.ndarray:
    """Return a stripped text array for a column, defaulting to empty strings."""
    if column not in df.columns:
        return np.full(len(df), "", dtype=object)
    s = df[column].astype("string").fillna("").str.strip()
    if lower:
        s = s.str.lower()
    return s.to_numpy(dtype=object, copy=False)


def _first_nonempty_normalised_text_array(
    df: "pd.DataFrame",
    fields: Iterable[str],
    *,
    lower: bool = False,
) -> np.ndarray:
    """Coalesce ordered text fields per row after stripping null values."""
    result = np.full(len(df), "", dtype=object)
    unresolved = np.ones(len(df), dtype=bool)
    for field_name in fields:
        if not unresolved.any():
            break
        values = _normalised_text_array(df, field_name, lower=lower)
        take = unresolved & np.fromiter(
            (bool(value) for value in values),
            dtype=bool,
            count=len(values),
        )
        if take.any():
            result[take] = values[take]
            unresolved[take] = False
    return result


def _contextual_cached_array(
    cache: Optional[Dict[Tuple[Any, ...], np.ndarray]],
    key: Tuple[Any, ...],
    builder,
) -> np.ndarray:
    """Build a contextual working array once without storing it in DataFrame attrs."""
    if cache is None:
        return builder()
    cached = cache.get(key)
    if cached is None:
        cached = builder()
        cache[key] = cached
    return cached


def _contextual_text_array(
    df: "pd.DataFrame",
    cache: Optional[Dict[Tuple[Any, ...], np.ndarray]],
    column: str,
    *,
    lower: bool = False,
) -> np.ndarray:
    return _contextual_cached_array(
        cache,
        ("text", column, bool(lower)),
        lambda: _normalised_text_array(df, column, lower=lower),
    )


def _contextual_file_paths(
    df: "pd.DataFrame",
    cache: Optional[Dict[Tuple[Any, ...], np.ndarray]],
    fields: Iterable[str],
) -> np.ndarray:
    path_fields = tuple(str(field) for field in fields if str(field))
    return _contextual_cached_array(
        cache,
        ("file_paths", path_fields),
        lambda: _best_effort_file_path_vectorised(df, path_fields).to_numpy(dtype=object, copy=False),
    )


def _contextual_path_lower(
    df: "pd.DataFrame",
    cache: Optional[Dict[Tuple[Any, ...], np.ndarray]],
    fields: Iterable[str],
) -> np.ndarray:
    path_fields = tuple(str(field) for field in fields if str(field))

    def build() -> np.ndarray:
        file_paths = _contextual_file_paths(df, cache, path_fields)
        return (
            pd.Series(file_paths, index=df.index, dtype="string")
            .fillna("")
            .str.strip()
            .str.lower()
            .str.replace("\\", "/", regex=False)
            .to_numpy(dtype=object, copy=False)
        )

    return _contextual_cached_array(cache, ("path_lower", path_fields), build)


def _text_array_contains_any(values: np.ndarray, tokens: Iterable[str]) -> np.ndarray:
    """Vectorised literal-token containment for contextual prefilters."""
    terms = tuple(str(token) for token in tokens if str(token))
    if not terms:
        return np.zeros(len(values), dtype=bool)
    pattern = "|".join(re.escape(token) for token in terms)
    return (
        pd.Series(values, dtype="string")
        .str.contains(pattern, regex=True, na=False)
        .to_numpy(dtype=bool, copy=False)
    )


def _extract_scheduled_command_text_values(
    actor_cmd: Any = None,
    command_line: Any = None,
    message: Any = None,
) -> str:
    actor_cmd_s = _safe_str(actor_cmd).strip()
    if actor_cmd_s:
        return actor_cmd_s
    command_line_s = _safe_str(command_line).strip()
    if command_line_s:
        return command_line_s
    message_s = _safe_str(message).strip()
    if not message_s:
        return ""
    m = re.search(r"CMD\s*\((.*?)\)", message_s, flags=re.IGNORECASE)
    if m:
        return _safe_str(m.group(1)).strip()
    return message_s[:200]





def _ip_scope(value: Any) -> Optional[str]:
    """Classify an IP for continuity analysis."""
    s = _safe_str(value).strip()
    if not s:
        return None
    try:
        ip = ipaddress.ip_address(s)
    except Exception:
        return None
    if ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_unspecified:
        return None
    if ip.is_private:
        return "private"
    if ip.is_global:
        return "public"
    return None


def _ip_subnet_label(value: Any, prefix_v4: int, prefix_v6: int) -> Optional[str]:
    """Return a subnet label for private-IP continuity comparison."""
    s = _safe_str(value).strip()
    if not s:
        return None
    try:
        ip = ipaddress.ip_address(s)
    except Exception:
        return None
    if not ip.is_private:
        return None
    prefix = prefix_v4 if ip.version == 4 else prefix_v6
    try:
        net = ipaddress.ip_network(f"{ip}/{prefix}", strict=False)
        return str(net)
    except Exception:
        return None


def _normalise_hash_series(series: pd.Series) -> pd.Series:
    """Normalise hash text for case/whitespace-insensitive lookups."""
    return series.astype("string").str.strip().str.upper()


def _reindex_lookup_frame_for_hashes(
    lookup_hash: pd.Series,
    lookup_df: pd.DataFrame,
    *,
    columns: Optional[Iterable[str]] = None,
) -> pd.DataFrame:
    """Align a hash-indexed lookup frame to a normalised hash Series in one pass."""
    cols = list(columns) if columns is not None else list(lookup_df.columns)
    if len(lookup_df) == 0:
        return pd.DataFrame(index=lookup_hash.index, columns=cols)

    aligned = lookup_df.reindex(pd.Index(lookup_hash.to_numpy(copy=False), name=lookup_df.index.name))
    aligned.index = lookup_hash.index
    if columns is not None:
        aligned = aligned.loc[:, cols]
    return aligned


def _truthy_like(value: Any) -> bool:
    """Interpret common CSV-style truthy values safely."""
    if value is None:
        return False
    try:
        if pd.isna(value):
            return False
    except Exception:
        pass
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        try:
            return float(value) != 0.0
        except Exception:
            return False
    return str(value).strip().lower() in {"1", "true", "t", "yes", "y"}


def _load_hash_hit_set_from_csv(
    csv_path: str,
    hit_col: str,
    csv_hash_col: str = "sha256",
) -> Set[str]:
    """Load the set of normalised hashes whose hit column is truthy."""
    enrich = _load_hash_enrichment_frame(csv_path, csv_hash_col=csv_hash_col)
    if hit_col not in enrich.columns:
        return set()
    hit_mask = enrich[hit_col].map(_truthy_like)
    idx = enrich.index[hit_mask]
    valid = idx[idx.notna()]
    str_vals = valid.astype(str)
    stripped = str_vals.str.strip()
    return set(str_vals[stripped != ""])


def _load_hash_enrichment_frame(
    csv_path: str,
    csv_hash_col: str = "sha256",
) -> pd.DataFrame:
    """Load and normalise a hash-keyed enrichment CSV once per file version."""
    p = Path(csv_path)
    stat = p.stat()
    cache_key = (str(p.resolve()), str(csv_hash_col), int(stat.st_mtime_ns), int(stat.st_size))
    cached = ChronoSiftEngine._hash_enrichment_cache.get(cache_key)
    if cached is not None:
        return cached

    enrich = pd.read_csv(csv_path, comment="#")
    if csv_hash_col not in enrich.columns:
        raise ValueError(f"Enrichment CSV missing required column: {csv_hash_col!r}")

    norm_name = "_chronosift_norm_hash"
    hash_col_matches = np.flatnonzero(enrich.columns.to_numpy(dtype=object) == csv_hash_col)
    if len(hash_col_matches) == 0:
        raise ValueError(f"Enrichment CSV missing required column: {csv_hash_col!r}")
    norm_hash = _normalise_hash_series(enrich.iloc[:, int(hash_col_matches[0])])
    valid_norm_hash = norm_hash.notna() & norm_hash.ne("")
    if not bool(valid_norm_hash.all()):
        enrich = enrich.loc[valid_norm_hash]
        norm_hash = norm_hash.loc[valid_norm_hash]
    norm_index = pd.Index(norm_hash.to_numpy(copy=False), name=norm_name)
    keep_mask = ~norm_index.duplicated(keep="last")
    if not bool(np.all(keep_mask)):
        enrich = enrich.loc[keep_mask]
        norm_index = norm_index[keep_mask]
    enrich.index = norm_index
    enrich = enrich.drop(columns=[csv_hash_col], errors="ignore")
    ChronoSiftEngine._hash_enrichment_cache[cache_key] = enrich
    return enrich


def _invalidate_hash_enrichment_cache(csv_path: Optional[str]) -> None:
    """Drop cached frames for one enrichment source before a manifest rebuild."""
    if not csv_path:
        return
    resolved_path = str(Path(csv_path).expanduser().resolve(strict=False))
    stale_keys = [
        key
        for key in ChronoSiftEngine._hash_enrichment_cache
        if key and key[0] == resolved_path
    ]
    for key in stale_keys:
        ChronoSiftEngine._hash_enrichment_cache.pop(key, None)


def _nsrl_lookup_candidate_mask(df: pd.DataFrame, hash_col: str = "sha256_hash") -> pd.Series:
    """Restrict NSRL lookups to rows that plausibly describe real file artefacts."""
    if hash_col not in df.columns:
        return pd.Series(False, index=df.index, dtype=bool)

    sha = _normalise_hash_series(df[hash_col])
    mask = sha.str.fullmatch(r"[0-9A-F]{64}", na=False)

    if "filename" in df.columns:
        fname_mask = df["filename"].astype("string").fillna("").str.strip().ne("")
        mask &= fname_mask

    return mask.fillna(False).astype(bool)


def _prepare_nsrl_cache_df(
    nsrl_cache_df: pd.DataFrame,
    os_component_application_type_contains: Iterable[str],
) -> pd.DataFrame:
    """Normalise an NSRL cache using the configured OS-component vocabulary."""
    df = nsrl_cache_df
    if df is None or len(df) == 0:
        return df
    if "sha256" not in df.columns:
        raise ValueError("NSRL cache missing sha256 column")
    if "nsrl_application_types" in df.columns and "nsrl_application_type" not in df.columns:
        df = df.rename(columns={"nsrl_application_types": "nsrl_application_type"})

    df = df.drop_duplicates("sha256")
    application_type = (
        df["nsrl_application_type"].astype("string")
        if "nsrl_application_type" in df.columns
        else pd.Series(pd.NA, index=df.index, dtype="string")
    )
    is_os_component = (
        df["nsrl_is_os_component"].astype("boolean").fillna(False)
        if "nsrl_is_os_component" in df.columns
        else pd.Series(False, index=df.index, dtype="boolean")
    )
    application_text = application_type.fillna("")
    for raw_token in os_component_application_type_contains:
        token = str(raw_token).strip()
        if token:
            is_os_component |= application_text.str.contains(
                token,
                case=False,
                regex=False,
            ).astype("boolean")
    df = pd.DataFrame(
        {
            "sha256": df["sha256"].astype("string").str.upper(),
            "nsrl_application_type": application_type,
            "nsrl_is_os_component": is_os_component,
        },
        index=df.index,
    )

    cache = df.set_index("sha256")
    df.attrs["_chronosift_lookup_df"] = cache.loc[:, ["nsrl_application_type", "nsrl_is_os_component"]]
    df.attrs["_chronosift_lookup_application_type"] = cache["nsrl_application_type"].to_dict()
    df.attrs["_chronosift_lookup_is_os_component"] = (
        cache["nsrl_is_os_component"].astype("boolean").fillna(False).astype(bool).to_dict()
    )
    return df


def _make_nsrl_cache_descriptor(parquet_path: str) -> pd.DataFrame:
    """Create a lightweight NSRL cache descriptor without materialising the parquet."""
    df = pd.DataFrame()
    df.attrs["_chronosift_nsrl_parquet_path"] = str(parquet_path)
    return df


def _ensure_duckdb_nsrl_lookup(parquet_path: str) -> str:
    con = _get_duckdb_connection()
    view_name = "_chronosift_nsrl_lookup"

    if ChronoSiftEngine._duckdb_nsrl_view_path == str(parquet_path):
        return view_name

    available = set(_duckdb_dataset_columns(parquet_path))
    if "sha256" not in available:
        raise ValueError(f"NSRL parquet missing required column: sha256 ({parquet_path})")

    if "nsrl_application_type" in available:
        app_expr = "nsrl_application_type"
    elif "nsrl_application_types" in available:
        app_expr = "nsrl_application_types"
    else:
        raise ValueError(
            f"NSRL parquet missing required application type column "
            f"(expected nsrl_application_type or nsrl_application_types): {parquet_path}"
        )

    os_expr = (
        "TRY_CAST(nsrl_is_os_component AS BOOLEAN)"
        if "nsrl_is_os_component" in available
        else "CAST(NULL AS BOOLEAN)"
    )

    parquet_sql = str(parquet_path).replace("'", "''")
    sql = f"""
        CREATE OR REPLACE TEMP VIEW {view_name} AS
        SELECT
            sha256,
            {app_expr} AS nsrl_application_type,
            {os_expr} AS nsrl_is_os_component
        FROM read_parquet('{parquet_sql}')
    """
    con.execute(sql)
    ChronoSiftEngine._duckdb_nsrl_view_path = str(parquet_path)
    return view_name

def _duckdb_lookup_nsrl_hashes(parquet_path: str, hashes: Iterable[str]) -> pd.DataFrame:
    """Resolve a distinct set of SHA-256 values against the NSRL parquet via DuckDB."""
    values = [str(x).upper() for x in hashes if pd.notna(x) and str(x).strip()]
    if not values:
        return pd.DataFrame(columns=["sha256", "nsrl_application_type", "nsrl_is_os_component"])

    con = _get_duckdb_connection()
    view_name = _ensure_duckdb_nsrl_lookup(parquet_path)
    unique_sha = pd.Series(pd.unique(pd.Series(values, dtype="string")), dtype="string")
    workload_df = pd.DataFrame({"sha256": unique_sha})
    rel_name = "chronosift_nsrl_workload_hashes"
    con.register(rel_name, workload_df)
    try:
        df = con.execute(
            f"""
            SELECT
                w.sha256,
                n.nsrl_application_type,
                COALESCE(n.nsrl_is_os_component, FALSE) AS nsrl_is_os_component
            FROM {rel_name} AS w
            LEFT JOIN {view_name} AS n
              ON n.sha256 = w.sha256
            """
        ).fetch_df()
    finally:
        try:
            con.unregister(rel_name)
        except Exception:
            pass

    if len(df) > 0:
        application_type = (
            df["nsrl_application_type"].astype("string")
            if "nsrl_application_type" in df.columns
            else pd.Series(pd.NA, index=df.index, dtype="string")
        )
        is_os_component = (
            df["nsrl_is_os_component"].astype("boolean")
            if "nsrl_is_os_component" in df.columns
            else pd.Series(False, index=df.index, dtype="boolean")
        )
        df = pd.DataFrame(
            {
                "sha256": df["sha256"].astype("string").str.upper(),
                "nsrl_application_type": application_type,
                "nsrl_is_os_component": is_os_component,
            },
            index=df.index,
        )
    return df


class ChronoSiftEngine:
    _dataset_columns_cache: ClassVar[Dict[Tuple[str, Tuple[Any, ...]], List[str]]] = {}
    _duckdb_conn: ClassVar[Any] = None
    _duckdb_nsrl_view_path: ClassVar[Optional[str]] = None
    _hash_enrichment_cache: ClassVar[Dict[Tuple[str, str, int, int], pd.DataFrame]] = {}

    def __init__(self, rules_doc: Dict[str, Any], weights_doc: Dict[str, Any], yara_metadata_path: Optional[str] = None):
        rules_doc = _policy_mapping(rules_doc, "rules configuration")
        _policy_keys(
            rules_doc,
            "rules configuration",
            required={
                "canonicalisation", "normalisation", "rules", "temporal_rules",
                "engine_config", "profiling",
                "geoip_enrichment", "rule_signal_merge", "detector_policy",
            },
            optional={"engine_notes"},
        )
        self.rules_doc = rules_doc
        self.weights_doc = weights_doc

        self.max_event_score, self.weights = _parse_weights_policy(weights_doc)

        # YAML sections. The shipped configuration is authoritative: required
        # sections are not reconstructed from engine defaults.
        self.canonicalisation_policy = _parse_canonicalisation_policy(
            rules_doc["canonicalisation"], "canonicalisation"
        )
        self.normalisation = _parse_normalisation_policy(
            rules_doc["normalisation"], "normalisation"
        )
        self.geoip_enrichment_policy = _parse_geoip_enrichment_policy(
            rules_doc["geoip_enrichment"], "geoip_enrichment"
        )
        self.rule_signal_merge_policy = _parse_rule_signal_merge_policy(
            rules_doc["rule_signal_merge"]
        )
        self.rules = self._parse_rules(rules_doc["rules"])
        self.temporal_rules = self._parse_temporal_rules(
            rules_doc["temporal_rules"]
        )
        self.engine_cfg = _policy_mapping(
            rules_doc["engine_config"], "engine_config"
        )
        # Parse detector policy before the compact engine-config contract so
        # retired rule-logic sections receive the purpose-built migration
        # error instead of a generic unknown-key error.
        self.detector_policy: DetectorPolicy = _parse_detector_policy(
            rules_doc, weights_doc
        )
        _validate_geoip_enrichment_bindings(
            self.geoip_enrichment_policy,
            self.detector_policy,
            self.canonicalisation_policy,
            self.normalisation,
        )
        _policy_keys(
            self.engine_cfg,
            "engine_config",
            required={
                "config_validation", "schema_aliases",
                "temporal_signal_policy", "trust_dampening",
            },
        )
        self.config_validation_policy = _parse_config_validation_policy(
            self.engine_cfg["config_validation"]
        )
        self.schema_aliases: Dict[str, Tuple[str, ...]] = _parse_schema_aliases(
            self.engine_cfg["schema_aliases"]
        )
        self.trust_dampening_policy = _parse_trust_dampening_policy(
            self.engine_cfg["trust_dampening"]
        )
        temporal_policy_cfg = _policy_mapping(
            self.engine_cfg["temporal_signal_policy"],
            "engine_config.temporal_signal_policy",
        )
        _policy_keys(
            temporal_policy_cfg,
            "engine_config.temporal_signal_policy",
            required={"ineligible_signals"},
        )
        self.temporal_ineligible_signals: Set[str] = set(
            _policy_signal_list(
                temporal_policy_cfg["ineligible_signals"],
                "engine_config.temporal_signal_policy.ineligible_signals",
            )
        )

        profiling_root = _policy_mapping(rules_doc["profiling"], "profiling")
        _policy_keys(profiling_root, "profiling", required={"hour_of_week"})
        self.profiling_policy = _parse_hour_of_week_profiling_policy(
            profiling_root["hour_of_week"]
        )
        enabled_profile_emissions: Set[str] = set()
        if self.profiling_policy.enabled:
            if self.profiling_policy.emit_activity_deficit_signal:
                enabled_profile_emissions.add(
                    self.profiling_policy.activity_deficit_signal
                )
            if self.profiling_policy.emit_quiet_signal:
                enabled_profile_emissions.add(self.profiling_policy.quiet_signal)
        missing_profile_weights = sorted(
            enabled_profile_emissions - self.weights.keys()
        )
        if missing_profile_weights:
            raise ValueError(
                "profiling.hour_of_week: enabled emissions missing weights: "
                + ", ".join(missing_profile_weights)
            )
        profile_output_names = {
            self.profiling_policy.hour_of_week_field,
            self.profiling_policy.activity_deficit_signal,
            self.profiling_policy.quiet_signal,
            self.profiling_policy.activity_deficit_score_field,
        }
        other_configured_outputs = {
            *self.canonicalisation_policy.output_fields,
            *(spec.name for spec in self.normalisation),
            *self.geoip_enrichment_policy.output_columns,
            *self.detector_policy.geographic_continuity.output_fields.values(),
            *self.detector_policy.impossible_travel.output_fields.values(),
        }
        web_outputs = self.detector_policy.web_request_classification.outputs
        other_configured_outputs.update(vars(web_outputs).values())
        correlation = self.detector_policy.referenced_file_correlation
        other_configured_outputs.update({
            correlation.upload_names_field,
            correlation.upload_hashes_field,
            correlation.upload_outcome_field,
            correlation.web_outcome_field,
            *correlation.web_feature_fields.values(),
            correlation.attack_indicators_field,
            correlation.source_ip_field,
            correlation.method_field,
            correlation.endpoint_field,
            correlation.status_field,
            correlation.attack_techniques_field,
        })
        profile_output_collisions = sorted(
            profile_output_names & other_configured_outputs
        )
        if profile_output_collisions:
            raise ValueError(
                "profiling.hour_of_week: output name(s) collide with other "
                "configured derived fields: "
                + ", ".join(profile_output_collisions)
            )

        profile_rule_ids = [
            self.profiling_policy.activity_deficit_explanation.rule_id,
            self.profiling_policy.quiet_explanation.rule_id,
            self.profiling_policy.score_amplifier.explanation.rule_id,
        ]
        duplicate_profile_rule_ids = sorted({
            rule_id
            for rule_id in profile_rule_ids
            if profile_rule_ids.count(rule_id) > 1
        })
        if duplicate_profile_rule_ids:
            raise ValueError(
                "profiling.hour_of_week: explanation rule_id(s) must "
                "be unique: " + ", ".join(duplicate_profile_rule_ids)
            )
        non_profile_rule_ids = {
            *(rule.rule_id for rule in self.rules),
            *(rule.rule_id for rule in self.temporal_rules),
            *(
                emission.rule_id
                for definition in self.detector_policy.definitions(
                    enabled_only=False
                )
                for emission in definition.emissions
            ),
            self.trust_dampening_policy.rule_id,
        }
        profile_rule_id_collisions = sorted(
            set(profile_rule_ids) & non_profile_rule_ids
        )
        if profile_rule_id_collisions:
            raise ValueError(
                "profiling.hour_of_week: explanation rule_id(s) already "
                "owned by another configured rule: "
                + ", ".join(profile_rule_id_collisions)
            )
        declared_signals = _collect_emitted_signals_from_rules(
            rules_doc,
            enabled_only=False,
        )
        unknown_ineligible_signals = sorted(
            self.temporal_ineligible_signals - declared_signals
        )
        if unknown_ineligible_signals:
            raise ValueError(
                "engine_config.temporal_signal_policy.ineligible_signals: "
                "signal(s) have no declared producer: "
                + ", ".join(unknown_ineligible_signals)
            )
        missing_post_profile_guards = sorted(
            _collect_profiling_output_signals(rules_doc)
            - self.temporal_ineligible_signals
        )
        if missing_post_profile_guards:
            raise ValueError(
                "engine_config.temporal_signal_policy.ineligible_signals: "
                "must include enabled profiling emission(s): "
                + ", ".join(missing_post_profile_guards)
            )
        for index, temporal_rule in enumerate(self.temporal_rules):
            temporal_inputs = {
                step.signal for step in temporal_rule.sequence
            } | {
                need.signal for need in temporal_rule.cooccur_all
            }
            forbidden_inputs = sorted(
                temporal_inputs & self.temporal_ineligible_signals
            )
            if forbidden_inputs:
                raise ValueError(
                    f"temporal_rules[{index}]: input signal(s) are configured "
                    "as temporally ineligible: " + ", ".join(forbidden_inputs)
                )
        unknown_trust_targets = sorted(
            self.trust_dampening_policy.signals - declared_signals
        )
        if unknown_trust_targets:
            raise ValueError(
                "engine_config.trust_dampening.signals: target signal(s) have "
                "no declared producer: " + ", ".join(unknown_trust_targets)
            )
        if self.trust_dampening_policy.enabled and not (
            self.trust_dampening_policy.trusted_principals
            or self.trust_dampening_policy.trusted_principal_patterns
            or self.trust_dampening_policy.trusted_ips
            or self.trust_dampening_policy.trusted_asns
        ):
            raise ValueError(
                "engine_config.trust_dampening: enabled policy requires at "
                "least one trusted selector"
            )
        self.rule_emit_signals: Dict[str, List[str]] = {
            r.rule_id: [str(es.name).strip() for es in r.emit_signals if str(es.name).strip()]
            for r in self.rules
        }
        self.temporal_emit_signals: Dict[str, List[str]] = {
            tr.rule_id: [str(es.name).strip() for es in tr.emit_signals if str(es.name).strip()]
            for tr in self.temporal_rules
        }
        for definition in self.detector_policy.definitions(enabled_only=True):
            registry = (
                self.temporal_emit_signals
                if definition.stage == "temporal"
                else self.rule_emit_signals
            )
            for emission in definition.emissions:
                registry[emission.rule_id] = [emission.name]
        self.profile_amplifier_rule_id = (
            self.profiling_policy.score_amplifier.explanation.rule_id
        )

        # Required columns for stable evaluation across datasets
        self.required_fields: Set[str] = self._collect_required_fields()

        # YARA Forge metadata index — maps rule names to forensic categories
        # and quality scores. The authoritative policy owns the resource path,
        # fallback behaviour, defaults, classification, and emissions; the
        # constructor argument remains a run-specific input override.
        self._yara_metadata_index: Optional[Dict[str, YaraRuleMeta]] = None
        self._yara_metadata_available: Optional[bool] = None
        yara_policy = self.detector_policy.yara_classification
        self._yara_metadata_path: Optional[str] = (
            yara_metadata_path or yara_policy.metadata_path
        )

    @property
    def yara_metadata_index(self) -> Dict[str, YaraRuleMeta]:
        """Lazily load the YARA Forge metadata index on first access."""
        if self._yara_metadata_index is None:
            policy = self.detector_policy.yara_classification
            if not policy.enabled:
                self._yara_metadata_index = {}
                self._yara_metadata_available = False
                return self._yara_metadata_index
            if self._yara_metadata_path and os.path.isfile(self._yara_metadata_path):
                try:
                    self._yara_metadata_index = parse_yara_forge_metadata(
                        self._yara_metadata_path,
                        policy,
                    )
                    self._yara_metadata_available = True
                except Exception:
                    if policy.metadata_on_parse_error == "fail":
                        raise
                    logger.warning(
                        "Failed to parse YARA Forge metadata from %s; "
                        "using configured name-only classification",
                        self._yara_metadata_path,
                    )
                    self._yara_metadata_index = {}
                    self._yara_metadata_available = False
            else:
                if policy.metadata_on_missing == "fail":
                    raise FileNotFoundError(
                        "Configured YARA Forge metadata file does not exist: "
                        f"{self._yara_metadata_path!r}"
                    )
                self._yara_metadata_index = {}
                self._yara_metadata_available = False
        return self._yara_metadata_index

    def _yara_rule_metadata(self, rule_name: str) -> YaraRuleMeta:
        """Resolve indexed or explicitly configured name-only YARA metadata."""
        policy = self.detector_policy.yara_classification
        metadata = self.yara_metadata_index.get(rule_name)
        if metadata is not None:
            return metadata
        use_name_classifier = (
            self._yara_metadata_available is False
            or policy.unindexed_rule == "name_only"
        )
        category = (
            _classify_yara_rule(rule_name, policy)
            if use_name_classifier
            else policy.default_category
        )
        return YaraRuleMeta(
            score=policy.unindexed_score,
            quality=policy.unindexed_quality,
            category=category,
        )

    @classmethod
    def from_yaml(cls, rules_path: str, weights_path: str, yara_metadata_path: Optional[str] = None) -> "ChronoSiftEngine":
        rules_doc = _load_unique_yaml_mapping(rules_path, "rules configuration")
        weights_doc = _load_unique_yaml_mapping(
            weights_path, "weights configuration"
        )
        # Construct first so the mandatory detector-policy contract fails before
        # optional alignment warnings are emitted.
        engine = cls(rules_doc, weights_doc, yara_metadata_path=yara_metadata_path)
        # Optional configuration hygiene checks.
        if engine.config_validation_policy.enabled:
            _validate_signal_weight_alignment(
                rules_doc,
                weights_doc,
                strict=engine.config_validation_policy.strict,
            )
        return engine

    def _materialise_normalised_web_features(self, df: pd.DataFrame) -> None:
        """Materialise typed HTTP features once for detectors and sidecars."""
        nrows = len(df)
        web_policy = self.detector_policy.web_request_classification
        web_inputs = web_policy.inputs
        web_outputs = web_policy.outputs
        correlation_policy = self.detector_policy.referenced_file_correlation
        message_vals = _column_values_or_none(df, web_inputs.message_field)
        header_vals = _column_values_or_none(df, web_inputs.headers_field)
        status_vals = _column_values_or_none(df, web_inputs.response_code_field)
        response_bytes_vals = _column_values_or_none(
            df, web_inputs.response_bytes_field
        )
        source_ip_values = tuple(
            _column_values_or_none(df, field)
            for field in web_inputs.source_ip_fields
        )
        ua_vals = _column_values_or_none(df, web_inputs.user_agent_field)
        referer_vals = _column_values_or_none(df, web_inputs.referer_field)
        body_vals = _column_values_or_none(df, web_inputs.body_field)
        disposition_vals = _column_values_or_none(
            df, web_inputs.content_disposition_field
        )
        upload_filename_vals = _column_values_or_none(
            df, web_inputs.upload_filename_field
        )
        upload_content_type_vals = _column_values_or_none(
            df, web_inputs.upload_content_type_field
        )
        upload_sha256_vals = _column_values_or_none(
            df, web_inputs.upload_sha256_field
        )
        request_length_vals = _column_values_or_none(
            df, web_inputs.request_content_length_field
        )
        web_log_parser_tokens = web_policy.web_log_parser_tokens

        # Vectorised prefilter. A forensic partition is overwhelmingly filestat
        # and registry rows, so interpreting every row in Python to discover it
        # is not a web event dominated this pass. The candidate test below is
        # exactly the condition the row loop used to apply one row at a time.
        request_text = _normalised_text_array(df, web_inputs.request_field)
        url_text = _normalised_text_array(df, web_inputs.url_field)
        parser_lower = _normalised_text_array(
            df, web_inputs.parser_field, lower=True
        )
        web_candidates = (request_text != "") | (url_text != "")
        if web_log_parser_tokens:
            web_candidates |= _text_array_contains_any(parser_lower, web_log_parser_tokens)
        candidate_rows = np.flatnonzero(web_candidates)

        # Columns are always created, even when no row qualifies, so the
        # sidecar schema stays identical across partitions. Object arrays are
        # allocated at C level rather than as Python lists of pd.NA.
        canonical_string_field_names = (
            "chronosift_web_method",
            "chronosift_web_request_target",
            "chronosift_web_endpoint",
            "chronosift_web_query",
            "chronosift_web_host",
            "chronosift_web_source_ip",
            "chronosift_web_user_agent",
            "chronosift_web_referer",
            "chronosift_web_content_type",
            "chronosift_web_upload_name",
            "chronosift_web_upload_names",
            "chronosift_web_upload_hashes",
            "chronosift_web_upload_content_types",
            "chronosift_web_upload_outcome",
            "chronosift_web_attack_indicators",
            "chronosift_web_outcome",
            "chronosift_web_file_hit_types",
            "chronosift_web_file_categories",
            "chronosift_web_file_rules",
            "chronosift_web_file_families",
            "chronosift_attack_techniques",
        )
        configured_string_field_names = (
            web_outputs.method_field,
            web_outputs.endpoint_field,
            web_outputs.source_ip_field,
            web_outputs.upload_names_field,
            web_outputs.upload_hashes_field,
            web_outputs.upload_outcome_field,
            web_outputs.attack_indicators_field,
            web_outputs.web_outcome_field,
            *correlation_policy.web_feature_fields.values(),
            correlation_policy.attack_techniques_field,
        )
        string_field_names = tuple(dict.fromkeys(
            (*canonical_string_field_names, *configured_string_field_names)
        ))
        integer_field_names = tuple(dict.fromkeys((
            "chronosift_web_status_code",
            "chronosift_web_response_bytes",
            "chronosift_web_upload_count",
            "chronosift_web_request_body_bytes",
            web_outputs.status_field,
        )))

        if candidate_rows.size == 0:
            # Nothing to interpret. Broadcasting the NA scalar lets pandas build
            # each column directly instead of validating a per-row object array,
            # which is an order of magnitude cheaper on a partition that holds
            # no web records at all — the common case in a forensic timeline.
            for name in string_field_names:
                df[name] = pd.Series(pd.NA, index=df.index, dtype="string")
            for name in integer_field_names:
                df[name] = pd.Series(pd.NA, index=df.index, dtype="Int64")
            df["chronosift_web_is_event"] = pd.Series(False, index=df.index, dtype="boolean")
            return

        string_fields: Dict[str, np.ndarray] = {
            name: np.full(nrows, None, dtype=object) for name in string_field_names
        }
        status_codes = np.full(nrows, None, dtype=object)
        response_sizes = np.full(nrows, None, dtype=object)
        upload_counts = np.full(nrows, None, dtype=object)
        request_body_sizes = np.full(nrows, None, dtype=object)
        is_web_event = np.zeros(nrows, dtype=bool)

        def assign_string_feature(
            canonical_name: str,
            configured_name: str,
            row_i: int,
            value: Any,
        ) -> None:
            for field_name in dict.fromkeys((canonical_name, configured_name)):
                string_fields[field_name][row_i] = value

        for row_i in candidate_rows:
            request = request_text[row_i]
            url = url_text[row_i]
            semantics = _extract_http_request_semantics(message_vals[row_i], request, url)
            request_target = _safe_str(semantics.get("path")).strip()
            if not request_target:
                continue
            is_web_event[row_i] = True
            method = _safe_str(semantics.get("method")).strip().upper()
            endpoint = _canonical_web_request_path(request_target)
            try:
                parsed_target = urlparse(
                    request_target if "://" in request_target else f"http://localhost{request_target if request_target.startswith('/') else '/' + request_target}"
                )
                query = parsed_target.query
            except Exception:
                query = request_target.split("?", 1)[1].split("#", 1)[0] if "?" in request_target else ""
            decoded_query = (
                _decode_http_detection_text_from_string(
                    query, web_policy.indicators.decode_rounds
                )
                if query else ""
            )
            content_type = _http_header_value(header_vals[row_i], "content-type")
            upload_names: List[str] = []
            upload_hashes: List[str] = []
            upload_content_types: List[str] = []
            if method in web_policy.upload.upload_methods:
                structured_names = (
                    *_extract_structured_upload_names(
                        upload_filename_vals[row_i],
                        query_parameter_names=web_policy.upload.query_parameter_names,
                        filename_extension_admission=(
                            web_policy.upload.filename_extension_admission
                        ),
                    ),
                    *_extract_http_upload_names(
                        disposition_vals[row_i], body_vals[row_i],
                        query_parameter_names=web_policy.upload.query_parameter_names,
                        filename_extension_admission=(
                            web_policy.upload.filename_extension_admission
                        ),
                    ),
                )
                upload_endpoint = any(
                    token in endpoint
                    for token in web_policy.upload.endpoint_tokens
                )
                legacy_names = ()
                if (
                    structured_names
                    or method in web_policy.upload.nameless_methods
                    or upload_endpoint
                    or (
                        content_type
                        and web_policy.upload.multipart_content_type
                        in content_type.lower()
                    )
                ):
                    legacy_names = _extract_http_upload_names(
                        message_vals[row_i], request, url, request_target,
                        query_parameter_names=web_policy.upload.query_parameter_names,
                        filename_extension_admission=(
                            web_policy.upload.filename_extension_admission
                        ),
                    )
                for candidate in (*structured_names, *legacy_names):
                    if candidate not in upload_names:
                        upload_names.append(candidate)
                if not upload_names and method in web_policy.upload.nameless_methods:
                    target_name = _normalise_upload_filename(
                        endpoint,
                        filename_extension_admission=(
                            web_policy.upload.filename_extension_admission
                        ),
                    )
                    if target_name:
                        upload_names.append(target_name)
                for source in (upload_sha256_vals[row_i], body_vals[row_i]):
                    for candidate in _extract_upload_sha256_values(source):
                        if candidate not in upload_hashes:
                            upload_hashes.append(candidate)
                for text in _bounded_metadata_strings(upload_content_type_vals[row_i]):
                    content_type_value = text.strip().lower()
                    if content_type_value and content_type_value not in upload_content_types:
                        upload_content_types.append(content_type_value)
                for text in _bounded_metadata_strings(body_vals[row_i]):
                    for match in _MULTIPART_CONTENT_TYPE_RE.finditer(text):
                        content_type_value = match.group(1).strip().lower()
                        if content_type_value and content_type_value not in upload_content_types:
                            upload_content_types.append(content_type_value)
            upload_name = upload_names[0] if upload_names else ""
            status_code = _normalise_integral_metadata_value(status_vals[row_i])
            request_body_size = _normalise_integral_metadata_value(request_length_vals[row_i])
            if request_body_size is None:
                request_body_size = _normalise_integral_metadata_value(
                    _http_header_value(header_vals[row_i], "content-length")
                )
            upload_semantics = bool(
                method in web_policy.upload.upload_methods
                and (
                    method in web_policy.upload.nameless_methods
                    or upload_names or upload_hashes
                    or (
                        content_type
                        and web_policy.upload.multipart_content_type
                        in content_type.lower()
                    )
                )
            )
            upload_outcome = ""
            if upload_semantics:
                if status_code is None:
                    upload_outcome = web_policy.outcomes.upload_unknown
                elif (
                    web_policy.outcomes.success_status_minimum
                    <= status_code
                    < web_policy.outcomes.success_status_maximum_exclusive
                ):
                    upload_outcome = web_policy.outcomes.upload_accepted
                elif (
                    web_policy.outcomes.redirect_status_minimum
                    <= status_code
                    < web_policy.outcomes.redirect_status_maximum_exclusive
                ):
                    upload_outcome = web_policy.outcomes.upload_redirected
                else:
                    upload_outcome = web_policy.outcomes.upload_rejected
            indicators = (
                list(_http_attack_indicators(request_target, web_policy.indicators))
                if web_policy.enabled
                else []
            )
            if web_policy.enabled and upload_semantics:
                indicators.append(web_policy.upload.file_upload_indicator)
            if web_policy.enabled and any(
                any(
                    name.endswith(extension)
                    for extension in web_policy.upload.executable_extensions
                )
                for name in upload_names
            ):
                indicators.append(web_policy.upload.executable_upload_indicator)
            if web_policy.enabled and any(
                name.count(".") >= web_policy.upload.double_extension_minimum_dots
                for name in upload_names
            ):
                indicators.append(web_policy.upload.double_extension_indicator)
            mime_values_admitted = bool(
                upload_names
                and upload_content_types
                and (
                    web_policy.upload.mime_value_pairing == "any_pair"
                    or (
                        len(upload_names) == 1
                        and len(upload_content_types) == 1
                    )
                )
            )
            mime_mismatch = mime_values_admitted and any(
                web_policy.upload.mime_mismatch.matches({
                    "image_extension": (
                        normalise_file_extension(name)
                        in web_policy.upload.image_extensions
                    ),
                    "executable_extension": any(
                        name.endswith(extension)
                        for extension in web_policy.upload.executable_extensions
                    ),
                    "image_content_type": content_type_value.startswith(
                        web_policy.upload.image_content_type_prefix
                    ),
                })
                for name in upload_names
                for content_type_value in upload_content_types
            )
            if web_policy.enabled and mime_mismatch:
                indicators.append(web_policy.upload.mime_extension_mismatch_indicator)
            indicators = list(dict.fromkeys(indicators))

            assign_string_feature(
                "chronosift_web_method",
                web_outputs.method_field,
                row_i,
                method or pd.NA,
            )
            string_fields["chronosift_web_request_target"][row_i] = request_target[:2000]
            assign_string_feature(
                "chronosift_web_endpoint",
                web_outputs.endpoint_field,
                row_i,
                endpoint or pd.NA,
            )
            string_fields["chronosift_web_query"][row_i] = decoded_query[:2000] or pd.NA
            string_fields["chronosift_web_host"][row_i] = _web_request_host(url or request_target, header_vals[row_i]) or pd.NA
            assign_string_feature(
                "chronosift_web_source_ip",
                web_outputs.source_ip_field,
                row_i,
                (
                    next((
                        value
                        for values in source_ip_values
                        if (value := _safe_str(values[row_i]).strip())
                    ), "")
                    or pd.NA
                ),
            )
            string_fields["chronosift_web_user_agent"][row_i] = _safe_str(ua_vals[row_i]).strip()[:500] or pd.NA
            string_fields["chronosift_web_referer"][row_i] = _safe_str(referer_vals[row_i]).strip()[:1000] or pd.NA
            string_fields["chronosift_web_content_type"][row_i] = content_type[:240] if content_type else pd.NA
            string_fields["chronosift_web_upload_name"][row_i] = upload_name[:500] or pd.NA
            assign_string_feature(
                "chronosift_web_upload_names",
                web_outputs.upload_names_field,
                row_i,
                "|".join(upload_names)[:2000] or pd.NA,
            )
            assign_string_feature(
                "chronosift_web_upload_hashes",
                web_outputs.upload_hashes_field,
                row_i,
                "|".join(upload_hashes) or pd.NA,
            )
            string_fields["chronosift_web_upload_content_types"][row_i] = "|".join(upload_content_types)[:1000] or pd.NA
            assign_string_feature(
                "chronosift_web_upload_outcome",
                web_outputs.upload_outcome_field,
                row_i,
                upload_outcome or pd.NA,
            )
            assign_string_feature(
                "chronosift_web_attack_indicators",
                web_outputs.attack_indicators_field,
                row_i,
                "|".join(indicators) or pd.NA,
            )
            assign_string_feature(
                "chronosift_web_outcome",
                web_outputs.web_outcome_field,
                row_i,
                web_policy.outcomes.select((
                    "observed",
                    *(
                        ("attempt",)
                        if web_policy.outcomes.attempt_when.matches(indicators)
                        else ()
                    ),
                )),
            )
            status_codes[row_i] = status_code
            response_sizes[row_i] = _normalise_integral_metadata_value(response_bytes_vals[row_i])
            upload_counts[row_i] = len(upload_names) if upload_semantics else pd.NA
            request_body_sizes[row_i] = request_body_size

        for column, values in string_fields.items():
            df[column] = pd.array(values, dtype="string")
        for field_name in dict.fromkeys((
            "chronosift_web_status_code",
            web_outputs.status_field,
        )):
            df[field_name] = pd.array(status_codes, dtype="Int64")
        df["chronosift_web_response_bytes"] = pd.array(response_sizes, dtype="Int64")
        df["chronosift_web_upload_count"] = pd.array(upload_counts, dtype="Int64")
        df["chronosift_web_request_body_bytes"] = pd.array(request_body_sizes, dtype="Int64")
        df["chronosift_web_is_event"] = pd.array(is_web_event, dtype="boolean")

    # -------------------------------------------------------------------------
    # Public API
    # -------------------------------------------------------------------------


    def _apply_hash_enrichment_csv(
        self,
        df: pd.DataFrame,
        csv_path: str,
        hash_col: str = "sha256_hash",
        csv_hash_col: str = "sha256",
    ) -> pd.DataFrame:
        """Join a hash-keyed enrichment CSV onto the timeline while preserving the index."""
        out = df
        if hash_col not in out.columns:
            return out

        enrich = _load_hash_enrichment_frame(csv_path, csv_hash_col=csv_hash_col)
        if len(enrich) == 0:
            return out

        lookup_hash = _normalise_hash_series(out[hash_col])
        matched = _reindex_lookup_frame_for_hashes(lookup_hash, enrich)
        for col in matched.columns:
            matched_col = matched[col]
            if col in out.columns:
                out[col] = matched_col.combine_first(out[col])
            else:
                out[col] = matched_col
        return out

    def _atomic_required_columns(self) -> List[str]:
        """
        Return the minimal column subset needed for the atomic pass.
        This includes:
          - all rule/normalisation required fields
          - enrichment inputs
          - fields required by sparse AV/YARA injection
          - fields needed later for candidate selection
        """
        # This method is part of the parquet/DuckDB optimisation contract. Any
        # new field added to atomic logic should be reflected here so projected
        # reads stay minimal instead of silently widening to full-row loads.
        cols: Set[str] = set(self.required_fields)

        # Core enrichment and injection inputs
        cols.update({
            CHRONOSIFT_ROW_ID_COLUMN,
            "sha256_hash",
            "filename",
            "file_path",
            "image_path",
            "message",
            "parser",
            "yara_match",
            "ip_address",
            "actor_ip",
            "src_ip",
            "dst_ip",
            "username",
            "actor_user",
            "actor_principal",
            "command",
            "command_line",
            "xml_string",
            "strings",
            "text",
        })

        # Profiling support
        if self.profiling_policy.enabled:
            cols.update({
                self.profiling_policy.parser_field,
                self.profiling_policy.nsrl_is_os_component_field,
                self.profiling_policy.nsrl_application_type_field,
                self.profiling_policy.filename_field,
            })

        # Candidate window actor columns
        cols.update({"actor_principal", "actor_user", "ip_address"})

        for canonical, aliases in self.schema_aliases.items():
            if canonical in cols:
                cols.update(a for a in aliases if a)

        return sorted(c for c in cols if c)

    def _apply_nsrl_enrichment_from_cache(
        self,
        df: pd.DataFrame,
        nsrl_cache_df: pd.DataFrame,
        hash_col: str = "sha256_hash",
    ) -> pd.DataFrame:
        """Apply NSRL enrichment from a prebuilt Parquet cache."""
        out = df
        if hash_col not in out.columns:
            return out
        if nsrl_cache_df is None:
            return out

        sha = _normalise_hash_series(out[hash_col])
        lookup_mask = _nsrl_lookup_candidate_mask(out, hash_col=hash_col)
        parquet_path = nsrl_cache_df.attrs.get("_chronosift_nsrl_parquet_path")
        app_output_field = self.profiling_policy.nsrl_application_type_field
        os_output_field = self.profiling_policy.nsrl_is_os_component_field

        for col in (app_output_field, os_output_field):
            if col in out.columns:
                out = out.drop(columns=[col])

        app_series = pd.Series(pd.NA, index=out.index, dtype="string")
        os_series = pd.Series(False, index=out.index, dtype=bool)

        if not lookup_mask.any():
            out[app_output_field] = app_series
            out[os_output_field] = os_series
            return out

        lookup_sha = sha[lookup_mask].dropna().drop_duplicates()
        if parquet_path:
            joined = _duckdb_lookup_nsrl_hashes(str(parquet_path), lookup_sha.tolist())
            joined = _prepare_nsrl_cache_df(
                joined,
                self.profiling_policy.exclude_nsrl_application_type_contains,
            )
            lookup_df = joined.attrs.get("_chronosift_lookup_df")
        else:
            if len(nsrl_cache_df) == 0:
                out[app_output_field] = app_series
                out[os_output_field] = os_series
                return out
            lookup_df = nsrl_cache_df.attrs.get("_chronosift_lookup_df")
            if lookup_df is None:
                nsrl_cache_df = _prepare_nsrl_cache_df(
                    nsrl_cache_df,
                    self.profiling_policy.exclude_nsrl_application_type_contains,
                )
                lookup_df = nsrl_cache_df.attrs.get("_chronosift_lookup_df")

        masked_sha = sha[lookup_mask]
        lookup_positions = np.flatnonzero(lookup_mask.to_numpy(dtype=bool, copy=False))
        aligned = _reindex_lookup_frame_for_hashes(
            masked_sha,
            lookup_df if lookup_df is not None else pd.DataFrame(columns=["nsrl_application_type", "nsrl_is_os_component"]),
            columns=("nsrl_application_type", "nsrl_is_os_component"),
        )
        app_series.iloc[lookup_positions] = aligned["nsrl_application_type"].astype("string").to_numpy(copy=False)
        os_series.iloc[lookup_positions] = aligned["nsrl_is_os_component"].astype("boolean").fillna(False).astype(bool).to_numpy(copy=False)

        out[app_output_field] = app_series
        out[os_output_field] = os_series
        return out

    def _extract_windows_auth_fields(self, df: pd.DataFrame) -> pd.DataFrame:
        """
        Materialise structured Windows auth/RDP fields from EVTX XML.

        This stage runs before normalisation so downstream canonical columns and
        rules can prefer event semantics over message matching. It is restricted
        to rows selected by the configured parser prefixes and XML field, so
        the Parquet/DuckDB read contract stays narrow.
        """
        out = df
        policy = self.canonicalisation_policy.windows_authentication
        derived_fields = list(policy.output_fields)
        out = _ensure_object_columns(out, [*policy.input_fields, *derived_fields])

        parser_vals = out[policy.parser_field].astype("string").fillna("").str.lower()
        xml_vals = out[policy.xml_field].astype("string").fillna("")
        evtx_mask = parser_vals.str.startswith(policy.parser_prefixes).to_numpy(dtype=bool, copy=False)
        xml_mask = xml_vals.ne("").to_numpy(dtype=bool, copy=False)
        target_mask = evtx_mask & xml_mask
        if not bool(target_mask.any()):
            return out

        target_pos = np.flatnonzero(target_mask)
        extracted = (
            out[policy.xml_field]
            .iloc[target_pos]
            .map(
                lambda value: _extract_windows_event_values_from_evtx_xml(
                    value,
                    policy,
                    self.canonicalisation_policy.excluded_networks,
                )
            )
        )
        extracted_df = pd.DataFrame(list(extracted), index=out.index[target_pos])
        if extracted_df.empty:
            return out

        for col in derived_fields:
            if col not in extracted_df.columns:
                continue
            target_values = extracted_df[col].astype("string")
            existing = out[col].iloc[target_pos]
            if policy.output_merge == "preserve_existing":
                merge_mask = _missing_meaningful_value_mask(
                    existing,
                    policy.placeholders,
                ).to_numpy(dtype=bool, copy=False)
            else:
                merge_mask = ~_missing_meaningful_value_mask(
                    target_values,
                    policy.placeholders,
                ).to_numpy(dtype=bool, copy=False)
            if not bool(merge_mask.any()):
                continue
            selected = np.flatnonzero(merge_mask)
            fill_pos = target_pos[selected]
            fill_values = target_values.iloc[selected].to_numpy(copy=False)
            col_loc = out.columns.get_loc(col)
            out.iloc[fill_pos, col_loc] = fill_values

        return out

    def _extract_ssh_auth_fields(self, df: pd.DataFrame) -> pd.DataFrame:
        """
        Materialise structured SSH auth fields from sshd/syslog messages.
        """
        out = df
        policy = self.canonicalisation_policy.ssh_authentication
        derived_fields = list(policy.output_fields)
        out = _ensure_object_columns(out, [*policy.input_fields, *derived_fields])

        parser_vals = out[policy.parser_field].astype("string").fillna("").str.lower()
        message_vals = out[policy.message_field].astype("string").fillna("")
        parser_match = parser_vals.isin(policy.parser_values)
        message_match = message_vals.str.contains(policy.message_regex, na=False)
        selector_match = (
            parser_match & message_match
            if policy.selector_match == "all"
            else parser_match | message_match
        )
        target_mask = selector_match & message_vals.ne("")
        if not bool(target_mask.any()):
            return out

        target_pos = np.flatnonzero(target_mask.to_numpy(dtype=bool, copy=False))
        extracted = out[policy.message_field].iloc[target_pos].map(
            lambda value: _extract_ssh_auth_fields_from_message(
                value,
                policy,
                self.canonicalisation_policy.excluded_networks,
            )
        )
        extracted_df = pd.DataFrame(list(extracted), index=out.index[target_pos])
        if extracted_df.empty:
            return out

        for col in derived_fields:
            if col not in extracted_df.columns:
                continue
            target_values = extracted_df[col].astype("string")
            existing = out[col].iloc[target_pos]
            if policy.output_merge == "preserve_existing":
                merge_mask = _missing_meaningful_value_mask(existing).to_numpy(
                    dtype=bool, copy=False
                )
            else:
                merge_mask = ~_missing_meaningful_value_mask(
                    target_values
                ).to_numpy(dtype=bool, copy=False)
            if not bool(merge_mask.any()):
                continue
            selected = np.flatnonzero(merge_mask)
            fill_pos = target_pos[selected]
            fill_values = target_values.iloc[selected].to_numpy(copy=False)
            col_loc = out.columns.get_loc(col)
            out.iloc[fill_pos, col_loc] = fill_values

        return out

    def _apply_schema_aliases(self, df: pd.DataFrame) -> pd.DataFrame:
        """
        Populate canonical columns from known schema aliases without widening
        rules to every source-specific field name.
        """
        out = df
        for canonical, aliases in self.schema_aliases.items():
            if not canonical:
                continue
            alias_fields = [a for a in aliases if a and a in out.columns]
            if canonical not in out.columns and not alias_fields:
                continue
            if canonical not in out.columns:
                out = _ensure_object_columns(out, [canonical])
                out[canonical] = _coalesce_first_meaningful(out, alias_fields)
                continue

            if not (
                pd.api.types.is_object_dtype(out[canonical].dtype)
                or pd.api.types.is_string_dtype(out[canonical].dtype)
            ):
                # Replace the whole column so pandas updates dtype before later
                # fill operations, rather than attempting an incompatible .loc
                # assignment into the existing numeric/boolean dtype.
                out[canonical] = out[canonical].astype("object")
            missing = _missing_meaningful_value_mask(out[canonical])
            if not bool(missing.any()) or not alias_fields:
                continue
            filled = _coalesce_first_meaningful_for_mask(out, alias_fields, missing)
            out.loc[missing, canonical] = filled.to_numpy(copy=False)
        return out

    def _derive_pivot_destination_fields(self, df: pd.DataFrame) -> pd.DataFrame:
        """
        Build deterministic destination identity fields for pivot narratives.

        Temporal grouping needs a single stable destination key, but evidence
        should still preserve the underlying IP/FQDN/hostname components. The
        configured precedence and prefixes define the stable identity.
        """
        out = df
        policy = self.canonicalisation_policy.pivot_destination
        out = _ensure_object_columns(
            out,
            [*policy.input_fields, *policy.output_fields],
        )

        for role, configured_sources in policy.sources.items():
            canonical = policy.outputs[role]
            source_fields = [field for field in configured_sources if field in out.columns]
            missing = _missing_meaningful_value_mask(out[canonical])
            if not bool(missing.any()) or not source_fields:
                continue
            filled = _coalesce_first_meaningful_for_mask(out, source_fields, missing)
            out.loc[missing, canonical] = filled.to_numpy(copy=False)

        normalised: Dict[str, pd.Series] = {}
        for role in policy.sources:
            values = out[policy.outputs[role]].astype("string").fillna("").str.strip()
            if role == "ip":
                role_values = pd.Series("", index=out.index, dtype="string")
                nonempty = values.ne("")
                if bool(nonempty.any()):
                    role_values.loc[nonempty] = (
                        values.loc[nonempty]
                        .map(
                            lambda value: _normalise_ip_literal(
                                value,
                                self.canonicalisation_policy.excluded_networks,
                            )
                        )
                        .fillna("")
                        .astype("string")
                    )
            else:
                role_values = (
                    values
                    .mask(values.str.lower().isin(PLACEHOLDER_STRINGS), "")
                    .str.lower()
                )
            normalised[role] = role_values

        identity_field = policy.outputs["identity"]
        pivot = pd.Series("", index=out.index, dtype="string")
        for precedence in policy.precedence:
            remaining = pivot.eq("")
            role_values = normalised[precedence.role]
            matched = remaining & role_values.ne("")
            if bool(matched.any()):
                pivot.loc[matched] = precedence.prefix + role_values.loc[matched]

        auth_like = pd.Series(False, index=out.index, dtype=bool)
        for field_name in policy.auth_like_any_fields:
            auth_like |= ~_missing_meaningful_value_mask(out[field_name])
        pivot = pivot.where(auth_like, "")
        out[identity_field] = pivot.replace("", pd.NA).astype("string")
        return out

    def _apply_canonical_auth_signals_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
    ) -> None:
        """
        Inject protocol-agnostic auth signals for continuity and temporal logic.
        """
        policy = self.detector_policy.canonical_authentication
        if not policy.enabled:
            return
        success_sources = tuple(policy.success_sources)
        fail_sources = tuple(policy.failure_sources)
        nrows = len(df)
        auth_protocol_vals = _normalised_text_array(
            df, policy.protocol_field, lower=True
        )
        auth_direction_vals = _normalised_text_array(
            df, policy.direction_field, lower=True
        )
        auth_outcome_vals = _normalised_text_array(
            df, policy.outcome_field, lower=True
        )
        logon_type_vals = _normalised_text_array(df, policy.logon_type_field)
        message_vals = _normalised_text_array(
            df, policy.message_field, lower=True
        )
        auth_pkg_vals = _normalised_text_array(
            df, policy.authentication_package_field, lower=True
        )

        _success_keys_lower = tuple(s.lower() for s in success_sources)
        _fail_keys_lower = tuple(s.lower() for s in fail_sources)
        success_source_mask = np.zeros(nrows, dtype=bool)
        failure_source_mask = np.zeros(nrows, dtype=bool)
        for _ri, _sigs in signal_map.items():
            if not (0 <= _ri < nrows) or not isinstance(_sigs, dict):
                continue
            for _key, _value in _sigs.items():
                if not isinstance(_value, (int, float)) or _is_null(_value):
                    continue
                if float(_value) <= policy.source_minimum_signal_value_exclusive:
                    continue
                _normalised_key = str(_key).strip().lower()
                if _normalised_key in _success_keys_lower:
                    success_source_mask[int(_ri)] = True
                if _normalised_key in _fail_keys_lower:
                    failure_source_mask[int(_ri)] = True

        def configured_fact_mask(
            mode: str,
            factors: Iterable[np.ndarray],
        ) -> np.ndarray:
            values = tuple(np.asarray(value, dtype=bool) for value in factors)
            if not values:
                return np.zeros(nrows, dtype=bool)
            result = values[0].copy()
            for value in values[1:]:
                if mode == "all":
                    result &= value
                else:
                    result |= value
            return result

        success_mask = configured_fact_mask(
            policy.outcome_source_match,
            (
                auth_outcome_vals == policy.success_value,
                success_source_mask,
            ),
        )
        failure_mask = configured_fact_mask(
            policy.outcome_source_match,
            (
                auth_outcome_vals == policy.failure_value,
                failure_source_mask,
            ),
        )
        conflict_mask = success_mask & failure_mask
        if policy.conflict_resolution == "prefer_success":
            failure_mask &= ~conflict_mask
        elif policy.conflict_resolution == "prefer_failure":
            success_mask &= ~conflict_mask
        elif policy.conflict_resolution == "suppress_both":
            success_mask &= ~conflict_mask
            failure_mask &= ~conflict_mask

        remote_mask = configured_fact_mask(
            policy.remote_match,
            (
                np.isin(
                    auth_direction_vals,
                    tuple(policy.remote_direction_values),
                ),
                np.isin(
                    auth_protocol_vals,
                    tuple(policy.remote_protocol_values),
                ),
            ),
        )
        remote_interactive_mask = configured_fact_mask(
            policy.remote_interactive_match,
            (
                np.isin(
                    auth_protocol_vals,
                    tuple(policy.remote_interactive_protocol_values),
                ),
                np.isin(
                    logon_type_vals,
                    tuple(policy.remote_interactive_logon_types),
                ),
            ),
        )
        remote_shell_mask = np.isin(
            auth_protocol_vals,
            tuple(policy.remote_shell_protocol_values),
        )
        invalid_user_mask = _text_array_contains_any(
            message_vals,
            policy.invalid_user_tokens,
        )
        new_credentials_mask = np.isin(
            logon_type_vals,
            tuple(policy.new_credentials_logon_types),
        )
        service_logon_mask = np.isin(
            logon_type_vals,
            tuple(policy.service_logon_types),
        )
        ntlm_package_mask = np.isin(
            auth_pkg_vals,
            tuple(policy.ntlm_authentication_packages),
        )
        lateral_match_count = (
            np.isin(logon_type_vals, tuple(policy.lateral_logon_types)).astype(
                np.int8
            )
            + np.isin(
                auth_pkg_vals,
                tuple(policy.lateral_authentication_packages),
            ).astype(np.int8)
        )
        if policy.lateral_include_remote:
            lateral_match_count += remote_mask.astype(np.int8)

        fact_masks = {
            "success": success_mask,
            "failure": failure_mask,
            "remote": remote_mask,
            "remote_interactive": remote_interactive_mask,
            "remote_shell": remote_shell_mask,
            "invalid_user": invalid_user_mask,
            "new_credentials": new_credentials_mask,
            "service_logon": service_logon_mask,
            "ntlm_package": ntlm_package_mask,
            "lateral_movement": (
                lateral_match_count >= policy.lateral_minimum_matches
            ),
        }
        eligible_mask = np.ones(nrows, dtype=bool)
        for fact_name in policy.eligibility.require_all:
            eligible_mask &= fact_masks[fact_name]
        if policy.eligibility.require_any:
            any_mask = np.zeros(nrows, dtype=bool)
            for fact_name in policy.eligibility.require_any:
                any_mask |= fact_masks[fact_name]
            eligible_mask &= any_mask
        for fact_name in policy.eligibility.exclude_any:
            eligible_mask &= ~fact_masks[fact_name]
        _candidate_rows = np.flatnonzero(eligible_mask)

        for row_i in _candidate_rows:
            signals = signal_map.get(row_i)
            if signals is None:
                signals = {}
            source_hits = {str(k).strip().lower(): v for k, v in signals.items()}
            added: List[Tuple[DetectorEmissionPolicy, str]] = []

            def emit_semantic(semantic: str, derived_from: str) -> None:
                emission = policy.emissions_by_semantic[semantic]
                prior = float(signals.get(emission.name, 0.0) or 0.0)
                if prior >= emission.value:
                    return
                signals[emission.name] = max(prior, emission.value)
                added.append((emission, derived_from))

            outcome = auth_outcome_vals[row_i]
            protocol = auth_protocol_vals[row_i]
            direction = auth_direction_vals[row_i]
            logon_type = logon_type_vals[row_i]
            message = message_vals[row_i]
            auth_pkg = auth_pkg_vals[row_i]

            success_source_hits = tuple(
                src
                for src in _success_keys_lower
                if isinstance(source_hits.get(src, 0.0), (int, float))
                and float(source_hits.get(src, 0.0))
                > policy.source_minimum_signal_value_exclusive
            )
            failure_source_hits = tuple(
                src
                for src in _fail_keys_lower
                if isinstance(source_hits.get(src, 0.0), (int, float))
                and float(source_hits.get(src, 0.0))
                > policy.source_minimum_signal_value_exclusive
            )

            facts = {
                name: bool(mask[row_i]) for name, mask in fact_masks.items()
            }
            fact_evidence = {
                "success": ",".join(success_source_hits) or outcome,
                "failure": ",".join(failure_source_hits) or outcome,
                "remote": protocol or direction or "remote",
                "remote_interactive": (
                    protocol or logon_type or "remote_interactive"
                ),
                "remote_shell": protocol or "remote_shell",
                "invalid_user": "invalid_user_message",
                "new_credentials": f"logon_type_{logon_type}",
                "service_logon": f"logon_type_{logon_type}",
                "ntlm_package": auth_pkg or "authentication_package",
                "lateral_movement": (
                    f"logon_type={logon_type},pkg={auth_pkg}"
                ),
            }
            for semantic, decision in policy.decisions_by_semantic.items():
                if not decision.matches(facts):
                    continue
                evidence_parts: List[str] = []
                for fact_name in sorted(
                    set(decision.require_all)
                    | {
                        name
                        for name in decision.require_any
                        if facts.get(name, False)
                    }
                ):
                    value = fact_evidence[fact_name]
                    if value and value not in evidence_parts:
                        evidence_parts.append(value)
                emit_semantic(semantic, ",".join(evidence_parts))

            if added:
                if row_i not in signal_map:
                    signal_map[row_i] = signals
                expl = self._sparse_explain_list(explain_map, row_i)
                for emission, sources in added:
                    expl.append({
                        "rule_id": emission.rule_id,
                        "description": emission.description,
                        "confidence": emission.confidence,
                        "evidence_type": policy.evidence_type,
                        "signals": [emission.name],
                        "evidence": {name: sources for name in policy.evidence},
                    })

    def _derive_execution_context_signals_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
    ) -> None:
        """
        Recover lightweight process-aware execution context from Plaso-visible
        command and path artefacts without assuming PID or parent/child lineage.
        """
        if len(df) == 0:
            return

        policy = self.detector_policy.execution_context_classifier
        if not policy.enabled:
            return

        path_candidates = _coalesce_first_meaningful(
            df,
            [c for c in policy.path_fields if c in df.columns],
        ) if any(c in df.columns for c in policy.path_fields) else pd.Series([None] * len(df), index=df.index)
        cmd_candidates = _coalesce_first_meaningful(
            df,
            [c for c in policy.command_fields if c in df.columns],
        ) if any(c in df.columns for c in policy.command_fields) else pd.Series([None] * len(df), index=df.index)
        actor_candidates = _coalesce_first_meaningful(
            df,
            [c for c in policy.actor_fields if c in df.columns],
        ) if any(c in df.columns for c in policy.actor_fields) else pd.Series([None] * len(df), index=df.index)

        path_vals = path_candidates.astype("string").fillna("").str.strip().to_numpy(dtype=object, copy=False)
        path_lower = (
            path_candidates.astype("string")
            .fillna("")
            .str.strip()
            .str.lower()
            .str.replace("\\", "/", regex=False)
            .to_numpy(dtype=object, copy=False)
        )
        basenames = np.array([os.path.basename(path) if path else "" for path in path_lower], dtype=object)
        cmd_vals = cmd_candidates.astype("string").fillna("").str.strip().to_numpy(dtype=object, copy=False)
        cmd_lower = (
            cmd_candidates.astype("string")
            .fillna("")
            .str.strip()
            .str.lower()
            .to_numpy(dtype=object, copy=False)
        )
        actor_lower = actor_candidates.astype("string").fillna("").str.strip().str.lower().to_numpy(dtype=object, copy=False)
        tmp_path_tokens = policy.temporary_path_tokens
        user_writable_tokens = policy.user_writable_path_tokens
        suspicious_path_tokens = policy.suspicious_path_tokens
        command_class_cache: Dict[str, Tuple[bool, bool, bool, bool]] = {}

        def classify_command(command: str) -> Tuple[bool, bool, bool, bool]:
            cached = command_class_cache.get(command)
            if cached is not None:
                return cached
            hits = [False, False, False, False]
            name_sets = (
                policy.compiler_names,
                policy.shell_names,
                policy.network_tool_names,
                policy.archive_tool_names,
            )
            for match in _COMMAND_TOKEN_RE.finditer(command):
                token = match.group(0)
                base = (
                    _basename_from_reference_path(token)
                    if "/" in token or "\\" in token
                    else token
                )
                for category_index, configured_names in enumerate(name_sets):
                    if not hits[category_index] and (
                        token in configured_names or base in configured_names
                    ):
                        hits[category_index] = True
                if all(hits):
                    break
            result = tuple(hits)
            command_class_cache[command] = result
            return result  # type: ignore[return-value]

        for row_i in range(len(df)):
            path = path_vals[row_i]
            path_l = path_lower[row_i]
            basename = basenames[row_i]
            cmd = cmd_vals[row_i]
            cmd_l = cmd_lower[row_i]
            actor = actor_lower[row_i]

            tmp_path = bool(path_l and any(tok in path_l for tok in tmp_path_tokens))
            user_writable = bool(path_l and any(tok in path_l for tok in user_writable_tokens))
            suspicious_path = bool(path_l and any(tok in path_l for tok in suspicious_path_tokens))
            system_binary_name = bool(
                basename and basename in policy.system_binary_names
            )
            compiler_hit, shell_hit, network_hit, archive_hit = classify_command(
                cmd_l
            )
            privileged_hit = actor in policy.privileged_actors
            suid_hit = bool(cmd_l and policy.suid_pattern.search(cmd_l))

            facts = {
                "temporary_path": tmp_path,
                "user_writable_path": user_writable,
                "suspicious_path": suspicious_path,
                "system_binary_name": system_binary_name,
                "compiler_command": compiler_hit,
                "shell_command": shell_hit,
                "network_command": network_hit,
                "archive_command": archive_hit,
                "privileged_actor": privileged_hit,
                "suid_command": suid_hit,
            }
            fact_evidence = {
                "temporary_path": path,
                "user_writable_path": path,
                "suspicious_path": path,
                "system_binary_name": path,
                "compiler_command": cmd,
                "shell_command": cmd,
                "network_command": cmd,
                "archive_command": cmd,
                "privileged_actor": actor,
                "suid_command": cmd,
            }
            to_emit: List[Tuple[str, str]] = []
            for semantic, decision in policy.decisions_by_semantic.items():
                if not decision.matches(facts):
                    continue
                evidence_parts: List[str] = []
                for fact_name in sorted(
                    set(decision.require_all)
                    | {
                        name
                        for name in decision.require_any
                        if facts.get(name, False)
                    }
                ):
                    value = fact_evidence[fact_name]
                    if value and value not in evidence_parts:
                        evidence_parts.append(value)
                to_emit.append((semantic, "|".join(evidence_parts)))

            if not to_emit:
                continue

            signals = self._sparse_signal_dict(signal_map, row_i)
            expl = self._sparse_explain_list(explain_map, row_i)
            for semantic, evidence_value in to_emit:
                emission = policy.emissions_by_semantic[semantic]
                prior = float(signals.get(emission.name, 0.0) or 0.0)
                if prior >= emission.value:
                    continue
                signals[emission.name] = max(prior, emission.value)
                evidence_values = {
                    "path": path[:240] if path else "",
                    "command": cmd[:240] if cmd else "",
                    "actor_user": actor,
                    "derived_from": (
                        evidence_value[:240]
                        if isinstance(evidence_value, str)
                        else _safe_str(evidence_value)[:240]
                    ),
                }
                expl.append({
                    "rule_id": emission.rule_id,
                    "description": emission.description,
                    "confidence": emission.confidence,
                    "evidence_type": policy.evidence_type,
                    "signals": [emission.name],
                    "evidence": {
                        name: evidence_values[name] for name in policy.evidence
                    },
                })

    def _resolve_row_policy_inputs(
        self,
        df: pd.DataFrame,
        inputs: Dict[str, RowInputPolicy],
        contextual_cache: Optional[Dict[Tuple[Any, ...], np.ndarray]],
    ) -> Dict[str, np.ndarray]:
        nrows = len(df)

        def normalise(values: np.ndarray, mode: str) -> np.ndarray:
            series = pd.Series(values, index=df.index, dtype="string").fillna("")
            series = series.str.strip()
            if mode in {"lower", "path_lower"}:
                series = series.str.lower()
            if mode == "path_lower":
                series = series.str.replace("\\", "/", regex=False)
            return series.to_numpy(dtype=object, copy=False)

        input_values: Dict[str, np.ndarray] = {}
        for input_name, input_policy in inputs.items():
            if input_policy.resolver == "row_field":
                values = _contextual_text_array(
                    df,
                    contextual_cache,
                    input_policy.fields[0],
                    lower=input_policy.normalise == "lower",
                )
                if input_policy.normalise == "path_lower":
                    values = normalise(values, "path_lower")
            elif input_policy.resolver == "best_effort_file_path":
                values = _contextual_file_paths(
                    df, contextual_cache, input_policy.fields
                )
                values = normalise(values, input_policy.normalise)
            elif input_policy.resolver == "first_nonempty":
                existing_fields = [
                    field for field in input_policy.fields if field in df.columns
                ]
                if existing_fields:
                    values = _coalesce_first_meaningful(
                        df, existing_fields
                    ).to_numpy(dtype=object, copy=False)
                else:
                    values = np.full(nrows, "", dtype=object)
                values = normalise(values, input_policy.normalise)
            elif input_policy.resolver == "concat":
                arrays = tuple(
                    _contextual_text_array(df, contextual_cache, field)
                    for field in input_policy.fields
                )
                first_existing_arrays = tuple(
                    _contextual_text_array(df, contextual_cache, field)
                    for field in input_policy.first_existing_fields
                )
                values = np.fromiter(
                    (
                        " ".join(
                            part
                            for part in (
                                *(array[row_i] for array in arrays),
                                next(
                                    (
                                        array[row_i]
                                        for array in first_existing_arrays
                                        if array[row_i]
                                    ),
                                    "",
                                ),
                            )
                            if part
                        )
                        for row_i in range(nrows)
                    ),
                    dtype=object,
                    count=nrows,
                )
                values = normalise(values, input_policy.normalise)
            elif input_policy.resolver == "timestamp_kind":
                descriptions = _contextual_text_array(
                    df, contextual_cache, input_policy.fields[0], lower=True
                )
                values = np.full(nrows, "", dtype=object)
                unclassified = np.ones(nrows, dtype=bool)
                for kind_name in input_policy.timestamp_kind_priority:
                    matches = _text_array_contains_any(
                        descriptions,
                        input_policy.timestamp_kind_tokens[kind_name],
                    ) & unclassified
                    values[matches] = kind_name
                    unclassified[matches] = False
            else:
                raise ValueError(
                    f"unsupported ordered-row input resolver: {input_policy.resolver}"
                )
            input_values[input_name] = values
        return input_values

    def _evaluate_row_policy_predicate(
        self,
        predicate: RowPredicatePolicy,
        input_values: Dict[str, np.ndarray],
        signal_map: Dict[int, Dict[str, Any]],
        nrows: int,
    ) -> np.ndarray:
        if predicate.operator in {"all", "any"}:
            children = tuple(
                self._evaluate_row_policy_predicate(
                    child, input_values, signal_map, nrows
                )
                for child in predicate.children
            )
            return (
                np.logical_and.reduce(children)
                if predicate.operator == "all"
                else np.logical_or.reduce(children)
            )
        if predicate.operator == "not":
            return ~self._evaluate_row_policy_predicate(
                predicate.children[0], input_values, signal_map, nrows
            )
        if predicate.operator == "at_least":
            children = tuple(
                self._evaluate_row_policy_predicate(
                    child, input_values, signal_map, nrows
                )
                for child in predicate.children
            )
            counts = np.sum(np.vstack(children), axis=0)
            return counts >= predicate.minimum_count
        if predicate.operator in {
            "signal_any_positive", "signal_all_positive"
        }:
            minimum_value_exclusive = predicate.minimum_value_exclusive
            if minimum_value_exclusive is None:
                raise RuntimeError(
                    "signal predicate is missing its parsed admission threshold"
                )
            mask = np.zeros(nrows, dtype=bool)
            for row_i, existing in signal_map.items():
                if not 0 <= row_i < nrows or not isinstance(existing, dict):
                    continue
                matches = []
                for signal_name in predicate.signals:
                    try:
                        value = float(existing.get(signal_name, 0.0) or 0.0)
                    except (TypeError, ValueError):
                        value = 0.0
                    matches.append(value > minimum_value_exclusive)
                mask[row_i] = (
                    any(matches)
                    if predicate.operator == "signal_any_positive"
                    else all(matches)
                )
            return mask

        values = input_values[predicate.input_name]
        if predicate.operator == "contains_any":
            return _text_array_contains_any(values, predicate.values)
        if predicate.operator == "equals_any":
            return np.isin(values, predicate.values)
        if predicate.operator == "starts_with_any":
            return np.fromiter(
                (
                    any(value.startswith(token) for token in predicate.values)
                    if value else False
                    for value in values
                ),
                dtype=bool,
                count=nrows,
            )
        if predicate.operator == "ends_with_any":
            return np.fromiter(
                (
                    any(value.endswith(token) for token in predicate.values)
                    if value else False
                    for value in values
                ),
                dtype=bool,
                count=nrows,
            )
        if predicate.operator == "regex":
            return (
                pd.Series(values, dtype="string")
                .str.contains(predicate.pattern, regex=True, na=False)
                .to_numpy(dtype=bool, copy=False)
            )
        if predicate.operator == "nonempty":
            return np.fromiter(
                (bool(value) for value in values),
                dtype=bool,
                count=nrows,
            )
        raise ValueError(
            f"unsupported ordered-row predicate: {predicate.operator}"
        )

    def _apply_ordered_row_rules_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
        contextual_cache: Optional[Dict[Tuple[Any, ...], np.ndarray]],
        *,
        detector_id: str,
    ) -> None:
        definition = self.detector_policy.definition(detector_id)
        policy = definition.payload
        nrows = len(df)
        if nrows == 0 or not policy.enabled:
            return

        input_values = self._resolve_row_policy_inputs(
            df, policy.inputs, contextual_cache
        )

        for rule in policy.rules:
            matched_rows = np.flatnonzero(
                self._evaluate_row_policy_predicate(
                    rule.predicate, input_values, signal_map, nrows
                )
            )
            emission = policy.emissions_by_id[rule.emission_id]
            for row_i in matched_rows:
                signals = self._sparse_signal_dict(signal_map, int(row_i))
                prior = float(signals.get(emission.name, 0.0) or 0.0)
                if prior < emission.value:
                    signals[emission.name] = max(prior, emission.value)
                resolved_evidence: Dict[str, Any] = {}
                for evidence_name in rule.evidence:
                    evidence_policy = policy.evidence[evidence_name]
                    value = _safe_str(
                        input_values[evidence_policy.input_name][row_i]
                    )
                    if evidence_policy.resolver == "regex_capture":
                        match = evidence_policy.pattern.search(value)
                        value = match.group(0) if match else ""
                    if evidence_policy.max_chars is not None:
                        value = value[:evidence_policy.max_chars]
                    resolved_evidence[evidence_name] = value
                explanations = self._sparse_explain_list(
                    explain_map, int(row_i)
                )
                if any(
                    item.get("detector_rule_id") == rule.rule_id
                    and emission.name in item.get("signals", [])
                    for item in explanations
                ):
                    continue
                explanations.append({
                    "rule_id": emission.rule_id,
                    "detector_rule_id": rule.rule_id,
                    "description": rule.description,
                    "confidence": rule.confidence,
                    "evidence_type": policy.evidence_type,
                    "signals": [emission.name],
                    "evidence": resolved_evidence,
                })

    def _apply_ordered_signal_adjustments_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
        contextual_cache: Optional[Dict[Tuple[Any, ...], np.ndarray]],
        *,
        detector_id: str,
    ) -> None:
        policy = self.detector_policy.definition(detector_id).payload
        nrows = len(df)
        if nrows == 0 or not policy.enabled:
            return
        input_values = self._resolve_row_policy_inputs(
            df, policy.inputs, contextual_cache
        )

        def positive(
            signals: Dict[str, Any],
            signal_name: str,
            minimum_value_exclusive: float,
        ) -> bool:
            try:
                return (
                    float(signals.get(signal_name, 0.0) or 0.0)
                    > minimum_value_exclusive
                )
            except (TypeError, ValueError):
                return False

        for rule in policy.rules:
            matched_rows = np.flatnonzero(
                self._evaluate_row_policy_predicate(
                    rule.predicate, input_values, signal_map, nrows
                )
            )
            for row_i_raw in matched_rows:
                row_i = int(row_i_raw)
                signals = signal_map.get(row_i)
                if not isinstance(signals, dict) or not signals:
                    continue
                conditions = rule.conditions
                if conditions.required_any and not any(
                    positive(
                        signals, name, conditions.minimum_value_exclusive
                    )
                    for name in conditions.required_any
                ):
                    continue
                if conditions.required_all and not all(
                    positive(
                        signals, name, conditions.minimum_value_exclusive
                    )
                    for name in conditions.required_all
                ):
                    continue
                if any(
                    positive(
                        signals, name, conditions.minimum_value_exclusive
                    )
                    for name in conditions.forbidden_any
                ):
                    continue

                changed: List[str] = []
                for signal_name in rule.target_signals:
                    raw_value = signals.get(signal_name)
                    if (
                        not isinstance(raw_value, (int, float))
                        or float(raw_value)
                        <= conditions.minimum_value_exclusive
                    ):
                        continue
                    adjusted_value = (
                        0.0
                        if rule.action == "zero"
                        else float(raw_value) * float(rule.multiplier)
                    )
                    if adjusted_value == float(raw_value):
                        continue
                    signals[signal_name] = adjusted_value
                    changed.append(signal_name)
                if not changed:
                    continue

                preserved = sorted(
                    signal_name
                    for signal_name in conditions.preserved
                    if positive(
                        signals,
                        signal_name,
                        conditions.minimum_value_exclusive,
                    )
                )
                resolved_evidence: Dict[str, Any] = {}
                for evidence_name in rule.evidence:
                    evidence_policy = policy.evidence[evidence_name]
                    if evidence_policy.resolver == "input":
                        value: Any = _safe_str(
                            input_values[evidence_policy.input_name][row_i]
                        )
                    elif evidence_policy.resolver == "changed_signals":
                        value = ",".join(sorted(changed))
                    elif evidence_policy.resolver == "preserved_positive_signals":
                        value = ",".join(preserved)
                    else:
                        value = (
                            0.0
                            if rule.action == "zero"
                            else round(float(rule.multiplier), 4)
                        )
                    if evidence_policy.max_chars is not None:
                        value = _safe_str(value)[:evidence_policy.max_chars]
                    resolved_evidence[evidence_name] = value
                self._sparse_explain_list(explain_map, row_i).append({
                    "rule_id": rule.rule_id,
                    "description": rule.description,
                    "confidence": rule.confidence,
                    "evidence_type": policy.evidence_type,
                    "evidence": resolved_evidence,
                })

    def _apply_grouped_signal_window_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
        *,
        detector_id: str,
    ) -> None:
        policy = self.detector_policy.definition(detector_id).payload
        if (
            len(df) == 0
            or not policy.enabled
            or not isinstance(df.index, pd.DatetimeIndex)
        ):
            return
        host_values = _normalised_text_array(
            df, policy.host_field, lower=True
        )
        command_arrays = tuple(
            _normalised_text_array(df, field)
            for field in policy.command_fields
        )
        message_values = _normalised_text_array(df, policy.message_field)
        events_by_key: Dict[
            Tuple[str, str], List[Tuple[int, pd.Timestamp]]
        ] = {}
        for row_i, existing in signal_map.items():
            if not 0 <= row_i < len(df) or not isinstance(existing, dict):
                continue
            qualifies = False
            for signal_name in policy.source_signals:
                try:
                    value = float(existing.get(signal_name, 0.0) or 0.0)
                except (TypeError, ValueError):
                    value = 0.0
                if value > policy.minimum_signal_value_exclusive:
                    qualifies = True
                    break
            if not qualifies:
                continue
            command = next(
                (array[row_i] for array in command_arrays if array[row_i]), ""
            )
            if not command:
                message = message_values[row_i]
                match = policy.message_pattern.search(message)
                command = (
                    match.group(1)
                    if match and match.lastindex
                    else message[:policy.message_fallback_max_chars]
                )
            command = _safe_str(command).strip().lower()
            if not command:
                continue
            key = (_safe_str(host_values[row_i]).strip().lower(), command)
            events_by_key.setdefault(key, []).append((row_i, df.index[row_i]))

        window = pd.Timedelta(policy.lookback)
        emission = policy.emission
        for key, events in events_by_key.items():
            left = 0
            emissions_for_key = 0
            for right, (row_i, timestamp) in enumerate(events):
                while left < right and timestamp - events[left][1] > window:
                    left += 1
                count_in_window = right - left + 1
                if count_in_window < policy.threshold:
                    continue
                signals = self._sparse_signal_dict(signal_map, row_i)
                prior = float(signals.get(emission.name, 0.0) or 0.0)
                if prior < emission.value:
                    signals[emission.name] = max(prior, emission.value)
                    evidence_values = {
                        "hostname": key[0],
                        "command": key[1][:240],
                        "count_in_window": int(count_in_window),
                        "window_seconds": int(window.total_seconds()),
                    }
                    self._sparse_explain_list(explain_map, row_i).append({
                        "rule_id": emission.rule_id,
                        "description": emission.description,
                        "confidence": emission.confidence,
                        "evidence_type": policy.evidence_type,
                        "signals": [emission.name],
                        "evidence": {
                            name: evidence_values[name]
                            for name in policy.evidence
                        },
                    })
                    emissions_for_key += 1
                if emissions_for_key >= policy.max_emissions_per_key:
                    break

    def _detector_policy_output_names(
        self,
        *detector_ids: str,
        enabled_only: bool = True,
    ) -> Tuple[str, ...]:
        """Return configured emission names for the selected semantic detectors."""
        names: List[str] = []
        for detector_id in detector_ids:
            definition = self.detector_policy.definition(detector_id)
            if enabled_only and not bool(definition.payload.enabled):
                continue
            names.extend(emission.name for emission in definition.emissions)
        return tuple(dict.fromkeys(names))

    def _clamav_category_output_names(
        self,
        *categories: str,
        enabled_only: bool = True,
    ) -> Tuple[str, ...]:
        """Return configured signal names for selected ClamAV semantic categories."""
        policy = self.detector_policy.clamav_classification
        if enabled_only and not policy.enabled:
            return ()
        return tuple(
            dict.fromkeys(policy.categories[category].emission.name for category in categories)
        )

    def _yara_category_output_names(
        self,
        *categories: str,
        enabled_only: bool = True,
    ) -> Tuple[str, ...]:
        """Return configured signal names for selected YARA semantic categories."""
        policy = self.detector_policy.yara_classification
        if enabled_only and not policy.enabled:
            return ()
        return tuple(
            dict.fromkeys(policy.categories[category].emission.name for category in categories)
        )

    def _apply_trust_dampening_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
    ) -> None:
        policy = self.trust_dampening_policy
        if not policy.enabled:
            return

        principal_vals = _normalised_text_array(
            df, policy.principal_field, lower=True
        )
        ip_vals = _normalised_text_array(df, policy.ip_field)
        asn_vals = _normalised_text_array(df, policy.asn_field)

        for row_i, signals in signal_map.items():
            if not signals or row_i >= len(df):
                continue
            principal = principal_vals[row_i]
            ip_s = ip_vals[row_i]
            asn_s = asn_vals[row_i]
            configured_selectors = {
                "principal_literal": bool(policy.trusted_principals),
                "principal_regex": bool(policy.trusted_principal_patterns),
                "ip": bool(policy.trusted_ips),
                "asn": bool(policy.trusted_asns),
            }
            selector_matches = {
                "principal_literal": bool(
                    principal and principal in policy.trusted_principals
                ),
                "principal_regex": bool(
                    principal
                    and any(
                        rx.search(principal)
                        for rx in policy.trusted_principal_patterns
                    )
                ),
                "ip": bool(ip_s and ip_s in policy.trusted_ips),
                "asn": bool(asn_s and asn_s in policy.trusted_asns),
            }
            configured_match_values = [
                selector_matches[role]
                for role, configured in configured_selectors.items()
                if configured
            ]
            trusted = bool(configured_match_values) and (
                all(configured_match_values)
                if policy.selector_match == "all"
                else any(configured_match_values)
            )
            if not trusted:
                continue
            trusted_reason = next(
                (
                    {
                        "principal_literal": "trusted_actor_principal",
                        "principal_regex": "trusted_actor_principal_regex",
                        "ip": "trusted_ip",
                        "asn": "trusted_asn",
                    }[role]
                    for role in policy.reason_precedence
                    if selector_matches[role]
                ),
                "",
            )

            changed: List[str] = []
            for sig_name, sig_val in list(signals.items()):
                sig_key = str(sig_name).strip().lower()
                if (
                    sig_key not in policy.signals
                    or not isinstance(sig_val, (int, float))
                ):
                    continue
                signals[sig_name] = float(sig_val) * policy.multiplier
                changed.append(sig_key)
            if changed:
                evidence_values = {
                    "reason": trusted_reason,
                    "multiplier": round(policy.multiplier, 4),
                    "signals": ",".join(sorted(changed)),
                }
                expl = self._sparse_explain_list(explain_map, row_i)
                expl.append({
                    "rule_id": policy.rule_id,
                    "description": policy.description,
                    "confidence": policy.confidence,
                    "evidence_type": policy.evidence_type,
                    "evidence": {
                        name: evidence_values[name] for name in policy.evidence
                    },
                })

    def _run_atomic_sparse(
        self,
        out: pd.DataFrame,
        apply_profiling: bool = True,
        enforce_required_fields: bool = True,
        geoip_city_db: Optional[str] = None,
        geoip_asn_db: Optional[str] = None,
        av_csv_path: Optional[str] = None,
        luhn_csv_path: Optional[str] = None,
        nsrl_parquet_path: Optional[str] = None,
        nsrl_cache_df: Optional[pd.DataFrame] = None,
        profile_manifest: Optional[Dict[str, Any]] = None,
    ) -> Tuple[pd.DataFrame, Dict[int, Dict[str, Any]], Dict[int, List[Dict[str, Any]]]]:
        # Atomic-stage ordering matters: normalise first, then enrichment, then
        # structured IP recovery, then profiling, then rule evaluation. Later
        # steps assume earlier canonical fields already exist.
        if enforce_required_fields:
            out = self.ensure_required_fields(out)

        out = self._apply_schema_aliases(out)
        out = self._extract_windows_auth_fields(out)
        out = self._extract_ssh_auth_fields(out)
        out = self._apply_normalisation(out)
        out = self._derive_pivot_destination_fields(out)

        if av_csv_path:
            out = self._apply_hash_enrichment_csv(out, av_csv_path, hash_col="sha256_hash", csv_hash_col="sha256")
        if luhn_csv_path:
            out = self._apply_hash_enrichment_csv(out, luhn_csv_path, hash_col="sha256_hash", csv_hash_col="sha256")

        for _col in ("av_hit", "luhn_hit"):
            if _col in out.columns:
                out[_col] = out[_col].astype("boolean").fillna(False).astype(bool)

        if nsrl_cache_df is not None:
            out = self._apply_nsrl_enrichment_from_cache(out, nsrl_cache_df, hash_col="sha256_hash")
        elif nsrl_parquet_path:
            nsrl_cache_df = _make_nsrl_cache_descriptor(nsrl_parquet_path)
            out = self._apply_nsrl_enrichment_from_cache(out, nsrl_cache_df, hash_col="sha256_hash")

        out = self._recover_ip_address(out)
        # Recovery can populate a configured source used by later coalesces.
        # Re-running the small declarative normalisation pipeline avoids an
        # engine-owned allowlist of output names.
        out = self._apply_normalisation(out)
        self._materialise_normalised_web_features(out)

        if "yara_match" not in out.columns:
            out["yara_match"] = None
        out["yara_match_count"] = normalise_yara_match_count_series(out["yara_match"])

        ip_recovery_field = self.canonicalisation_policy.ip_recovery.output_field
        if geoip_city_db and geoip_asn_db and ip_recovery_field in out.columns:
            geo_df = build_geoip_enrichment_table(
                out,
                geoip_city_db,
                geoip_asn_db,
                ip_field=ip_recovery_field,
                output_fields=self.geoip_enrichment_policy.output_fields,
            )
            geo_df = geo_df.set_index(ip_recovery_field)
            overlap = [c for c in geo_df.columns if c in out.columns]
            if overlap:
                out = out.drop(columns=overlap)
            out = out.join(geo_df, on=ip_recovery_field)

        if apply_profiling and self.profiling_policy.enabled:
            out = self._apply_hour_of_week_profiling(out, profile_manifest=profile_manifest)

        try:
            signal_map, explain_map = self._eval_atomic_rules_sparse(out)
        except Exception:
            logger.exception("Atomic stage: vectorized rule evaluation failed; falling back to legacy tuple evaluation")
            signal_map, explain_map = self._eval_atomic_rules_sparse_legacy(out)
        self._apply_web_request_classifier_sparse(out, signal_map, explain_map)
        self._apply_canonical_auth_signals_sparse(out, signal_map, explain_map)
        self._derive_execution_context_signals_sparse(out, signal_map, explain_map)

        self._inject_av_signal_sparse(out, signal_map, explain_map)
        self._inject_yara_signal_sparse(out, signal_map, explain_map)
        self._apply_policy_signal_gates_sparse(
            out,
            signal_map,
            explain_map,
            stage="atomic",
        )
        if apply_profiling and self.profiling_policy.enabled:
            self._inject_profile_base_signals_sparse(
                out, signal_map, explain_map
            )
        out["chronosift_score"] = self._score_signal_map_sparse(
            len(out), signal_map, index=out.index
        )
        out.attrs.setdefault("chronosift_sparse", {})
        out.attrs["chronosift_sparse"]["signal_map"] = signal_map
        out.attrs["chronosift_sparse"]["explain_map"] = explain_map
        return out, signal_map, explain_map

    def apply_atomic(
        self,
        df: pd.DataFrame,
        apply_profiling: bool = True,
        enforce_required_fields: bool = True,
        geoip_city_db: Optional[str] = None,
        geoip_asn_db: Optional[str] = None,
        av_csv_path: Optional[str] = None,
        luhn_csv_path: Optional[str] = None,
        nsrl_parquet_path: Optional[str] = None,
        nsrl_cache_df: Optional[pd.DataFrame] = None,
        materialise_event_columns: bool = False,
        profile_manifest: Optional[Dict[str, Any]] = None,
    ) -> pd.DataFrame:
        logger.info("Atomic stage: validating input frame")
        if not isinstance(df.index, pd.DatetimeIndex):
            raise ValueError("DataFrame index must be a DatetimeIndex.")
        if df.index.hasnans:
            raise ValueError(
                "DataFrame index contains NaT values. Drop rows with invalid timestamps "
                "before calling ChronoSiftEngine.apply_atomic()."
            )
        df = _stable_sort_datetime_frame(df)
        out = df
        logger.info("Atomic stage: evaluating atomic rules and enrichment")
        out, signal_map, explain_map = self._run_atomic_sparse(
            out,
            apply_profiling=apply_profiling,
            enforce_required_fields=enforce_required_fields,
            geoip_city_db=geoip_city_db,
            geoip_asn_db=geoip_asn_db,
            av_csv_path=av_csv_path,
            luhn_csv_path=luhn_csv_path,
            nsrl_parquet_path=nsrl_parquet_path,
            nsrl_cache_df=nsrl_cache_df,
            profile_manifest=profile_manifest,
        )
        if materialise_event_columns:
            logger.info("Atomic stage: materialising sparse event columns")
            self._materialise_sparse_event_columns(out, signal_map, explain_map)
        logger.info("Atomic stage: complete")
        return out

    def apply_contextual(
        self,
        df: pd.DataFrame,
        apply_temporal: bool = True,
        apply_profiling: bool = True,
        materialise_event_columns: bool = True,
        file_hit_manifest: Optional[Dict[str, Any]] = None,
        impossible_travel_state: Optional[Dict[tuple, Dict[str, Any]]] = None,
    ) -> pd.DataFrame:
        logger.info("Contextual stage: loading sparse state")
        signal_map = ((df.attrs.get("chronosift_sparse", {}) or {}).get("signal_map", {}) or {})
        explain_map = ((df.attrs.get("chronosift_sparse", {}) or {}).get("explain_map", {}) or {})

        self._apply_non_temporal_contextual_sparse(
            df,
            signal_map,
            explain_map,
            file_hit_manifest=file_hit_manifest,
        )

        if apply_temporal:
            self._apply_temporal_contextual_sparse(
                df,
                signal_map,
                explain_map,
                impossible_travel_state=impossible_travel_state,
            )

        self._apply_contextual_postprocessing_sparse(
            df,
            signal_map,
            explain_map,
            apply_profiling=apply_profiling,
        )

        logger.info("Contextual stage: scoring contextual output")
        df["chronosift_score"] = self._score_signal_map_sparse(
            len(df),
            signal_map,
            index=df.index,
            score_multipliers=(
                self._profile_score_amplifier_values(df)
                if apply_profiling
                else None
            ),
        )

        if materialise_event_columns:
            logger.info("Contextual stage: materialising sparse event columns")
            self._materialise_sparse_event_columns(df, signal_map, explain_map)
        else:
            df.attrs.setdefault("chronosift_sparse", {})
            df.attrs["chronosift_sparse"]["signal_map"] = signal_map
            df.attrs["chronosift_sparse"]["explain_map"] = explain_map
        logger.info("Contextual stage: complete")
        return df

    def _contextual_required_columns(
        self,
        apply_temporal: bool = True,
        apply_profiling: bool = True,
    ) -> List[str]:
        """Return the minimal column subset needed for contextual processing."""
        cols: Set[str] = set()

        cols.update({
            "filename",
            "relative_path",
            "display_name",
            "pathspec",
            "link_target",
            "message",
            "xml_string",
            "parser",
            "hostname",
            "timestamp_desc",
            "is_allocated",
            "file_size",
            "file_ext",
            "actor_cmd",
            "command_line",
            "event_identifier",
            "target_user_name",
            "group_name",
            "member_name",
            "share_name",
            "share_local_path",
            "relative_target_name",
            "provider_name",
            "workstation_name",
            "authentication_package",
            "url",
            "actor_url",
            "http_request",
            "http_headers",
            "http_request_user_agent",
            "http_request_body",
            "http_content_disposition",
            "http_upload_filename",
            "http_upload_content_type",
            "http_upload_sha256",
            "http_request_content_length",
            "src_ip",
            "dst_ip",
            "actor_principal",
            "auth_protocol",
            "auth_outcome",
            "logon_type",
            "av_hit",
            "luhn_hit",
            "yara_match_count",
        })

        if apply_profiling and self.profiling_policy.enabled:
            cols.update({
                self.profiling_policy.activity_deficit_signal,
                self.profiling_policy.hour_of_week_field,
            })

        if self.trust_dampening_policy.enabled:
            cols.update({
                self.trust_dampening_policy.principal_field,
                self.trust_dampening_policy.ip_field,
                self.trust_dampening_policy.asn_field,
            })

        if apply_temporal:
            for tr in self.temporal_rules:
                for k in tr.key_by:
                    if k:
                        cols.add(k)
                if tr.field:
                    cols.add(tr.field)
            for definition in self.detector_policy.definitions(
                stage="temporal",
                enabled_only=True,
            ):
                cols.update(_detector_definition_required_fields(definition))

        for definition in self.detector_policy.definitions(
            stage="contextual",
            enabled_only=True,
        ):
            cols.update(_detector_definition_required_fields(definition))

        return sorted(c for c in cols if c)

    def _temporal_required_columns(self) -> List[str]:
        """Return the minimal column subset needed for stateful temporal processing."""
        cols: Set[str] = set()
        for tr in self.temporal_rules:
            for k in tr.key_by:
                if k:
                    cols.add(k)
            if tr.field:
                cols.add(tr.field)
        for definition in self.detector_policy.definitions(
            stage="temporal",
            enabled_only=True,
        ):
            cols.update(_detector_definition_required_fields(definition))
        return sorted(c for c in cols if c)

    def _apply_non_temporal_contextual_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
        apply_profiling: Optional[bool] = None,
        file_hit_manifest: Optional[Dict[str, Any]] = None,
        retain_zero_weight_lifecycle_signals: bool = True,
    ) -> None:
        contextual_cache: Dict[Tuple[Any, ...], np.ndarray] = {}
        logger.info("Contextual stage: applying file lifecycle signals")
        self._apply_file_lifecycle_signals_sparse(
            df,
            signal_map,
            explain_map,
            contextual_cache=contextual_cache,
            retain_zero_weight_generic_signals=retain_zero_weight_lifecycle_signals,
        )
        logger.info("Contextual stage: applying MFT timestomping detection")
        self._apply_timestomping_detection_sparse(
            df, signal_map, explain_map, contextual_cache=contextual_cache
        )
        logger.info("Contextual stage: applying persistence and system-change signals")
        self._apply_persistence_and_config_signals_sparse(
            df, signal_map, explain_map, contextual_cache=contextual_cache
        )
        logger.info("Contextual stage: applying systemd persistence policy")
        self._apply_systemd_service_persistence_sparse(
            df, signal_map, explain_map, contextual_cache=contextual_cache
        )

        logger.info("Contextual stage: propagating referenced-file hit signals")
        self._apply_referenced_file_hit_signals_sparse(df, signal_map, explain_map, hit_manifest=file_hit_manifest)

        logger.info("Contextual stage: applying evidence-qualified web ATT&CK mapping")
        self._apply_web_attack_mapping_sparse(df, signal_map, explain_map)

        logger.info("Contextual stage: applying configured web-shell artefact policy")
        self._apply_webshell_artifact_policy_sparse(
            df, signal_map, explain_map, contextual_cache=contextual_cache
        )

        logger.info("Contextual stage: applying direct dead-box ATT&CK signals")
        self._apply_deadbox_direct_signals_sparse(
            df, signal_map, explain_map, contextual_cache=contextual_cache
        )
        self._apply_policy_signal_projections_sparse(
            signal_map,
            explain_map,
            stage="contextual",
        )
        self._apply_policy_signal_gates_sparse(
            df, signal_map, explain_map, contextual_cache=contextual_cache
        )
        self._apply_ordered_signal_adjustments_sparse(
            df,
            signal_map,
            explain_map,
            contextual_cache,
            detector_id="contextual_signal_adjustments",
        )

    def _apply_contextual_postprocessing_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
        *,
        apply_profiling: bool,
    ) -> None:
        # Trust changes signal values first. The validated profile then explains
        # the single event-score amplifier that scoring applies to the complete
        # post-trust signal map.
        self._apply_trust_dampening_sparse(df, signal_map, explain_map)
        if apply_profiling and self.profiling_policy.enabled:
            logger.info("Contextual stage: applying validated profile amplifier")
            self._append_profile_score_amplifier_explanations_sparse(
                df, signal_map, explain_map
            )

    def _apply_temporal_contextual_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
        geo_continuity_state: Optional[Dict[tuple, Dict[str, Any]]] = None,
        impossible_travel_state: Optional[Dict[tuple, Dict[str, Any]]] = None,
        ip_continuity_state: Optional[Dict[tuple, Dict[str, Any]]] = None,
    ) -> None:
        if self.detector_policy.geographic_continuity.enabled:
            logger.info("Contextual stage: applying geo continuity detection")
            self._apply_geo_continuity_sparse(
                df,
                signal_map,
                explain_map,
                carried_state=geo_continuity_state,
            )

        if self.detector_policy.impossible_travel.enabled:
            logger.info("Contextual stage: applying impossible travel detection")
            self._apply_impossible_travel_sparse(
                df,
                signal_map,
                explain_map,
                carried_last=impossible_travel_state,
            )

        if self.detector_policy.ip_scope_continuity.enabled:
            logger.info("Contextual stage: applying IP-scope continuity detection")
            self._apply_private_ip_continuity_sparse(
                df, signal_map, explain_map,
                carried_last=ip_continuity_state,
            )

        if self.temporal_rules:
            logger.info("Contextual stage: applying temporal rules")
            self._apply_temporal_rules_sparse(df, signal_map, explain_map)

        logger.info("Contextual stage: applying dead-box temporal composites")
        self._apply_deadbox_temporal_composites_sparse(df, signal_map, explain_map)
        self._apply_policy_signal_projections_sparse(
            signal_map,
            explain_map,
            stage="temporal",
        )

    def _temporal_candidate_reduction_safe(self) -> bool:
        if self.detector_policy.ip_scope_continuity.enabled:
            return False
        for tr in self.temporal_rules:
            if tr.mode in {"first_seen_value", "change_detected"}:
                return False
        return True

    def _enabled_temporal_policy_detectors(self) -> Tuple[Tuple[str, Any], ...]:
        return tuple(
            (definition.detector_id, definition.payload)
            for definition in self.detector_policy.definitions(
                stage="temporal",
                enabled_only=True,
            )
        )

    def _temporal_candidate_actor_columns(self) -> List[str]:
        cols: List[str] = list(dict.fromkeys((
            "actor_principal",
            "src_ip",
            self.canonicalisation_policy.ip_recovery.output_field,
        )))
        for policy in (
            self.detector_policy.geographic_continuity,
            self.detector_policy.impossible_travel,
            self.detector_policy.ip_scope_continuity,
        ):
            if not policy.enabled:
                continue
            for key_field in policy.key_fields:
                if key_field not in cols:
                    cols.append(key_field)
        for tr in self.temporal_rules:
            for k in tr.key_by:
                ks = str(k).strip()
                if ks and ks not in cols:
                    cols.append(ks)
        return cols

    def _temporal_candidate_base_mask(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
    ) -> pd.Series:
        base = pd.Series(False, index=df.index, dtype=bool)
        needed_signals: Set[str] = set()
        for tr in self.temporal_rules:
            if tr.mode == "cooccur":
                needed_signals.update(
                    need.signal for need in tr.cooccur_all if getattr(need, "signal", None)
                )
            elif tr.mode == "sequence":
                needed_signals.update(
                    step.signal for step in tr.sequence if getattr(step, "signal", None)
                )

        for _, policy in self._enabled_temporal_policy_detectors():
            needed_signals.update(policy.source_signals)
            needed_signals.update(policy.target_signals)

        for pos, signals in signal_map.items():
            if not (0 <= pos < len(df)):
                continue
            if not isinstance(signals, dict) or not signals:
                continue

            include = False
            if needed_signals:
                for name, value in signals.items():
                    if name not in needed_signals:
                        continue
                    if isinstance(value, (int, float)):
                        if float(value) > 0:
                            include = True
                            break
                    elif not _is_null(value) and bool(value):
                        include = True
                        break

            if include:
                base.iat[pos] = True

        return base

    def _temporal_candidate_window(self, base_window: Union[str, timedelta]) -> timedelta:
        td = parse_lookback(base_window) if isinstance(base_window, str) else base_window
        for tr in self.temporal_rules:
            if tr.mode in {"cooccur", "sequence"} and tr.lookback > td:
                td = tr.lookback
        for _, policy in self._enabled_temporal_policy_detectors():
            if policy.lookback > td:
                td = policy.lookback
        return td

    def apply(
        self,
        df: pd.DataFrame,
        apply_temporal: bool = True,
        apply_profiling: bool = True,
        enforce_required_fields: bool = True,
        geoip_city_db: Optional[str] = None,
        geoip_asn_db: Optional[str] = None,
        av_csv_path: Optional[str] = None,
        luhn_csv_path: Optional[str] = None,
        nsrl_parquet_path: Optional[str] = None,
        nsrl_cache_df: Optional[pd.DataFrame] = None,
        materialise_event_columns: bool = True,
        profile_manifest: Optional[Dict[str, Any]] = None,
        file_hit_manifest: Optional[Dict[str, Any]] = None,
    ) -> pd.DataFrame:
        """
        Apply ChronoSift to a timeline DataFrame.

        Performance note
        ----------------
        ChronoSift operates in-place on the supplied DataFrame. During processing,
        event signals and explanations are held internally in sparse form.
        """
        out = self.apply_atomic(
            df,
            apply_profiling=apply_profiling,
            enforce_required_fields=enforce_required_fields,
            geoip_city_db=geoip_city_db,
            geoip_asn_db=geoip_asn_db,
            av_csv_path=av_csv_path,
            luhn_csv_path=luhn_csv_path,
            nsrl_parquet_path=nsrl_parquet_path,
            nsrl_cache_df=nsrl_cache_df,
            materialise_event_columns=False,
            profile_manifest=profile_manifest,
        )

        out = self.apply_contextual(
            out,
            apply_temporal=apply_temporal,
            apply_profiling=apply_profiling,
            materialise_event_columns=materialise_event_columns,
            file_hit_manifest=file_hit_manifest,
        )

        out.attrs.setdefault("chronosift_metadata", {})
        out.attrs["chronosift_metadata"]["geoip"] = {
            "city": _geoip_db_metadata(geoip_city_db),
            "asn": _geoip_db_metadata(geoip_asn_db),
        }
        out.attrs["chronosift_metadata"]["enrichment"] = {
            "av_csv_path": av_csv_path,
            "luhn_csv_path": luhn_csv_path,
            "nsrl_parquet_path": nsrl_parquet_path,
        }

        return out

    def _sparse_signal_dict(self, signal_map: Dict[int, Dict[str, Any]], row_i: int) -> Dict[str, Any]:
        return signal_map.setdefault(row_i, {})

    def _sparse_explain_list(self, explain_map: Dict[int, List[Dict[str, Any]]], row_i: int) -> List[Dict[str, Any]]:
        return explain_map.setdefault(row_i, [])

    def _infer_explain_evidence_type(self, item: Dict[str, Any]) -> str:
        explicit = _safe_str(item.get("evidence_type")).strip().lower()
        if explicit:
            return explicit
        evidence = item.get("evidence")
        if isinstance(evidence, dict):
            evidence_type = _safe_str(evidence.get("evidence_type")).strip().lower()
            if evidence_type:
                return evidence_type

        rule_id = _safe_str(item.get("rule_id")).strip()
        if rule_id in self.temporal_emit_signals:
            return "temporal"
        if (
            rule_id == self.profiling_policy.activity_deficit_explanation.rule_id
            or rule_id == self.profiling_policy.quiet_explanation.rule_id
            or rule_id == self.profile_amplifier_rule_id
        ):
            return "profiling"
        if rule_id == self.trust_dampening_policy.rule_id:
            return "contextual"
        return "direct"

    def _explain_signal_names(self, item: Dict[str, Any]) -> List[str]:
        explicit = item.get("signals")
        if isinstance(explicit, str) and explicit.strip():
            return [explicit.strip()]
        if isinstance(explicit, (list, tuple)):
            out: List[str] = []
            for sig in explicit:
                sig_s = str(sig).strip()
                if sig_s:
                    out.append(sig_s)
            if out:
                return out

        evidence = item.get("evidence")
        if isinstance(evidence, dict):
            target_signal = _safe_str(evidence.get("target_signal")).strip()
            if target_signal:
                return [target_signal]
            evidence_signals = evidence.get("signals")
            if isinstance(evidence_signals, str) and evidence_signals.strip():
                return [s for s in (part.strip() for part in evidence_signals.split(",")) if s]

        rule_id = _safe_str(item.get("rule_id")).strip()
        if rule_id in self.rule_emit_signals:
            return list(self.rule_emit_signals[rule_id])
        if rule_id in self.temporal_emit_signals:
            return list(self.temporal_emit_signals[rule_id])
        if rule_id == self.profiling_policy.activity_deficit_explanation.rule_id:
            return [self.profiling_policy.activity_deficit_signal]
        if rule_id == self.profiling_policy.quiet_explanation.rule_id:
            return [self.profiling_policy.quiet_signal]

        lower_rule = rule_id.lower()
        if lower_rule in self.weights:
            return [lower_rule]
        return []

    def _normalise_explain_item(
        self,
        item: Dict[str, Any],
        row_i: int,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        canonical_actor_values: Any = None,
        canonical_src_ip_values: Any = None,
    ) -> Dict[str, Any]:
        # Explain items are materialised late in the pipeline and can be numerous
        # on hot partitions. A shallow copy of the top-level item plus any
        # directly embedded container fields preserves output isolation without
        # the full cost of deepcopy on every record.
        out = dict(item)
        if isinstance(out.get("evidence"), dict):
            out["evidence"] = dict(out["evidence"])
        if isinstance(out.get("signals"), list):
            out["signals"] = list(out["signals"])
        # Arrow nested encoding requires stable scalar types for the same field
        # path. Normalise file_size here so one malformed row cannot force a
        # per-subchunk JSON fallback late in write-out.
        if "file_size" in out:
            out["file_size"] = _normalise_integral_metadata_value(out.get("file_size"))
        evidence = out.get("evidence")
        if isinstance(evidence, dict) and "file_size" in evidence:
            evidence["file_size"] = _normalise_integral_metadata_value(evidence.get("file_size"))
        out["evidence_type"] = self._infer_explain_evidence_type(out)

        canonical_actor = None
        if canonical_actor_values is not None and 0 <= row_i < len(canonical_actor_values):
            canonical_actor = canonical_actor_values[row_i]
        elif "actor_principal" in df.columns and 0 <= row_i < len(df):
            actor_val = df["actor_principal"].iloc[row_i]
            if not _is_null(actor_val):
                actor_s = _safe_str(actor_val).strip()
                canonical_actor = actor_s or None

        canonical_src_ip = None
        if canonical_src_ip_values is not None and 0 <= row_i < len(canonical_src_ip_values):
            canonical_src_ip = canonical_src_ip_values[row_i]
        elif 0 <= row_i < len(df):
            src_val = None
            if "src_ip" in df.columns:
                src_val = df["src_ip"].iloc[row_i]
            else:
                ip_field = self.canonicalisation_policy.ip_recovery.output_field
                if ip_field in df.columns:
                    src_val = df[ip_field].iloc[row_i]
            if not _is_null(src_val):
                src_s = _safe_str(src_val).strip()
                canonical_src_ip = src_s or None
        out["canonical_actor"] = canonical_actor
        out["canonical_src_ip"] = canonical_src_ip

        signal_names = self._explain_signal_names(out)
        row_signals = signal_map.get(row_i, {}) or {}
        signal_details: List[Dict[str, Any]] = []
        total_weight = 0.0
        total_value = 0.0
        total_contribution = 0.0
        for signal_name in signal_names:
            sig_key = str(signal_name).strip()
            if not sig_key:
                continue
            sig_val = row_signals.get(sig_key)
            if not isinstance(sig_val, (int, float)):
                continue
            weight = float(self.weights.get(sig_key.lower(), 0.0))
            value = float(sig_val)
            contribution = value * weight
            signal_details.append({
                "name": sig_key,
                "signal_weight": weight,
                "signal_value": value,
                "score_contribution": contribution,
            })
            total_weight += weight
            total_value += value
            total_contribution += contribution

        out["signal_weight"] = total_weight
        out["signal_value"] = total_value
        out["score_contribution"] = total_contribution
        if signal_details:
            out["signals"] = signal_details
        return out

    def _materialise_sparse_event_columns(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
        materialise_explain_columns: bool = True,
    ) -> None:
        if getattr(df, "attrs", None):
            # Sparse state is passed in explicitly here, so keeping attrs on the
            # frame only creates avoidable propagation work while we assign the
            # nested review columns on hot partitions.
            df.attrs = {}

        n = len(df)
        hour_contrib = self._activity_deficit_contribution_values(n, signal_map)
        canonical_actor_values: Optional[np.ndarray] = None
        if "actor_principal" in df.columns:
            actor_series = df["actor_principal"].astype("string").fillna("").str.strip()
            actor_series = actor_series.mask(actor_series.str.lower().isin(PLACEHOLDER_STRINGS), "")
            canonical_actor_values = actor_series.where(actor_series.ne(""), other=None).to_numpy(copy=False)

        canonical_src_ip_values: Optional[np.ndarray] = None
        recovered_ip_field = self.canonicalisation_policy.ip_recovery.output_field
        src_field = (
            "src_ip"
            if "src_ip" in df.columns
            else (recovered_ip_field if recovered_ip_field in df.columns else None)
        )
        if src_field is not None:
            src_series = df[src_field].astype("string").fillna("").str.strip()
            src_series = src_series.mask(src_series.str.lower().isin(PLACEHOLDER_STRINGS), "")
            canonical_src_ip_values = src_series.where(src_series.ne(""), other=None).to_numpy(copy=False)

        if signal_map:
            signals_col: List[Optional[Dict[str, Any]]] = [None] * n
            for i, sig in signal_map.items():
                if 0 <= i < n:
                    signals_col[i] = dict(sig)
            df["chronosift_signals"] = signals_col
        else:
            _delete_columns_inplace(df, ["chronosift_signals"])

        activity_deficit_score_field = self.profiling_policy.activity_deficit_score_field
        if hour_contrib is not None:
            df[activity_deficit_score_field] = hour_contrib
        else:
            _delete_columns_inplace(df, [activity_deficit_score_field])

        if materialise_explain_columns:
            if explain_map:
                explain_col: List[Optional[List[Dict[str, Any]]]] = [None] * n
                for i, expl in explain_map.items():
                    if 0 <= i < n:
                        explain_col[i] = [
                            self._normalise_explain_item(
                                item,
                                i,
                                df,
                                signal_map,
                                canonical_actor_values=canonical_actor_values,
                                canonical_src_ip_values=canonical_src_ip_values,
                            )
                            for item in expl
                        ]

                df["chronosift_explain"] = explain_col
            else:
                _delete_columns_inplace(df, ["chronosift_explain"])

        else:
            _delete_columns_inplace(df, ["chronosift_explain"])

    def _activity_deficit_values(self, df: Optional[pd.DataFrame]) -> Optional[Any]:
        activity_deficit_signal = self.profiling_policy.activity_deficit_signal
        if df is None or activity_deficit_signal not in df.columns:
            return None
        hour_series = df[activity_deficit_signal]
        if pd.api.types.is_numeric_dtype(hour_series.dtype):
            try:
                return hour_series.to_numpy(dtype="float64", na_value=0.0, copy=False)
            except TypeError:
                pass
            values = hour_series.to_numpy(copy=False)
            if str(getattr(values, "dtype", "")) == "float64":
                if pd.isna(values).any():
                    values[pd.isna(values)] = 0.0
                return values
            return hour_series.fillna(0.0).astype("float64", copy=False).to_numpy(copy=False)
        return pd.to_numeric(hour_series, errors="coerce").fillna(0.0).to_numpy(dtype="float64", copy=False)

    def _profile_score_amplifier_values(
        self, df: Optional[pd.DataFrame]
    ) -> Optional[Any]:
        policy = self.profiling_policy
        if not policy.enabled or not policy.score_amplifier.enabled:
            return None
        manifest = (
            (df.attrs.get("_chronosift_profile_manifest", {}) or {})
            if df is not None
            else {}
        )
        validation = manifest.get("validation", {}) or {}
        if not bool(validation.get("accepted", False)):
            return None
        activity_deficits = self._activity_deficit_values(df)
        if activity_deficits is None:
            return None
        return 1.0 + np.clip(
            np.nan_to_num(
                activity_deficits,
                nan=0.0,
                posinf=0.0,
                neginf=0.0,
            ),
            0.0,
            1.0,
        )

    def _activity_deficit_contribution_values(
        self,
        n_rows: int,
        signal_map: Dict[int, Dict[str, Any]],
    ) -> Optional[Any]:
        policy = self.profiling_policy
        hour_weight = float(self.weights.get(policy.activity_deficit_signal, 0.0))
        if (
            hour_weight == 0.0
            or not policy.enabled
            or not policy.emit_activity_deficit_signal
        ):
            return None
        contributions = np.zeros(n_rows, dtype=np.float64)
        found = False
        for row_i, signals in signal_map.items():
            if not (0 <= row_i < n_rows) or not isinstance(signals, dict):
                continue
            raw_value = signals.get(policy.activity_deficit_signal)
            if not isinstance(raw_value, (int, float)) or _is_null(raw_value):
                continue
            contributions[row_i] = float(raw_value) * hour_weight
            found = True
        return contributions if found else None

    def _score_signal_map_sparse(
        self,
        n_rows: int,
        signal_map: Dict[int, Dict[str, Any]],
        index=None,
        score_multipliers: Optional[Any] = None,
    ) -> pd.Series:
        scores = [0.0] * n_rows
        for row_i, signals in signal_map.items():
            scores[row_i] = self._score_signals(signals)
        if index is None:
            index = range(n_rows)
        score_series = pd.Series(scores, index=index, dtype="float64")
        if score_multipliers is not None:
            factors = np.asarray(score_multipliers, dtype=np.float64)
            if len(factors) != n_rows:
                raise ValueError(
                    "profile score amplifier length does not match score rows"
                )
            factors = np.clip(
                np.nan_to_num(factors, nan=1.0, posinf=1.0, neginf=1.0),
                1.0,
                2.0,
            )
            score_series = score_series * factors

        return score_series.clip(upper=self.max_event_score)

    def _apply_referenced_file_hit_signals_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
        hit_manifest: Optional[Dict[str, Any]] = None,
    ) -> None:
        policy = self.detector_policy.referenced_file_correlation
        upload_policy = self.detector_policy.web_request_classification.upload
        if not policy.enabled:
            return
        _validate_file_hit_manifest_compatibility(
            hit_manifest,
            expected_clamav_policy_digest=(
                self.detector_policy.clamav_classification.policy_digest
            ),
            expected_yara_policy_digest=(
                self.detector_policy.yara_classification.policy_digest
            ),
            expected_correlation_policy_digest=policy.policy_digest,
        )
        if policy.current_path_field not in df.columns and hit_manifest is None:
            return

        if hit_manifest is not None:
            hit_map = (hit_manifest.get("hit_map", {}) or {})
            basename_map = (hit_manifest.get("basename_map", {}) or {})
            web_path_map = (hit_manifest.get("web_path_map", {}) or {})
            web_basename_map = (hit_manifest.get("web_basename_map", {}) or {})
            web_identity_map = (hit_manifest.get("web_identity_map", {}) or {})
            web_basename_identity_map = (hit_manifest.get("web_basename_identity_map", {}) or {})
            hash_hit_map = (hit_manifest.get("hash_hit_map", {}) or {})
            hash_identity_map = (hit_manifest.get("hash_identity_map", {}) or {})
        else:
            hit_map = {}
            basename_map = {}
            web_path_map = {}
            web_basename_map = {}
            web_identity_map = {}
            web_basename_identity_map = {}
            hash_hit_map = {}
            hash_identity_map = {}

            current_filenames = _normalise_reference_path_series(
                df[policy.current_path_field]
            ).to_numpy(dtype=object, copy=False)
            _av_mask = df["av_hit"].astype(bool, errors="ignore").fillna(False).to_numpy() if "av_hit" in df.columns else np.zeros(len(df), dtype=bool)
            _luhn_mask = df["luhn_hit"].astype(bool, errors="ignore").fillna(False).to_numpy() if "luhn_hit" in df.columns else np.zeros(len(df), dtype=bool)
            _ymc_arr = pd.to_numeric(df["yara_match_count"], errors="coerce").fillna(0).to_numpy() if "yara_match_count" in df.columns else np.zeros(len(df))
            _yara_mask = _ymc_arr > 0
            # Only iterate rows with at least one hit type
            _any_hit = _av_mask | _luhn_mask | _yara_mask
            for i in np.flatnonzero(_any_hit):
                fname = current_filenames[i]
                if not fname:
                    continue
                tags: Set[str] = set()
                if _av_mask[i]:
                    tags.add("av")
                if _luhn_mask[i]:
                    tags.add("luhn")
                if _yara_mask[i]:
                    tags.add("yara")
                if tags:
                    hit_map.setdefault(fname, set()).update(tags)
                    base = _basename_from_reference_path(fname)
                    if base:
                        basename_map.setdefault(base, set()).update(tags)

        if not hit_map and not web_path_map and not hash_hit_map:
            return

        current_filenames = (
            _normalise_reference_path_series(df[policy.current_path_field]).to_numpy(dtype=object, copy=False)
            if policy.current_path_field in df.columns
            else np.full(len(df), None, dtype=object)
        )
        messages = _column_values_or_none(df, policy.message_field)
        parser_vals = _column_values_or_none(df, policy.parser_field)
        http_request_vals = _column_values_or_none(df, policy.request_field)
        url_vals = _column_values_or_none(df, policy.url_field)
        response_code_vals = _column_values_or_none(df, policy.response_code_field)
        response_bytes_vals = _column_values_or_none(df, policy.response_bytes_field)
        upload_names_vals = _column_values_or_none(df, policy.upload_names_field)
        upload_hashes_vals = _column_values_or_none(df, policy.upload_hashes_field)
        upload_outcome_vals = _column_values_or_none(df, policy.upload_outcome_field)

        # Collect execution-context columns that may reference hit files.
        # These cover scheduled tasks, services, prefetch, amcache, process
        # creation, and command lines — all of which may reference a file
        # that carries AV/Luhn/YARA hits independently of the message field.
        exec_ctx_text_vals: List[np.ndarray] = []
        exec_ctx_direct_vals: List[np.ndarray] = []
        for col in policy.execution_text_fields:
            if col in df.columns:
                exec_ctx_text_vals.append(df[col].to_numpy(copy=False))
                exec_ctx_direct_vals.append(_normalise_reference_path_series(df[col]).to_numpy(dtype=object, copy=False))
        for col in policy.execution_path_fields:
            if col in df.columns:
                exec_ctx_direct_vals.append(_normalise_reference_path_series(df[col]).to_numpy(dtype=object, copy=False))

        for i in range(len(df)):
            msg = messages[i]
            current_fname = current_filenames[i]
            # Extract referenced paths from message text.
            refs = _extract_referenced_paths_from_text(msg)
            ref_set = set(refs)
            refs = list(refs)
            # Also extract from execution-context fields so that prefetch,
            # scheduled tasks, services, and process creation events can
            # propagate AV/Luhn/YARA hits from the files they reference.
            for vals in exec_ctx_text_vals:
                for rp in _extract_referenced_paths_from_text(vals[i]):
                    if rp not in ref_set:
                        ref_set.add(rp)
                        refs.append(rp)
            for direct_vals in exec_ctx_direct_vals:
                # For columns that ARE a path (not free-text), also do a
                # direct normalised lookup so single-token filenames like
                # "malware.exe" are caught even without a directory prefix.
                direct = direct_vals[i]
                if direct and direct not in ref_set:
                    ref_set.add(direct)
                    refs.append(direct)
            matched: Dict[str, List[str]] = {"yara": [], "av": [], "luhn": []}
            for rp in refs:
                if policy.exclude_self_reference and current_fname and rp == current_fname:
                    continue
                tags = hit_map.get(rp)
                if (
                    not tags
                    and policy.basename_fallback == "relative_only"
                    and (rp.startswith("./") or rp.startswith("../"))
                ):
                    base = _basename_from_reference_path(rp)
                    tags = basename_map.get(base)
                if not tags:
                    continue
                for tag in tags:
                    matched[tag].append(rp)

            http_method = ""
            http_path = ""
            canonical_web_path = None
            web_access_tags: Set[str] = set()
            web_upload_tags: Set[str] = set()
            web_access_identity = _empty_file_identity()
            web_upload_identity = _empty_file_identity()
            upload_name_tags: Set[str] = set()
            upload_hash_tags: Set[str] = set()
            upload_name_identity = _empty_file_identity()
            upload_hash_identity = _empty_file_identity()
            upload_name_paths: Dict[str, List[str]] = {
                "yara": [], "av": [], "luhn": [],
            }
            upload_hash_paths: Dict[str, List[str]] = {
                "yara": [], "av": [], "luhn": [],
            }
            parser = _safe_str(parser_vals[i]).strip().lower()
            request_semantics = (
                bool(_safe_str(http_request_vals[i]).strip())
                or bool(_safe_str(url_vals[i]).strip())
                or any(token in parser for token in policy.web_log_parser_tokens)
            )
            if (web_path_map or web_basename_map or hash_hit_map) and request_semantics:
                http_semantics = _extract_http_request_semantics(msg, http_request_vals[i], url_vals[i])
                http_method = _safe_str(http_semantics.get("method")).strip().upper()
                http_path = _safe_str(http_semantics.get("path")).strip()
                canonical_web_path = _canonical_web_request_path(http_path)
                if canonical_web_path:
                    web_path_key = canonical_web_path.casefold()
                    web_access_tags.update(web_path_map.get(web_path_key, set()) or set())
                    _merge_file_identity(web_access_identity, web_identity_map.get(web_path_key))
                    for tag in web_access_tags:
                        matched[tag].append(canonical_web_path)

                if http_method in policy.upload_methods and web_basename_map:
                    upload_names = [
                        value for value in _safe_str(upload_names_vals[i]).split("|") if value
                    ] or list(
                        _extract_http_upload_names(
                            msg,
                            http_request_vals[i],
                            url_vals[i],
                            http_path,
                            query_parameter_names=upload_policy.query_parameter_names,
                            filename_extension_admission=(
                                upload_policy.filename_extension_admission
                            ),
                        )
                    )
                    for upload_name in upload_names:
                        upload_key = upload_name.casefold()
                        name_tags = web_basename_map.get(upload_key, set()) or set()
                        upload_name_tags.update(name_tags)
                        _merge_file_identity(
                            upload_name_identity,
                            web_basename_identity_map.get(upload_key),
                        )
                        for tag in name_tags:
                            upload_name_paths[tag].append(f"upload:{upload_name}")
                if http_method in policy.upload_methods and hash_hit_map:
                    for upload_hash in _safe_str(upload_hashes_vals[i]).split("|"):
                        upload_hash = upload_hash.strip().upper()
                        if not upload_hash:
                            continue
                        hash_tags = hash_hit_map.get(upload_hash, set()) or set()
                        upload_hash_tags.update(hash_tags)
                        _merge_file_identity(
                            upload_hash_identity,
                            hash_identity_map.get(upload_hash),
                        )
                        for tag in hash_tags:
                            upload_hash_paths[tag].append(
                                f"upload-sha256:{upload_hash}"
                            )
                # A content hash identifies the uploaded bytes more precisely
                # than a basename. When at least one supplied hash resolves,
                # do not union potentially ambiguous name evidence into that
                # exact identity.
                if upload_hash_tags:
                    web_upload_tags = upload_hash_tags
                    web_upload_identity = upload_hash_identity
                    selected_upload_paths = upload_hash_paths
                else:
                    web_upload_tags = upload_name_tags
                    web_upload_identity = upload_name_identity
                    selected_upload_paths = upload_name_paths
                for tag, paths in selected_upload_paths.items():
                    matched[tag].extend(paths)

            if not any(matched.values()):
                continue

            sig = self._sparse_signal_dict(signal_map, i)
            expl = self._sparse_explain_list(explain_map, i)
            for tag, paths in matched.items():
                if not paths:
                    continue
                branch = policy.propagation.get(tag)
                if branch is None:
                    continue
                emission = policy.emissions_by_id[branch.emission_id]
                signal_name = emission.name
                sig[signal_name] = max(
                    float(sig.get(signal_name, 0.0) or 0.0),
                    emission.value,
                )
                all_evidence = {
                    "evidence_type": "propagated",
                    "signal_value": emission.value,
                    "target_filename": current_fname or "",
                    "source_path_count": len(sorted(set(paths))),
                    "referenced_paths": "|".join(sorted(set(paths))),
                    "message": _safe_str(msg)[:240],
                }
                expl.append({
                    "rule_id": emission.rule_id,
                    "description": emission.description,
                    "confidence": emission.confidence,
                    "evidence_type": policy.evidence_type,
                    "signals": [signal_name],
                    "evidence": {
                        name: all_evidence[name] for name in branch.evidence
                    },
                })

            if web_access_tags or web_upload_tags:
                response_code = _normalise_integral_metadata_value(response_code_vals[i])
                response_bytes = _normalise_integral_metadata_value(response_bytes_vals[i])
                successful_response = (
                    response_code is not None
                    and policy.success_status_minimum
                    <= response_code
                    < policy.success_status_maximum_exclusive
                )
                all_web_tags = web_access_tags | web_upload_tags
                combined_identity = _empty_file_identity()
                _merge_file_identity(combined_identity, web_access_identity)
                _merge_file_identity(combined_identity, web_upload_identity)
                combined_identity["hit_types"].update(all_web_tags)
                categories = sorted(combined_identity["av_categories"] | combined_identity["yara_categories"])
                rules = sorted(combined_identity["yara_rules"])
                families = sorted(combined_identity["av_families"])

                feature_values = {
                    "hit_types": "|".join(sorted(all_web_tags)),
                    "categories": "|".join(categories),
                    "rules": "|".join(rules),
                    "families": "|".join(families),
                }
                canonical_feature_fields = {
                    "hit_types": "chronosift_web_file_hit_types",
                    "categories": "chronosift_web_file_categories",
                    "rules": "chronosift_web_file_rules",
                    "families": "chronosift_web_file_families",
                }
                for role, value in feature_values.items():
                    for column in dict.fromkeys((
                        canonical_feature_fields[role],
                        policy.web_feature_fields[role],
                    )):
                        if column in df.columns:
                            df.iat[i, df.columns.get_loc(column)] = value or pd.NA

                for branch in policy.web_branches:
                    if branch.source == "access":
                        branch_tags = set(web_access_tags)
                        branch_identity = _normalise_file_identity(web_access_identity)
                    elif branch.source == "upload":
                        branch_tags = set(web_upload_tags)
                        branch_identity = _normalise_file_identity(web_upload_identity)
                    else:
                        branch_tags = set(all_web_tags)
                        branch_identity = _normalise_file_identity(combined_identity)
                    branch_identity["hit_types"].update(branch_tags)
                    branch_categories = (
                        branch_identity["av_categories"]
                        | branch_identity["yara_categories"]
                    )
                    if branch.hit_types and not (branch_tags & branch.hit_types):
                        continue
                    if branch.categories and not (branch_categories & branch.categories):
                        continue
                    if branch.methods and http_method not in branch.methods:
                        continue
                    if branch.response == "successful" and not successful_response:
                        continue

                    emission = policy.emissions_by_id[branch.emission_id]
                    sig[emission.name] = max(
                        float(sig.get(emission.name, 0.0) or 0.0),
                        emission.value,
                    )
                    serialised_identity = _serialise_file_identity(branch_identity)
                    all_evidence = {
                        "evidence_type": "web_file_identity",
                        "http_method": http_method,
                        "http_path": http_path[:240],
                        "canonical_web_path": canonical_web_path or "",
                        "http_response_code": response_code,
                        "http_response_bytes": response_bytes,
                        "upload_outcome": _safe_str(upload_outcome_vals[i]).strip(),
                        "file_hit_types": "|".join(sorted(branch_tags)),
                        "file_categories": "|".join(sorted(branch_categories)),
                        "yara_rules": "|".join(sorted(branch_identity["yara_rules"])),
                        "av_families": "|".join(sorted(branch_identity["av_families"])),
                        "yara_rule_metadata": serialised_identity["yara_rule_metadata"],
                    }
                    expl.append({
                        "rule_id": emission.rule_id,
                        "description": emission.description,
                        "confidence": emission.confidence,
                        "evidence_type": policy.evidence_type,
                        "signals": [emission.name],
                        "evidence": {
                            name: all_evidence[name] for name in branch.evidence
                        },
                    })
                    if branch.successful_outcome:
                        outcome_value = (
                            branch.successful_outcome
                            if successful_response
                            else branch.other_outcome
                        )
                        for outcome_field in dict.fromkeys((
                            "chronosift_web_outcome",
                            policy.web_outcome_field,
                        )):
                            if outcome_field in df.columns:
                                merged_outcome = policy.web_outcome_merge.merge(
                                    df.iat[
                                        i,
                                        df.columns.get_loc(outcome_field),
                                    ],
                                    outcome_value,
                                )
                                df.iat[i, df.columns.get_loc(outcome_field)] = (
                                    merged_outcome
                                )

    def _apply_web_attack_mapping_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
    ) -> None:
        """Apply the configured web-evidence mappings and ATT&CK labels."""
        policy = self.detector_policy.referenced_file_correlation
        if not policy.enabled or not policy.mapping_enabled:
            return

        indicator_vals = _column_values_or_none(df, policy.attack_indicators_field)
        category_vals = _column_values_or_none(
            df, policy.web_feature_fields["categories"]
        )
        source_ip_vals = _column_values_or_none(df, policy.source_ip_field)
        method_vals = _column_values_or_none(df, policy.method_field)
        endpoint_vals = _column_values_or_none(df, policy.endpoint_field)
        status_vals = _column_values_or_none(df, policy.status_field)
        upload_outcome_vals = _column_values_or_none(df, policy.upload_outcome_field)
        technique_cols = tuple(
            df.columns.get_loc(field_name)
            for field_name in dict.fromkeys((
                "chronosift_attack_techniques",
                policy.attack_techniques_field,
            ))
            if field_name in df.columns
        )

        for row_i in range(len(df)):
            indicators = {
                token.casefold()
                for token in _safe_str(indicator_vals[row_i]).split("|")
                if token
            }
            categories = {
                token.casefold()
                for token in _safe_str(category_vals[row_i]).split("|")
                if token
            }
            method = _safe_str(method_vals[row_i]).strip().upper()
            upload_outcome = _safe_str(upload_outcome_vals[row_i]).strip().casefold()
            source_ip = _safe_str(source_ip_vals[row_i]).strip()
            source_ip_scope = _ip_scope(source_ip) or ""
            signals = signal_map.get(row_i, {}) or {}

            def matches(condition: WebMappingConditionPolicy) -> bool:
                groups: List[bool] = []
                if condition.indicators_any:
                    groups.append(bool(indicators & condition.indicators_any))
                if condition.indicator_prefixes_any:
                    groups.append(any(
                        indicator.startswith(prefix)
                        for indicator in indicators
                        for prefix in condition.indicator_prefixes_any
                    ))
                if condition.signals_any:
                    groups.append(any(
                        float(signals.get(name, 0.0) or 0.0)
                        > float(condition.minimum_signal_value_exclusive)
                        for name in condition.signals_any
                    ))
                if condition.categories_any:
                    groups.append(bool(categories & condition.categories_any))
                if condition.methods_any:
                    groups.append(method in condition.methods_any)
                if condition.upload_outcomes_any:
                    groups.append(upload_outcome in condition.upload_outcomes_any)
                if condition.source_ip_scopes_any:
                    groups.append(source_ip_scope in condition.source_ip_scopes_any)
                return all(groups) if condition.match == "all" else any(groups)

            matched_branches = [
                branch
                for branch in policy.mapping_branches
                if matches(branch.conditions)
                and not (branch.exclude is not None and matches(branch.exclude))
            ]
            if not matched_branches:
                continue

            mutable_signals = self._sparse_signal_dict(signal_map, row_i)
            explanations = self._sparse_explain_list(explain_map, row_i)
            techniques: Set[str] = set()
            for branch in matched_branches:
                branch_technique_id = next((
                    policy.mapping_outputs[output_id].attack_technique_id
                    for output_id in branch.output_ids
                    if policy.mapping_outputs[output_id].attack_technique_id
                ), "")
                for output_id in branch.output_ids:
                    output = policy.mapping_outputs[output_id]
                    emission = output.emission
                    mutable_signals[emission.name] = max(
                        float(mutable_signals.get(emission.name, 0.0) or 0.0),
                        emission.value,
                    )
                    if output.attack_technique_id:
                        techniques.add(output.attack_technique_id)
                    all_evidence = {
                        "attack_technique_id": (
                            output.attack_technique_id or branch_technique_id
                        ),
                        "http_method": method,
                        "canonical_endpoint": _safe_str(endpoint_vals[row_i]).strip(),
                        "http_response_code": _normalise_integral_metadata_value(
                            status_vals[row_i]
                        ),
                        "attack_indicators": "|".join(sorted(indicators)),
                        "file_categories": "|".join(sorted(categories)),
                        "source_ip": source_ip,
                        "upload_outcome": upload_outcome,
                    }
                    explanations.append({
                        "rule_id": emission.rule_id,
                        "description": emission.description,
                        "confidence": emission.confidence,
                        "evidence_type": (
                            "mapping"
                            if output.attack_technique_id
                            else policy.evidence_type
                        ),
                        "signals": [emission.name],
                        "evidence": {
                            name: all_evidence[name] for name in branch.evidence
                        },
                    })

            if technique_cols and techniques:
                for technique_col in technique_cols:
                    existing = {
                        token
                        for token in _safe_str(
                            df.iat[row_i, technique_col]
                        ).split("|")
                        if token
                    }
                    df.iat[row_i, technique_col] = "|".join(
                        sorted(existing | techniques)
                    )

    def _apply_web_request_classifier_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
    ) -> None:
        """Apply the authoritative web indicator, SQLi, and exploit policy."""
        if len(df) == 0:
            return

        policy = self.detector_policy.web_request_classification
        if not policy.enabled:
            return
        outputs = policy.outputs
        inference = policy.sqli
        method_vals = _column_values_or_none(df, outputs.method_field)
        path_vals = _column_values_or_none(df, "chronosift_web_request_target")
        endpoint_vals = _column_values_or_none(df, outputs.endpoint_field)
        host_vals = _column_values_or_none(df, "chronosift_web_host")
        status_vals = _column_values_or_none(df, outputs.status_field)
        response_bytes_vals = _column_values_or_none(df, "chronosift_web_response_bytes")
        actor_ip_vals = _column_values_or_none(df, outputs.source_ip_field)
        ua_vals = _column_values_or_none(df, "chronosift_web_user_agent")
        attack_indicator_vals = _column_values_or_none(
            df, outputs.attack_indicators_field
        )
        upload_name_vals = _column_values_or_none(
            df, "chronosift_web_upload_name"
        )
        upload_names_vals = _column_values_or_none(df, outputs.upload_names_field)
        upload_outcome_vals = _column_values_or_none(
            df, outputs.upload_outcome_field
        )

        if (
            inference.baseline_lookback is not None
            and not isinstance(df.index, pd.DatetimeIndex)
        ):
            raise ValueError(
                "web_request_classification.sqli.baseline.lookback requires "
                "a DatetimeIndex when configured with a finite duration"
            )
        timestamp_values = (
            df.index.asi8
            if isinstance(df.index, pd.DatetimeIndex)
            else np.arange(len(df), dtype=np.int64)
        )
        baseline_lookback_ticks = (
            _timedelta_ticks_for_datetime_index(
                inference.baseline_lookback, df.index
            )
            if (
                inference.baseline_lookback is not None
                and isinstance(df.index, pd.DatetimeIndex)
            )
            else None
        )

        def baseline_key(context: Dict[str, Any]) -> Optional[Tuple[str, ...]]:
            values = tuple(
                _safe_str(context[role]).strip().casefold()
                for role in inference.baseline_key_fields
            )
            by_role = dict(zip(inference.baseline_key_fields, values))
            if any(
                not by_role[role]
                for role in inference.baseline_require_nonempty_keys
            ):
                return None
            return values

        row_context: Dict[int, Dict[str, Any]] = {}
        baseline_groups: Dict[
            Tuple[str, ...], List[Tuple[int, int, int]]
        ] = {}
        for row_i in range(len(df)):
            http_path = _safe_str(path_vals[row_i]).strip()
            if not http_path:
                continue
            endpoint = _safe_str(endpoint_vals[row_i]).strip()
            method = _safe_str(method_vals[row_i]).strip().upper()
            host = _safe_str(host_vals[row_i]).strip().lower()
            indicators = _http_sqli_indicators(http_path, policy.indicators)
            attack_indicators = tuple(
                token.strip().lower()
                for token in _safe_str(attack_indicator_vals[row_i]).split("|")
                if token.strip()
            )
            status_code = _normalise_integral_metadata_value(status_vals[row_i])
            response_bytes = _normalise_integral_metadata_value(response_bytes_vals[row_i])
            successful_response = (
                status_code is not None
                and policy.outcomes.success_status_minimum
                <= status_code
                < policy.outcomes.success_status_maximum_exclusive
            )
            context = {
                "method": method,
                "host": host,
                "http_path": http_path,
                "endpoint": endpoint or "",
                "indicators": indicators,
                "attack_indicators": attack_indicators,
                "status_code": status_code,
                "response_bytes": response_bytes,
                "successful_response": successful_response,
                "timestamp_tick": int(timestamp_values[row_i]),
                "upload_name": _safe_str(upload_name_vals[row_i]).strip(),
                "upload_names": _safe_str(upload_names_vals[row_i]).strip(),
                "upload_outcome": _safe_str(upload_outcome_vals[row_i]).strip(),
            }
            row_context[row_i] = context
            indicators_match = (
                inference.baseline_sample_indicators == "any"
                or (
                    inference.baseline_sample_indicators == "present"
                    and bool(indicators)
                )
                or (
                    inference.baseline_sample_indicators == "absent"
                    and not indicators
                )
            )
            response_match = (
                inference.baseline_sample_response == "any"
                or successful_response
            )
            bytes_match = (
                response_bytes is not None
                and (
                    response_bytes >= 0
                    if inference.baseline_sample_bytes == "nonnegative"
                    else response_bytes > 0
                )
            )
            group_key = baseline_key(context)
            if (
                group_key is not None
                and indicators_match
                and response_match
                and bytes_match
            ):
                baseline_groups.setdefault(group_key, []).append(
                    (row_i, context["timestamp_tick"], response_bytes)
                )

        for row_i, context in row_context.items():
            indicators = context["indicators"]
            group_key = baseline_key(context)
            baseline_records = (
                baseline_groups.get(group_key, [])
                if group_key is not None
                else []
            )
            baseline_values: List[int] = []
            for sample_row_i, sample_timestamp_tick, sample_value in baseline_records:
                if (
                    inference.baseline_scope == "prior_rows"
                    and sample_row_i >= row_i
                ):
                    continue
                if baseline_lookback_ticks is not None:
                    delta_ticks = (
                        context["timestamp_tick"] - sample_timestamp_tick
                    )
                    if inference.baseline_scope == "partition":
                        delta_ticks = abs(delta_ticks)
                    if (
                        delta_ticks < 0
                        or delta_ticks > baseline_lookback_ticks
                    ):
                        continue
                baseline_values.append(sample_value)

            baseline_statistic_value: Optional[float] = None
            anomaly_threshold = float(inference.absolute_large_response_bytes)
            if len(baseline_values) >= inference.baseline_min_samples:
                numeric_baseline = np.asarray(
                    baseline_values, dtype=np.float64
                )
                if inference.baseline_statistic == "median":
                    baseline_statistic_value = float(np.median(numeric_baseline))
                else:
                    baseline_statistic_value = float(np.mean(numeric_baseline))
                threshold_values = {
                    "response_minimum": float(inference.response_minimum_bytes),
                    "baseline_ratio": (
                        baseline_statistic_value * inference.response_ratio
                    ),
                    "baseline_delta": (
                        baseline_statistic_value
                        + float(inference.response_delta_bytes)
                    ),
                }
                configured_thresholds = [
                    threshold_values[name]
                    for name in inference.threshold_terms
                ]
                anomaly_threshold = (
                    max(configured_thresholds)
                    if inference.threshold_combine == "maximum"
                    else min(configured_thresholds)
                )
            status_code = context["status_code"]
            response_bytes = context["response_bytes"]
            successful_response = context["successful_response"]
            threshold_exceeded = (
                response_bytes is not None
                and (
                    float(response_bytes) >= anomaly_threshold
                    if inference.threshold_comparison
                    == "greater_than_or_equal"
                    else float(response_bytes) > anomaly_threshold
                )
            )
            decision_facts = {
                "baseline_available": (
                    baseline_statistic_value is not None
                ),
                "indicators": bool(indicators),
                "response_bytes": response_bytes is not None,
                "successful_response": successful_response,
                "threshold_exceeded": threshold_exceeded,
            }

            sig = self._sparse_signal_dict(signal_map, row_i)
            expl = self._sparse_explain_list(explain_map, row_i)

            evidence_values = {
                "http_method": context["method"],
                "http_path": context["http_path"][:500],
                "canonical_endpoint": context["endpoint"],
                "sqli_indicators": "|".join(indicators),
                "http_response_code": status_code,
                "http_response_bytes": response_bytes,
                "baseline_response_statistic": baseline_statistic_value,
                "baseline_statistic": inference.baseline_statistic,
                "baseline_sample_count": len(baseline_values),
                "response_anomaly_threshold": round(anomaly_threshold, 3),
                "actor_ip": _safe_str(actor_ip_vals[row_i]).strip(),
                "http_request_user_agent": _safe_str(ua_vals[row_i])[:240],
                "attack_indicators": "|".join(context["attack_indicators"]),
                "upload_name": context["upload_name"][:120],
                "upload_names": context["upload_names"][:480],
                "upload_outcome": context["upload_outcome"],
            }

            def emit(
                emission: DetectorEmissionPolicy,
                *,
                description: Optional[str] = None,
                confidence: Optional[str] = None,
                evidence_names: Tuple[str, ...],
            ) -> bool:
                prior = float(sig.get(emission.name, 0.0) or 0.0)
                if prior >= emission.value:
                    return False
                sig[emission.name] = max(prior, emission.value)
                expl.append({
                    "rule_id": emission.rule_id,
                    "description": description or emission.description,
                    "confidence": confidence or emission.confidence,
                    "evidence_type": policy.evidence_type,
                    "signals": [emission.name],
                    "evidence": {
                        name: evidence_values[name] for name in evidence_names
                    },
                })
                return True

            emission_ids_by_semantic = {
                "attempt": inference.attempt_emission_id,
                "response_anomaly": inference.anomaly_emission_id,
                "probable_success": inference.probable_success_emission_id,
            }
            matched_semantics: Set[str] = set()
            for semantic, decision in inference.decisions_by_semantic.items():
                if not decision.matches(decision_facts):
                    continue
                matched_semantics.add(semantic)
                emit(
                    policy.emissions_by_id[
                        emission_ids_by_semantic[semantic]
                    ],
                    evidence_names=inference.evidence,
                )

            outcome_candidates = {"observed"}
            if "probable_success" in matched_semantics:
                outcome_candidates.add("probable_success")
            if (
                "attempt" in matched_semantics
                or policy.outcomes.attempt_when.matches(
                    context["attack_indicators"]
                )
            ):
                outcome_candidates.add("attempt")
            outcome_value = policy.outcomes.select(outcome_candidates)
            for outcome_field in dict.fromkeys((
                "chronosift_web_outcome",
                outputs.web_outcome_field,
            )):
                if outcome_field in df.columns:
                    df.iat[row_i, df.columns.get_loc(outcome_field)] = outcome_value

            current_signals = signal_map.get(row_i) or {}
            attack_indicators_set = set(context["attack_indicators"])
            for branch in policy.exploit_branches:
                conditions = branch.conditions
                group_matches: List[bool] = []
                if conditions.indicators_all:
                    group_matches.append(
                        conditions.indicators_all.issubset(attack_indicators_set)
                    )
                if conditions.indicators_any:
                    group_matches.append(bool(
                        conditions.indicators_any & attack_indicators_set
                    ))
                if conditions.indicator_prefixes_any:
                    group_matches.append(any(
                        indicator.startswith(prefix)
                        for indicator in attack_indicators_set
                        for prefix in conditions.indicator_prefixes_any
                    ))
                if conditions.signals_any:
                    group_matches.append(any(
                        float(current_signals.get(name, 0.0) or 0.0)
                        > float(conditions.minimum_signal_value_exclusive)
                        for name in conditions.signals_any
                    ))
                if group_matches and all(group_matches):
                    emit(
                        policy.exploit_emission,
                        description=branch.description,
                        confidence=branch.confidence,
                        evidence_names=branch.evidence,
                    )
                    break

    def _apply_file_lifecycle_signals_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
        contextual_cache: Optional[Dict[Tuple[Any, ...], np.ndarray]] = None,
        retain_zero_weight_generic_signals: bool = True,
    ) -> None:
        policy = self.detector_policy.file_lifecycle
        if (
            len(df) == 0
            or not policy.enabled
            or not isinstance(df.index, pd.DatetimeIndex)
        ):
            return

        required = {policy.timestamp_field}
        if not required.issubset(set(df.columns)):
            return

        nrows = len(df)
        timestamp_desc_vals = _contextual_text_array(
            df, contextual_cache, policy.timestamp_field
        )
        timestamp_desc_lower = _contextual_text_array(
            df, contextual_cache, policy.timestamp_field, lower=True
        )
        file_paths = _contextual_file_paths(
            df, contextual_cache, policy.path_fields
        )
        path_lower = _contextual_path_lower(
            df, contextual_cache, policy.path_fields
        )
        kinds = np.full(nrows, "", dtype=object)
        unclassified = np.ones(nrows, dtype=bool)
        for kind_name in policy.timestamp_kind_priority:
            matches = _text_array_contains_any(
                timestamp_desc_lower, policy.timestamp_kind_tokens[kind_name]
            ) & unclassified
            kinds[matches] = kind_name
            unclassified[matches] = False
        file_exts = np.full(nrows, "", dtype=object)
        web_root_flags = np.zeros(nrows, dtype=bool)
        web_script_flags = np.zeros(nrows, dtype=bool)
        web_content_flags = np.zeros(nrows, dtype=bool)
        archive_flags = np.zeros(nrows, dtype=bool)
        sensitive_flags = np.zeros(nrows, dtype=bool)
        excluded_update_flags = np.zeros(nrows, dtype=bool)
        host_vals = _contextual_text_array(
            df, contextual_cache, policy.host_field
        )
        host_lower = _contextual_text_array(
            df, contextual_cache, policy.host_field, lower=True
        )
        parser_vals = _contextual_text_array(
            df, contextual_cache, policy.parser_field
        )
        message_vals = _contextual_text_array(
            df, contextual_cache, policy.message_field
        )
        message_lower = _contextual_text_array(
            df, contextual_cache, policy.message_field, lower=True
        )
        size_vals = _column_values_or_none(df, policy.file_size_field)
        alloc_vals = _column_values_or_none(df, policy.allocation_field)
        web_script_exts = policy.web_script_extensions
        web_content_exts = policy.web_content_extensions
        web_root_patterns = policy.web_root_tokens
        sensitive_path_patterns = policy.sensitive_path_tokens
        database_dump_patterns = policy.database_dump_name_tokens
        database_dump_extensions = policy.database_dump_extensions
        archive_extensions = policy.archive_extensions

        def emit(
            row_i: int,
            semantic: str,
            evidence_values: Dict[str, Any],
        ) -> None:
            emission = policy.emissions_by_semantic[semantic]
            if (
                semantic in policy.weight_aware_semantics
                and not retain_zero_weight_generic_signals
                and float(self.weights.get(emission.name, 0.0) or 0.0) == 0.0
            ):
                return
            signals = self._sparse_signal_dict(signal_map, row_i)
            prior = float(signals.get(emission.name, 0.0) or 0.0)
            if prior >= emission.value:
                return
            signals[emission.name] = max(prior, emission.value)
            evidence = {
                name: evidence_values.get(name, "")
                for name in policy.evidence_by_semantic[semantic]
            }
            self._sparse_explain_list(explain_map, row_i).append({
                "rule_id": emission.rule_id,
                "description": emission.description,
                "confidence": emission.confidence,
                "evidence_type": policy.evidence_type,
                "signals": [emission.name],
                "evidence": evidence,
            })

        file_exts[:] = np.fromiter(
            (os.path.splitext(path)[1] if path else "" for path in path_lower),
            dtype=object,
            count=nrows,
        )
        basenames = np.fromiter(
            (os.path.basename(path) if path else "" for path in path_lower),
            dtype=object,
            count=nrows,
        )
        parent_paths = np.fromiter(
            (os.path.dirname(path) if path else "" for path in path_lower),
            dtype=object,
            count=nrows,
        )
        web_root_flags[:] = _text_array_contains_any(path_lower, web_root_patterns)
        web_script_flags[:] = np.isin(file_exts, tuple(web_script_exts))
        web_content_flags[:] = np.isin(file_exts, tuple(web_content_exts))
        archive_flags[:] = np.isin(file_exts, tuple(archive_extensions))
        sensitive_flags[:] = _text_array_contains_any(path_lower, sensitive_path_patterns)
        database_dump_extension_flags = np.isin(
            file_exts, tuple(database_dump_extensions)
        )
        database_dump_basename_flags = _text_array_contains_any(
            basenames, database_dump_patterns
        )
        database_dump_message_flags = _text_array_contains_any(
            message_lower, database_dump_patterns
        )
        excluded_update_flags[:] = _text_array_contains_any(
            path_lower, policy.excluded_update_path_tokens
        )
        suspicious_temp_flags = _text_array_contains_any(
            basenames, policy.suspicious_temp_basename_tokens
        )
        ransomware_matches = np.fromiter(
            (
                next(
                    (
                        suffix
                        for suffix in policy.ransomware_extension_suffixes
                        if basename.endswith(suffix)
                    ),
                    "",
                )
                for basename in basenames
            ),
            dtype=object,
            count=nrows,
        )

        row_facts: List[Dict[str, bool]] = []
        for row_i in range(nrows):
            path = file_paths[row_i]
            kind = kinds[row_i]
            alloc_val = alloc_vals[row_i]
            alloc_bool = None if _is_null(alloc_val) else bool(alloc_val)
            predicates: Dict[str, bool] = {
                "path_present": bool(path),
                "extension_present": bool(file_exts[row_i]),
                "web_root": bool(web_root_flags[row_i]),
                "web_script_extension": bool(web_script_flags[row_i]),
                "web_content_extension": bool(web_content_flags[row_i]),
                "archive_extension": bool(archive_flags[row_i]),
                "database_dump_extension": bool(
                    database_dump_extension_flags[row_i]
                ),
                "database_dump_basename": bool(
                    database_dump_basename_flags[row_i]
                ),
                "database_dump_message": bool(
                    database_dump_message_flags[row_i]
                ),
                "sensitive_path": bool(sensitive_flags[row_i]),
                "allocated": alloc_bool is True,
                "unallocated": alloc_bool is False,
                "excluded_update_path": bool(excluded_update_flags[row_i]),
                "suspicious_temp_basename": bool(
                    suspicious_temp_flags[row_i]
                ),
                "ransomware_extension_suffix": bool(
                    ransomware_matches[row_i]
                ),
            }
            for name, derivation in policy.derived_predicates_by_name.items():
                predicates[name] = derivation.matches(predicates)
            row_facts.append(predicates)
            evidence_values = {
                "path": path,
                "timestamp_desc": timestamp_desc_vals[row_i][:120],
                "parser": parser_vals[row_i],
                "hostname": host_vals[row_i],
                "file_size": size_vals[row_i],
                "message": message_vals[row_i][:200],
                "is_allocated": alloc_bool,
            }
            for semantic, decision in policy.row_decisions_by_semantic.items():
                if decision.matches(kind, predicates):
                    emit(row_i, semantic, evidence_values)

        def lifecycle_key(row_i: int, fields: Tuple[str, ...]) -> Tuple[str, ...]:
            values = {
                "host": host_lower[row_i],
                "path": path_lower[row_i],
                "parent_directory": parent_paths[row_i],
            }
            return tuple(values[name] for name in fields)

        short_policy = policy.short_lived
        short_lived_window = pd.Timedelta(short_policy.lookback)
        create_candidates: Dict[Tuple[str, ...], Tuple[int, pd.Timestamp]] = {}
        for row_i in range(nrows):
            key = lifecycle_key(row_i, short_policy.key_fields)
            kind = kinds[row_i]
            if kind in short_policy.source_timestamp_kinds:
                if (
                    short_policy.source_selection == "latest"
                    or key not in create_candidates
                ):
                    create_candidates[key] = (row_i, df.index[row_i])
            if kind not in short_policy.target_timestamp_kinds:
                continue
            prior = create_candidates.get(key)
            if prior is None:
                continue
            create_i, create_ts = prior
            delta = df.index[row_i] - create_ts
            ordering_matches = (
                delta > pd.Timedelta(0)
                if short_policy.ordering == "strictly_before"
                else delta >= pd.Timedelta(0)
            )
            bounds_match = (
                delta < short_lived_window
                if short_policy.window_bounds == "open"
                else delta <= short_lived_window
            )
            facts = {
                f"source_{name}": value
                for name, value in row_facts[create_i].items()
            }
            facts.update({
                f"target_{name}": value
                for name, value in row_facts[row_i].items()
            })
            if (
                ordering_matches
                and bounds_match
                and short_policy.conditions.matches(facts)
            ):
                emit_i = create_i if short_policy.emit_on == "source" else row_i
                emit(emit_i, "short_lived_file", {
                    "path": file_paths[emit_i],
                    "create_timestamp": create_ts.isoformat(),
                    "delete_timestamp": df.index[row_i].isoformat(),
                    "lifetime_seconds": int(delta.total_seconds()),
                })

        def outside_window(
            delta: pd.Timedelta,
            window_policy: FileLifecycleThresholdWindowPolicy,
        ) -> bool:
            lookback = pd.Timedelta(window_policy.lookback)
            return (
                delta >= lookback
                if window_policy.window_bounds == "open"
                else delta > lookback
            )

        def threshold_reached(
            count: int,
            window_policy: FileLifecycleThresholdWindowPolicy,
        ) -> bool:
            return (
                count > window_policy.threshold
                if window_policy.threshold_comparison == "greater_than"
                else count >= window_policy.threshold
            )

        mass_policy = policy.mass_modification
        mod_events: Dict[Tuple[str, ...], List[Tuple[int, pd.Timestamp]]] = {}
        for row_i in range(nrows):
            if kinds[row_i] not in mass_policy.eligible_timestamp_kinds:
                continue
            facts = row_facts[row_i]
            if not mass_policy.conditions.matches(facts):
                continue
            key = lifecycle_key(row_i, mass_policy.group_by)
            mod_events.setdefault(key, []).append((row_i, df.index[row_i]))

        mass_window = pd.Timedelta(mass_policy.lookback)
        for key, events in mod_events.items():
            left = 0
            emission_count = 0
            for right, (row_i, ts_now) in enumerate(events):
                while left < right and outside_window(
                    ts_now - events[left][1], mass_policy
                ):
                    left += 1
                count_in_window = right - left + 1
                if threshold_reached(count_in_window, mass_policy):
                    emit(row_i, "mass_file_modification", {
                        "host": host_lower[row_i],
                        "directory": parent_paths[row_i],
                        "window_seconds": int(mass_window.total_seconds()),
                        "count_in_window": int(count_in_window),
                    })
                    emission_count += 1
                    if emission_count >= mass_policy.max_emissions_per_group:
                        break

        ransom_policy = policy.ransomware_burst
        ransom_ext_window = pd.Timedelta(ransom_policy.lookback)
        ransom_events: Dict[
            Tuple[str, ...], List[Tuple[int, pd.Timestamp, str]]
        ] = {}
        for row_i in range(nrows):
            if kinds[row_i] not in ransom_policy.eligible_timestamp_kinds:
                continue
            matched_ext = str(ransomware_matches[row_i])
            facts = row_facts[row_i]
            if not ransom_policy.conditions.matches(facts):
                continue
            key = lifecycle_key(row_i, ransom_policy.group_by)
            ransom_events.setdefault(key, []).append(
                (row_i, df.index[row_i], matched_ext)
            )

        for key, events in ransom_events.items():
            left = 0
            ext_counts: Dict[str, int] = {}
            emission_count = 0
            for right, (row_i, ts_now, ext_now) in enumerate(events):
                if ext_now:
                    ext_counts[ext_now] = ext_counts.get(ext_now, 0) + 1
                while left < right and outside_window(
                    ts_now - events[left][1], ransom_policy
                ):
                    _, _, ext_left = events[left]
                    if ext_left:
                        ext_counts[ext_left] = ext_counts.get(ext_left, 0) - 1
                        if ext_counts[ext_left] <= 0:
                            ext_counts.pop(ext_left, None)
                    left += 1
                count_in_window = right - left + 1
                if threshold_reached(count_in_window, ransom_policy):
                    emit(row_i, "ransomware_extension_burst", {
                        "host": host_lower[row_i],
                        "window_seconds": int(ransom_ext_window.total_seconds()),
                        "count_in_window": int(count_in_window),
                        "extensions": ",".join(sorted(ext_counts.keys()))[:240],
                    })
                    emission_count += 1
                    if emission_count >= ransom_policy.max_emissions_per_group:
                        break

    def _apply_timestomping_detection_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
        contextual_cache: Optional[Dict[Tuple[Any, ...], np.ndarray]] = None,
    ) -> None:
        """Apply the configured MFT attribute-timestamp comparison policy."""
        policy = self.detector_policy.mft_timestomping
        if len(df) == 0 or not policy.enabled:
            return
        if (
            policy.parser_field not in df.columns
            or policy.timestamp_field not in df.columns
        ):
            return

        parser_vals = _contextual_text_array(
            df, contextual_cache, policy.parser_field, lower=True
        )
        timestamp_desc_vals = _contextual_text_array(
            df, contextual_cache, policy.timestamp_field, lower=True
        )
        path_keys = _contextual_path_lower(
            df, contextual_cache, policy.path_fields
        )

        si_creation: Dict[str, List[Tuple[int, pd.Timestamp]]] = {}
        fn_creation: Dict[str, List[Tuple[int, pd.Timestamp]]] = {}

        mft_rows = np.flatnonzero(
            _text_array_contains_any(parser_vals, policy.parser_tokens)
        )
        for row_i in mft_rows:
            parser_s = parser_vals[row_i]
            if not any(token in parser_s for token in policy.parser_tokens):
                continue
            td = timestamp_desc_vals[row_i]
            if not any(token in td for token in policy.creation_tokens):
                continue
            path_key = path_keys[row_i]
            if not path_key:
                continue
            ts = df.index[row_i]

            is_fn = any(token in td for token in policy.file_name_tokens)
            is_si = any(
                token in td for token in policy.standard_information_tokens
            )
            if not is_fn and not is_si:
                # If the timestamp_desc does not specify the attribute, try
                # to infer from the broader description. Default: ambiguous,
                # skip this row to avoid false positives.
                continue

            if is_si:
                si_creation.setdefault(path_key, []).append((row_i, ts))
            elif is_fn:
                fn_creation.setdefault(path_key, []).append((row_i, ts))

        min_delta = pd.Timedelta(policy.minimum_delta)

        # ── Archive-extraction false-positive dampening ────────────────
        # When files are extracted from archives (ZIP/RAR/7z/tar), Windows
        # sets $SI creation to the original timestamp from inside the
        # archive while $FN creation reflects the actual extraction time.
        # This produces the same $FN > $SI pattern as timestomping.
        #
        # Heuristic 1: OS-update / installer paths are excluded outright.
        # Heuristic 2: If ≥ BULK_THRESHOLD files in the same parent
        #   directory all show $FN > $SI, it is almost certainly bulk
        #   extraction rather than targeted anti-forensics.  Those hits
        #   are downgraded to confidence "low" and flagged as likely
        #   archive extraction.

        excluded_path_tokens = policy.excluded_path_tokens

        # First pass: collect all candidate hits and their parent directories
        candidates: List[Tuple[str, int, pd.Timestamp, pd.Timestamp]] = []  # (path_key, si_row_i, si_ts, fn_ts)
        parent_counts: Dict[str, int] = {}

        for path_key, si_entries in si_creation.items():
            fn_entries = fn_creation.get(path_key)
            if not fn_entries:
                continue
            earliest_si = min(si_entries, key=lambda x: x[1])
            earliest_fn = min(fn_entries, key=lambda x: x[1])
            si_row_i, si_ts = earliest_si
            fn_row_i, fn_ts = earliest_fn
            if fn_ts - si_ts > min_delta:
                # Exclude OS-update/installer paths entirely
                if any(pat in path_key for pat in excluded_path_tokens):
                    continue
                candidates.append((path_key, si_row_i, si_ts, fn_ts))
                # Extract parent directory for bulk-extraction grouping.
                # Files with no directory separator (bare filenames) use a
                # sentinel that cannot collide with real directory paths,
                # preventing unrelated rootless-path files from aggregating.
                parent = path_key.rsplit("/", 1)[0] if "/" in path_key else f"__rootless__{path_key}"
                parent_counts[parent] = parent_counts.get(parent, 0) + 1

        # Second pass: emit signals with appropriate confidence
        for path_key, si_row_i, si_ts, fn_ts in candidates:
            parent = path_key.rsplit("/", 1)[0] if "/" in path_key else f"__rootless__{path_key}"
            bulk_extraction_likely = (
                parent_counts.get(parent, 0) >= policy.bulk_group_threshold
            )

            sig = self._sparse_signal_dict(signal_map, si_row_i)
            expl = self._sparse_explain_list(explain_map, si_row_i)
            emission = policy.emission
            prior = float(sig.get(emission.name, 0.0) or 0.0)
            if prior >= emission.value:
                continue
            sig[emission.name] = max(prior, emission.value)
            explanation = (
                policy.bulk_explanation
                if bulk_extraction_likely
                else policy.targeted_explanation
            )
            evidence_values = {
                "path": path_key,
                "si_creation": si_ts.isoformat(),
                "fn_creation": fn_ts.isoformat(),
                "delta_seconds": int((fn_ts - si_ts).total_seconds()),
                "bulk_extraction_dampened": bool(bulk_extraction_likely),
                "directory_hit_count": parent_counts.get(parent, 0),
            }
            expl.append({
                "rule_id": emission.rule_id,
                "description": explanation.description,
                "confidence": explanation.confidence,
                "evidence_type": policy.evidence_type,
                "signals": [emission.name],
                "evidence": {
                    name: evidence_values[name] for name in explanation.evidence
                },
            })

    def _apply_persistence_and_config_signals_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
        contextual_cache: Optional[Dict[Tuple[Any, ...], np.ndarray]] = None,
    ) -> None:
        self._apply_ordered_row_rules_sparse(
            df,
            signal_map,
            explain_map,
            contextual_cache,
            detector_id="persistence_configuration",
        )
        self._apply_grouped_signal_window_sparse(
            df,
            signal_map,
            explain_map,
            detector_id="repeated_scheduled_execution",
        )
    def _apply_policy_signal_projections_sparse(
        self,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
        *,
        stage: str,
    ) -> None:
        definitions = self.detector_policy.definitions(
            stage=stage,
            executor="signal_projection",
            enabled_only=True,
        )
        for definition in definitions:
            policy = definition.payload
            for row_i, existing in list(signal_map.items()):
                if not isinstance(existing, dict) or not existing:
                    continue
                for projection in policy.projections:
                    matched: List[Tuple[str, float]] = []
                    input_matches: List[bool] = []
                    for signal_name in projection.input_signals:
                        try:
                            value = float(existing.get(signal_name, 0.0) or 0.0)
                        except (TypeError, ValueError):
                            value = 0.0
                        qualifies = value > projection.minimum_value_exclusive
                        input_matches.append(qualifies)
                        if qualifies:
                            matched.append((signal_name, value))
                    qualifies = (
                        any(input_matches)
                        if projection.match == "any"
                        else all(input_matches)
                    )
                    if not qualifies or not matched:
                        continue
                    projected_value = (
                        max(value for _, value in matched)
                        * projection.emission.value
                    )
                    prior = float(
                        existing.get(projection.emission.name, 0.0) or 0.0
                    )
                    if projected_value <= prior:
                        continue
                    existing[projection.emission.name] = projected_value
                    matched_names = ",".join(sorted(name for name, _ in matched))
                    evidence = {
                        evidence_value.name: matched_names
                        for evidence_value in policy.evidence
                    }
                    self._sparse_explain_list(explain_map, row_i).append({
                        "rule_id": projection.emission.rule_id,
                        "description": projection.emission.description,
                        "confidence": projection.emission.confidence,
                        "evidence_type": policy.evidence_type,
                        "signals": [projection.emission.name],
                        "evidence": evidence,
                    })

    def _apply_policy_signal_gates_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
        contextual_cache: Optional[Dict[Tuple[Any, ...], np.ndarray]] = None,
        *,
        stage: str = "contextual",
    ) -> None:
        policies = tuple(
            definition.payload
            for definition in self.detector_policy.definitions(
                stage=stage,
                executor="signal_gate",
                enabled_only=True,
            )
        )
        nrows = len(df)
        if nrows == 0:
            return

        for policy in policies:
            resolver_data: Dict[str, Any] = {}
            for evidence_value in policy.evidence:
                if evidence_value.resolver == "best_effort_file_path":
                    resolver_data[evidence_value.name] = _contextual_file_paths(
                        df,
                        contextual_cache,
                        evidence_value.fields,
                    )
                elif evidence_value.resolver == "row_field":
                    resolver_data[evidence_value.name] = _contextual_text_array(
                        df,
                        contextual_cache,
                        evidence_value.fields[0],
                    )
                elif evidence_value.resolver == "first_nonempty":
                    resolver_data[evidence_value.name] = tuple(
                        _contextual_text_array(df, contextual_cache, field)
                        for field in evidence_value.fields
                    )
                else:
                    resolver_data[evidence_value.name] = None

            for row_i, existing in list(signal_map.items()):
                if not (0 <= row_i < nrows) or not isinstance(existing, dict):
                    continue
                matched_signals: List[str] = []
                group_matches: List[bool] = []
                for group in policy.input_groups:
                    matches: List[bool] = []
                    for signal_name in group.signals:
                        try:
                            value = float(existing.get(signal_name, 0.0) or 0.0)
                        except (TypeError, ValueError):
                            value = 0.0
                        matched = value > policy.minimum_value_exclusive
                        matches.append(matched)
                        if matched:
                            matched_signals.append(signal_name)
                    group_matches.append(
                        any(matches) if group.match == "any" else all(matches)
                    )
                gate_matched = (
                    any(group_matches)
                    if policy.match == "any"
                    else all(group_matches)
                )
                if not gate_matched:
                    continue

                evidence: Dict[str, Any] = {}
                for evidence_value in policy.evidence:
                    data = resolver_data[evidence_value.name]
                    if evidence_value.resolver == "matched_signals":
                        resolved = ",".join(sorted(matched_signals))
                    elif evidence_value.resolver == "first_nonempty":
                        resolved = next(
                            (values[row_i] for values in data if values[row_i]),
                            "",
                        )
                    else:
                        resolved = data[row_i]
                    resolved_text = _safe_str(resolved)
                    if evidence_value.max_chars is not None:
                        resolved_text = resolved_text[:evidence_value.max_chars]
                    evidence[evidence_value.name] = resolved_text

                for emission in policy.emissions:
                    signals = self._sparse_signal_dict(signal_map, row_i)
                    prior = float(signals.get(emission.name, 0.0) or 0.0)
                    if prior >= emission.value:
                        continue
                    signals[emission.name] = max(prior, emission.value)
                    explain = self._sparse_explain_list(explain_map, row_i)
                    explain.append({
                        "rule_id": emission.rule_id,
                        "description": emission.description,
                        "confidence": emission.confidence,
                        "evidence_type": policy.evidence_type,
                        "signals": [emission.name],
                        "evidence": dict(evidence),
                    })

    def _apply_webshell_artifact_policy_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
        contextual_cache: Optional[Dict[Tuple[Any, ...], np.ndarray]] = None,
    ) -> None:
        policy = self.detector_policy.webshell_artifact
        nrows = len(df)
        if nrows == 0 or not policy.enabled:
            return

        paths = _contextual_file_paths(df, contextual_cache, policy.path_fields)
        path_lower = np.fromiter(
            (
                _safe_str(path).strip().lower().replace("\\", "/")
                for path in paths
            ),
            dtype=object,
            count=nrows,
        )
        basenames = np.fromiter(
            (os.path.basename(path) if path else "" for path in path_lower),
            dtype=object,
            count=nrows,
        )
        extensions = np.fromiter(
            (os.path.splitext(path)[1] if path else "" for path in path_lower),
            dtype=object,
            count=nrows,
        )
        normalised_path_patterns = tuple(
            token.replace("\\", "/") for token in policy.path_patterns
        )
        path_matches = _text_array_contains_any(
            path_lower, normalised_path_patterns
        )
        extension_matches = np.isin(extensions, tuple(policy.script_extensions))

        text_arrays = tuple(
            _contextual_text_array(df, contextual_cache, field)
            for field in policy.text_fields
        )
        first_existing_arrays = tuple(
            _contextual_text_array(df, contextual_cache, field)
            for field in policy.first_existing_text_fields
        )
        first_existing_values = np.fromiter(
            (
                next(
                    (values[row_i] for values in first_existing_arrays if values[row_i]),
                    "",
                )
                for row_i in range(nrows)
            ),
            dtype=object,
            count=nrows,
        )
        combined_lower = np.fromiter(
            (
                " ".join(
                    part
                    for part in (
                        *(values[row_i] for values in text_arrays),
                        first_existing_values[row_i],
                    )
                    if part
                ).lower()
                for row_i in range(nrows)
            ),
            dtype=object,
            count=nrows,
        )

        basename_support = _text_array_contains_any(
            basenames, policy.basename_tokens
        )
        text_support = _text_array_contains_any(
            combined_lower, policy.combined_text_tokens
        )
        signal_support = np.zeros(nrows, dtype=bool)
        matched_signal_names: Dict[int, Tuple[str, ...]] = {}
        for row_i, existing in signal_map.items():
            if not 0 <= row_i < nrows or not isinstance(existing, dict):
                continue
            matched: List[str] = []
            for signal_name in policy.support_signals:
                try:
                    value = float(existing.get(signal_name, 0.0) or 0.0)
                except (TypeError, ValueError):
                    value = 0.0
                if value > policy.minimum_signal_value_exclusive:
                    matched.append(signal_name)
            if matched:
                signal_support[row_i] = True
                matched_signal_names[row_i] = tuple(sorted(matched))

        support_groups = (basename_support, text_support, signal_support)
        if policy.support_match == "all":
            support_matches = np.logical_and.reduce(support_groups)
        else:
            support_matches = np.logical_or.reduce(support_groups)
        candidates = np.flatnonzero(
            path_matches & extension_matches & support_matches
        )
        if len(candidates) == 0:
            return

        resolver_data: Dict[str, Any] = {}
        for evidence_value in policy.evidence:
            if evidence_value.resolver == "best_effort_file_path":
                resolver_data[evidence_value.name] = _contextual_file_paths(
                    df, contextual_cache, evidence_value.fields
                )
            elif evidence_value.resolver == "row_field":
                resolver_data[evidence_value.name] = _contextual_text_array(
                    df, contextual_cache, evidence_value.fields[0]
                )
            elif evidence_value.resolver == "first_nonempty":
                resolver_data[evidence_value.name] = tuple(
                    _contextual_text_array(df, contextual_cache, field)
                    for field in evidence_value.fields
                )
            else:
                resolver_data[evidence_value.name] = None

        emission = policy.emission
        for row_i in candidates:
            evidence: Dict[str, Any] = {}
            for evidence_value in policy.evidence:
                data = resolver_data[evidence_value.name]
                if evidence_value.resolver == "matched_signals":
                    resolved = ",".join(matched_signal_names.get(row_i, ()))
                elif evidence_value.resolver == "first_nonempty":
                    resolved = next(
                        (values[row_i] for values in data if values[row_i]), ""
                    )
                else:
                    resolved = data[row_i]
                resolved_text = _safe_str(resolved)
                if evidence_value.max_chars is not None:
                    resolved_text = resolved_text[:evidence_value.max_chars]
                evidence[evidence_value.name] = resolved_text

            signals = self._sparse_signal_dict(signal_map, row_i)
            prior = float(signals.get(emission.name, 0.0) or 0.0)
            if prior >= emission.value:
                continue
            signals[emission.name] = max(prior, emission.value)
            explain = self._sparse_explain_list(explain_map, row_i)
            explain.append({
                "rule_id": emission.rule_id,
                "description": emission.description,
                "confidence": emission.confidence,
                "evidence_type": policy.evidence_type,
                "signals": [emission.name],
                "evidence": evidence,
            })

    def _apply_systemd_service_persistence_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
        contextual_cache: Optional[Dict[Tuple[Any, ...], np.ndarray]] = None,
    ) -> None:
        policy = self.detector_policy.systemd_service_persistence
        nrows = len(df)
        if nrows == 0 or not policy.enabled:
            return

        path_lower = _contextual_path_lower(
            df, contextual_cache, policy.path_fields
        )
        timestamp_descriptions_lower = _contextual_text_array(
            df, contextual_cache, policy.timestamp_field, lower=True
        )
        timestamp_kinds = np.full(nrows, "", dtype=object)
        unclassified_timestamps = np.ones(nrows, dtype=bool)
        for kind_name in policy.timestamp_kind_priority:
            kind_matches = _text_array_contains_any(
                timestamp_descriptions_lower,
                policy.timestamp_kind_tokens[kind_name],
            ) & unclassified_timestamps
            timestamp_kinds[kind_matches] = kind_name
            unclassified_timestamps[kind_matches] = False
        text_arrays = tuple(
            _contextual_text_array(df, contextual_cache, field)
            for field in policy.text_fields
        )
        first_existing_arrays = tuple(
            _contextual_text_array(df, contextual_cache, field)
            for field in policy.first_existing_text_fields
        )
        first_existing_values = np.fromiter(
            (
                next(
                    (values[row_i] for values in first_existing_arrays if values[row_i]),
                    "",
                )
                for row_i in range(nrows)
            ),
            dtype=object,
            count=nrows,
        )
        evidence_arrays: Dict[str, np.ndarray] = {}
        for evidence_value in policy.evidence:
            if evidence_value.resolver == "best_effort_file_path":
                values = _contextual_file_paths(
                    df, contextual_cache, evidence_value.fields
                )
            elif evidence_value.resolver == "row_field":
                values = _contextual_text_array(
                    df, contextual_cache, evidence_value.fields[0]
                )
            elif evidence_value.resolver == "first_nonempty":
                arrays = tuple(
                    _contextual_text_array(df, contextual_cache, field)
                    for field in evidence_value.fields
                )
                values = np.fromiter(
                    (
                        next(
                            (array[row_i] for array in arrays if array[row_i]),
                            "",
                        )
                        for row_i in range(nrows)
                    ),
                    dtype=object,
                    count=nrows,
                )
            else:
                raise ValueError(
                    "unsupported systemd evidence resolver: "
                    f"{evidence_value.resolver}"
                )
            if evidence_value.max_chars is not None:
                limit = evidence_value.max_chars
                values = np.fromiter(
                    (_safe_str(value)[:limit] for value in values),
                    dtype=object,
                    count=nrows,
                )
            evidence_arrays[evidence_value.name] = values

        path_patterns = tuple(
            token.replace("\\", "/")
            for token in policy.artifact.path_patterns
        )
        unit_extensions = frozenset(
            token.lower() for token in policy.artifact.unit_extensions
        )
        extensions = np.fromiter(
            (
                os.path.splitext(path)[1] if path else ""
                for path in path_lower
            ),
            dtype=object,
            count=nrows,
        )
        artifact_path_matches = _text_array_contains_any(
            path_lower, path_patterns
        )
        unit_extension_matches = np.isin(
            extensions, tuple(unit_extensions)
        )
        timestamp_kind_matches = np.isin(
            timestamp_kinds,
            tuple(policy.artifact.timestamp_kinds),
        )

        combined_text = np.fromiter(
            (
                " ".join(
                    part
                    for part in (
                        *(values[row_i] for values in text_arrays),
                        first_existing_values[row_i],
                    )
                    if part
                ).lower()
                for row_i in range(nrows)
            ),
            dtype=object,
            count=nrows,
        )
        persistent_matches = _text_array_contains_any(
            combined_text, policy.command.persistent_tokens
        )
        transient_matches = _text_array_contains_any(
            combined_text, policy.command.transient_tokens
        )
        unit_reference_extension_matches = _text_array_contains_any(
            combined_text, policy.command.unit_reference_extensions
        )
        unit_reference_path_matches = _text_array_contains_any(
            combined_text, policy.command.unit_reference_path_tokens
        )

        fact_masks = {
            "artifact_path": artifact_path_matches,
            "unit_extension": unit_extension_matches,
            "timestamp_kind": timestamp_kind_matches,
            "persistent_token": persistent_matches,
            "transient_token": transient_matches,
            "unit_reference_extension": unit_reference_extension_matches,
            "unit_reference_path": unit_reference_path_matches,
        }

        def branch_mask(
            conditions: SystemdBranchConditionPolicy,
        ) -> np.ndarray:
            result = np.zeros(nrows, dtype=bool)
            for required_facts in conditions.any_all:
                clause = np.ones(nrows, dtype=bool)
                for fact_name in required_facts:
                    clause &= fact_masks[fact_name]
                result |= clause
            return result

        branch_policies = {
            "artifact_change": policy.artifact,
            "command_activity": policy.command,
        }
        branch_masks = {
            branch_id: branch_mask(branch_policies[branch_id].conditions)
            for branch_id in policy.branch_order
        }
        any_branch_matches = np.zeros(nrows, dtype=bool)
        for matches in branch_masks.values():
            any_branch_matches |= matches

        emission = policy.emission
        for row_i in np.flatnonzero(any_branch_matches):
            matched_branch_ids = [
                branch_id
                for branch_id in policy.branch_order
                if branch_masks[branch_id][row_i]
            ]
            if policy.branch_mode == "first_match":
                matched_branch_ids = matched_branch_ids[:1]
            signals = self._sparse_signal_dict(signal_map, int(row_i))
            prior = float(signals.get(emission.name, 0.0) or 0.0)
            if prior >= emission.value:
                continue
            signals[emission.name] = max(prior, emission.value)
            explanations = self._sparse_explain_list(explain_map, int(row_i))
            for branch_id in matched_branch_ids:
                branch = branch_policies[branch_id]
                explanations.append({
                    "rule_id": emission.rule_id,
                    "description": branch.description,
                    "confidence": branch.confidence,
                    "evidence_type": policy.evidence_type,
                    "signals": [emission.name],
                    "evidence": {
                        name: evidence_arrays[name][row_i]
                        for name in branch.evidence
                    },
                })

    def _apply_deadbox_direct_signals_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
        contextual_cache: Optional[Dict[Tuple[Any, ...], np.ndarray]] = None,
    ) -> None:
        self._apply_ordered_row_rules_sparse(
            df,
            signal_map,
            explain_map,
            contextual_cache,
            detector_id="direct_attack_semantics",
        )
    def _emit_temporal_policy_signal(
        self,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
        row_i: int,
        emission: DetectorEmissionPolicy,
        evidence_type: str,
        evidence: Dict[str, Any],
        *,
        description: Optional[str] = None,
    ) -> None:
        signals = self._sparse_signal_dict(signal_map, row_i)
        prior = float(signals.get(emission.name, 0.0) or 0.0)
        if prior >= emission.value:
            return
        signals[emission.name] = max(prior, emission.value)
        self._sparse_explain_list(explain_map, row_i).append({
            "rule_id": emission.rule_id,
            "description": description or emission.description,
            "confidence": emission.confidence,
            "evidence_type": evidence_type,
            "signals": [emission.name],
            "evidence": evidence,
        })

    def _apply_ransomware_impact_policy_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
    ) -> None:
        policy = self.detector_policy.ransomware_impact
        if not policy.enabled or len(df) == 0:
            return
        timestamps = list(df.index)
        row_evidence_values = {
            item.name: _column_values_or_none(df, item.fields[0])
            for item in policy.evidence
            if item.resolver == "row_field"
        }
        paths = _best_effort_file_path_vectorised(
            df, policy.note_path_fields
        ).to_numpy(copy=False)
        support_events: List[Tuple[int, pd.Timestamp]] = []
        note_events: List[Tuple[int, pd.Timestamp]] = []
        for row_i, ts in enumerate(timestamps):
            signals = signal_map.get(row_i) or {}
            if any(
                float(signals.get(name, 0.0) or 0.0)
                > policy.support_minimum_signal_value_exclusive
                for name in policy.support_signals
            ):
                support_events.append((row_i, ts))
            path = _safe_str(paths[row_i]).strip().lower().replace("\\", "/")
            basename = os.path.basename(path) if path else ""
            if path and any(token in basename for token in policy.note_basename_tokens):
                note_events.append((row_i, ts))
        support_times = [ts for _, ts in support_events]
        note_times = [ts for _, ts in note_events]
        window = pd.Timedelta(policy.lookback)
        for row_i, ts in enumerate(timestamps):
            signals = signal_map.get(row_i) or {}
            matched_sources = tuple(
                name for name in policy.source_signals
                if float(signals.get(name, 0.0) or 0.0)
                > policy.source_minimum_signal_value_exclusive
            )
            if not matched_sources:
                continue
            derived_evidence: Dict[str, Any] = {
                "matched_source_signals": ",".join(sorted(matched_sources)),
                "support_timestamp": "",
                "ransom_note_timestamp": "",
            }
            lo = bisect.bisect_left(support_times, ts - window)
            hi = bisect.bisect_right(support_times, ts)
            description = policy.support_description
            if lo < hi:
                derived_evidence["support_timestamp"] = support_events[lo][1].isoformat()
            else:
                lo = bisect.bisect_left(note_times, ts)
                hi = bisect.bisect_right(note_times, ts + window)
                if lo >= hi:
                    continue
                derived_evidence["ransom_note_timestamp"] = note_events[lo][1].isoformat()
                description = policy.note_description
            evidence: Dict[str, Any] = {}
            for item in policy.evidence:
                if item.resolver == "row_field":
                    value = _safe_str(row_evidence_values[item.name][row_i]).strip()
                else:
                    value = derived_evidence[item.resolver]
                if item.max_chars is not None:
                    value = _safe_str(value)[:item.max_chars]
                evidence[item.name] = value
            self._emit_temporal_policy_signal(
                signal_map,
                explain_map,
                row_i,
                policy.emission,
                policy.evidence_type,
                evidence,
                description=description,
            )

    def _apply_counted_signal_window_policies_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
    ) -> None:
        timestamps = list(df.index)
        for definition in self.detector_policy.definitions(
            executor="counted_signal_window", enabled_only=True
        ):
            policy = definition.payload
            minimum_signal_value = policy.minimum_signal_value_exclusive
            row_evidence_values = {
                item.name: _column_values_or_none(df, item.fields[0])
                for item in policy.evidence
                if item.resolver == "row_field"
            }

            def admitted(signals: Dict[str, Any], names: Iterable[str]) -> bool:
                return any(
                    float(signals.get(name, 0.0) or 0.0) > minimum_signal_value
                    for name in names
                )

            counted_events = [
                (row_i, ts)
                for row_i, ts in enumerate(timestamps)
                if admitted(
                    signal_map.get(row_i) or {},
                    policy.counted_signals,
                )
            ]
            counted_times = [ts for _, ts in counted_events]
            window_support_events = [
                (row_i, ts)
                for row_i, ts in enumerate(timestamps)
                if admitted(
                    signal_map.get(row_i) or {},
                    policy.window_support_signals,
                )
            ]
            support_times = [ts for _, ts in window_support_events]
            window = pd.Timedelta(policy.lookback)
            for row_i, ts in enumerate(timestamps):
                lo = bisect.bisect_left(counted_times, ts - window)
                hi = bisect.bisect_right(counted_times, ts)
                count = hi - lo
                if count < policy.threshold:
                    continue
                support_lo = bisect.bisect_left(support_times, ts - window)
                support_hi = bisect.bisect_right(support_times, ts)
                signals = signal_map.get(row_i) or {}
                current_row_roles = {
                    "counted": admitted(signals, policy.counted_signals),
                    "current_support": admitted(
                        signals, policy.current_support_signals
                    ),
                    "window_support": admitted(
                        signals, policy.window_support_signals
                    ),
                }
                if not any(
                    current_row_roles[role] for role in policy.emit_on_roles
                ):
                    continue
                current_support = admitted(
                    signals,
                    policy.current_support_signals,
                )
                if support_lo >= support_hi and not current_support:
                    continue
                derived_evidence = {
                    "count_in_window": count,
                    "window_seconds": int(window.total_seconds()),
                }
                evidence: Dict[str, Any] = {}
                for item in policy.evidence:
                    if item.resolver == "row_field":
                        value = _safe_str(
                            row_evidence_values[item.name][row_i]
                        ).strip()
                    else:
                        value = derived_evidence[item.resolver]
                    if item.max_chars is not None:
                        value = _safe_str(value)[:item.max_chars]
                    evidence[item.name] = value
                self._emit_temporal_policy_signal(
                    signal_map,
                    explain_map,
                    row_i,
                    policy.emission,
                    policy.evidence_type,
                    evidence,
                )

    def _apply_artifact_follow_on_policies_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
    ) -> None:
        timestamps = list(df.index)
        for definition in self.detector_policy.definitions(
            executor="artifact_follow_on_sequence", enabled_only=True
        ):
            policy = definition.payload
            row_evidence_values = {
                item.name: _column_values_or_none(df, item.fields[0])
                for item in policy.evidence
                if item.resolver == "row_field"
            }
            paths = _best_effort_file_path_vectorised(
                df, policy.path_fields
            ).to_numpy(copy=False)
            text_arrays = tuple(
                _normalised_text_array(df, field, lower=True)
                for field in policy.text_fields
            )
            combined_text: List[str] = []
            labels_by_row: List[Set[str]] = []
            follow_events: List[Tuple[int, pd.Timestamp, Set[str]]] = []
            for row_i, ts in enumerate(timestamps):
                path = _safe_str(paths[row_i]).strip().lower().replace("\\", "/")
                basename = os.path.basename(path) if path else ""
                combined = " ".join(
                    part for part in (
                        *(values[row_i] for values in text_arrays),
                        path,
                        basename,
                    ) if part
                ).replace("\\ ", " ")
                combined_text.append(combined)
                labels = {
                    token for token in policy.source_label_tokens if token in combined
                }
                labels_by_row.append(labels)
                signals = signal_map.get(row_i) or {}
                qualification_facts = {
                    "copy_command": any(
                        token in combined for token in policy.copy_tokens
                    ),
                    "copy_text_support": any(
                        token in combined
                        for token in policy.copy_text_support_tokens
                    ),
                    "copy_signal_support": any(
                        float(signals.get(name, 0.0) or 0.0)
                        > policy.copy_support_minimum_signal_value_exclusive
                        for name in policy.copy_support_signals
                    ),
                    "follow_on_signal": any(
                        float(signals.get(name, 0.0) or 0.0)
                        > policy.follow_on_minimum_signal_value_exclusive
                        for name in policy.follow_on_signals
                    ),
                }
                if policy.follow_on_qualification.matches(qualification_facts):
                    follow_events.append((row_i, ts, labels))
            follow_times = [ts for _, ts, _ in follow_events]
            window = pd.Timedelta(policy.lookback)
            for row_i, ts in enumerate(timestamps):
                signals = signal_map.get(row_i) or {}
                if not any(
                    float(signals.get(name, 0.0) or 0.0)
                    > policy.source_minimum_signal_value_exclusive
                    for name in policy.source_signals
                ):
                    continue
                source_labels = labels_by_row[row_i]
                lo = bisect.bisect_left(follow_times, ts)
                hi = bisect.bisect_right(follow_times, ts + window)
                matched = False
                for event_index in range(lo, hi):
                    follow_labels = follow_events[event_index][2]
                    if source_labels:
                        if source_labels.intersection(follow_labels):
                            matched = True
                            break
                    elif policy.allow_unlabelled_follow_on:
                        matched = True
                        break
                if not matched:
                    continue
                derived_evidence = {
                    "source_timestamp": ts.isoformat(),
                    "window_seconds": int(window.total_seconds()),
                }
                evidence: Dict[str, Any] = {}
                for item in policy.evidence:
                    if item.resolver == "row_field":
                        value = _safe_str(
                            row_evidence_values[item.name][row_i]
                        ).strip()
                    else:
                        value = derived_evidence[item.resolver]
                    if item.max_chars is not None:
                        value = _safe_str(value)[:item.max_chars]
                    evidence[item.name] = value
                self._emit_temporal_policy_signal(
                    signal_map,
                    explain_map,
                    row_i,
                    policy.emission,
                    policy.evidence_type,
                    evidence,
                )

    def _apply_deadbox_temporal_composites_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
    ) -> None:
        if len(df) == 0 or not isinstance(df.index, pd.DatetimeIndex):
            return

        download_policy = self.detector_policy.download_to_execution
        sequence_definitions = self.detector_policy.definitions(
            executor="signal_sequence",
            enabled_only=True,
        )
        download_window = pd.Timedelta(download_policy.lookback)
        # Hostname is unreliable in dead-box images: blank, inconsistent, or
        # filled with crud.  Use a single global sentinel so all events
        # correlate as one host (which is the ground truth for a single image).
        # The raw hostname is kept only for evidence/explain output.
        _DEADBOX_HOST_SENTINEL = "__deadbox__"
        host_vals = (
            df[download_policy.host_field].values
            if download_policy.host_field in df.columns
            else np.array([None] * len(df), dtype=object)
        )
        sequence_key_vals = {
            definition.detector_id: (
                df[definition.payload.key_field].values
                if definition.payload.key_scope == "field"
                and definition.payload.key_field in df.columns
                else np.array([None] * len(df), dtype=object)
            )
            for definition in sequence_definitions
        }
        sequence_target_evidence_vals = {
            (definition.detector_id, evidence_value.name): (
                df[evidence_value.fields[0]].values
                if evidence_value.resolver == "target_field"
                and evidence_value.fields[0] in df.columns
                else np.array([None] * len(df), dtype=object)
            )
            for definition in sequence_definitions
            for evidence_value in definition.payload.evidence
            if evidence_value.resolver == "target_field"
        }
        sequence_target_context_paths = {
            definition.detector_id: [
                _safe_str(value).strip().lower().replace("\\", "/")
                for value in _best_effort_file_path_vectorised(
                    df, definition.payload.target_context.path_fields
                ).to_numpy(copy=False)
            ]
            for definition in sequence_definitions
            if definition.payload.target_context is not None
            and definition.payload.target_context.path_fields
        }
        sequence_target_context_text = {}
        for definition in sequence_definitions:
            context = definition.payload.target_context
            if context is None or not context.combined_text_fields:
                continue
            context_arrays = [
                _normalised_text_array(df, field, lower=True)
                for field in context.combined_text_fields
            ]
            sequence_target_context_text[definition.detector_id] = [
                " ".join(
                    _safe_str(values[row_i]).strip()
                    for values in context_arrays
                    if _safe_str(values[row_i]).strip()
                ).replace("\\ ", " ")
                for row_i in range(len(df))
            ]
        download_path_vals = _best_effort_file_path_vectorised(
            df, download_policy.artifact_fields
        ).to_numpy(copy=False)
        download_path_norm = [
            _safe_str(v).strip().lower().replace("\\", "/")
            for v in download_path_vals
        ]
        download_events: Dict[Tuple[str, str], List[Tuple[int, pd.Timestamp]]] = {}
        sequence_events: Dict[
            str,
            Dict[str, List[Tuple[int, pd.Timestamp]]],
        ] = {definition.detector_id: {} for definition in sequence_definitions}
        n_rows = len(df)
        _cached_download_host = [None] * n_rows
        _cached_sequence_keys: Dict[str, List[Optional[str]]] = {
            definition.detector_id: [None] * n_rows
            for definition in sequence_definitions
        }
        _cached_download_base = [None] * n_rows
        ts_vals = list(df.index)

        for row_i in range(n_rows):
            signals = signal_map.get(row_i) or {}
            raw_host = _safe_str(host_vals[row_i]).strip()
            download_host = (
                _DEADBOX_HOST_SENTINEL
                if download_policy.key_scope == "deadbox_global"
                else raw_host.lower()
            )
            sequence_keys = {
                definition.detector_id: (
                    _DEADBOX_HOST_SENTINEL
                    if definition.payload.key_scope == "deadbox_global"
                    else _safe_str(
                        sequence_key_vals[definition.detector_id][row_i]
                    ).strip().lower()
                )
                for definition in sequence_definitions
            }
            download_path = download_path_norm[row_i]
            download_base = os.path.basename(download_path) if download_path else ""
            ts = ts_vals[row_i]
            _cached_download_host[row_i] = download_host
            for detector_id, sequence_key in sequence_keys.items():
                _cached_sequence_keys[detector_id][row_i] = sequence_key
            _cached_download_base[row_i] = download_base

            if download_policy.enabled and download_base and any(
                float(signals.get(name, 0.0) or 0.0)
                > download_policy.source_minimum_signal_value_exclusive
                for name in download_policy.source_signals
            ):
                download_events.setdefault((download_host, download_base), []).append((row_i, ts))
            for definition in sequence_definitions:
                policy = definition.payload
                sequence_key = sequence_keys[definition.detector_id]
                if policy.key_scope == "field" and not sequence_key:
                    continue
                if any(
                    float(signals.get(name, 0.0) or 0.0)
                    > policy.source_minimum_signal_value_exclusive
                    for name in policy.source_signals
                ):
                    detector_events = sequence_events[definition.detector_id]
                    detector_events.setdefault(
                        sequence_key,
                        [],
                    ).append((row_i, ts))

        # ── Build sorted timestamp indices for O(log n) window lookups ─────
        # For each accumulator, extract per-host sorted timestamp arrays so
        # pass 2 can use bisect instead of linear scans.  This converts O(n²)
        # temporal window checks into O(n log n) overall.

        def _build_ts_index_2(events_dict):
            """Build {host: sorted_ts_list} from 2-tuple accumulators."""
            return {k: [t for _, t in v] for k, v in events_dict.items()}

        download_ts_idx = _build_ts_index_2(download_events)
        sequence_ts_indexes = {
            detector_id: _build_ts_index_2(detector_events)
            for detector_id, detector_events in sequence_events.items()
        }
        def _download_in_window(key, ts):
            """Apply the configured download-sequence boundary and source selection."""
            sorted_ts = download_ts_idx.get(key)
            if not sorted_ts:
                return False, None
            lo = bisect.bisect_left(sorted_ts, ts - download_window)
            if download_policy.ordering == "source_before_target":
                hi = bisect.bisect_left(sorted_ts, ts)
            else:
                hi = bisect.bisect_right(sorted_ts, ts)
            if lo >= hi:
                return False, None
            selected = lo if download_policy.source_selection == "earliest_in_window" else hi - 1
            return True, download_events[key][selected]

        def _configured_sequence_in_window(policy, ts_idx, events_dict, key, ts):
            """Apply a configured signal-sequence boundary and source selection."""
            sorted_ts = ts_idx.get(key)
            if not sorted_ts:
                return False, None
            lo = bisect.bisect_left(sorted_ts, ts - pd.Timedelta(policy.lookback))
            if policy.ordering == "source_before_target":
                hi = bisect.bisect_left(sorted_ts, ts)
            else:
                hi = bisect.bisect_right(sorted_ts, ts)
            if lo >= hi:
                return False, None
            selected = lo if policy.source_selection == "earliest_in_window" else hi - 1
            return True, events_dict[key][selected]

        for row_i in range(n_rows):
            signals = signal_map.get(row_i) or {}
            download_host = _cached_download_host[row_i]
            raw_hostname = _safe_str(host_vals[row_i]).strip()  # original for evidence
            download_base = _cached_download_base[row_i]
            ts = ts_vals[row_i]

            def emit(
                signal_name: str,
                description: str,
                confidence: str,
                evidence: Dict[str, Any],
                *,
                value: float = 1.0,
                rule_id: Optional[str] = None,
                evidence_type: str = "contextual",
            ) -> None:
                sig = self._sparse_signal_dict(signal_map, row_i)
                prior = float(sig.get(signal_name, 0.0) or 0.0)
                if prior >= value:
                    return
                sig[signal_name] = max(prior, value)
                expl = self._sparse_explain_list(explain_map, row_i)
                expl.append({
                    "rule_id": rule_id or signal_name.upper(),
                    "description": description,
                    "confidence": confidence,
                    "evidence_type": evidence_type,
                    "signals": [signal_name],
                    "evidence": evidence,
                })

            download_execution_like = any(
                float(signals.get(name, 0.0) or 0.0)
                > download_policy.target_minimum_signal_value_exclusive
                for name in download_policy.target_signals
            )
            if download_policy.enabled and download_base and download_execution_like:
                found, ev = _download_in_window((download_host, download_base), ts)
                if found:
                    dl_ts = ev[1]
                    download_evidence_values = {
                        "filename": download_base,
                        "download_timestamp": dl_ts.isoformat(),
                        "execution_timestamp": ts.isoformat(),
                        "hostname": raw_hostname,
                    }
                    evidence = {
                        key: download_evidence_values[key]
                        for key in download_policy.evidence
                    }
                    for emission in download_policy.emissions:
                        emit(
                            emission.name,
                            emission.description,
                            emission.confidence,
                            evidence,
                            value=emission.value,
                            rule_id=emission.rule_id,
                            evidence_type=download_policy.evidence_type,
                        )

            for definition in sequence_definitions:
                policy = definition.payload
                target_matched = any(
                    float(signals.get(name, 0.0) or 0.0)
                    > policy.target_minimum_signal_value_exclusive
                    for name in policy.target_signals
                )
                if not target_matched:
                    continue
                target_context = policy.target_context
                if target_context is not None:
                    context_matches: List[bool] = []
                    if target_context.path_contains:
                        context_path = sequence_target_context_paths[
                            definition.detector_id
                        ][row_i]
                        context_matches.append(any(
                            token in context_path
                            for token in target_context.path_contains
                        ))
                    if target_context.combined_text_contains:
                        context_text = sequence_target_context_text[
                            definition.detector_id
                        ][row_i]
                        context_matches.append(any(
                            token in context_text
                            for token in target_context.combined_text_contains
                        ))
                    context_matched = (
                        all(context_matches)
                        if target_context.match == "all"
                        else any(context_matches)
                    )
                    if not context_matched:
                        continue
                detector_id = definition.detector_id
                sequence_key = _cached_sequence_keys[detector_id][row_i]
                if policy.key_scope == "field" and not sequence_key:
                    continue
                found, ev = _configured_sequence_in_window(
                    policy,
                    sequence_ts_indexes[detector_id],
                    sequence_events[detector_id],
                    sequence_key,
                    ts,
                )
                if not found:
                    continue
                source_ts = ev[1]
                evidence: Dict[str, Any] = {}
                for evidence_value in policy.evidence:
                    if evidence_value.resolver == "source_timestamp":
                        resolved: Any = source_ts.isoformat()
                    elif evidence_value.resolver == "target_timestamp":
                        resolved = ts.isoformat()
                    else:
                        resolved = _safe_str(
                            sequence_target_evidence_vals[
                                (detector_id, evidence_value.name)
                            ][row_i]
                        ).strip()
                    if evidence_value.max_chars is not None:
                        resolved = _safe_str(resolved)[:evidence_value.max_chars]
                    evidence[evidence_value.name] = resolved
                for emission in policy.emissions:
                    emit(
                        emission.name,
                        emission.description,
                        emission.confidence,
                        evidence,
                        value=emission.value,
                        rule_id=emission.rule_id,
                        evidence_type=policy.evidence_type,
                    )

        self._apply_ransomware_impact_policy_sparse(df, signal_map, explain_map)
        self._apply_counted_signal_window_policies_sparse(
            df, signal_map, explain_map
        )
        self._apply_artifact_follow_on_policies_sparse(
            df, signal_map, explain_map
        )

    def _inject_av_signal_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
    ) -> None:
        classifier_policy = self.detector_policy.clamav_classification
        if not classifier_policy.enabled:
            return
        if "av_hit" not in df.columns:
            return
        av_vals = df["av_hit"].to_numpy(copy=False)
        filenames = _column_values_or_none(df, "filename")
        avsig_vals = _column_values_or_none(df, "av_signature")
        for i in range(len(df)):
            if not _truthy_like(av_vals[i]):
                continue

            sig = self._sparse_signal_dict(signal_map, i)
            expl = self._sparse_explain_list(explain_map, i)

            raw_sig = _safe_str(avsig_vals[i]).strip()
            parsed = (
                parse_clamav_signature(raw_sig, classifier_policy)
                if raw_sig
                else None
            )
            evidence_values: Dict[str, Any] = {
                "filename": _safe_str(filenames[i]),
                "av_signature": raw_sig if raw_sig else None,
                "platform": parsed.platform if parsed else None,
                "category": parsed.category_token if parsed else None,
                "family": parsed.family if parsed else None,
                "forensic_category": parsed.forensic_category if parsed else None,
            }

            def emit(
                emission: DetectorEmissionPolicy,
                description: str,
                evidence_fields: Tuple[str, ...],
            ) -> None:
                prior = float(sig.get(emission.name, 0.0) or 0.0)
                sig[emission.name] = max(prior, emission.value)
                expl.append({
                    "rule_id": emission.rule_id,
                    "description": description,
                    "confidence": emission.confidence,
                    "evidence_type": classifier_policy.evidence_type,
                    "signals": [emission.name],
                    "evidence": {
                        name: evidence_values[name]
                        for name in evidence_fields
                    },
                })

            if parsed is None:
                emit(
                    classifier_policy.generic_emission,
                    classifier_policy.generic_unclassified_description,
                    classifier_policy.generic_evidence,
                )
                continue

            category_policy = classifier_policy.categories[parsed.forensic_category]
            if not category_policy.suppress_generic:
                emit(
                    classifier_policy.generic_emission,
                    classifier_policy.generic_emission.description.replace(
                        "{forensic_category}",
                        parsed.forensic_category,
                    ),
                    classifier_policy.generic_evidence,
                )
            emit(
                category_policy.emission,
                category_policy.emission.description,
                category_policy.evidence,
            )

    def _inject_yara_signal_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
    ) -> None:
        classifier_policy = self.detector_policy.yara_classification
        if not classifier_policy.enabled:
            return
        if "yara_match_count" not in df.columns:
            return

        # Pre-filter: only iterate rows with yara_match_count > 0
        ymc_arr = pd.to_numeric(df["yara_match_count"], errors="coerce").fillna(0).to_numpy()
        candidate_rows = np.flatnonzero(ymc_arr > 0)
        if len(candidate_rows) == 0:
            return

        ym_vals = df["yara_match"].values if "yara_match" in df.columns else np.array([None] * len(df))

        for i in candidate_rows:
            match_count = int(ymc_arr[i])
            raw_rule_names = extract_yara_rule_names(ym_vals[i])
            rule_names: List[str] = []
            seen_rule_names: Set[str] = set()
            for raw_rule_name in raw_rule_names:
                rule_name = _safe_str(raw_rule_name).strip()
                normalised_rule_name = rule_name.casefold()
                if not rule_name or normalised_rule_name in seen_rule_names:
                    continue
                seen_rule_names.add(normalised_rule_name)
                rule_names.append(rule_name)

            strength_policy = classifier_policy.strength
            if not rule_names:
                base_strength = min(
                    1.0,
                    match_count / float(strength_policy.saturation_count),
                )
                final_strength = (
                    base_strength
                    * strength_policy.unnamed_multiplier
                    * strength_policy.emission.value
                )
                if final_strength > 0.0:
                    sig = self._sparse_signal_dict(signal_map, i)
                    expl = self._sparse_explain_list(explain_map, i)
                    sig[strength_policy.emission.name] = max(
                        float(sig.get(strength_policy.emission.name, 0.0) or 0.0),
                        final_strength,
                    )
                    evidence_values = {
                        "yara_match_count": match_count,
                        "contributing_rule_count": match_count,
                        "strength": final_strength,
                        "best_score": None,
                        "score_multiplier": strength_policy.unnamed_multiplier,
                        "rule_names": [],
                    }
                    expl.append({
                        "rule_id": strength_policy.emission.rule_id,
                        "description": strength_policy.emission.description,
                        "confidence": strength_policy.emission.confidence,
                        "evidence_type": classifier_policy.evidence_type,
                        "signals": [strength_policy.emission.name],
                        "evidence": {
                            name: evidence_values[name]
                            for name in strength_policy.evidence
                        },
                    })
                continue

            category_hits: Dict[str, List[Tuple[str, YaraRuleMeta]]] = {}
            contributing_rule_metadata: List[YaraRuleMeta] = []
            for rn in rule_names:
                meta = self._yara_rule_metadata(rn)
                if meta.category not in classifier_policy.categories:
                    raise ValueError(
                        f"YARA rule {rn!r} resolved unsupported category "
                        f"{meta.category!r}"
                    )
                category_hits.setdefault(meta.category, []).append((rn, meta))
                if classifier_policy.categories[
                    meta.category
                ].contributes_to_strength:
                    contributing_rule_metadata.append(meta)

            contributing_count = len(contributing_rule_metadata)
            best_score = max(
                (int(meta.score) for meta in contributing_rule_metadata),
                default=0,
            )
            refined_strength = (
                min(
                    1.0,
                    contributing_count / float(strength_policy.saturation_count),
                )
                if contributing_count
                else 0.0
            )
            score_multiplier = max(
                strength_policy.minimum_multiplier,
                min(
                    strength_policy.maximum_multiplier,
                    best_score / strength_policy.score_divisor,
                ),
            )
            final_strength = (
                refined_strength
                * score_multiplier
                * strength_policy.emission.value
            )

            sig = self._sparse_signal_dict(signal_map, i)
            expl = self._sparse_explain_list(explain_map, i)
            if final_strength > 0.0:
                sig[strength_policy.emission.name] = max(
                    float(sig.get(strength_policy.emission.name, 0.0) or 0.0),
                    final_strength,
                )
                strength_confidence = (
                    strength_policy.score_confidence.confidence
                    if best_score >= strength_policy.score_confidence.minimum_score
                    else strength_policy.emission.confidence
                )
                strength_evidence_values = {
                    "yara_match_count": match_count,
                    "contributing_rule_count": contributing_count,
                    "strength": final_strength,
                    "best_score": best_score,
                    "score_multiplier": round(score_multiplier, 3),
                    "rule_names": rule_names[:strength_policy.max_rule_names],
                }
                expl.append({
                    "rule_id": strength_policy.emission.rule_id,
                    "description": strength_policy.emission.description,
                    "confidence": strength_confidence,
                    "evidence_type": classifier_policy.evidence_type,
                    "signals": [strength_policy.emission.name],
                    "evidence": {
                        name: strength_evidence_values[name]
                        for name in strength_policy.evidence
                    },
                })

            for category in classifier_policy.category_order:
                rule_metadata = category_hits.get(category)
                if not rule_metadata:
                    continue
                category_policy = classifier_policy.categories[category]
                emission = category_policy.emission
                category_best_score = max(
                    int(meta.score) for _, meta in rule_metadata
                )
                category_best_quality = max(
                    int(meta.quality) for _, meta in rule_metadata
                )
                category_confidence = (
                    category_policy.score_confidence.confidence
                    if category_best_score
                    >= category_policy.score_confidence.minimum_score
                    else emission.confidence
                )
                sig[emission.name] = max(
                    float(sig.get(emission.name, 0.0) or 0.0),
                    emission.value,
                )
                category_rule_names = [name for name, _ in rule_metadata]
                category_evidence_values = {
                    "category": category,
                    "rule_count": len(rule_metadata),
                    "rule_names": category_rule_names[
                        :category_policy.max_rule_names
                    ],
                    "best_score": category_best_score,
                    "best_quality": category_best_quality,
                }
                expl.append({
                    "rule_id": emission.rule_id,
                    "description": emission.description,
                    "confidence": category_confidence,
                    "evidence_type": classifier_policy.evidence_type,
                    "signals": [emission.name],
                    "evidence": {
                        name: category_evidence_values[name]
                        for name in category_policy.evidence
                    },
                })

    def _inject_profile_base_signals_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
    ) -> None:
        policy = self.profiling_policy
        if (
            not policy.enabled
            or policy.activity_deficit_signal not in df.columns
        ):
            return

        activity_deficit_values = self._activity_deficit_values(df)
        if activity_deficit_values is None:
            return
        hour_bins = (
            df[policy.hour_of_week_field].to_numpy(copy=False)
            if policy.hour_of_week_field in df.columns
            else np.full(len(df), None, dtype=object)
        )
        quiet_hours = df.attrs.get("_chronosift_quiet_hours_profile")

        def merge_signal(
            signals: Dict[str, Any],
            name: str,
            value: float,
            merge: str,
        ) -> None:
            prior = float(signals.get(name, 0.0) or 0.0)
            signals[name] = (
                max(prior, value) if merge == "maximum" else prior + value
            )

        for row_i in range(len(df)):
            activity_deficit = float(activity_deficit_values[row_i])
            hour_bin = hour_bins[row_i]
            quiet_hit = bool(
                policy.emit_quiet_signal
                and quiet_hours is not None
                and pd.notna(hour_bin)
                and int(hour_bin) in quiet_hours
            )
            activity_deficit_hit = (
                policy.emit_activity_deficit_signal and activity_deficit > 0.0
            )
            if not activity_deficit_hit and not quiet_hit:
                continue
            signals = self._sparse_signal_dict(signal_map, row_i)
            if activity_deficit_hit:
                merge_signal(
                    signals,
                    policy.activity_deficit_signal,
                    activity_deficit,
                    policy.activity_deficit_signal_merge,
                )
                self._sparse_explain_list(explain_map, row_i).append(
                    _activity_deficit_explain_item(policy)
                )
            if quiet_hit:
                merge_signal(
                    signals,
                    policy.quiet_signal,
                    policy.quiet_signal_value,
                    policy.quiet_signal_merge,
                )
                self._sparse_explain_list(explain_map, row_i).append(
                    _quiet_time_explain_item(policy, int(hour_bin))
                )
    def _append_profile_score_amplifier_explanations_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
    ) -> None:
        policy = self.profiling_policy
        amplifier_policy = policy.score_amplifier
        if (
            not amplifier_policy.enabled
            or policy.activity_deficit_signal not in df.columns
        ):
            return

        activity_deficit_values = self._activity_deficit_values(df)
        if activity_deficit_values is None:
            return
        hour_values = (
            df[policy.hour_of_week_field].to_numpy(copy=False)
            if policy.hour_of_week_field in df.columns
            else np.full(len(df), None, dtype=object)
        )
        manifest = dict(
            df.attrs.get("_chronosift_profile_manifest", {}) or {}
        )
        probabilities = {
            int(key): float(value)
            for key, value in (manifest.get("probabilities", {}) or {}).items()
        }
        upper_bounds = {
            int(key): float(value)
            for key, value in (
                manifest.get("upper_probability_bounds", {}) or {}
            ).items()
        }
        validation = dict(manifest.get("validation", {}) or {})
        if not bool(validation.get("accepted", False)):
            df.attrs.pop("_chronosift_quiet_hours_profile", None)
            return
        reference_probability = float(
            validation.get("reference_probability", 1.0 / 168.0)
        )
        validation_lower_bound = float(
            validation.get("lower_confidence_bound", 0.0) or 0.0
        )
        complete_week_count = int(
            validation.get("complete_week_count", 0) or 0
        )
        explanation = amplifier_policy.explanation
        for i in sorted(signal_map):
            sig = signal_map.get(i)
            if not isinstance(sig, dict):
                continue
            activity_deficit = float(
                np.clip(activity_deficit_values[i], 0.0, 1.0)
            )
            if activity_deficit <= 0.0 or self._score_signals(sig) <= 0.0:
                continue
            hour_value = hour_values[i]
            hour = int(hour_value) if not _is_null(hour_value) else -1
            evidence_values = {
                "hour_of_week": hour,
                "activity_probability": probabilities.get(hour, 0.0),
                "upper_probability_bound": upper_bounds.get(hour, 0.0),
                "reference_probability": reference_probability,
                "activity_deficit": activity_deficit,
                "multiplier": 1.0 + activity_deficit,
                "validation_lower_bound": validation_lower_bound,
                "complete_week_count": complete_week_count,
            }
            weighted_signals = sorted(
                str(name)
                for name, value in sig.items()
                if (
                    isinstance(value, (int, float))
                    and float(value) != 0.0
                    and float(self.weights.get(str(name).strip().lower(), 0.0))
                    != 0.0
                )
            )
            self._sparse_explain_list(explain_map, i).append({
                "rule_id": explanation.rule_id,
                "description": explanation.description,
                "confidence": explanation.confidence,
                "evidence_type": explanation.evidence_type,
                "signals": weighted_signals,
                "evidence": {
                    name: evidence_values[name] for name in explanation.evidence
                },
            })

        df.attrs.pop("_chronosift_quiet_hours_profile", None)

    def _apply_private_ip_continuity_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
        carried_last: Optional[Dict[tuple, Dict[str, Any]]] = None,
    ) -> None:
        policy = self.detector_policy.ip_scope_continuity
        if not policy.enabled:
            return
        if (
            not any(field_name in df.columns for field_name in policy.ip_fields)
            or not set(policy.key_fields).issubset(df.columns)
        ):
            return

        key_vals = [_normalised_text_array(df, k) for k in policy.key_fields]
        ip_vals = _first_nonempty_normalised_text_array(
            df, policy.ip_fields
        )
        times = df.index

        groups: Dict[Tuple[str, ...], List[int]] = {}
        for i in range(len(df)):
            actor = tuple(col[i] for col in key_vals)
            if all(not part for part in actor):
                continue
            groups.setdefault(actor, []).append(i)

        state: Dict[tuple, Dict[str, Any]] = (
            carried_last if carried_last is not None else {}
        )

        for actor, idxs in groups.items():
            for row_i in idxs:
                cur_ip = ip_vals[row_i]
                cur_scope = _ip_scope(cur_ip)
                if not cur_scope:
                    continue

                cur_subnet = _ip_subnet_label(
                    cur_ip,
                    prefix_v4=policy.subnet_prefix_v4,
                    prefix_v6=policy.subnet_prefix_v6,
                )
                t_now = times[row_i]
                observation = {
                    "ip": cur_ip,
                    "scope": cur_scope,
                    "subnet": cur_subnet,
                    "ts": t_now,
                }
                actor_state = state.get(actor)
                if actor_state is None:
                    state[actor] = {
                        "retained_reference": observation,
                        "previous_observation": observation,
                    }
                    continue

                reference = actor_state[
                    "retained_reference"
                    if policy.reference_selection == "retained_reference"
                    else "previous_observation"
                ]
                prev_ip = reference["ip"]
                prev_scope = reference["scope"]
                prev_subnet = reference["subnet"]
                delta = t_now - reference["ts"]
                if policy.lookback_window_bounds == "closed":
                    within_lookback = timedelta(0) <= delta <= policy.lookback
                else:
                    within_lookback = timedelta(0) < delta < policy.lookback
                address_change_matches = (
                    cur_ip != prev_ip
                    if policy.require_address_change
                    else True
                )
                comparison_eligible = within_lookback and address_change_matches
                transition_matched = False
                if comparison_eligible:
                    evidence_values = {
                        "actor_key": "|".join(actor),
                        "previous_ip": prev_ip,
                        "current_ip": cur_ip,
                        "delta_seconds": int(delta.total_seconds()),
                        "previous_subnet": prev_subnet,
                        "current_subnet": cur_subnet,
                        "previous_scope": prev_scope,
                        "current_scope": cur_scope,
                        "key_fields": "|".join(policy.key_fields),
                    }
                    for transition in policy.transition_rules:
                        if (
                            transition.previous_scope != prev_scope
                            or transition.current_scope != cur_scope
                        ):
                            continue
                        if transition.subnet_change == "required" and not (
                            prev_subnet
                            and cur_subnet
                            and prev_subnet != cur_subnet
                        ):
                            continue
                        transition_matched = True
                        emission = policy.emissions_by_semantic[
                            transition.emission_id
                        ]
                        sig = self._sparse_signal_dict(signal_map, row_i)
                        expl = self._sparse_explain_list(explain_map, row_i)
                        sig[emission.name] = max(
                            float(sig.get(emission.name, 0.0) or 0.0),
                            emission.value,
                        )
                        expl.append({
                            "rule_id": emission.rule_id,
                            "description": emission.description,
                            "confidence": emission.confidence,
                            "evidence_type": policy.evidence_type,
                            "signals": [emission.name],
                            "evidence": _resolve_continuity_evidence(
                                policy.evidence_by_semantic[
                                    transition.emission_id
                                ],
                                evidence_values,
                            ),
                        })
                        if policy.branch_mode == "first_match":
                            break

                actor_state["previous_observation"] = observation
                should_update_reference = (
                    policy.state_update == "every_valid_observation"
                    or (
                        policy.state_update == "after_in_window_comparison"
                        and comparison_eligible
                    )
                    or (
                        policy.state_update == "after_transition_match"
                        and transition_matched
                    )
                )
                if should_update_reference:
                    actor_state["retained_reference"] = observation

    def _get_signal_value_sparse(self, signal_map: Dict[int, Dict[str, Any]], row_i: int, name: str) -> float:
        signals = signal_map.get(row_i, {})
        v = signals.get(name, 0.0)
        try:
            return float(v) if isinstance(v, (int, float)) else 0.0
        except Exception:
            return 0.0

    def _is_temporal_eligible_signal(self, name: str) -> bool:
        sig = str(name).strip().lower()
        if not sig:
            return False
        return sig not in self.temporal_ineligible_signals

    def _temporal_emit_sparse(
        self,
        tr: TemporalRule,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
        row_i: int,
        key_tuple: Tuple[str, ...],
    ) -> None:
        sig = self._sparse_signal_dict(signal_map, row_i)
        expl = self._sparse_explain_list(explain_map, row_i)

        for es in tr.emit_signals:
            _merge_rule_signal_value(
                sig,
                es,
                self.rule_signal_merge_policy.temporal_rules,
            )

        expl.append({
            "rule_id": tr.rule_id,
            "description": tr.description,
            "confidence": tr.confidence,
            "evidence_type": "temporal",
            "signals": [str(es.name).strip() for es in tr.emit_signals if str(es.name).strip()],
            "evidence": {
                "temporal": tr.mode,
                "key_by": ",".join(tr.key_by),
                "key": "|".join(key_tuple),
                "lookback_seconds": int(tr.lookback.total_seconds()),
            },
        })

    def _apply_temporal_rules_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
    ) -> None:
        if not self.temporal_rules or len(df) == 0:
            return
        if not isinstance(df.index, pd.DatetimeIndex):
            return

        cols_present = set(df.columns)
        nrows = len(df)
        time_values = df.index.asi8

        thresholds_by_signal: Dict[str, Set[float]] = {}
        for tr in self.temporal_rules:
            temporal_inputs: List[str] = []
            if tr.mode == "cooccur":
                temporal_inputs = [need.signal for need in tr.cooccur_all if getattr(need, "signal", None)]
            elif tr.mode == "sequence":
                temporal_inputs = [step.signal for step in tr.sequence if getattr(step, "signal", None)]
            if temporal_inputs and not all(self._is_temporal_eligible_signal(sig) for sig in temporal_inputs):
                continue
            for signal_name in temporal_inputs:
                thresholds_by_signal.setdefault(signal_name, set()).add(
                    tr.minimum_signal_value_exclusive
                )

        signal_hit_flags: Dict[Tuple[str, float], bytearray] = {
            (name, minimum): bytearray(nrows)
            for name, thresholds in thresholds_by_signal.items()
            for minimum in thresholds
            if name
        }
        signal_has_hits: Set[Tuple[str, float]] = set()

        def _signal_admitted(value: Any, minimum: float) -> bool:
            numeric = _safe_num(value)
            return numeric is not None and numeric > minimum

        def _refresh_needed_signal_hits(row_i: int) -> None:
            if not signal_hit_flags or not (0 <= row_i < nrows):
                return
            signals = signal_map.get(row_i, {})
            if not isinstance(signals, dict):
                return
            for name, value in signals.items():
                for minimum in thresholds_by_signal.get(name, ()):
                    signal_key = (name, minimum)
                    if _signal_admitted(value, minimum):
                        signal_hit_flags[signal_key][row_i] = 1
                        signal_has_hits.add(signal_key)

        if signal_hit_flags:
            for pos in signal_map.keys():
                _refresh_needed_signal_hits(pos)

        normalised_col_cache: Dict[str, np.ndarray] = {}
        normalised_code_cache: Dict[str, np.ndarray] = {}
        group_cache: Dict[Tuple[str, ...], Optional[TemporalGroupPlan]] = {}

        def _normalised_values(col: str) -> np.ndarray:
            cached = normalised_col_cache.get(col)
            if cached is not None:
                return cached
            values = df[col].astype("string").fillna("").str.strip()
            placeholder_mask = values.str.lower().isin(PLACEHOLDER_STRINGS)
            if bool(placeholder_mask.any()):
                values = values.mask(placeholder_mask, "")
            arr = values.to_numpy(dtype=object, na_value="")
            normalised_col_cache[col] = arr
            return arr

        def _normalised_codes(col: str) -> np.ndarray:
            cached = normalised_code_cache.get(col)
            if cached is not None:
                return cached
            values = _normalised_values(col)
            codes, _ = pd.factorize(values, sort=False)
            codes = codes.astype(np.int64, copy=False)
            empty_mask = values == ""
            if bool(np.any(empty_mask)):
                codes[empty_mask] = -1
            normalised_code_cache[col] = codes
            return codes

        def _group_plan(key_by_tuple: Tuple[str, ...]) -> Optional[TemporalGroupPlan]:
            if key_by_tuple in group_cache:
                return group_cache[key_by_tuple]
            if not key_by_tuple or any(k not in cols_present for k in key_by_tuple):
                group_cache[key_by_tuple] = None
                return None

            key_code_columns = [_normalised_codes(k) for k in key_by_tuple]
            valid_mask = np.ones(nrows, dtype=bool)
            for codes in key_code_columns:
                valid_mask &= codes >= 0

            valid_rows = np.flatnonzero(valid_mask)
            if valid_rows.size == 0:
                plan = TemporalGroupPlan(
                    ordered_rows=np.empty(0, dtype=np.int64),
                    group_slices=[],
                    groups_seen=0,
                    largest_group=0,
                )
                group_cache[key_by_tuple] = plan
                return plan

            valid_code_columns = [codes[valid_rows] for codes in key_code_columns]
            order = np.arange(valid_rows.size, dtype=np.int64)
            for valid_codes in reversed(valid_code_columns):
                order = order[np.argsort(valid_codes[order], kind="stable")]

            ordered_rows = valid_rows[order]
            ordered_code_columns = [valid_codes[order] for valid_codes in valid_code_columns]
            group_start_mask = np.zeros(ordered_rows.size, dtype=bool)
            group_start_mask[0] = True
            for ordered_codes in ordered_code_columns:
                group_start_mask[1:] |= ordered_codes[1:] != ordered_codes[:-1]

            group_starts = np.flatnonzero(group_start_mask)
            group_ends = np.empty_like(group_starts)
            if group_starts.size > 1:
                group_ends[:-1] = group_starts[1:]
            group_ends[-1] = ordered_rows.size

            key_value_columns = [_normalised_values(k) for k in key_by_tuple]
            group_slices: List[Tuple[int, int, Tuple[str, ...]]] = []
            largest_group = 0
            for idx, start in enumerate(group_starts):
                end = int(group_ends[idx])
                start = int(start)
                first_row = int(ordered_rows[start])
                key_tuple = tuple(str(col_values[first_row]) for col_values in key_value_columns)
                group_slices.append((start, end, key_tuple))
                if (end - start) > largest_group:
                    largest_group = end - start

            plan = TemporalGroupPlan(
                ordered_rows=ordered_rows,
                group_slices=group_slices,
                groups_seen=len(group_slices),
                largest_group=largest_group,
            )
            group_cache[key_by_tuple] = plan
            return plan

        for tr in self.temporal_rules:
            rule_start = time.perf_counter()
            emitted = 0
            temporal_inputs: List[str] = []
            if tr.mode == "cooccur":
                temporal_inputs = [need.signal for need in tr.cooccur_all if getattr(need, "signal", None)]
            elif tr.mode == "sequence":
                temporal_inputs = [step.signal for step in tr.sequence if getattr(step, "signal", None)]
            if temporal_inputs and not all(self._is_temporal_eligible_signal(sig) for sig in temporal_inputs):
                continue

            key_by_tuple = tuple(str(k).strip() for k in tr.key_by if str(k).strip())
            if not key_by_tuple:
                continue

            group_plan = _group_plan(key_by_tuple)
            if group_plan is None:
                continue

            ordered_rows = group_plan.ordered_rows
            group_slices = group_plan.group_slices
            groups_seen = group_plan.groups_seen
            largest_group = group_plan.largest_group
            lookback_ticks = _timedelta_ticks_for_datetime_index(
                tr.lookback, df.index
            )
            lower_bound_inclusive = tr.lookback_lower_bound == "inclusive"

            def outside_lookback(delta_ticks: int) -> bool:
                return (
                    delta_ticks > lookback_ticks
                    if lower_bound_inclusive
                    else delta_ticks >= lookback_ticks
                )

            if tr.mode == "cooccur":
                needs = [need for need in tr.cooccur_all if getattr(need, "signal", None)]
                need_names = [need.signal for need in needs]
                signal_keys = [
                    (name, tr.minimum_signal_value_exclusive)
                    for name in need_names
                ]
                if needs and all(key in signal_has_hits for key in signal_keys):
                    need_flags = [signal_hit_flags[key] for key in signal_keys]
                    need_counts = [max(int(getattr(need, "min_count", 1)), 1) for need in needs]

                    for start, end, key_tuple in group_slices:
                        left = 0
                        counts = [0] * len(need_flags)
                        idxs = ordered_rows[start:end]
                        for right, row_pos in enumerate(idxs):
                            row_i = int(row_pos)
                            t_now = int(time_values[row_i])
                            while left < right and (
                                outside_lookback(
                                    t_now - int(time_values[int(idxs[left])])
                                )
                            ):
                                left_row = int(idxs[left])
                                for need_i, flags in enumerate(need_flags):
                                    if flags[left_row]:
                                        counts[need_i] -= 1
                                left += 1

                            for need_i, flags in enumerate(need_flags):
                                if flags[row_i]:
                                    counts[need_i] += 1

                            if not any(flags[row_i] for flags in need_flags):
                                continue

                            matched = True
                            for need_i, min_count in enumerate(need_counts):
                                if counts[need_i] < min_count:
                                    matched = False
                                    break
                            if matched:
                                emit_row_i = row_i
                                if tr.emit_on == "window_start":
                                    for anchor_pos in range(left, right + 1):
                                        anchor_row_i = int(idxs[anchor_pos])
                                        if any(
                                            flags[anchor_row_i]
                                            for flags in need_flags
                                        ):
                                            emit_row_i = anchor_row_i
                                            break
                                self._temporal_emit_sparse(
                                    tr, signal_map, explain_map,
                                    emit_row_i, key_tuple,
                                )
                                _refresh_needed_signal_hits(emit_row_i)
                                emitted += 1

            elif tr.mode == "sequence":
                expanded_steps: List[str] = []
                for step in tr.sequence:
                    if not getattr(step, "signal", None):
                        continue
                    expanded_steps.extend([step.signal] * max(int(getattr(step, "min_count", 1)), 1))

                signal_keys = [
                    (name, tr.minimum_signal_value_exclusive)
                    for name in expanded_steps
                ]
                if expanded_steps and all(
                    key in signal_has_hits for key in set(signal_keys)
                ):
                    step_flags = [signal_hit_flags[key] for key in signal_keys]
                    last_step = len(step_flags) - 1

                    for start, end, key_tuple in group_slices:
                        left = 0
                        latest_start = [-1] * len(step_flags)
                        idxs = ordered_rows[start:end]

                        for right, row_pos in enumerate(idxs):
                            row_i = int(row_pos)
                            t_now = int(time_values[row_i])
                            while left < right and (
                                outside_lookback(
                                    t_now - int(time_values[int(idxs[left])])
                                )
                            ):
                                left += 1

                            for step_i in range(last_step, -1, -1):
                                if not step_flags[step_i][row_i]:
                                    continue
                                if step_i == 0:
                                    if right > latest_start[0]:
                                        latest_start[0] = right
                                else:
                                    prev_start = latest_start[step_i - 1]
                                    if prev_start >= 0 and prev_start > latest_start[step_i]:
                                        latest_start[step_i] = prev_start

                            if step_flags[last_step][row_i] and latest_start[last_step] >= left:
                                emit_row_i = (
                                    int(idxs[latest_start[last_step]])
                                    if tr.emit_on == "sequence_start"
                                    else row_i
                                )
                                self._temporal_emit_sparse(
                                    tr, signal_map, explain_map,
                                    emit_row_i, key_tuple,
                                )
                                _refresh_needed_signal_hits(emit_row_i)
                                emitted += 1

            elif tr.mode in {"first_seen_value", "change_detected"}:
                if tr.field and tr.field in cols_present:
                    field_values = _normalised_values(tr.field)
                    observe_empty = (
                        tr.condition_empty_value_behavior == "observe"
                    )

                    for start, end, key_tuple in group_slices:
                        left = 0
                        seen_counts: Dict[str, int] = {}
                        observation_positions: List[int] = []
                        head = 0
                        idxs = ordered_rows[start:end]

                        for right, row_pos in enumerate(idxs):
                            row_i = int(row_pos)
                            t_now = int(time_values[row_i])
                            while left < right and (
                                outside_lookback(
                                    t_now - int(time_values[int(idxs[left])])
                                )
                            ):
                                old_val = field_values[int(idxs[left])]
                                if old_val or observe_empty:
                                    remaining = seen_counts.get(old_val, 0) - 1
                                    if remaining > 0:
                                        seen_counts[old_val] = remaining
                                    else:
                                        seen_counts.pop(old_val, None)
                                if (
                                    head < len(observation_positions)
                                    and observation_positions[head] == left
                                ):
                                    head += 1
                                left += 1

                            cur_val = field_values[row_i]
                            if not cur_val and not observe_empty:
                                continue

                            has_reference = head < len(observation_positions)
                            reference_pos = -1
                            if has_reference:
                                if tr.condition_reference_selection == "window_start":
                                    reference_pos = observation_positions[head]
                                else:
                                    reference_pos = observation_positions[-1]

                            if tr.mode == "first_seen_value":
                                if (
                                    tr.condition_reference_selection
                                    == "rolling_window"
                                ):
                                    condition_matched = (
                                        seen_counts.get(cur_val, 0) == 0
                                    )
                                else:
                                    reference_val = (
                                        field_values[int(idxs[reference_pos])]
                                        if has_reference else ""
                                    )
                                    condition_matched = (
                                        not has_reference
                                        or cur_val != reference_val
                                    )
                            else:
                                reference_val = (
                                    field_values[int(idxs[reference_pos])]
                                    if has_reference else ""
                                )
                                condition_matched = (
                                    has_reference and cur_val != reference_val
                                )

                            should_emit = (
                                condition_matched
                                if has_reference
                                else (
                                    tr.condition_first_observation_behavior
                                    == "emit"
                                )
                            )
                            if should_emit:
                                emit_row_i = (
                                    int(idxs[reference_pos])
                                    if tr.emit_on == "reference_observation"
                                    else row_i
                                )
                                self._temporal_emit_sparse(
                                    tr, signal_map, explain_map,
                                    emit_row_i, key_tuple,
                                )
                                _refresh_needed_signal_hits(emit_row_i)
                                emitted += 1

                            seen_counts[cur_val] = seen_counts.get(cur_val, 0) + 1
                            observation_positions.append(right)
                            if (
                                head > 1024
                                and head * 2 >= len(observation_positions)
                            ):
                                observation_positions = observation_positions[head:]
                                head = 0

            elapsed = time.perf_counter() - rule_start
            logger.info(
                "Temporal rule stats | rule=%s mode=%s groups=%d largest_group=%d emitted=%d time=%.2fs",
                tr.rule_id,
                tr.mode,
                groups_seen,
                largest_group,
                emitted,
                elapsed,
            )

    def _apply_impossible_travel_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
        carried_last: Optional[Dict[tuple, Dict[str, Any]]] = None,
    ) -> None:
        policy = self.detector_policy.impossible_travel
        if not policy.enabled:
            return
        required = {
            *policy.key_fields,
            policy.latitude_field,
            policy.longitude_field,
            policy.country_field,
        }
        if (
            not any(field_name in df.columns for field_name in policy.ip_fields)
            or not required.issubset(df.columns)
        ):
            return

        for semantic in ("distance_km", "dt_hours", "velocity_kmh"):
            df[policy.output_fields[semantic]] = math.nan
        for semantic in ("from_country", "to_country", "from_ip"):
            df[policy.output_fields[semantic]] = None

        output_locations = {
            semantic: df.columns.get_loc(field_name)
            for semantic, field_name in policy.output_fields.items()
        }

        idx_values = list(df.index)
        ip_values = _first_nonempty_normalised_text_array(
            df, policy.ip_fields
        )
        lat_values = df[policy.latitude_field].tolist()
        lon_values = df[policy.longitude_field].tolist()
        country_values = df[policy.country_field].tolist()
        key_columns = [df[k].tolist() for k in policy.key_fields]

        auth_positions = sorted(
            pos for pos, signals in signal_map.items()
            if 0 <= pos < len(df) and _signals_indicate_auth_success(
                signals,
                policy.success_signals,
                policy.minimum_signal_value_exclusive,
            )
        )
        if not auth_positions:
            return

        state: Dict[tuple, Dict[str, Any]] = (
            carried_last if carried_last is not None else {}
        )

        def threshold_matches(
            value: float,
            threshold: float,
            comparison: str,
        ) -> bool:
            if comparison == "greater_than_or_equal":
                return value >= threshold
            return value > threshold

        for pos in auth_positions:
            key = tuple(_safe_str(col[pos]) for col in key_columns)
            if all(part == "" for part in key):
                continue

            lat = lat_values[pos]
            lon = lon_values[pos]
            if lat is None or lon is None:
                continue
            try:
                lat = float(lat)
                lon = float(lon)
            except Exception:
                continue
            if pd.isna(lat) or pd.isna(lon):
                continue

            ts = idx_values[pos]
            observation = {
                "ts": ts,
                "lat": lat,
                "lon": lon,
                "country": country_values[pos],
                "ip": ip_values[pos],
            }
            actor_state = state.get(key)
            if actor_state is None:
                state[key] = {
                    "retained_reference": observation,
                    "previous_observation": observation,
                }
                continue

            prev = actor_state[
                "retained_reference"
                if policy.reference_selection == "retained_reference"
                else "previous_observation"
            ]
            comparison_qualifies = False
            if prev:
                dt_seconds = (ts - prev["ts"]).total_seconds()
                if threshold_matches(
                    dt_seconds,
                    policy.minimum_time_seconds,
                    policy.minimum_time_comparison,
                ):
                    dist_km = _haversine_km(prev["lat"], prev["lon"], lat, lon)
                    if threshold_matches(
                        dist_km,
                        policy.minimum_distance_km,
                        policy.minimum_distance_comparison,
                    ):
                        comparison_qualifies = True
                        vel_kmh = (dist_km / dt_seconds) * 3600.0
                        if threshold_matches(
                            vel_kmh,
                            policy.velocity_kmh_threshold,
                            policy.velocity_comparison,
                        ):
                            sig = self._sparse_signal_dict(signal_map, pos)
                            expl = self._sparse_explain_list(explain_map, pos)
                            emission = policy.emission
                            sig[emission.name] = max(
                                float(sig.get(emission.name, 0.0) or 0.0),
                                emission.value,
                            )
                            dt_hours = dt_seconds / 3600.0
                            df.iat[pos, output_locations["distance_km"]] = dist_km
                            df.iat[pos, output_locations["dt_hours"]] = dt_hours
                            df.iat[pos, output_locations["velocity_kmh"]] = vel_kmh
                            df.iat[pos, output_locations["from_country"]] = prev.get("country")
                            df.iat[pos, output_locations["to_country"]] = country_values[pos]
                            df.iat[pos, output_locations["from_ip"]] = prev.get("ip")
                            evidence_values = {
                                "distance_km": dist_km,
                                "dt_hours": dt_hours,
                                "velocity_kmh": vel_kmh,
                                "previous_ip": prev.get("ip"),
                                "current_ip": ip_values[pos],
                                "previous_country": prev.get("country"),
                                "current_country": country_values[pos],
                                "velocity_threshold_kmh": policy.velocity_kmh_threshold,
                                "minimum_distance_km": policy.minimum_distance_km,
                                "key_fields": "|".join(policy.key_fields),
                                "actor_key": "|".join(key),
                            }
                            expl.append({
                                "rule_id": emission.rule_id,
                                "description": emission.description,
                                "confidence": emission.confidence,
                                "evidence_type": policy.evidence_type,
                                "signals": [emission.name],
                                "evidence": _resolve_continuity_evidence(
                                    policy.evidence, evidence_values
                                ),
                            })

            actor_state["previous_observation"] = observation
            update_mode = (
                policy.qualifying_comparison_update
                if comparison_qualifies
                else policy.rejected_observation_update
            )
            if update_mode == "update_reference":
                actor_state["retained_reference"] = observation

    def _apply_geo_continuity_sparse(
        self,
        df: pd.DataFrame,
        signal_map: Dict[int, Dict[str, Any]],
        explain_map: Dict[int, List[Dict[str, Any]]],
        carried_state: Optional[Dict[tuple, Dict[str, Any]]] = None,
    ) -> None:
        if len(df) == 0:
            return
        policy = self.detector_policy.geographic_continuity
        if not policy.enabled:
            return
        required = set(policy.key_fields) | {
            policy.country_field,
            policy.asn_field,
        }
        if not required.issubset(df.columns):
            return
        if policy.history_lookback is not None and not isinstance(
            df.index, pd.DatetimeIndex
        ):
            raise ValueError(
                "geographic_continuity.history.retention requires a "
                "DatetimeIndex when configured with a finite duration"
            )

        has_city = policy.city_field in df.columns
        for output_field in policy.output_fields.values():
            if output_field not in df.columns:
                df[output_field] = False

        key_columns = [
            _normalised_text_array(df, key_field)
            for key_field in policy.key_fields
        ]
        # Vectorised string cleaning — produce object-dtype numpy arrays (None, not pd.NA)
        _country_s = df[policy.country_field].astype("string").fillna("").str.strip().str.upper()
        country_values = np.where(_country_s.ne("").to_numpy(), _country_s.to_numpy(dtype=object, copy=False, na_value=None), None)
        _asn_s = df[policy.asn_field].astype("string").fillna("").str.strip()
        asn_values = np.where(_asn_s.ne("").to_numpy(), _asn_s.to_numpy(dtype=object, copy=False, na_value=None), None)
        if has_city:
            _city_s = df[policy.city_field].astype("string").fillna("").str.strip()
            city_values = np.where(_city_s.ne("").to_numpy(), _city_s.to_numpy(dtype=object, copy=False, na_value=None), None)
        else:
            city_values = np.array([None] * len(df), dtype=object)
        ip_values = _first_nonempty_normalised_text_array(
            df, policy.ip_fields
        )

        state = carried_state if carried_state is not None else {}
        timestamp_values_ns = (
            _datetime_index_absolute_ns(df.index)
            if isinstance(df.index, pd.DatetimeIndex)
            else tuple(range(len(df)))
        )
        history_lookback_ns = (
            pd.Timedelta(policy.history_lookback).value
            if policy.history_lookback is not None
            else None
        )

        auth_positions = sorted(
            pos for pos, signals in signal_map.items()
            if 0 <= pos < len(df) and _signals_indicate_auth_success(
                signals,
                policy.success_signals,
                policy.minimum_signal_value_exclusive,
            )
        )
        if not auth_positions:
            return

        # Cache column locations for .iat[] writes inside the loop
        output_locations = {
            semantic: df.columns.get_loc(field_name)
            for semantic, field_name in policy.output_fields.items()
        }

        for pos in auth_positions:
            key = tuple(col[pos] for col in key_columns)
            if all(part == "" for part in key):
                continue

            country = country_values[pos]
            asn = asn_values[pos]
            if not country and not asn:
                continue

            entry = state.setdefault(
                key,
                {
                    "seen_countries": {},
                    "seen_asns": {},
                    "seen_cities": {},
                    "last_country": None,
                    "last_country_seen_at_ns": None,
                    "last_ip": None,
                    "last_asn": None,
                    "last_asn_seen_at_ns": None,
                    "last_city": None,
                    "last_city_seen_at_ns": None,
                    "sequence": 0,
                },
            )
            event_ns = int(timestamp_values_ns[pos])
            if event_ns == pd.NaT.value:
                continue
            cutoff_ns = (
                event_ns - history_lookback_ns
                if history_lookback_ns is not None
                else None
            )

            if cutoff_ns is not None:
                for history_name in (
                    "seen_countries", "seen_asns", "seen_cities"
                ):
                    history = entry[history_name]
                    expired = [
                        value
                        for value, metadata in history.items()
                        if metadata["seen_at_ns"] < cutoff_ns
                    ]
                    for value in expired:
                        del history[value]
                for value_name, timestamp_name in (
                    ("last_country", "last_country_seen_at_ns"),
                    ("last_asn", "last_asn_seen_at_ns"),
                    ("last_city", "last_city_seen_at_ns"),
                ):
                    last_seen_at_ns = entry.get(timestamp_name)
                    if (
                        last_seen_at_ns is not None
                        and last_seen_at_ns < cutoff_ns
                    ):
                        entry[value_name] = None
                        entry[timestamp_name] = None
                        if value_name == "last_country":
                            entry["last_ip"] = None

            sequence = int(entry.get("sequence", 0)) + 1

            sig = None
            expl = None

            def ensure():
                nonlocal sig, expl
                if sig is None:
                    sig = self._sparse_signal_dict(signal_map, pos)
                if expl is None:
                    expl = self._sparse_explain_list(explain_map, pos)
                return sig, expl

            def emit_semantic(
                semantic: str,
                evidence_values: Dict[str, Any],
            ) -> None:
                emission = policy.emissions_by_semantic[semantic]
                current_sig, current_expl = ensure()
                current_sig[emission.name] = max(
                    float(current_sig.get(emission.name, 0.0) or 0.0),
                    emission.value,
                )
                current_expl.append({
                    "rule_id": emission.rule_id,
                    "description": emission.description,
                    "confidence": emission.confidence,
                    "evidence_type": policy.evidence_type,
                    "signals": [emission.name],
                    "evidence": _resolve_continuity_evidence(
                        policy.evidence_by_semantic[semantic],
                        evidence_values,
                    ),
                })

            def novelty_status(
                value: Optional[str],
                history_name: str,
                last_value_name: str,
            ) -> Tuple[bool, bool, Tuple[str, ...]]:
                if not value:
                    return False, False, ()
                history = entry[history_name]
                previous_value = entry.get(last_value_name)
                first_observation = not history
                if policy.novelty_reference == "all_seen":
                    novel = value not in history
                    comparison_values = tuple(sorted(history))
                else:
                    novel = previous_value is None or value != previous_value
                    comparison_values = (
                        (str(previous_value),) if previous_value is not None else ()
                    )
                return novel, first_observation, comparison_values

            country_novel, country_first, previous_countries = novelty_status(
                country, "seen_countries", "last_country"
            )
            if country_novel:
                if not country_first or policy.mark_first_observation:
                    df.iat[pos, output_locations["new_country"]] = True
                if not country_first or policy.emit_first_observation:
                    emit_semantic("new_country", {
                        "current_country": country,
                        "previous_countries": "|".join(previous_countries),
                        "current_ip": ip_values[pos],
                        "key_fields": "|".join(policy.key_fields),
                        "actor_key": "|".join(key),
                    })

            asn_novel, asn_first, previous_asns = novelty_status(
                asn, "seen_asns", "last_asn"
            )
            if asn_novel:
                if not asn_first or policy.mark_first_observation:
                    df.iat[pos, output_locations["new_asn"]] = True
                if not asn_first or policy.emit_first_observation:
                    emit_semantic("new_asn", {
                        "current_asn": asn,
                        "previous_asns": "|".join(previous_asns),
                        "current_ip": ip_values[pos],
                        "key_fields": "|".join(policy.key_fields),
                        "actor_key": "|".join(key),
                    })

            city = city_values[pos]
            city_novel, city_first, previous_cities = novelty_status(
                city, "seen_cities", "last_city"
            )
            if city_novel:
                if not city_first or policy.mark_first_observation:
                    df.iat[pos, output_locations["new_city"]] = True
                if not city_first or policy.emit_first_observation:
                    emit_semantic("new_city", {
                        "current_city": city,
                        "current_country": country or "",
                        "previous_cities": "|".join(previous_cities),
                        "current_ip": ip_values[pos],
                        "key_fields": "|".join(policy.key_fields),
                        "actor_key": "|".join(key),
                    })

            previous_boundary_country = None
            previous_boundary_ip = None
            if country and policy.boundary_reference == "previous_observation":
                prev_country = entry.get("last_country")
                if prev_country and country != prev_country:
                    previous_boundary_country = prev_country
                    previous_boundary_ip = entry.get("last_ip")
            elif country:
                prior_distinct = [
                    (metadata["sequence"], value, metadata.get("ip"))
                    for value, metadata in entry["seen_countries"].items()
                    if value != country
                ]
                if prior_distinct:
                    _, previous_boundary_country, previous_boundary_ip = max(
                        prior_distinct, key=lambda item: item[0]
                    )

            if previous_boundary_country is not None:
                df.iat[pos, output_locations["boundary_crossing"]] = True
                emit_semantic("boundary_crossing", {
                    "previous_country": previous_boundary_country,
                    "current_country": country,
                    "previous_ip": _safe_str(previous_boundary_ip),
                    "current_ip": ip_values[pos],
                    "key_fields": "|".join(policy.key_fields),
                    "actor_key": "|".join(key),
                })

            if country:
                entry["seen_countries"][country] = {
                    "seen_at_ns": event_ns,
                    "sequence": sequence,
                    "ip": ip_values[pos],
                }
                entry["last_country"] = country
                entry["last_ip"] = ip_values[pos]
                entry["last_country_seen_at_ns"] = event_ns
            if asn:
                entry["seen_asns"][asn] = {
                    "seen_at_ns": event_ns,
                    "sequence": sequence,
                }
                entry["last_asn"] = asn
                entry["last_asn_seen_at_ns"] = event_ns
            if city:
                entry["seen_cities"][city] = {
                    "seen_at_ns": event_ns,
                    "sequence": sequence,
                }
                entry["last_city"] = city
                entry["last_city_seen_at_ns"] = event_ns
            entry["sequence"] = sequence

    def ensure_required_fields(self, df: pd.DataFrame) -> pd.DataFrame:
        out = df

        # Enrichment-owned fields are created by dedicated enrichment stages and
        # should not be pre-created here as placeholders. Doing so can collide
        # with authoritative enrichment results during later joins.
        enrichment_fields = {
            *self.geoip_enrichment_policy.output_columns,
            "yara_match_count",
            "av_hit",
            "luhn_hit",
            "nsrl_application_type",
            "nsrl_is_os_component",
            self.profiling_policy.nsrl_application_type_field,
            self.profiling_policy.nsrl_is_os_component_field,
        }

        needed = [
            col
            for col in sorted(self.required_fields)
            if col and col not in enrichment_fields
        ]
        out = _ensure_object_columns(out, needed)

        return out

    # -------------------------------------------------------------------------
    # Required field collection
    # -------------------------------------------------------------------------

    def _collect_required_fields(self) -> Set[str]:
        fields: Set[str] = set()

        # Normalisation inputs
        for spec in self.normalisation:
            if spec.source:
                fields.add(spec.source)
            fields.update(spec.fields)

        fields.update(self.canonicalisation_policy.input_fields)
        fields.update(self.canonicalisation_policy.output_fields)

        def add_conditions(conds: List[Condition]) -> None:
            for c in conds:
                if c.field:
                    fields.add(c.field)

        for r in self.rules:
            add_conditions(r.scope_any)
            add_conditions(r.scope_all)
            add_conditions(r.when_any)
            add_conditions(r.when_all)
            for evf in r.evidence_fields:
                if evf:
                    fields.add(evf)

        for tr in self.temporal_rules:
            for k in tr.key_by:
                if k:
                    fields.add(k)
            if tr.field:
                fields.add(tr.field)

        for definition in self.detector_policy.definitions(enabled_only=True):
            fields.update(_detector_definition_required_fields(definition))

        if self.profiling_policy.enabled:
            fields.update({
                self.profiling_policy.parser_field,
                self.profiling_policy.filename_field,
                self.profiling_policy.nsrl_is_os_component_field,
                self.profiling_policy.nsrl_application_type_field,
            })

        if self.trust_dampening_policy.enabled:
            fields.update({
                self.trust_dampening_policy.principal_field,
                self.trust_dampening_policy.ip_field,
                self.trust_dampening_policy.asn_field,
            })

        aliased = set()
        for field in list(fields):
            for alias in self.schema_aliases.get(field, ()):
                if alias:
                    aliased.add(alias)
        fields.update(aliased)

        return fields

    # -------------------------------------------------------------------------
    # Normalisation
    # -------------------------------------------------------------------------

    def _apply_normalisation(
        self,
        df: pd.DataFrame,
    ) -> pd.DataFrame:
        out = df

        # Normalisation creates canonical actor/file/network columns from the
        # heterogeneous source schema. Rules should prefer these derived fields
        # over parser-specific raw names whenever the semantics match.
        for spec in self.normalisation:
            name = spec.name
            method = spec.method

            if method == "coalesce":
                # Earlier extraction and schema aliasing can populate canonical
                # fields before normalisation runs. Preserve that value as the
                # highest-priority coalesce input so the semantic layer does not
                # erase structured data when a specific source field is absent.
                source_fields = [field_name for field_name in spec.fields if field_name != name]
                ensure_fields = [name] + source_fields
                out = _ensure_object_columns(out, ensure_fields)
                if not source_fields:
                    continue

                missing = _missing_meaningful_value_mask(out[name])
                if not bool(missing.any()):
                    continue

                if bool((~missing).any()):
                    filled = _coalesce_first_meaningful_for_mask(out, source_fields, missing)
                    out.loc[missing, name] = filled.to_numpy(copy=False)
                else:
                    out[name] = _coalesce_first_meaningful(out, source_fields)

            elif method == "regex_first":
                src = spec.source
                if not src or src not in out.columns:
                    out = _ensure_object_columns(out, [name])
                    continue
                assert spec.pattern is not None
                derived = out[src].map(
                    lambda value: (
                        match.group(spec.group)
                        if (match := spec.pattern.search(_safe_str(value))) is not None
                        else None
                    )
                )
                if name in out.columns:
                    existing = out[name]
                    missing = _missing_meaningful_value_mask(existing)
                    if bool(missing.any()):
                        out.loc[missing, name] = derived.loc[missing]
                else:
                    out[name] = derived

            elif method == "file_extension":
                src = spec.source
                if not src or src not in out.columns:
                    out = _ensure_object_columns(out, [name])
                    continue
                # Vectorised: extract last dot-delimited extension via pandas str ops
                s = out[src].astype("string").fillna("").str.strip()
                ext = s.str.extract(r'(\.[^./\\]+)$', expand=False).str.lower()
                out[name] = ext

            elif method == "ipv4_first":
                src = spec.source
                if not src or src not in out.columns:
                    out = _ensure_object_columns(out, [name])
                    continue
                out[name] = normalise_ipv4_first_series(out[src])

        return out

    # -------------------------------------------------------------------------
    # IP recovery (structured-first)
    # -------------------------------------------------------------------------

    def _recover_ip_address(self, df: pd.DataFrame) -> pd.DataFrame:
        out = df
        policy = self.canonicalisation_policy.ip_recovery
        windows_policy = self.canonicalisation_policy.windows_authentication
        # Recovery is intentionally structured-first: preserve parser-provided
        # output, then walk the configured ordered sources. The engine owns IP
        # parsing mechanics; field selection, precedence, and context gating are
        # part of the mandatory YAML policy.
        out = _ensure_object_columns(out, policy.input_fields)
        # Recover only where missing/placeholder.
        missing = out[policy.output_field].map(_is_null)
        missing_mask = missing.to_numpy(dtype=bool, copy=False)
        if missing_mask.any():
            pending_pos = np.flatnonzero(missing_mask)
            recovered = pd.Series(pd.NA, index=pd.RangeIndex(len(pending_pos)), dtype="string")

            def _prefilter_text_positions(local_pos: np.ndarray, field: str, require_context: bool = False) -> np.ndarray:
                if len(local_pos) == 0:
                    return local_pos
                values = out[field].iloc[pending_pos[local_pos]].astype("string").fillna("")
                ip_like = values.str.contains(_IP_LITERAL_CANDIDATE_RE.pattern, regex=True, na=False).to_numpy(dtype=bool, copy=False)
                if require_context:
                    with warnings.catch_warnings():
                        warnings.filterwarnings(
                            "ignore",
                            message="This pattern is interpreted as a regular expression, and has match groups.*",
                            category=UserWarning,
                        )
                        ctx = values.str.contains(
                            policy.context_regex,
                            regex=True,
                            na=False,
                        ).to_numpy(dtype=bool, copy=False)
                    ip_like &= ctx
                if not bool(ip_like.any()):
                    return np.empty(0, dtype=np.int64)
                return local_pos[np.flatnonzero(ip_like)]

            parser_vals = (
                out[policy.parser_field]
                .iloc[pending_pos]
                .astype("string")
                .fillna("")
                .str.lower()
            )
            windows_mask = parser_vals.str.startswith(
                policy.windows_parser_prefixes
            ).to_numpy(dtype=bool, copy=False)

            for source in policy.sources:
                unresolved = recovered.isna().to_numpy(dtype=bool, copy=False)
                if not unresolved.any():
                    break
                unresolved_pos = np.flatnonzero(unresolved)

                if source.kind.startswith("windows_"):
                    unresolved_pos = unresolved_pos[windows_mask[unresolved_pos]]
                    if len(unresolved_pos) == 0:
                        continue

                for field_name in source.fields:
                    unresolved = recovered.iloc[unresolved_pos].isna().to_numpy(
                        dtype=bool, copy=False
                    )
                    if not unresolved.any():
                        break
                    source_pos = unresolved_pos[np.flatnonzero(unresolved)]

                    if source.kind == "windows_fields":
                        candidate_pos = source_pos
                        extractor = lambda value: _normalise_ip_literal(
                            value,
                            self.canonicalisation_policy.excluded_networks,
                        )
                    elif source.kind == "windows_xml":
                        candidate_pos = source_pos
                        extractor = lambda value: _extract_ip_from_evtx_xml(
                            value,
                            windows_policy,
                            self.canonicalisation_policy.excluded_networks,
                        )
                    elif source.kind == "windows_strings":
                        candidate_pos = source_pos
                        extractor = lambda value: _extract_ip_from_strings_field(
                            value,
                            self.canonicalisation_policy.excluded_networks,
                        )
                    else:
                        candidate_pos = _prefilter_text_positions(
                            source_pos,
                            field_name,
                            require_context=source.require_context,
                        )
                        extractor = lambda value, require=source.require_context: (
                            _extract_ip_from_text_field(
                                value,
                                require_context=require,
                                context_regex=policy.context_regex,
                                excluded_networks=(
                                    self.canonicalisation_policy.excluded_networks
                                ),
                            )
                        )
                    if len(candidate_pos) == 0:
                        continue
                    recovered.iloc[candidate_pos] = (
                        out[field_name]
                        .iloc[pending_pos[candidate_pos]]
                        .map(extractor)
                        .astype("string")
                        .to_numpy(copy=False)
                    )

            resolved_mask = recovered.notna().to_numpy(dtype=bool, copy=False)
            if resolved_mask.any():
                ip_col_loc = out.columns.get_loc(policy.output_field)
                resolved_pos = pending_pos[resolved_mask]
                resolved_vals = recovered.iloc[np.flatnonzero(resolved_mask)].to_numpy(copy=False)
                out.iloc[resolved_pos, ip_col_loc] = resolved_vals
        return out

    # -------------------------------------------------------------------------
    # Profiling: dataset-wide hour-of-week activity deficit
    # -------------------------------------------------------------------------

    def _apply_hour_of_week_profiling(self, df: pd.DataFrame, profile_manifest: Optional[Dict[str, Any]] = None) -> pd.DataFrame:
        out = df
        policy = self.profiling_policy
        if not policy.enabled:
            return out

        dt_all = _ensure_datetime_series(out)
        how_all = _hour_of_week(dt_all)
        out[policy.hour_of_week_field] = how_all

        if profile_manifest is None:
            profile_df = _select_profile_events(out, policy)
            component_field_available = (
                policy.nsrl_is_os_component_field in out.columns
            )
            filters_applied = bool(
                policy.parser_field in out.columns
                or component_field_available
                or (
                    policy.nsrl_application_type_field in out.columns
                    and (
                        policy.nsrl_exclusion_combine == "any_available"
                        or not component_field_available
                    )
                    and policy.exclude_nsrl_application_type_contains
                )
                or (
                    policy.filename_field in out.columns
                    and policy.exclude_filename_contains
                )
            )

            def build_attempt(
                selected: pd.DataFrame,
                *,
                selection_mode: str,
                used_filtered_subset: bool,
                filters: List[str],
            ) -> Dict[str, Any]:
                if len(selected) < policy.min_profile_events:
                    return _empty_hour_of_week_manifest(
                        alpha=policy.smoothing_alpha,
                        quiet_quantile=policy.quiet_quantile,
                        selection_mode=selection_mode,
                        source_event_count=len(out),
                        selected_event_count=len(selected),
                        selection_filters=filters,
                        validation={
                            "status": "inconclusive",
                            "accepted": False,
                            "reason": "insufficient_profile_events",
                            "method": policy.validation.method,
                            "reference": policy.validation.reference,
                            "block": policy.validation.block,
                            "selected_event_count": len(selected),
                            "minimum_profile_events": policy.min_profile_events,
                        },
                    )
                return _hour_of_week_manifest_from_weekly_counts(
                    _complete_week_hour_counts_from_frame(selected, out),
                    policy,
                    selection_mode=selection_mode,
                    used_filtered_subset=used_filtered_subset,
                    source_event_count=len(out),
                    selected_event_count=len(selected),
                    selection_filters=filters,
                )

            initial_mode = "filtered" if filters_applied else "unfiltered"
            profile_manifest = build_attempt(
                profile_df,
                selection_mode=initial_mode,
                used_filtered_subset=filters_applied,
                filters=["in_memory_profile_selection"] if filters_applied else [],
            )
            if (
                not profile_manifest.get("profile")
                and filters_applied
                and policy.insufficient_filtered_events == "full_dataset"
            ):
                first_attempt = {
                    "selection_mode": initial_mode,
                    **dict(profile_manifest.get("validation", {})),
                }
                profile_manifest = build_attempt(
                    out,
                    selection_mode="fallback_full_dataset",
                    used_filtered_subset=False,
                    filters=["fallback:filtered_profile_not_validated"],
                )
                profile_manifest["validation_attempts"] = [first_attempt]

        profile_is_validated = bool(
            (profile_manifest.get("validation", {}) or {}).get(
                "accepted", False
            )
        )
        profile = (
            {
                int(k): float(v)
                for k, v in (profile_manifest.get("profile", {}) or {}).items()
            }
            if profile_is_validated
            else {}
        )
        quiet_hours = frozenset(
            int(x)
            for x in (
                profile_manifest.get("quiet_hours", [])
                if profile_is_validated
                else []
            )
        )

        _profile_arr = np.zeros(168, dtype=np.float64)
        for _k, _v in profile.items():
            _profile_arr[int(_k)] = float(_v)
        _valid = how_all.notna()
        _idx = how_all.to_numpy(dtype=np.float64, na_value=0.0).astype(np.intp)
        np.clip(_idx, 0, 167, out=_idx)
        out[policy.activity_deficit_signal] = np.where(
            _valid.to_numpy(), _profile_arr[_idx], 0.0
        )
        out.attrs["_chronosift_quiet_hours_profile"] = frozenset(quiet_hours)
        out.attrs["_chronosift_profile_manifest"] = profile_manifest
        out.attrs["_chronosift_profile_metadata"] = {
            "selection_mode": profile_manifest.get("selection_mode"),
            "used_filtered_subset": bool(
                profile_manifest.get("used_filtered_subset", False)
            ),
            "source_event_count": int(
                profile_manifest.get("source_event_count", 0) or 0
            ),
            "selected_event_count": int(
                profile_manifest.get("selected_event_count", 0) or 0
            ),
            "validation": dict(profile_manifest.get("validation", {}) or {}),
            "validation_attempts": list(
                profile_manifest.get("validation_attempts", []) or []
            ),
        }
        return out


    # -------------------------------------------------------------------------
    # Parsing rules
    # -------------------------------------------------------------------------

    def _parse_condition(self, raw: Dict[str, Any], path: str) -> Condition:
        cfg = _policy_mapping(raw, path)
        op = _policy_enum(
            cfg.get("op"),
            f"{path}.op",
            OP_MAP,
        )
        required = {"field", "op"}
        optional: Set[str] = set()
        if op == "exists":
            optional.add("value")
        else:
            required.add("value")
        _policy_keys(cfg, path, required=required, optional=optional)
        field = _policy_string(cfg["field"], f"{path}.field")
        value = cfg.get("value")
        if op in {"in", "in_ci"}:
            if not isinstance(value, list) or not value:
                raise ValueError(f"{path}.value: expected a non-empty list")
        elif op in {"contains", "contains_ci", "regex"}:
            value = _policy_string(value, f"{path}.value")
            if op == "regex":
                try:
                    re.compile(value)
                except re.error as exc:
                    raise ValueError(f"{path}.value: invalid regex: {exc}") from exc
        elif op in {"lt", "lte", "gt", "gte"}:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(f"{path}.value: expected a finite number")
            value = float(value)
            if not math.isfinite(value):
                raise ValueError(f"{path}.value: expected a finite number")
        return Condition(field=field, op=op, value=value)

    def _parse_rules(self, raw_rules: List[Dict[str, Any]]) -> List[Rule]:
        if not isinstance(raw_rules, list):
            raise ValueError("rules: expected a list")
        parsed: List[Rule] = []
        seen_rule_ids: Set[str] = set()
        for rule_index, raw_rule in enumerate(raw_rules):
            path = f"rules[{rule_index}]"
            rr = _policy_mapping(raw_rule, path)
            _policy_keys(
                rr,
                path,
                required={
                    "id", "description", "priority", "scope", "when",
                    "emit", "confidence",
                },
            )
            rid = _policy_string(rr["id"], f"{path}.id")
            if rid in seen_rule_ids:
                raise ValueError(f"{path}.id: duplicate rule id {rid!r}")
            seen_rule_ids.add(rid)

            def parse_condition_group(group_name: str) -> Tuple[List[Condition], List[Condition]]:
                group_path = f"{path}.{group_name}"
                group_cfg = _policy_mapping(rr[group_name], group_path)
                _policy_keys(group_cfg, group_path, required={"any", "all"})
                parsed_groups: List[List[Condition]] = []
                for branch_name in ("any", "all"):
                    branch_path = f"{group_path}.{branch_name}"
                    raw_conditions = group_cfg[branch_name]
                    if not isinstance(raw_conditions, list):
                        raise ValueError(f"{branch_path}: expected a list")
                    parsed_groups.append([
                        self._parse_condition(condition, f"{branch_path}[{index}]")
                        for index, condition in enumerate(raw_conditions)
                    ])
                return parsed_groups[0], parsed_groups[1]

            scope_any, scope_all = parse_condition_group("scope")
            when_any, when_all = parse_condition_group("when")

            emit_path = f"{path}.emit"
            emit = _policy_mapping(rr["emit"], emit_path)
            _policy_keys(
                emit,
                emit_path,
                required={"signals", "evidence"},
            )
            raw_signals = emit["signals"]
            if not isinstance(raw_signals, list) or not raw_signals:
                raise ValueError(f"{emit_path}.signals: expected a non-empty list")
            emit_signals: List[EmitSignal] = []
            seen_signal_names: Set[str] = set()
            for signal_index, raw_signal in enumerate(raw_signals):
                signal_path = f"{emit_path}.signals[{signal_index}]"
                signal_cfg = _policy_mapping(raw_signal, signal_path)
                _policy_keys(signal_cfg, signal_path, required={"name", "value"})
                signal_name = _policy_signal_name(
                    signal_cfg["name"], f"{signal_path}.name"
                )
                if signal_name in seen_signal_names:
                    raise ValueError(
                        f"{signal_path}.name: duplicate emission {signal_name!r}"
                    )
                seen_signal_names.add(signal_name)
                signal_value = _policy_positive_number(
                    signal_cfg["value"], f"{signal_path}.value"
                )
                emit_signals.append(EmitSignal(name=signal_name, value=signal_value))

            raw_evidence = emit["evidence"]
            if not isinstance(raw_evidence, list):
                raise ValueError(f"{emit_path}.evidence: expected a list")
            evidence_fields: List[str] = []
            for evidence_index, raw_item in enumerate(raw_evidence):
                evidence_path = f"{emit_path}.evidence[{evidence_index}]"
                evidence_cfg = _policy_mapping(raw_item, evidence_path)
                _policy_keys(evidence_cfg, evidence_path, required={"field"})
                field = _policy_string(evidence_cfg["field"], f"{evidence_path}.field")
                if field in evidence_fields:
                    raise ValueError(
                        f"{evidence_path}.field: duplicate evidence field {field!r}"
                    )
                evidence_fields.append(field)

            parsed.append(Rule(
                rule_id=rid,
                description=_policy_string(rr["description"], f"{path}.description"),
                priority=_policy_nonnegative_int(rr["priority"], f"{path}.priority"),
                scope_any=scope_any,
                scope_all=scope_all,
                when_any=when_any,
                when_all=when_all,
                emit_signals=emit_signals,
                evidence_fields=evidence_fields,
                confidence=_policy_confidence(rr["confidence"], f"{path}.confidence"),
            ))

        parsed.sort(key=lambda r: r.priority, reverse=True)
        return parsed

    def _parse_temporal_rules(self, raw_tr: List[Dict[str, Any]]) -> List[TemporalRule]:
        if not isinstance(raw_tr, list):
            raise ValueError("temporal_rules: expected a list")
        parsed: List[TemporalRule] = []
        seen_rule_ids: Set[str] = set()
        for rule_index, raw_rule in enumerate(raw_tr):
            path = f"temporal_rules[{rule_index}]"
            tr = _policy_mapping(raw_rule, path)
            _policy_keys(
                tr,
                path,
                required={
                    "id", "description", "priority", "key_by", "lookback",
                    "lookback_lower_bound", "emit_on",
                    "minimum_signal_value_exclusive", "emit", "confidence",
                },
                optional={"sequence", "cooccur", "condition"},
            )
            rid = _policy_string(tr["id"], f"{path}.id")
            if rid in seen_rule_ids:
                raise ValueError(f"{path}.id: duplicate rule id {rid!r}")
            seen_rule_ids.add(rid)
            key_by = list(_policy_string_list(tr["key_by"], f"{path}.key_by"))
            try:
                lookback = parse_lookback(tr["lookback"])
            except (TypeError, ValueError) as exc:
                raise ValueError(f"{path}.lookback: {exc}") from exc
            if lookback <= timedelta(0):
                raise ValueError(f"{path}.lookback: expected a duration greater than zero")
            lookback_lower_bound = _policy_enum(
                tr["lookback_lower_bound"],
                f"{path}.lookback_lower_bound",
                {"inclusive", "exclusive"},
            )
            desc = _policy_string(tr["description"], f"{path}.description")
            prio = _policy_nonnegative_int(tr["priority"], f"{path}.priority")
            conf = _policy_confidence(tr["confidence"], f"{path}.confidence")
            minimum_signal_value_exclusive = _policy_nonnegative_number(
                tr["minimum_signal_value_exclusive"],
                f"{path}.minimum_signal_value_exclusive",
            )

            mode = ""
            seq: List[TemporalNeed] = []
            co_all: List[TemporalNeed] = []
            fld: Optional[str] = None
            condition_empty_value_behavior: Optional[str] = None
            condition_first_observation_behavior: Optional[str] = None
            condition_reference_selection: Optional[str] = None

            configured_modes = [
                name for name in ("sequence", "cooccur", "condition")
                if name in tr
            ]
            if len(configured_modes) != 1:
                raise ValueError(
                    f"{path}: expected exactly one of sequence, cooccur, condition"
                )
            if configured_modes[0] == "sequence":
                mode = "sequence"
                raw_sequence = tr["sequence"]
                if not isinstance(raw_sequence, list) or not raw_sequence:
                    raise ValueError(f"{path}.sequence: expected a non-empty list")
                for step_index, raw_step in enumerate(raw_sequence):
                    step_path = f"{path}.sequence[{step_index}]"
                    step_cfg = _policy_mapping(raw_step, step_path)
                    _policy_keys(step_cfg, step_path, required={"signal", "min_count"})
                    seq.append(TemporalNeed(
                        signal=_policy_signal_name(
                            step_cfg["signal"], f"{step_path}.signal"
                        ),
                        min_count=_policy_positive_int(
                            step_cfg["min_count"], f"{step_path}.min_count"
                        ),
                    ))
            elif configured_modes[0] == "cooccur":
                mode = "cooccur"
                cooccur_path = f"{path}.cooccur"
                cooccur_cfg = _policy_mapping(tr["cooccur"], cooccur_path)
                _policy_keys(cooccur_cfg, cooccur_path, required={"all"})
                raw_needs = cooccur_cfg["all"]
                if not isinstance(raw_needs, list) or not raw_needs:
                    raise ValueError(f"{cooccur_path}.all: expected a non-empty list")
                for need_index, raw_need in enumerate(raw_needs):
                    need_path = f"{cooccur_path}.all[{need_index}]"
                    need_cfg = _policy_mapping(raw_need, need_path)
                    _policy_keys(need_cfg, need_path, required={"signal", "min_count"})
                    co_all.append(TemporalNeed(
                        signal=_policy_signal_name(
                            need_cfg["signal"], f"{need_path}.signal"
                        ),
                        min_count=_policy_positive_int(
                            need_cfg["min_count"], f"{need_path}.min_count"
                        ),
                    ))
            else:
                condition_path = f"{path}.condition"
                condition_cfg = _policy_mapping(tr["condition"], condition_path)
                _policy_keys(
                    condition_cfg,
                    condition_path,
                    required={
                        "kind", "field", "empty_value_behavior",
                        "first_observation_behavior", "reference_selection",
                    },
                )
                mode = _policy_enum(
                    condition_cfg["kind"],
                    f"{condition_path}.kind",
                    {"first_seen_value", "change_detected"},
                )
                fld = _policy_string(condition_cfg["field"], f"{condition_path}.field")
                condition_empty_value_behavior = _policy_enum(
                    condition_cfg["empty_value_behavior"],
                    f"{condition_path}.empty_value_behavior",
                    {"ignore", "observe"},
                )
                condition_first_observation_behavior = _policy_enum(
                    condition_cfg["first_observation_behavior"],
                    f"{condition_path}.first_observation_behavior",
                    {"emit", "suppress"},
                )
                allowed_reference_selections = (
                    {"rolling_window", "previous_observation"}
                    if mode == "first_seen_value"
                    else {"previous_observation", "window_start"}
                )
                condition_reference_selection = _policy_enum(
                    condition_cfg["reference_selection"],
                    f"{condition_path}.reference_selection",
                    allowed_reference_selections,
                )

            allowed_emit_on = {
                "sequence": {"sequence_completion", "sequence_start"},
                "cooccur": {"current_input", "window_start"},
                "first_seen_value": {"condition_match"},
                "change_detected": {
                    "condition_match", "reference_observation",
                },
            }[mode]
            emit_on = _policy_enum(
                tr["emit_on"],
                f"{path}.emit_on",
                allowed_emit_on,
            )
            if (
                emit_on == "reference_observation"
                and condition_first_observation_behavior == "emit"
            ):
                raise ValueError(
                    f"{path}.emit_on: reference_observation requires "
                    f"{path}.condition.first_observation_behavior=suppress"
                )

            emit_path = f"{path}.emit"
            emit_cfg = _policy_mapping(tr["emit"], emit_path)
            _policy_keys(emit_cfg, emit_path, required={"signals"})
            raw_signals = emit_cfg["signals"]
            if not isinstance(raw_signals, list) or not raw_signals:
                raise ValueError(f"{emit_path}.signals: expected a non-empty list")
            emit_signals: List[EmitSignal] = []
            seen_signal_names: Set[str] = set()
            for signal_index, raw_signal in enumerate(raw_signals):
                signal_path = f"{emit_path}.signals[{signal_index}]"
                signal_cfg = _policy_mapping(raw_signal, signal_path)
                _policy_keys(signal_cfg, signal_path, required={"name", "value"})
                signal_name = _policy_signal_name(
                    signal_cfg["name"], f"{signal_path}.name"
                )
                if signal_name in seen_signal_names:
                    raise ValueError(
                        f"{signal_path}.name: duplicate emission {signal_name!r}"
                    )
                seen_signal_names.add(signal_name)
                emit_signals.append(EmitSignal(
                    name=signal_name,
                    value=_policy_positive_number(
                        signal_cfg["value"], f"{signal_path}.value"
                    ),
                ))

            parsed.append(TemporalRule(
                rule_id=rid,
                description=desc,
                priority=prio,
                key_by=key_by,
                lookback=lookback,
                lookback_lower_bound=lookback_lower_bound,
                mode=mode,
                emit_on=emit_on,
                minimum_signal_value_exclusive=minimum_signal_value_exclusive,
                sequence=seq,
                cooccur_all=co_all,
                field=fld,
                condition_empty_value_behavior=condition_empty_value_behavior,
                condition_first_observation_behavior=(
                    condition_first_observation_behavior
                ),
                condition_reference_selection=condition_reference_selection,
                emit_signals=emit_signals,
                confidence=conf,
            ))

        parsed.sort(key=lambda r: r.priority, reverse=True)
        return parsed

    # -------------------------------------------------------------------------
    # Per-event evaluation (tuple-based for performance)
    # -------------------------------------------------------------------------

    def _get_field_tuple(self, row: Any, field: str) -> Any:
        return getattr(row, field, None)

    def _cond_match_tuple(self, row: Any, cond: Condition) -> bool:
        if not cond.field or not cond.op or cond.op not in OP_MAP:
            return False
        field_val = self._get_field_tuple(row, cond.field)
        op_func = OP_MAP[cond.op]
        try:
            if cond.op == "exists":
                return op_func(field_val)
            if cond.op == "regex":
                return op_func(field_val, cond.value)
            if cond.op in ("in", "in_ci"):
                return op_func(field_val, cond.value or [])
            if cond.op in ("contains", "contains_ci"):
                return op_func(field_val, str(cond.value))
            if cond.op in ("lt", "lte", "gt", "gte"):
                return op_func(field_val, cond.value)
            return op_func(field_val, cond.value)
        except Exception:
            return False

    def _conds_all_tuple(self, row: Any, conds: List[Condition]) -> bool:
        return all(self._cond_match_tuple(row, c) for c in conds) if conds else True

    def _conds_any_tuple(self, row: Any, conds: List[Condition]) -> bool:
        return any(self._cond_match_tuple(row, c) for c in conds) if conds else True

    def _rule_matches_tuple(self, row: Any, rule: Rule) -> bool:
        if not self._conds_all_tuple(row, rule.scope_all):
            return False
        if rule.scope_any and not self._conds_any_tuple(row, rule.scope_any):
            return False
        if not self._conds_all_tuple(row, rule.when_all):
            return False
        if rule.when_any and not self._conds_any_tuple(row, rule.when_any):
            return False
        return True

    def _eval_row_tuple(self, row: Any) -> Tuple[Dict[str, Any], List[Dict[str, Any]]]:
        signals: Dict[str, Any] = {}
        explain: List[Dict[str, Any]] = []

        for rule in self.rules:
            if not self._rule_matches_tuple(row, rule):
                continue

            for es in rule.emit_signals:
                if not es.name:
                    continue
                _merge_rule_signal_value(
                    signals,
                    es,
                    self.rule_signal_merge_policy.atomic_rules,
                )

            ev: Dict[str, str] = {}
            for f in rule.evidence_fields:
                v = self._get_field_tuple(row, f)
                if not _is_null(v):
                    s = _safe_str(v)
                    ev[f] = _truncate_evidence_text(s)

            explain.append({
                "rule_id": rule.rule_id,
                "description": rule.description,
                "confidence": rule.confidence,
                "evidence": ev,
            })

        return signals, explain

    def _eval_atomic_rules_sparse_legacy(
        self,
        df: pd.DataFrame,
    ) -> Tuple[Dict[int, Dict[str, Any]], Dict[int, List[Dict[str, Any]]]]:
        signal_map: Dict[int, Dict[str, Any]] = {}
        explain_map: Dict[int, List[Dict[str, Any]]] = {}

        for i, row in enumerate(df.itertuples(index=False, name="ChronoRow")):
            signals, explain = self._eval_row_tuple(row)
            if signals:
                signal_map[i] = signals
            if explain:
                explain_map[i] = explain

        return signal_map, explain_map

    def _eval_atomic_rules_sparse(
        self,
        df: pd.DataFrame,
    ) -> Tuple[Dict[int, Dict[str, Any]], Dict[int, List[Dict[str, Any]]]]:
        nrows = len(df)
        if nrows == 0 or not self.rules:
            return {}, {}

        signal_map: Dict[int, Dict[str, Any]] = {}
        explain_map: Dict[int, List[Dict[str, Any]]] = {}

        raw_cache: Dict[str, pd.Series] = {}
        text_cache: Dict[str, pd.Series] = {}
        lower_cache: Dict[str, pd.Series] = {}
        strip_lower_cache: Dict[str, pd.Series] = {}
        numeric_cache: Dict[str, pd.Series] = {}
        null_mask_cache: Dict[str, np.ndarray] = {}
        evidence_cache: Dict[str, np.ndarray] = {}
        condition_cache: Dict[Tuple[str, str, str], np.ndarray] = {}

        def _field_series(field: str) -> pd.Series:
            ser = raw_cache.get(field)
            if ser is None:
                if field in df.columns:
                    ser = df[field]
                else:
                    ser = pd.Series(pd.NA, index=df.index, dtype=object)
                raw_cache[field] = ser
            return ser

        def _text_series(field: str) -> pd.Series:
            ser = text_cache.get(field)
            if ser is None:
                raw = _field_series(field).astype("string")
                stripped = raw.str.strip()
                placeholder_mask = stripped.str.lower().isin(PLACEHOLDER_STRINGS)
                ser = raw.mask(stripped.eq("") | placeholder_mask, "")
                text_cache[field] = ser
            return ser

        def _lower_text_series(field: str) -> pd.Series:
            ser = lower_cache.get(field)
            if ser is None:
                ser = _text_series(field).str.lower()
                lower_cache[field] = ser
            return ser

        def _strip_lower_text_series(field: str) -> pd.Series:
            ser = strip_lower_cache.get(field)
            if ser is None:
                ser = _text_series(field).str.strip().str.lower()
                strip_lower_cache[field] = ser
            return ser

        def _numeric_series(field: str) -> pd.Series:
            ser = numeric_cache.get(field)
            if ser is None:
                ser = pd.to_numeric(_field_series(field), errors="coerce")
                numeric_cache[field] = ser
            return ser

        def _semantic_null_mask(field: str) -> np.ndarray:
            mask = null_mask_cache.get(field)
            if mask is None:
                raw = _field_series(field)
                if str(raw.dtype) == "string" or pd.api.types.is_object_dtype(raw.dtype):
                    mask = _text_series(field).eq("").to_numpy(dtype=bool, copy=False)
                else:
                    mask = pd.isna(raw).to_numpy(dtype=bool, copy=False)
                null_mask_cache[field] = mask
            return mask

        def _condition_mask(cond: Condition) -> np.ndarray:
            key = (str(cond.field), str(cond.op), repr(cond.value))
            cached = condition_cache.get(key)
            if cached is not None:
                return cached

            field = str(cond.field or "").strip()
            op = str(cond.op or "").strip()
            if not field or not op or op not in OP_MAP:
                mask = np.zeros(nrows, dtype=bool)
                condition_cache[key] = mask
                return mask

            try:
                if op == "exists":
                    mask = ~_semantic_null_mask(field)
                elif op == "eq":
                    series = _field_series(field)
                    mask = series.eq(cond.value).fillna(False).to_numpy(dtype=bool, copy=False) & ~_semantic_null_mask(field)
                elif op == "in":
                    series = _field_series(field)
                    mask = series.isin(cond.value or []).fillna(False).to_numpy(dtype=bool, copy=False) & ~_semantic_null_mask(field)
                elif op == "in_ci":
                    needles = {str(v).strip().lower() for v in (cond.value or []) if str(v).strip()}
                    if needles:
                        mask = _strip_lower_text_series(field).isin(needles).fillna(False).to_numpy(dtype=bool, copy=False)
                    else:
                        mask = np.zeros(nrows, dtype=bool)
                elif op == "contains":
                    needle = str(cond.value)
                    if needle:
                        mask = _text_series(field).str.contains(needle, regex=False, na=False).to_numpy(dtype=bool, copy=False)
                    else:
                        mask = np.zeros(nrows, dtype=bool)
                elif op == "contains_ci":
                    needle = str(cond.value).lower()
                    if needle:
                        mask = _lower_text_series(field).str.contains(needle, regex=False, na=False).to_numpy(dtype=bool, copy=False)
                    else:
                        mask = np.zeros(nrows, dtype=bool)
                elif op == "regex":
                    pattern = str(cond.value or "")
                    if pattern:
                        with warnings.catch_warnings():
                            warnings.filterwarnings(
                                "ignore",
                                message="This pattern is interpreted as a regular expression, and has match groups.*",
                                category=UserWarning,
                            )
                            mask = _text_series(field).str.contains(pattern, regex=True, na=False).to_numpy(dtype=bool, copy=False)
                    else:
                        mask = np.zeros(nrows, dtype=bool)
                elif op == "lt":
                    mask = (_numeric_series(field) < float(cond.value)).fillna(False).to_numpy(dtype=bool, copy=False)
                elif op == "lte":
                    mask = (_numeric_series(field) <= float(cond.value)).fillna(False).to_numpy(dtype=bool, copy=False)
                elif op == "gt":
                    mask = (_numeric_series(field) > float(cond.value)).fillna(False).to_numpy(dtype=bool, copy=False)
                elif op == "gte":
                    mask = (_numeric_series(field) >= float(cond.value)).fillna(False).to_numpy(dtype=bool, copy=False)
                else:
                    mask = np.zeros(nrows, dtype=bool)
            except Exception:
                mask = np.zeros(nrows, dtype=bool)

            condition_cache[key] = mask
            return mask

        def _rule_mask(rule: Rule) -> np.ndarray:
            mask = np.ones(nrows, dtype=bool)

            for cond in rule.scope_all:
                mask &= _condition_mask(cond)
                if not bool(mask.any()):
                    return mask

            if rule.scope_any:
                any_mask = np.zeros(nrows, dtype=bool)
                for cond in rule.scope_any:
                    any_mask |= _condition_mask(cond)
                mask &= any_mask
                if not bool(mask.any()):
                    return mask

            for cond in rule.when_all:
                mask &= _condition_mask(cond)
                if not bool(mask.any()):
                    return mask

            if rule.when_any:
                any_mask = np.zeros(nrows, dtype=bool)
                for cond in rule.when_any:
                    any_mask |= _condition_mask(cond)
                mask &= any_mask

            return mask

        for rule in self.rules:
            match_mask = _rule_mask(rule)
            if not bool(match_mask.any()):
                continue

            positions = np.flatnonzero(match_mask)
            evidence_fields = [f for f in rule.evidence_fields if f]

            for pos in positions:
                row_i = int(pos)
                signals = signal_map.get(row_i)

                if signals is None and rule.emit_signals:
                    signals = {}
                    signal_map[row_i] = signals

                if signals is not None:
                    for es in rule.emit_signals:
                        if not es.name:
                            continue
                        _merge_rule_signal_value(
                            signals,
                            es,
                            self.rule_signal_merge_policy.atomic_rules,
                        )

                ev: Dict[str, str] = {}
                for field in evidence_fields:
                    values = evidence_cache.get(field)
                    if values is None:
                        if field in df.columns:
                            values = df[field].to_numpy(dtype=object, copy=False)
                        else:
                            values = np.full(nrows, None, dtype=object)
                        evidence_cache[field] = values
                    value = values[row_i]
                    if not _is_null(value):
                        s = _safe_str(value)
                        ev[field] = _truncate_evidence_text(s)

                explain_map.setdefault(row_i, []).append({
                    "rule_id": rule.rule_id,
                    "description": rule.description,
                    "confidence": rule.confidence,
                    "evidence": ev,
                })

        return signal_map, explain_map

